def _paper_behavior_receipt_archive_root(root: Path | None = None) -> Path:
    selected = PAPER_BEHAVIOR_RECEIPT_ARCHIVE_ROOT if root is None else Path(root)
    return selected.expanduser().resolve()


def _runtime_default_symbol() -> str:
    from v2.backend.app.services.v2_symbol_runtime_universe import resolve_symbols

    return resolve_symbols()[0]


def _utc_iso() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="milliseconds").replace("+00:00", "Z")


_OPERATOR_ET_ZONE = ZoneInfo("America/New_York")


def _operator_et_iso(value: Any) -> str | None:
    if value in (None, ""):
        return None
    if isinstance(value, datetime):
        parsed = value
    else:
        try:
            parsed = datetime.fromisoformat(str(value).replace("Z", "+00:00"))
        except ValueError:
            return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(_OPERATOR_ET_ZONE).isoformat(timespec="milliseconds")


_OPERATOR_ET_TIMESTAMP_SOURCES: tuple[tuple[str, tuple[str, ...]], ...] = (
    ("generated_et", ("generated_utc", "generated_at", "heartbeat_generated_at")),
    (
        "decision_time_et",
        ("decision_time", "model_decision_time", "runtime_cost_capture_decision_time"),
    ),
    (
        "entry_time_et",
        ("entry_time", "accepted_at", "opened_at", "fill_price_utc", "decision_time"),
    ),
    (
        "exit_time_et",
        ("exit_time", "closed_at", "exit_price_utc", "execution_time", "generated_utc"),
    ),
    (
        "available_at_et",
        ("available_at", "entry_feature_available_at", "entry_spread_available_at"),
    ),
    ("last_update_et", ("last_update_utc", "updated_at", "generated_utc", "generated_at")),
)


def _with_operator_et_timestamp_fields(row: dict[str, Any]) -> dict[str, Any]:
    enriched = dict(row)
    for target, sources in _OPERATOR_ET_TIMESTAMP_SOURCES:
        if enriched.get(target) not in (None, ""):
            continue
        for source in sources:
            converted = _operator_et_iso(enriched.get(source))
            if converted is not None:
                enriched[target] = converted
                break
    enriched.setdefault("operator_display_timezone", "America/New_York")
    enriched.setdefault("raw_utc_allowed_for_machine_trace", True)
    return enriched


def _with_operator_et_timestamp_rows(rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
    return [_with_operator_et_timestamp_fields(row) for row in rows if isinstance(row, dict)]


def _utc_iso_from_strategy_time(value: Any) -> str | None:
    parsed = _parse_strategy_time(value)
    if parsed is None:
        return None
    return parsed.astimezone(timezone.utc).isoformat(timespec="milliseconds").replace("+00:00", "Z")


def _normalize_closed_paper_exploration_economics(row: dict[str, Any]) -> dict[str, Any]:
    item = dict(row)
    if not _is_paper_risk_controller_exploration_row(item):
        return item

    if item.get("entry_time") in (None, ""):
        item["entry_time"] = _first_present(
            _utc_iso_from_strategy_time(item.get("entry_time_et")),
            item.get("policy_activated_at"),
            item.get("fill_price_utc"),
            item.get("decision_time"),
        )
    if item.get("exit_time") in (None, ""):
        item["exit_time"] = _first_present(
            _utc_iso_from_strategy_time(item.get("exit_time_et")),
            item.get("exit_price_utc"),
            item.get("closed_at"),
            item.get("generated_utc"),
        )
    if item.get("realized_gross_pnl_usd") in (None, ""):
        item["realized_gross_pnl_usd"] = _first_present(
            item.get("gross_realized_pnl_usd"),
            item.get("realized_pnl_usd"),
            item.get("realized_pnl_usdt"),
            item.get("realized_pnl"),
        )
    if item.get("fees_usd") in (None, ""):
        item["fees_usd"] = _first_present(item.get("fees"), item.get("fee_usd"))
    if item.get("slippage_usd") in (None, ""):
        item["slippage_usd"] = _first_present(
            item.get("slippage"),
            item.get("realized_slippage_usd"),
            item.get("implementation_shortfall_usd"),
        )
    if item.get("funding_usd") in (None, ""):
        item["funding_usd"] = _first_present(item.get("funding"), item.get("funding_pnl_usd"))
    if item.get("max_adverse_usd") in (None, ""):
        item["max_adverse_usd"] = _first_present(item.get("mae_usd"), item.get("MAE_usd"))
    if item.get("max_favorable_usd") in (None, ""):
        item["max_favorable_usd"] = _first_present(item.get("mfe_usd"), item.get("MFE_usd"))

    if item.get("realized_pnl_usd") in (None, ""):
        entry_price = _coerce_float(item.get("entry_price"))
        exit_price = _coerce_float(item.get("exit_price"))
        quantity = _coerce_float(item.get("quantity") or item.get("order_size"))
        fees = _coerce_float(item.get("fees_usd") or item.get("fees") or 0.0) or 0.0
        slippage = _coerce_float(item.get("slippage_usd") or item.get("slippage") or 0.0) or 0.0
        if entry_price is not None and exit_price is not None and quantity is not None:
            pnl_before_costs = (exit_price - entry_price) * quantity
            realized_pnl_usd = round(pnl_before_costs - fees - slippage, 8)
            item["realized_pnl_usd"] = realized_pnl_usd

    if item.get("win_loss") in (None, ""):
        winner = item.get("winner")
        if winner is True:
            item["win_loss"] = "win"
        elif winner is False:
            item["win_loss"] = "loss"
        else:
            net = _coerce_float(item.get("realized_pnl_usd") or item.get("realized_net_pnl_usd"))
            if net is not None:
                item["win_loss"] = "win" if net > 0 else "loss"
    if item.get("dirty_flag") is None:
        item["dirty_flag"] = bool(item.get("dirty_reasons"))
    if item.get("dirty_reasons") is None:
        item["dirty_reasons"] = []
    if item.get("trainer_consumable") is None and item.get("trainer_feedback_id") not in (None, ""):
        item["trainer_consumable"] = False
        item["trainer_consumable_block_reason"] = "TRAINER_FEEDBACK_STATUS_SEE_FEEDBACK_QUEUE"

    item["paper_only"] = True
    for field in (
        "routes_to_live",
        "places_real_order",
        "live_order",
        "test_order",
        "order_submitted",
        "test_order_submitted",
        "leverage_mutated",
        "margin_mutated",
        "counts_as_A_plus",
        "counts_as_final_A_plus",
        "counts_as_final_a_plus",
        "counts_as_live_ready",
    ):
        item[field] = False
    return item


def _normalize_closed_paper_exploration_economics_rows(
    rows: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    return [
        _normalize_closed_paper_exploration_economics(row) for row in rows if isinstance(row, dict)
    ]


def _closed_trades_shrink_guard(
    r,
    closes: list[dict[str, Any]],
    *,
    session_id: Any,
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    """Never let a transient read failure destroy closed-trade history.

    2026-07-08 incident (CG-F044): one cycle read the existing closes as empty
    and unconditionally rewrote v2:paper:closed_trades, permanently destroying
    17 rows across every mirror. This guard re-reads the live key at write
    time; if the new set would shrink the same-session history by more than
    half (and the session did not change), it merges the union instead and
    flags the event. Explicit quarantine/reset flows bypass this by changing
    the session id.
    """
    status: dict[str, Any] = {"guard": "CLOSED_TRADES_SHRINK_GUARD", "engaged": False}
    try:
        raw = r.get(f"{V2_REDIS_PREFIX}paper:closed_trades")
        existing = json.loads(raw) if raw else []
        if not isinstance(existing, list):
            existing = []
    except Exception:
        existing = []
    same_session = [
        row
        for row in existing
        if isinstance(row, dict) and row.get("paper_session_id") == session_id
    ]
    if len(same_session) >= 4 and len(closes) < max(2, len(same_session) // 2):

        def _row_key(row: dict[str, Any]) -> str:
            return str(
                row.get("close_id")
                or row.get("outcome_label_id")
                or row.get("position_id")
                or f"{row.get('symbol')}|{row.get('exit_price_utc')}|{row.get('realized_pnl_bps')}"
            )

        merged: dict[str, dict[str, Any]] = {}
        for row in same_session:
            merged[_row_key(row)] = row
        for row in closes:
            if isinstance(row, dict):
                merged[_row_key(row)] = row
        status.update(
            {
                "engaged": True,
                "existing_same_session": len(same_session),
                "incoming": len(closes),
                "merged": len(merged),
                "reason": "INCOMING_SET_WOULD_SHRINK_HISTORY_OVER_50PCT_WITHOUT_SESSION_CHANGE",
            }
        )
        return list(merged.values()), status
    return closes, status


CLOSE_EXIT_EVIDENCE_FIELDS = (
    "close_id",
    "paper_close_id",
    "exit_time",
    "exit_price_utc",
    "exit_price",
    "exit_fill_price",
)


def _split_closes_without_exit_evidence(
    closes: list[dict[str, Any]],
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    """Quarantine close rows that carry no exit evidence at all.

    CG-F044 follow-up: the row that displaced 17 real closed trades was a
    pytest fixture (position_id=pos_incomplete) with no close_id, no exit
    timestamp, and no exit price. A real close always records at least one
    exit-evidence field; operator-restored compact rows are exempt via their
    reconstructed_from_artifacts provenance stamp. Rows failing both checks
    are moved to the quarantine key instead of being counted as history.
    """
    real: list[dict[str, Any]] = []
    synthetic: list[dict[str, Any]] = []
    for row in closes:
        if not isinstance(row, dict):
            continue
        if row.get("reconstructed_from_artifacts") is True or any(
            row.get(field) not in (None, "") for field in CLOSE_EXIT_EVIDENCE_FIELDS
        ):
            real.append(row)
        else:
            synthetic.append(
                {
                    **row,
                    "quarantine_reason": "NO_EXIT_EVIDENCE_SYNTHETIC_OR_TEST_ROW",
                    "counts_as_closed_trade": False,
                }
            )
    return real, synthetic


def _connect_redis():
    try:
        import redis  # type: ignore
    except Exception:
        return None
    try:
        r = redis.Redis(host="127.0.0.1", port=6379, db=0, decode_responses=True)
        r.ping()
        return r
    except Exception:
        return None


def _configured_paper_fee_bps() -> float:
    from v2.backend.app.services.adaptive_capital_allocator import AllocationInput

    return float(AllocationInput.__dataclass_fields__["fee_bps"].default)


def _fee_schedule_evidence_sha256(
    *,
    fee_bps_per_side: Any,
    fee_source: Any,
) -> str | None:
    fee_bps = _coerce_float(fee_bps_per_side)
    source = str(fee_source or "").strip()
    if fee_bps is None or fee_bps < 0.0 or not source:
        return None
    evidence = {
        "schema_version": "paper_cost_fee_schedule_evidence_v1",
        "configuration_kind": "CONFIGURED_TAKER_FEE_BPS_PER_SIDE",
        "taker_fee_bps_per_side": fee_bps,
        "fee_source": source,
    }
    encoded = json.dumps(
        evidence,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=True,
        allow_nan=False,
    ).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def _fee_bps_from_readonly_schedule(
    schedule: dict[str, Any] | None,
) -> tuple[float | None, str | None]:
    if not isinstance(schedule, dict):
        return None, None
    source = str(
        _first_present(
            schedule.get("source"),
            schedule.get("redis_key"),
            schedule.get("fee_schedule_source"),
            "READ_ONLY_FEE_SCHEDULE",
        )
    )
    for key in (
        "taker_fee_bps",
        "fee_bps",
        "expected_fee_bps",
        "actual_fee_bps",
        "commission_bps",
    ):
        parsed = _coerce_float(schedule.get(key))
        if parsed is not None:
            return parsed, f"{source}.{key}"
    for key in ("taker_fee_rate", "fee_rate", "commission_rate"):
        parsed = _coerce_float(schedule.get(key))
        if parsed is not None:
            return parsed * 10000.0, f"{source}.{key}:rate_to_bps"
    return None, None


def _read_readonly_fee_schedule_context(
    redis_client: Any | None,
    *,
    symbol: str,
) -> dict[str, Any]:
    if redis_client is None:
        return {}
    sym = str(symbol or "").upper().strip()
    keys = [
        f"{V2_REDIS_PREFIX}account:fee_schedule:{sym}",
        f"{V2_REDIS_PREFIX}exchange:fee_schedule:{sym}",
        f"{V2_REDIS_PREFIX}market:fee_schedule:{sym}",
        f"{V2_REDIS_PREFIX}fee_schedule:{sym}",
        f"{V2_REDIS_PREFIX}account:fee_schedule",
        f"{V2_REDIS_PREFIX}exchange:fee_schedule",
        f"{V2_REDIS_PREFIX}market:fee_schedule",
        f"{V2_REDIS_PREFIX}fee_schedule",
    ]
    for key in keys:
        if not sym and key.endswith(":"):
            continue
        try:
            raw = redis_client.get(key)
        except Exception:  # noqa: BLE001
            continue
        if not raw:
            continue
        try:
            decoded = json.loads(raw)
        except (TypeError, json.JSONDecodeError):
            continue
        candidates: list[dict[str, Any]] = []
        if isinstance(decoded, dict):
            if isinstance(decoded.get(sym), dict):
                candidates.append(decoded[sym])
            for container_key in ("symbols", "fees", "fee_schedules", "data"):
                container = decoded.get(container_key)
                if isinstance(container, dict) and isinstance(container.get(sym), dict):
                    candidates.append(container[sym])
            candidates.append(decoded)
        for candidate in candidates:
            if not isinstance(candidate, dict):
                continue
            payload = dict(candidate)
            payload.setdefault("source", f"READ_ONLY_FEE_SCHEDULE_REDIS:{key}")
            if _fee_bps_from_readonly_schedule(payload)[0] is not None:
                # Preserve distinct producer clocks.  Do not infer
                # available_at from an event/effective time: a schedule can
                # exist at the venue before this process could observe it.
                payload["fee_schedule_available_at"] = _first_present(
                    payload.get("available_at"),
                    payload.get("source_available_at"),
                )
                payload["fee_schedule_ingested_at"] = payload.get("ingested_at")
                payload["fee_schedule_generated_at"] = _first_present(
                    payload.get("generated_at"),
                    payload.get("generated_utc"),
                )
                payload["fee_schedule_effective_at"] = _first_present(
                    payload.get("effective_at"),
                    payload.get("event_time"),
                )
                payload["fee_schedule_redis_key"] = key
                return payload
    return {}


def _pre_trade_fee_context(
    *,
    signal: dict[str, Any],
    prediction: dict[str, Any],
    fee_schedule_context: dict[str, Any] | None,
) -> dict[str, Any]:
    features = prediction.get("features") if isinstance(prediction.get("features"), dict) else {}
    fee_bps, fee_source = _first_numeric_field_from(
        ("signal", signal),
        ("prediction", prediction),
        ("prediction_features", features),
        keys=("actual_fee_bps", "fee_bps", "taker_fee_bps", "expected_fee_bps"),
    )
    if fee_bps is not None:
        return {
            "fee_bps": fee_bps,
            "fee_bps_source": fee_source,
            "fee_bps_readonly_schedule": False,
            "fee_bps_configured_schedule": False,
        }
    readonly_fee_bps, readonly_fee_source = _fee_bps_from_readonly_schedule(
        fee_schedule_context,
    )
    if readonly_fee_bps is not None:
        return {
            "fee_bps": readonly_fee_bps,
            "fee_bps_source": readonly_fee_source,
            "fee_bps_readonly_schedule": True,
            "fee_bps_configured_schedule": False,
        }
    return {
        "fee_bps": _configured_paper_fee_bps(),
        "fee_bps_source": PAPER_CONFIGURED_FEE_SCHEDULE_SOURCE,
        "fee_bps_readonly_schedule": False,
        "fee_bps_configured_schedule": True,
    }


def _build_trainer_feedback_rows(
    *,
    close_events: list[dict[str, Any]],
    outcome_labels: list[dict[str, Any]],
    entry_context_rows: list[dict[str, Any]] | None = None,
    predictions_by_id: dict[str, dict[str, Any]] | None = None,
    feature_snapshots_by_id: dict[str, dict[str, Any]] | None = None,
    behavior_receipt_archive_root: Path | None = None,
) -> list[dict[str, Any]]:
    behavior_receipt_archive_root = _paper_behavior_receipt_archive_root(
        behavior_receipt_archive_root
    )
    outcomes_by_feedback_id = {
        row.get("trainer_feedback_id"): row
        for row in outcome_labels
        if isinstance(row, dict) and row.get("trainer_feedback_id")
    }
    entry_context_by_fill_id = _entry_feedback_context_by_fill_id(entry_context_rows or [])
    predictions_by_id = predictions_by_id or {}
    require_feature_snapshot_deref = feature_snapshots_by_id is not None
    feature_snapshots_by_id = feature_snapshots_by_id or {}
    rows: list[dict[str, Any]] = []
    for close_event in close_events:
        if not isinstance(close_event, dict):
            continue
        feedback_id = close_event.get("trainer_feedback_id")
        outcome = outcomes_by_feedback_id.get(feedback_id)
        if not isinstance(outcome, dict):
            continue
        source_context = _source_entry_context_for_close(
            close_event=close_event,
            entry_context_by_fill_id=entry_context_by_fill_id,
        )
        if source_context:
            close_event = _with_feedback_context_fallback(close_event, source_context)
            outcome = _with_feedback_context_fallback(outcome, source_context)
        entry_prediction_id = str(
            _first_present(
                close_event.get("entry_prediction_id"),
                outcome.get("entry_prediction_id"),
                close_event.get("prediction_id"),
                outcome.get("prediction_id"),
                "",
            )
        )
        entry_feature_snapshot_id = _first_present(
            close_event.get("entry_feature_snapshot_id"),
            outcome.get("entry_feature_snapshot_id"),
            close_event.get("feature_snapshot_id"),
            outcome.get("feature_snapshot_id"),
        )
        prediction = predictions_by_id.get(entry_prediction_id, {}) if entry_prediction_id else {}
        embedded_prediction = _embedded_entry_prediction_snapshot(
            close_event, prediction_id=entry_prediction_id
        ) or _embedded_entry_prediction_snapshot(outcome, prediction_id=entry_prediction_id)
        if not prediction and embedded_prediction is not None:
            prediction = embedded_prediction
            close_event.setdefault("entry_prediction_snapshot_used", True)
            outcome.setdefault("entry_prediction_snapshot_used", True)
        feature_snapshot = (
            feature_snapshots_by_id.get(str(entry_feature_snapshot_id))
            if entry_feature_snapshot_id
            else None
        )
        if feature_snapshot is None:
            feature_snapshot = _embedded_entry_feature_snapshot(
                close_event,
                feature_snapshot_id=str(entry_feature_snapshot_id)
                if entry_feature_snapshot_id not in (None, "")
                else None,
            ) or _embedded_entry_feature_snapshot(
                outcome,
                feature_snapshot_id=str(entry_feature_snapshot_id)
                if entry_feature_snapshot_id not in (None, "")
                else None,
            )
        if not prediction:
            prediction = _self_contained_entry_prediction_from_closed_row(
                {**outcome, **close_event},
                prediction_id=entry_prediction_id,
                feature_snapshot=feature_snapshot,
            )
            if prediction:
                close_event.setdefault("self_contained_entry_prediction_used", True)
                outcome.setdefault("self_contained_entry_prediction_used", True)
        close_event = _reconstruct_trust_from_prediction(
            row=close_event,
            prediction=prediction,
            feature_snapshot=feature_snapshot,
            require_feature_snapshot_deref=require_feature_snapshot_deref,
            prediction_id=entry_prediction_id,
            feature_snapshot_id=entry_feature_snapshot_id,
        )
        outcome = _reconstruct_trust_from_prediction(
            row=outcome,
            prediction=prediction,
            feature_snapshot=feature_snapshot,
            require_feature_snapshot_deref=require_feature_snapshot_deref,
            prediction_id=entry_prediction_id,
            feature_snapshot_id=entry_feature_snapshot_id,
        )
        feedback_row = build_strategy_hedge_exit_feedback(
            close_event=close_event,
            outcome_label=outcome,
        )
        # Preserve the exact finalized close economics needed to recompute the
        # terminal PPO reward. These are copied from the already-sealed paper
        # outcome; no value is synthesized from a later trainer/runtime clock.
        for _outcome_field in (
            "close_id",
            "close_event_time",
            "outcome_generated_at",
            "outcome_available_at",
            "outcome_availability_status",
            "gross_realized_pnl_usd",
            "realized_gross_pnl_usd",
            "realized_net_pnl_usd",
            "realized_net_pnl_bps",
            "fees",
            "fees_usd",
            "entry_fee_usd",
            "exit_fee_usd",
            "total_fees_usd",
            "slippage",
            "slippage_usd",
            "entry_slippage_usd",
            "exit_slippage_usd",
            "total_slippage_usd",
            "total_execution_costs_usd",
            "funding",
            "funding_usd",
            "funding_pnl_usd",
            "closed_quantity",
            "entry_price",
            "exit_price",
            "side",
            "closed_entry_notional_usd",
            "closed_exit_notional_usd",
            "paper_round_trip_cost_accounting_version",
            "paper_cost_rate_scope",
            "paper_net_pnl_formula",
            "round_trip_cost_fallback_used",
            "round_trip_cost_provenance_status",
            "entry_cost_accounting_version",
            "entry_cost_allocation_method",
            "entry_cost_allocation_fraction_of_pre_close_position",
            "entry_cost_pre_close_quantity",
            "entry_cost_closed_quantity",
            "entry_cost_is_final_close",
            "entry_fee_source",
            "entry_fee_fallback",
            "entry_fee_fallback_bps_per_side",
            "entry_fee_bps_per_side",
            "entry_slippage_source",
            "entry_slippage_fallback",
            "entry_slippage_fallback_bps_per_side",
            "entry_slippage_bps_per_side",
            "entry_cost_basis_status",
            "exit_fee_source",
            "exit_fee_fallback",
            "exit_fee_rate_basis",
            "exit_fee_bps_per_side",
            "exit_slippage_source",
            "exit_slippage_available_at",
            "exit_slippage_fallback",
            "exit_slippage_provenance_status",
            "exit_slippage_bps_per_side",
        ):
            _outcome_value = _first_present(
                close_event.get(_outcome_field),
                outcome.get(_outcome_field),
            )
            if _outcome_value not in (None, ""):
                feedback_row[_outcome_field] = deepcopy(_outcome_value)
        _unit_explicit_costs = {
            "fees_usd": _first_present(close_event.get("fees"), outcome.get("fees")),
            "slippage_usd": _first_present(close_event.get("slippage"), outcome.get("slippage")),
            "funding_usd": _first_present(
                close_event.get("funding_pnl_usd"),
                outcome.get("funding_pnl_usd"),
            ),
        }
        if all(value not in (None, "") for value in _unit_explicit_costs.values()):
            feedback_row.update(_unit_explicit_costs)
            feedback_row["outcome_cost_unit"] = "USD"
        if feedback_row.get("entry_prediction_snapshot") in (None, "", {}, []) and isinstance(
            close_event.get("entry_prediction_snapshot"), dict
        ):
            feedback_row["entry_prediction_snapshot"] = dict(
                close_event["entry_prediction_snapshot"]
            )
        if feedback_row.get("entry_feature_snapshot") in (None, "", {}, []) and isinstance(
            close_event.get("entry_feature_snapshot"), dict
        ):
            feedback_row["entry_feature_snapshot"] = dict(close_event["entry_feature_snapshot"])
        # PPO on-policy contract: entry-time probability/value fields are
        # necessary but not sufficient. The action must also have been sampled
        # from the exact distribution whose log-probability PPO will compare.
        # Deterministic expected-move-aligned argmax rows remain valid
        # outcome-supervised evidence but are never represented as on-policy.
        _on_policy_log_prob = _coerce_float(
            _first_present(
                close_event.get("old_log_prob"),
                outcome.get("old_log_prob"),
            )
        )
        _on_policy_selected_probability = _coerce_float(
            _first_present(
                close_event.get("selected_action_probability"),
                outcome.get("selected_action_probability"),
            )
        )
        _behavior_sampling_mode = (
            str(
                _first_present(
                    close_event.get("behavior_policy_sampling_mode"),
                    outcome.get("behavior_policy_sampling_mode"),
                )
                or ""
            )
            .strip()
            .upper()
        )
        _behavior_distribution_contract = (
            str(
                _first_present(
                    close_event.get("behavior_policy_distribution_contract"),
                    outcome.get("behavior_policy_distribution_contract"),
                )
                or ""
            )
            .strip()
            .upper()
        )
        _behavior_receipt = _first_present(
            close_event.get("behavior_policy_receipt"),
            outcome.get("behavior_policy_receipt"),
        )
        _behavior_action_index = _first_present(
            close_event.get("behavior_action_index"),
            outcome.get("behavior_action_index"),
            close_event.get("selected_action_index"),
            outcome.get("selected_action_index"),
        )
        _behavior_policy_fingerprint = _first_present(
            close_event.get("behavior_policy_fingerprint"),
            outcome.get("behavior_policy_fingerprint"),
        )
        _behavior_receipt_hash = _first_present(
            close_event.get("behavior_policy_receipt_hash"),
            outcome.get("behavior_policy_receipt_hash"),
        )
        _behavior_receipt_key = _first_present(
            close_event.get("behavior_policy_receipt_key"),
            outcome.get("behavior_policy_receipt_key"),
        )
        _behavior_receipt_write_success = _first_present(
            close_event.get("behavior_policy_receipt_write_success"),
            outcome.get("behavior_policy_receipt_write_success"),
        )
        _on_policy_action_receipt_valid = _first_present(
            close_event.get("on_policy_action_receipt_valid"),
            outcome.get("on_policy_action_receipt_valid"),
        )
        _strategy_supply_hypothesis = _first_present(
            close_event.get("strategy_supply_hypothesis"),
            outcome.get("strategy_supply_hypothesis"),
        )
        _receipt_rejection_reasons = behavior_receipt_rejection_reasons(
            _behavior_receipt,
            expected_prediction_id=entry_prediction_id,
            expected_symbol=_first_present(close_event.get("symbol"), outcome.get("symbol")),
            expected_timeframe=_first_present(
                close_event.get("timeframe"), outcome.get("timeframe")
            ),
            expected_action=_first_present(
                close_event.get("selected_action"),
                outcome.get("selected_action"),
                close_event.get("side"),
                outcome.get("side"),
            ),
            expected_action_index=_behavior_action_index,
            expected_checkpoint_id=_first_present(
                close_event.get("checkpoint_id"),
                outcome.get("checkpoint_id"),
            ),
            expected_checkpoint_weight_sha256=_first_present(
                close_event.get("behavior_policy_checkpoint_hash"),
                outcome.get("behavior_policy_checkpoint_hash"),
            ),
            expected_feature_tensor_id=_first_present(
                close_event.get("feature_tensor_id"),
                outcome.get("feature_tensor_id"),
            ),
            expected_feature_vector_hash=_first_present(
                close_event.get("feature_vector_hash"),
                outcome.get("feature_vector_hash"),
            ),
            expected_feature_cutoff=_first_present(
                close_event.get("feature_cutoff"),
                outcome.get("feature_cutoff"),
            ),
            expected_available_at=_first_present(
                close_event.get("available_at"),
                outcome.get("available_at"),
            ),
            expected_decision_time=_first_present(
                close_event.get("decision_time"),
                outcome.get("decision_time"),
            ),
            expected_policy_fingerprint=_behavior_policy_fingerprint,
            expected_sampling_plan_hash=_first_present(
                close_event.get("on_policy_sampling_plan_hash"),
                outcome.get("on_policy_sampling_plan_hash"),
            ),
            expected_sampling_plan_input_hash=_first_present(
                close_event.get("on_policy_sampling_plan_input_hash"),
                outcome.get("on_policy_sampling_plan_input_hash"),
            ),
        )
        _receipt_embedded_hash = (
            _behavior_receipt.get("receipt_hash")
            if isinstance(_behavior_receipt, Mapping)
            else None
        )
        if _behavior_receipt_hash != _receipt_embedded_hash:
            _receipt_rejection_reasons.append("behavior_policy_receipt_flat_hash_mismatch")
        _expected_receipt_key = (
            f"{V2_REDIS_PREFIX}trainer:hybrid_cuda:on_policy_receipt:" f"{_behavior_receipt_hash}"
            if _behavior_receipt_hash not in (None, "")
            else None
        )
        if _behavior_receipt_key != _expected_receipt_key:
            _receipt_rejection_reasons.append("behavior_policy_receipt_key_binding_mismatch")
        if _behavior_receipt_write_success is not True:
            _receipt_rejection_reasons.append("behavior_policy_receipt_not_durable_at_entry")
        _archive_content_sha256 = _first_present(
            close_event.get("behavior_policy_receipt_archive_content_sha256"),
            outcome.get("behavior_policy_receipt_archive_content_sha256"),
        )
        if isinstance(_behavior_receipt, Mapping):
            try:
                _archive_verification = verify_archived_behavior_receipt(
                    _behavior_receipt,
                    root=behavior_receipt_archive_root,
                )
                if _archive_content_sha256 not in (None, "") and (
                    _archive_content_sha256 != _archive_verification["archive_content_sha256"]
                ):
                    _receipt_rejection_reasons.append(
                        "behavior_policy_receipt_archive_hash_binding_mismatch"
                    )
                _archive_lifecycle = receipt_lifecycle_status(
                    _behavior_receipt_hash,
                    root=behavior_receipt_archive_root,
                )
                if _archive_lifecycle.get("entry_accepted_durable") is not True:
                    _receipt_rejection_reasons.append(
                        "behavior_policy_receipt_archive_entry_event_missing"
                    )
                _receipt_cost_provenance = _behavior_receipt.get("cost_provenance")
                _receipt_cost_payload = (
                    _receipt_cost_provenance.get("source_payload")
                    if isinstance(_receipt_cost_provenance, Mapping)
                    else None
                )
                _receipt_fee_identity = (
                    _receipt_cost_payload.get("fee_schedule_evidence_sha256")
                    if isinstance(_receipt_cost_payload, Mapping)
                    else None
                )
                _entry_archive_binding = _archive_lifecycle.get("event_bindings", {}).get(
                    EVENT_ENTRY_ACCEPTED,
                    {},
                )
                if (
                    not isinstance(_entry_archive_binding, Mapping)
                    or _entry_archive_binding.get("entry_fee_schedule_evidence_sha256")
                    != _receipt_fee_identity
                ):
                    _receipt_rejection_reasons.append(
                        "behavior_policy_fee_schedule_identity_lifecycle_mismatch"
                    )
                feedback_row.update(
                    {
                        "behavior_policy_receipt_archive_verified": True,
                        "behavior_policy_receipt_archive_content_sha256": (
                            _archive_verification["archive_content_sha256"]
                        ),
                        "behavior_policy_receipt_archive_lifecycle_status": (_archive_lifecycle),
                    }
                )
            except BehaviorReceiptArchiveError as exc:
                _receipt_rejection_reasons.append(
                    "behavior_policy_receipt_archive_invalid:" + str(exc)
                )
                feedback_row["behavior_policy_receipt_archive_verified"] = False
        if _on_policy_action_receipt_valid is not True:
            _receipt_rejection_reasons.append("behavior_policy_receipt_not_validated_at_entry")
        if (
            _first_present(
                close_event.get("on_policy_sampling_selected"),
                outcome.get("on_policy_sampling_selected"),
            )
            is not True
        ):
            _receipt_rejection_reasons.append("adaptive_on_policy_sampling_lane_not_selected")
        if _strategy_supply_hypothesis is True:
            _receipt_rejection_reasons.append("strategy_supply_action_not_sampled_from_cuda_policy")
        _receipt_rejection_reasons = sorted(set(_receipt_rejection_reasons))
        if _behavior_sampling_mode:
            feedback_row["behavior_policy_sampling_mode"] = _behavior_sampling_mode
        if _behavior_distribution_contract:
            feedback_row["behavior_policy_distribution_contract"] = _behavior_distribution_contract
        _on_policy_value = _coerce_float(
            _first_present(
                close_event.get("old_value"),
                outcome.get("old_value"),
            )
        )
        _on_policy_rollout_id = _first_present(
            close_event.get("rollout_id"),
            outcome.get("rollout_id"),
        )
        _on_policy_trajectory_index = _coerce_float(
            _first_present(
                close_event.get("trajectory_index"),
                outcome.get("trajectory_index"),
            )
        )
        _on_policy_reward = _coerce_float(
            _first_present(
                feedback_row.get("realized_after_cost_reward"),
                outcome.get("realized_after_cost_reward"),
                close_event.get("realized_after_cost_reward"),
            )
        )
        if _on_policy_reward is None:
            _outcome_targets = feedback_row.get("outcome_targets")
            if not isinstance(_outcome_targets, Mapping):
                _outcome_targets = {}
            _realized_net_pnl_bps = _coerce_float(
                _first_present(
                    feedback_row.get("realized_net_pnl_bps"),
                    outcome.get("realized_net_pnl_bps"),
                    close_event.get("realized_net_pnl_bps"),
                    _outcome_targets.get("realized_net_pnl_bps"),
                )
            )
            if _realized_net_pnl_bps is not None:
                _on_policy_reward = _realized_net_pnl_bps / 100.0
                feedback_row.setdefault(
                    "realized_after_cost_reward",
                    _on_policy_reward,
                )
                feedback_row.setdefault(
                    "realized_reward_source",
                    "realized_net_pnl_bps_after_cost",
                )
        for _behavior_field in BEHAVIOR_POLICY_LINEAGE_FIELDS:
            _behavior_value = _first_present(
                close_event.get(_behavior_field),
                outcome.get(_behavior_field),
            )
            if _behavior_value not in (None, ""):
                feedback_row[_behavior_field] = deepcopy(_behavior_value)
        _receipt_selected_probability = (
            _coerce_float(_behavior_receipt.get("selected_action_probability"))
            if isinstance(_behavior_receipt, Mapping)
            else None
        )
        _receipt_log_probability = (
            _coerce_float(_behavior_receipt.get("selected_action_log_prob"))
            if isinstance(_behavior_receipt, Mapping)
            else None
        )
        _receipt_policy_value = (
            _coerce_float(_behavior_receipt.get("policy_value"))
            if isinstance(_behavior_receipt, Mapping)
            else None
        )
        for _field, _observed, _expected in (
            (
                "selected_probability",
                _on_policy_selected_probability,
                _receipt_selected_probability,
            ),
            ("old_log_probability", _on_policy_log_prob, _receipt_log_probability),
            ("old_policy_value", _on_policy_value, _receipt_policy_value),
        ):
            if (
                _observed is None
                or _expected is None
                or not math.isclose(
                    _observed,
                    _expected,
                    rel_tol=1e-12,
                    abs_tol=1e-12,
                )
            ):
                _receipt_rejection_reasons.append(f"behavior_policy_receipt_{_field}_mismatch")
        if (
            _on_policy_trajectory_index is None
            or not _on_policy_trajectory_index.is_integer()
            or _on_policy_trajectory_index < 0.0
        ):
            _receipt_rejection_reasons.append("behavior_policy_entry_trajectory_index_invalid")
        if (
            _first_present(
                close_event.get("ppo_on_policy_entry_fields_present"),
                outcome.get("ppo_on_policy_entry_fields_present"),
            )
            is not True
        ):
            _receipt_rejection_reasons.append("behavior_policy_entry_fields_not_prevalidated")
        _finalized_outcome_binding: dict[str, Any] | None = None
        if (
            _behavior_sampling_mode == "CATEGORICAL_SAMPLE"
            and _behavior_distribution_contract == ON_POLICY_DISTRIBUTION_CONTRACT
            and isinstance(_behavior_receipt, Mapping)
        ):
            try:
                _finalized_outcome_binding = build_finalized_outcome_binding(feedback_row)
                feedback_row.update(_finalized_outcome_binding)
                feedback_row["ppo_consumption_update_key"] = build_ppo_consumption_update_key(
                    behavior_policy_receipt_hash=_behavior_receipt_hash,
                    finalized_outcome_digest=_finalized_outcome_binding["finalized_outcome_digest"],
                    parent_behavior_fingerprint=_behavior_policy_fingerprint,
                )
                feedback_row["ppo_consumption_ledger_eligible"] = True
                _bound_reward = _coerce_float(
                    _finalized_outcome_binding["finalized_outcome_reward"]
                )
                if (
                    _on_policy_reward is None
                    or _bound_reward is None
                    or not math.isclose(
                        _on_policy_reward,
                        _bound_reward,
                        rel_tol=1e-12,
                        abs_tol=1e-12,
                    )
                ):
                    _receipt_rejection_reasons.append("finalized_outcome_reward_binding_mismatch")
            except (TypeError, ValueError) as exc:
                _receipt_rejection_reasons.append(str(exc))
        if (
            _finalized_outcome_binding is not None
            and isinstance(_behavior_receipt, Mapping)
            and not _receipt_rejection_reasons
        ):
            try:
                _outcome_event = append_behavior_receipt_lifecycle_event(
                    receipt_hash=str(_behavior_receipt_hash or ""),
                    event_type=EVENT_OUTCOME_FINALIZED,
                    binding={
                        "finalized_outcome_id": _finalized_outcome_binding["finalized_outcome_id"],
                        "finalized_outcome_digest": _finalized_outcome_binding[
                            "finalized_outcome_digest"
                        ],
                        "ppo_consumption_update_key": feedback_row["ppo_consumption_update_key"],
                        "outcome_available_at": _finalized_outcome_binding[
                            "finalized_outcome_digest_material"
                        ]["outcome_available_at"],
                    },
                    root=behavior_receipt_archive_root,
                    recorded_at=str(
                        _first_present(
                            feedback_row.get("outcome_available_at"),
                            feedback_row.get("outcome_generated_at"),
                        )
                        or ""
                    ),
                )
                feedback_row.update(
                    {
                        "behavior_policy_receipt_archive_finalized": True,
                        "behavior_policy_receipt_archive_finalization_event_hash": (
                            _outcome_event.event_hash
                        ),
                        "behavior_policy_receipt_archive_retention_required_until_trainer_consumption": True,
                    }
                )
            except BehaviorReceiptArchiveError as exc:
                _receipt_rejection_reasons.append(
                    "behavior_policy_receipt_archive_finalization_failed:" + str(exc)
                )
                feedback_row["behavior_policy_receipt_archive_finalized"] = False
        _receipt_rejection_reasons = sorted(set(_receipt_rejection_reasons))
        feedback_row["ppo_on_policy_receipt_rejection_reasons"] = list(_receipt_rejection_reasons)
        _exact_on_policy_sample = (
            _behavior_sampling_mode == "CATEGORICAL_SAMPLE"
            and _behavior_distribution_contract == ON_POLICY_DISTRIBUTION_CONTRACT
            and not _receipt_rejection_reasons
        )
        if (
            _on_policy_log_prob is not None
            and _on_policy_value is not None
            and _on_policy_rollout_id
            and _on_policy_reward is not None
            and _on_policy_trajectory_index is not None
            and _finalized_outcome_binding is not None
            and _exact_on_policy_sample
        ):
            feedback_row["selected_action_log_prob"] = _on_policy_log_prob
            feedback_row["old_log_prob"] = _on_policy_log_prob
            feedback_row["old_value"] = _on_policy_value
            feedback_row["reward"] = _finalized_outcome_binding["finalized_outcome_reward"]
            feedback_row["done"] = True
            feedback_row["rollout_id"] = str(_on_policy_rollout_id)
            feedback_row["trajectory_index"] = int(_on_policy_trajectory_index)
            feedback_row["ppo_on_policy_entry_fields_present"] = True
            feedback_row["paper_learning_lane"] = "PPO_ON_POLICY_PAPER_EXPLORATION"
            feedback_row["entry_policy_fields_source"] = _first_present(
                close_event.get("entry_policy_fields_source"),
                outcome.get("entry_policy_fields_source"),
            )
        else:
            feedback_row["ppo_on_policy_entry_fields_present"] = False
            inherited_reason = _first_present(
                close_event.get("ppo_on_policy_ineligible_reason"),
                outcome.get("ppo_on_policy_ineligible_reason"),
            )
            if inherited_reason not in (None, ""):
                ppo_ineligible_reason = str(inherited_reason)
            elif (
                _behavior_sampling_mode == "DETERMINISTIC_ARGMAX_ALIGNMENT"
                or _behavior_distribution_contract == "EXPECTED_MOVE_ALIGNED_POLICY_V1"
            ):
                ppo_ineligible_reason = "DETERMINISTIC_POLICY_NOT_ON_POLICY_SAMPLED"
            elif _receipt_rejection_reasons:
                ppo_ineligible_reason = "BEHAVIOR_POLICY_RECEIPT_INVALID"
            elif (
                _on_policy_log_prob is not None
                and _on_policy_value is not None
                and _on_policy_rollout_id
                and _on_policy_reward is not None
            ):
                ppo_ineligible_reason = "BEHAVIOR_POLICY_SAMPLING_OR_DISTRIBUTION_PROOF_MISSING"
            else:
                ppo_ineligible_reason = "PPO_ON_POLICY_INELIGIBLE_MISSING_ENTRY_POLICY_FIELDS"
            feedback_row["ppo_on_policy_ineligible_reason"] = ppo_ineligible_reason
            feedback_row["paper_learning_lane"] = (
                "STRATEGY_SUPPLY_HYPOTHESIS_PAPER"
                if _first_present(
                    close_event.get("strategy_supply_hypothesis"),
                    outcome.get("strategy_supply_hypothesis"),
                )
                is True
                else "OUTCOME_SUPERVISED_PAPER"
            )
        rows.append(feedback_row)
    return rows


def _with_paper_session_metadata(
    row: dict[str, Any],
    *,
    paper_session_id: str | None,
    starting_equity_usd: float | None,
) -> dict[str, Any]:
    enriched = dict(row)
    if paper_session_id:
        enriched.setdefault("paper_session_id", paper_session_id)
        enriched.setdefault("session_id", paper_session_id)
        enriched.setdefault("reset_session_id", paper_session_id)
    if starting_equity_usd is not None:
        enriched.setdefault("starting_equity_usd", starting_equity_usd)
    enriched.setdefault("paper_only", True)
    enriched.setdefault("routes_to_live", False)
    enriched.setdefault("places_real_order", False)
    return enriched


def _with_paper_session_metadata_rows(
    rows: list[dict[str, Any]],
    *,
    paper_session_id: str | None,
    starting_equity_usd: float | None,
) -> list[dict[str, Any]]:
    return [
        _with_paper_session_metadata(
            row,
            paper_session_id=paper_session_id,
            starting_equity_usd=starting_equity_usd,
        )
        for row in rows
        if isinstance(row, dict)
    ]


def _read_active_paper_provisional_cohort(r: Any) -> dict[str, Any] | None:
    """Resolve the fresh provisional cohort identity (Phase 5-6), or None.

    Read order: PAPER_PROVISIONAL_ACTIVE_COHORT_ID env override, then the shared
    Redis activation record (``v2:paper:provisional_cohort_activation``). The
    activation is frozen once at cohort activation so the cohort id is STABLE.
    Returns None when no fresh cohort is active — ordinary/historical intents then
    keep the unchanged global breaker (the July losing cohort stays HALTED).
    """
    env_cohort = str(os.environ.get("PAPER_PROVISIONAL_ACTIVE_COHORT_ID") or "").strip()
    if env_cohort:
        return {"paper_strategy_cohort_id": env_cohort}
    if r is None:
        return None
    try:
        raw = r.get(f"{V2_REDIS_PREFIX}paper:provisional_cohort_activation")
    except Exception:
        return None
    if not raw:
        return None
    try:
        rec = json.loads(raw)
    except Exception:
        return None
    if not isinstance(rec, dict):
        return None
    cohort_id = str(rec.get("paper_strategy_cohort_id") or "").strip()
    if not cohort_id:
        return None
    return rec


def _stamp_paper_cohort_metadata(
    row: dict[str, Any],
    cohort: Mapping[str, Any] | None,
) -> dict[str, Any]:
    """Stamp the fresh provisional cohort identity onto a provisional-cohort row.

    Idempotent and non-relabeling: if the row already carries a DIFFERENT
    ``paper_strategy_cohort_id`` it is returned unchanged (history is never
    relabeled — the historical losing cohort keeps its own id and its global
    HALTED_PERFORMANCE breaker). When ``cohort`` is None the row is unchanged.
    """
    if not isinstance(row, dict) or not isinstance(cohort, Mapping):
        return row
    cohort_id = str(cohort.get("paper_strategy_cohort_id") or "").strip()
    if not cohort_id:
        return row
    existing = str(row.get("paper_strategy_cohort_id") or "").strip()
    if existing and existing != cohort_id:
        return row
    enriched = dict(row)
    enriched["paper_strategy_cohort_id"] = cohort_id
    if cohort.get("checkpoint_id"):
        enriched.setdefault("paper_cohort_checkpoint_id", str(cohort.get("checkpoint_id")))
    if cohort.get("paper_cohort_activation_utc"):
        enriched.setdefault(
            "paper_cohort_activation_utc", str(cohort.get("paper_cohort_activation_utc"))
        )
    if cohort.get("paper_cohort_initial_equity_usd") is not None:
        enriched.setdefault(
            "paper_cohort_initial_equity_usd",
            _coerce_float(cohort.get("paper_cohort_initial_equity_usd")),
        )
    enriched.setdefault("paper_only", True)
    enriched.setdefault("routes_to_live", False)
    enriched.setdefault("places_real_order", False)
    enriched.setdefault("live_eligible", False)
    return enriched


