def _paper_exploration_apply_decision_label_fallbacks(row: dict[str, Any]) -> None:
    for decision_field, decision_id_field in (
        ("risk_decision", "risk_decision_id"),
        ("orchestrator_decision", "orchestrator_decision_id"),
        ("allocator_decision", "allocator_decision_id"),
    ):
        if row.get(decision_field) in (None, "") and row.get(decision_id_field) not in (
            None,
            "",
        ):
            row[decision_field] = "PASS"


def _paper_exploration_queue_runtime_feedback_context(
    queue_row: Mapping[str, Any],
    runtime_rows: list[dict[str, Any]],
) -> dict[str, Any]:
    queue_signal = _paper_exploration_queue_signal(queue_row)
    preserve_source_loss_probability = _paper_exploration_should_preserve_source_loss_probability(
        queue_signal
    )
    for runtime_row in runtime_rows:
        if not _paper_exploration_queue_runtime_row_revalidates(
            queue_row,
            runtime_row,
        ):
            continue
        context = {
            field: runtime_row.get(field)
            for field in _PAPER_EXPLORATION_RUNTIME_FEEDBACK_CONTEXT_FIELDS
            if runtime_row.get(field) not in (None, "", [], {})
        }
        if preserve_source_loss_probability:
            runtime_loss_probability = context.pop("pre_trade_loss_probability", None)
            for source_field in (
                "pre_trade_loss_probability_source",
                "loss_probability_reason",
                "loss_probability_reasons",
                "loss_probability_calibration",
            ):
                context.pop(source_field, None)
            if runtime_loss_probability not in (None, "", [], {}) and context.get(
                "runtime_revalidated_pre_trade_loss_probability"
            ) in (None, "", [], {}):
                context["runtime_revalidated_pre_trade_loss_probability"] = runtime_loss_probability
                context["runtime_revalidated_loss_probability_source"] = (
                    "paper_loop_runtime_matching_row"
                )
            for runtime_field, source_field in (
                ("runtime_revalidated_preemptive_decision", "preemptive_decision"),
                ("runtime_revalidated_preemptive_decision_id", "preemptive_decision_id"),
                (
                    "runtime_revalidated_preemptive_decision_reasons",
                    "preemptive_decision_reasons",
                ),
            ):
                if context.get(runtime_field) not in (None, "", [], {}):
                    continue
                value = runtime_row.get(source_field)
                if value not in (None, "", [], {}):
                    context[runtime_field] = value
        return context
    return {}


def _paper_exploration_remaining_queue_after_resolution(
    *,
    active_queue_rows: list[dict[str, Any]],
    active_queue_signals: list[dict[str, Any]],
    resolved_queue_ids: set[str],
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    remaining_active_queue_rows = [
        row for row in active_queue_rows if str(row.get("queue_id") or "") not in resolved_queue_ids
    ]
    remaining_active_queue_signals = [
        row
        for row in active_queue_signals
        if str(row.get("materialization_queue_id") or "") not in resolved_queue_ids
    ]
    return remaining_active_queue_rows, remaining_active_queue_signals


def _paper_exploration_queue_payload_after_resolution(
    *,
    remaining_active_queue_rows: list[dict[str, Any]],
    pending_source_queue_rows: list[dict[str, Any]],
    resolved_queue_ids: set[str],
    generated_utc: str,
) -> dict[str, Any]:
    return {
        "schema_version": "paper_exploration_materialization_queue_v1",
        "generated_utc": generated_utc,
        "rows": [
            *remaining_active_queue_rows,
            *pending_source_queue_rows,
        ],
        "pending_source_rows": pending_source_queue_rows,
        "resolved_after_queue_ids": sorted(resolved_queue_ids),
        "paper_only": True,
        "routes_to_live": False,
        "places_real_order": False,
    }


def _paper_exploration_materialized_queue_ids_from_rows(
    rows: list[dict[str, Any]],
) -> set[str]:
    queue_ids: set[str] = set()
    for row in rows:
        if not isinstance(row, Mapping):
            continue
        queue_id = str(row.get("materialization_queue_id") or "")
        if not queue_id:
            continue
        tier = str(row.get("paper_opportunity_tier") or "").strip().upper()
        if tier != PAPER_TIER_RISK_CONTROLLER_EXPLORATION:
            continue
        unsafe_truthy_fields = (
            "routes_to_live",
            "places_real_order",
            "live_order",
            "test_order",
            "order_submitted",
            "test_order_submitted",
            "leverage_mutated",
            "margin_mutated",
            "counts_as_A_plus",
            "counts_as_final_A_plus",
            "counts_as_final_a_plus",
            "counts_as_live_ready",
        )
        if row.get("paper_only") is not True:
            continue
        if any(row.get(field) is True for field in unsafe_truthy_fields):
            continue
        queue_ids.add(queue_id)
    return queue_ids


def _paper_exploration_current_cycle_materialized_queue_ids(
    *,
    open_position_rows: list[dict[str, Any]],
    current_accepted_rows: list[dict[str, Any]],
    current_queue_accepted_ids: set[str],
) -> set[str]:
    """Return materialized exploration queue IDs accepted in this cycle only."""

    current_ids = {str(queue_id) for queue_id in current_queue_accepted_ids if queue_id}
    if not current_ids:
        return set()
    materialized_ids = _paper_exploration_materialized_queue_ids_from_rows(
        open_position_rows
    ) | _paper_exploration_materialized_queue_ids_from_rows(current_accepted_rows)
    return materialized_ids & current_ids


_PAPER_EXPLORATION_POSITIVE_EVIDENCE_REASON_TOKENS = (
    "A_PLUS_GATE:ALLOCATOR_ALLOWS",
    "A_PLUS_GATE:EXIT_PLAN_VALID",
    "A_PLUS_GATE:HTF_ALIGNED",
    "A_PLUS_GATE:MICROSTRUCTURE_TRUST_CONFIRMS",
    "A_PLUS_GATE:NO_QUARANTINE_BUCKET",
    "A_PLUS_GATE:REGIME_ALIGNED",
    "A_PLUS_GATE:TRADE_TAPE_CONFIRMS",
)


def _paper_exploration_negative_reasons_for_classification(
    reasons: list[str],
) -> list[str]:
    negative_reasons: list[str] = []
    for reason in reasons:
        upper = str(reason).upper()
        if any(token in upper for token in _PAPER_EXPLORATION_POSITIVE_EVIDENCE_REASON_TOKENS):
            continue
        negative_reasons.append(upper)
    return negative_reasons


def _paper_exploration_queue_policy_revalidation_reasons(
    row: Mapping[str, Any],
) -> list[str]:
    if row.get("paper_risk_controller_exploration_above_floor") is True:
        return []
    confidence = _coerce_float(row.get("confidence_executable_trade"))
    floor = _coerce_float(row.get("dynamic_exploration_floor"))
    if confidence is not None and floor is not None and confidence < floor:
        return [
            (
                "EXPLORATION_POLICY_REVALIDATION:"
                f"CONFIDENCE_BELOW_DYNAMIC_FLOOR:{confidence:.6f}<{floor:.6f}"
            )
        ]
    return ["EXPLORATION_POLICY_REVALIDATION:NOT_ABOVE_DYNAMIC_FLOOR"]


def _materialization_queue_policy_snapshot(
    *,
    signal: Mapping[str, Any],
    intent: Mapping[str, Any],
) -> dict[str, Any] | None:
    queue_id = _first_present(
        signal.get("materialization_queue_id"),
        signal.get("queue_id"),
        intent.get("materialization_queue_id"),
        intent.get("queue_id"),
    )
    if queue_id in (None, ""):
        return None
    above_floor = _first_present(
        signal.get("paper_risk_controller_exploration_above_floor"),
        intent.get("paper_risk_controller_exploration_above_floor"),
    )
    if above_floor is not True:
        return None
    confidence = _coerce_float(
        _first_present(
            signal.get("confidence_executable_trade"),
            intent.get("confidence_executable_trade"),
        )
    )
    floor = _coerce_float(
        _first_present(
            signal.get("dynamic_exploration_floor"),
            intent.get("dynamic_exploration_floor"),
        )
    )
    if confidence is not None and floor is not None and confidence < floor:
        return None
    return {
        "materialization_queue_id": str(queue_id),
        "confidence_executable_trade": confidence,
        "dynamic_exploration_floor": floor,
        "dynamic_exploration_floor_formula": _first_present(
            signal.get("dynamic_exploration_floor_formula"),
            intent.get("dynamic_exploration_floor_formula"),
        ),
        "exploration_floor_inputs": _first_present(
            signal.get("exploration_floor_inputs"),
            intent.get("exploration_floor_inputs"),
        ),
        "exploration_floor_range": _first_present(
            signal.get("exploration_floor_range"),
            intent.get("exploration_floor_range"),
        ),
    }


def _apply_materialization_queue_policy_snapshot_if_safe(
    *,
    policy: dict[str, Any],
    policy_row: Mapping[str, Any],
    snapshot: Mapping[str, Any] | None,
) -> dict[str, Any]:
    if not snapshot:
        return policy
    blockers = list(policy.get("eligibility_block_reasons") or [])
    if not blockers:
        return policy
    residual_blockers = list(blockers)
    confidence_floor_blockers = {
        "CONFIDENCE_EXECUTABLE_TRADE_BELOW_DYNAMIC_EXPLORATION_FLOOR",
        # Same untrained-model confidence signal expressed via the allocator
        # (kept in sync with paper_exploration.policy.BOOTSTRAP_OVERRIDABLE_BLOCKERS).
        "ALLOCATOR_HARD_BLOCK:BLOCK_LOW_CONFIDENCE",
    }
    residual_blockers = [
        blocker for blocker in residual_blockers if blocker not in confidence_floor_blockers
    ]
    if (
        "LOSS_CLUSTER_OR_QUARANTINE_ACTIVE" in residual_blockers
        and _paper_risk_exploration_advisory_only_quarantine_context(policy_row)
    ):
        residual_blockers = [
            blocker
            for blocker in residual_blockers
            if blocker != "LOSS_CLUSTER_OR_QUARANTINE_ACTIVE"
        ]
    if residual_blockers:
        return {
            **policy,
            "materialization_queue_policy_snapshot_retained": False,
            "materialization_queue_policy_snapshot_residual_blockers": residual_blockers,
        }
    retained = dict(policy)
    retained["runtime_recomputed_dynamic_exploration_floor"] = policy.get(
        "dynamic_exploration_floor"
    )
    retained["runtime_recomputed_above_dynamic_floor"] = policy.get("above_dynamic_floor")
    retained["runtime_recomputed_eligibility_block_reasons"] = blockers
    if snapshot.get("dynamic_exploration_floor") is not None:
        retained["dynamic_exploration_floor"] = snapshot.get("dynamic_exploration_floor")
    if snapshot.get("dynamic_exploration_floor_formula") not in (None, ""):
        retained["dynamic_exploration_floor_formula"] = snapshot.get(
            "dynamic_exploration_floor_formula"
        )
    if snapshot.get("exploration_floor_inputs") not in (None, "", [], {}):
        retained["floor_inputs"] = snapshot.get("exploration_floor_inputs")
    if snapshot.get("exploration_floor_range") not in (None, "", [], {}):
        retained["floor_range"] = snapshot.get("exploration_floor_range")
    retained["eligible"] = True
    retained["above_dynamic_floor"] = True
    retained["materialization_queue_policy_snapshot_retained"] = True
    retained["materialization_queue_policy_snapshot_retained_reason"] = (
        "ACCEPTED_QUEUE_POLICY_SNAPSHOT_RETAINED_NO_HARD_REVALIDATION_BLOCK"
    )
    retained["materialization_queue_id"] = snapshot.get("materialization_queue_id")
    retained["eligibility_block_reasons"] = []
    retained["eligibility_reasons"] = sorted(
        set(
            list(policy.get("eligibility_reasons") or [])
            + ["MATERIALIZATION_QUEUE_ACCEPTED_POLICY_SNAPSHOT_RETAINED"]
        )
    )
    return retained


def _apply_materialization_queue_fill_gate_snapshot_if_safe(
    *,
    fill_gate: dict[str, Any],
    policy_row: Mapping[str, Any],
    policy: Mapping[str, Any],
) -> dict[str, Any]:
    if policy.get("materialization_queue_policy_snapshot_retained") is not True:
        return fill_gate
    blockers = list(fill_gate.get("paper_fill_block_reasons") or [])
    if not blockers:
        return fill_gate
    residual_blockers = [
        blocker
        for blocker in blockers
        if blocker
        not in (
            "CONFIDENCE_EXECUTABLE_TRADE_BELOW_DYNAMIC_EXPLORATION_FLOOR",
            "ALLOCATOR_HARD_BLOCK:BLOCK_LOW_CONFIDENCE",
        )
    ]
    if (
        "LOSS_CLUSTER_OR_QUARANTINE_ACTIVE" in residual_blockers
        and _paper_risk_exploration_advisory_only_quarantine_context(policy_row)
    ):
        residual_blockers = [
            blocker
            for blocker in residual_blockers
            if blocker != "LOSS_CLUSTER_OR_QUARANTINE_ACTIVE"
        ]
    if residual_blockers == blockers:
        return fill_gate
    updated = dict(fill_gate)
    updated["runtime_recomputed_paper_fill_block_reasons"] = blockers
    updated["paper_fill_block_reasons"] = sorted(set(residual_blockers))
    updated["paper_fill_allowed"] = not residual_blockers
    updated["materialization_queue_policy_snapshot_retained"] = True
    return updated


def _paper_exploration_queue_no_fill_reason(reasons: list[str]) -> str:
    upper_reasons = _paper_exploration_negative_reasons_for_classification(reasons)
    reason_text = " ".join(upper_reasons)
    if (
        "LIFECYCLE_OR_NO_TRADE_STRATEGY_NOT_ENTRY_EVIDENCE" in reason_text
        or "NO_TRADE_ENTRY_EVIDENCE:" in reason_text
    ):
        return "TRUE_ENTRY_GATE_BLOCK_AFTER_QUEUE_CONSUMPTION"
    if (
        "PAPER_FILL_WRITE_INVARIANT_BLOCKED" in reason_text
        or "MISSING_PRODUCTION_GRADE_COST_FLAG" in reason_text
        or "FALLBACK_COST_NOT_ALLOWED" in reason_text
    ):
        return "TRUE_PAPER_FILL_WRITE_INVARIANT_BLOCK_AFTER_QUEUE_CONSUMPTION"
    if any(
        token in reason_text
        for token in (
            "ENTRY_FEATURE",
            "MISSING_EXPLICIT_FUNDING",
            "CANDLE",
            "ORDERBOOK",
            "KLINE",
            "VALID_FOR_PAPER_NOT_TRUE",
            "HARD_MARKET_INTEGRITY",
            "MISSING_MARKET_DEPTH",
            "MICROSTRUCTURE_TRUST_MISSING",
            "MISSING_SOURCED_SQUEEZE",
            "MISSING_V2_MARKET_PRICE",
            "PRICE_MISSING",
            "PRICE_STALE",
            "MARK_PRICE_MISSING",
            "CURRENT_PRICE_MISSING",
            "CURRENT_PRICE_STALE",
            "SPREAD_MISSING",
            "SPREAD_STALE",
            "SLIPPAGE_MISSING",
            "SLIPPAGE_STALE",
        )
    ):
        return "MARKET_INTEGRITY_BLOCKED_AFTER_QUEUE_CONSUMPTION"
    if (
        "LOSS_CLUSTER_SYMBOL:" in reason_text
        or "LOSS_CLUSTER_STRATEGY" in reason_text
        or "LOSS_CLUSTER_SIDE_TIMEFRAME" in reason_text
    ):
        return "TRUE_BUCKET_SPECIFIC_LOSS_CLUSTER_AFTER_QUEUE_CONSUMPTION"
    if "PAPER_BUCKET_QUARANTINE_BLOCKED_REENTRY" in reason_text:
        return "TRUE_BUCKET_SPECIFIC_QUARANTINE_AFTER_QUEUE_CONSUMPTION"
    if (
        "PAPER_BUCKET_QUARANTINE_BLOCKED_REENTRY" in reason_text
        or "PAPER_HIGH_CONFIDENCE_LOSS_CLUSTER_BLOCKED_REENTRY" in reason_text
        or "LOSS_CLUSTER" in reason_text
    ):
        return "TRUE_LOSS_CLUSTER_OR_QUARANTINE_AFTER_QUEUE_CONSUMPTION"
    if "ENTRY_GATE:" in reason_text or "P0_ENTRY_GATE_BLOCKED" in reason_text:
        if "SYMBOL_EXPLICITLY_EXCLUDED_BY_OPERATOR" in reason_text:
            return "TRUE_ENTRY_GATE_SYMBOL_EXCLUDED_AFTER_QUEUE_CONSUMPTION"
        if "EXPECTED_MOVE_NOT_FAVORABLE_FOR_SIDE" in reason_text:
            return "TRUE_ENTRY_GATE_EXPECTED_MOVE_NOT_FAVORABLE_AFTER_QUEUE_CONSUMPTION"
        return "TRUE_ENTRY_GATE_BLOCK_AFTER_QUEUE_CONSUMPTION"
    if any(
        token in reason_text
        for token in (
            "EXPECTED_EDGE_AFTER_COST_NON_POSITIVE",
            "EXPECTED_EDGE_NON_POSITIVE",
            "EXPECTED_MOVE_DOES_NOT_COVER_COST",
            "FVG_CONFLUENCE_WITHOUT_POSITIVE_AFTER_COST_EDGE",
        )
    ):
        return "TRUE_ENTRY_GATE_EXPECTED_MOVE_NOT_FAVORABLE_AFTER_QUEUE_CONSUMPTION"
    if any(
        token in reason_text
        for token in (
            "EXIT_FEASIBILITY_LOW",
            "FVG_CONFLUENCE_WITHOUT_VALID_EXIT_FEASIBILITY",
            "MFE_REQUIRED_UNREALISTIC_FOR_STOP_RISK",
        )
    ):
        return "TRUE_ENTRY_GATE_BLOCK_AFTER_QUEUE_CONSUMPTION"
    if (
        "ALLOCATOR_DECISION_NOT_EXPLORATION_FILL_ELIGIBLE" in reason_text
        or "BLOCK_INSUFFICIENT_LIQUIDITY" in reason_text
        or "ALLOCATOR" in reason_text
    ):
        return "TRUE_ALLOCATOR_BLOCK_AFTER_QUEUE_CONSUMPTION"
    if "PAPER_TIER:NON_EXECUTABLE_PAPER_TIER" in reason_text:
        return "NON_EXECUTABLE_PAPER_TIER_AFTER_QUEUE_CONSUMPTION"
    if "PAPER_LOSS_BUCKET_QUARANTINE" in reason_text:
        return "STRATEGY_ROUTER_BLOCKED_AFTER_QUEUE_CONSUMPTION"
    if "BUCKET_QUARANTINE_MATCH" in reason_text:
        return "PAPER_PERFORMANCE_CIRCUIT_BREAKER_BLOCKED_AFTER_QUEUE_CONSUMPTION"
    if any(
        token in reason_text
        for token in (
            "HIGH_CONFIDENCE_LOSS_RATE",
            "LOSS_RATE_FORMING",
            "ATR_STOP_RISK_FORMING",
            "BUCKET_PF_OR_EXPECTANCY_NEGATIVE",
        )
    ):
        return "PAPER_PERFORMANCE_CIRCUIT_BREAKER_BLOCKED_AFTER_QUEUE_CONSUMPTION"
    if any("PAPER_PERFORMANCE_CIRCUIT_BREAKER" in reason for reason in upper_reasons):
        return "PAPER_PERFORMANCE_CIRCUIT_BREAKER_BLOCKED_AFTER_QUEUE_CONSUMPTION"
    if any(
        token in reason_text
        for token in (
            "FVG_CONFLUENCE_WITHOUT_SUFFICIENT_MICROSTRUCTURE_TRUST",
            "FVG_CONFLUENCE_WITHOUT_TRADE_TAPE_CONFIRMATION",
            "REDUCED_BY_MICROSTRUCTURE_TRUST_GATE",
            "MICROSTRUCTURE_TRUST_LOW",
            "MICROSTRUCTURE_ACTION_NO_TRADE",
            "MICROSTRUCTURE_ACTION_SHADOW_ONLY",
            "MICROSTRUCTURE_ACTION_CLOSE_OR_REDUCE_ONLY",
            "BLOCKED_MICROSTRUCTURE_ACTION",
        )
    ):
        return "TRUE_TRUST_UNSAFE_AFTER_QUEUE_CONSUMPTION"
    if "EXPLORATION_POLICY_REVALIDATION" in reason_text:
        return "EXPLORATION_POLICY_REVALIDATION_BLOCK_AFTER_QUEUE_CONSUMPTION"
    if "RISK" in reason_text:
        return "TRUE_RISK_BLOCK_AFTER_QUEUE_CONSUMPTION"
    if "ORCHESTRATOR" in reason_text:
        return "TRUE_ORCHESTRATOR_BLOCK_AFTER_QUEUE_CONSUMPTION"
    if "ALLOCATOR" in reason_text:
        return "TRUE_ALLOCATOR_BLOCK_AFTER_QUEUE_CONSUMPTION"
    if "QUARANTINE" in reason_text or "LOSS_CLUSTER" in reason_text:
        return "ACTIVE_BUCKET_QUARANTINE_AFTER_QUEUE_CONSUMPTION"
    if "STRATEGY_ROUTER:" in reason_text:
        return "STRATEGY_ROUTER_BLOCKED_AFTER_QUEUE_CONSUMPTION"
    if "TEMPORAL" in reason_text or "SOURCE_PREDICTION_NOT_CURRENT" in reason_text:
        return "TEMPORAL_INTEGRITY_BLOCKED_AFTER_QUEUE_CONSUMPTION"
    return "PAPER_QUEUE_REJECTED_WITHOUT_MATCHED_RUNTIME_REASON"


def _paper_exploration_exact_no_fill_reason(
    rejected_after_queue_reason_counts: Mapping[str, int],
) -> tuple[str | None, list[str]]:
    reasons = sorted(
        str(reason) for reason, count in rejected_after_queue_reason_counts.items() if count
    )
    if not reasons:
        return None, []
    if len(reasons) == 1:
        only_reason = reasons[0]
        if only_reason == "MARKET_INTEGRITY_BLOCKED_AFTER_QUEUE_CONSUMPTION":
            return "ALL_CURRENT_ROWS_MARKET_INTEGRITY_BLOCKED", reasons
        if only_reason == "PAPER_PERFORMANCE_CIRCUIT_BREAKER_BLOCKED_AFTER_QUEUE_CONSUMPTION":
            return "ALL_CURRENT_ROWS_PAPER_PERFORMANCE_CIRCUIT_BREAKER_BLOCKED", reasons
        if only_reason in {
            "TRUE_BUCKET_SPECIFIC_LOSS_CLUSTER_AFTER_QUEUE_CONSUMPTION",
            "TRUE_BUCKET_SPECIFIC_QUARANTINE_AFTER_QUEUE_CONSUMPTION",
            "TRUE_LOSS_CLUSTER_OR_QUARANTINE_AFTER_QUEUE_CONSUMPTION",
            "ACTIVE_BUCKET_QUARANTINE_AFTER_QUEUE_CONSUMPTION",
        }:
            return "ALL_CURRENT_ROWS_TRUE_BUCKET_QUARANTINE", reasons
        if only_reason == "TRUE_RISK_BLOCK_AFTER_QUEUE_CONSUMPTION":
            return "ALL_CURRENT_ROWS_TRUE_RISK_BLOCKED", reasons
        if only_reason == "TRUE_ORCHESTRATOR_BLOCK_AFTER_QUEUE_CONSUMPTION":
            return "ALL_CURRENT_ROWS_TRUE_ORCHESTRATOR_BLOCKED", reasons
        if only_reason == "TRUE_ALLOCATOR_BLOCK_AFTER_QUEUE_CONSUMPTION":
            return "ALL_CURRENT_ROWS_TRUE_ALLOCATOR_BLOCKED", reasons
        if only_reason == "TRUE_TRUST_UNSAFE_AFTER_QUEUE_CONSUMPTION":
            return "ALL_CURRENT_ROWS_TRUE_TRUST_UNSAFE", reasons
        if only_reason == "EXPLORATION_POLICY_REVALIDATION_BLOCK_AFTER_QUEUE_CONSUMPTION":
            return "ALL_CURRENT_ROWS_EXPLORATION_POLICY_REVALIDATION_BLOCKED", reasons
        if only_reason == "TRUE_ENTRY_GATE_BLOCK_AFTER_QUEUE_CONSUMPTION":
            return "ALL_CURRENT_ROWS_TRUE_ENTRY_GATE_BLOCKED", reasons
        return only_reason, reasons

    true_no_fill_reasons = {
        "EXPLORATION_POLICY_REVALIDATION_BLOCK_AFTER_QUEUE_CONSUMPTION",
        "MARKET_INTEGRITY_BLOCKED_AFTER_QUEUE_CONSUMPTION",
        "PAPER_PERFORMANCE_CIRCUIT_BREAKER_BLOCKED_AFTER_QUEUE_CONSUMPTION",
        "TRUE_ALLOCATOR_BLOCK_AFTER_QUEUE_CONSUMPTION",
        "TRUE_BUCKET_SPECIFIC_LOSS_CLUSTER_AFTER_QUEUE_CONSUMPTION",
        "TRUE_BUCKET_SPECIFIC_QUARANTINE_AFTER_QUEUE_CONSUMPTION",
        "TRUE_ENTRY_GATE_BLOCK_AFTER_QUEUE_CONSUMPTION",
        "TRUE_ENTRY_GATE_EXPECTED_MOVE_NOT_FAVORABLE_AFTER_QUEUE_CONSUMPTION",
        "TRUE_ENTRY_GATE_SYMBOL_EXCLUDED_AFTER_QUEUE_CONSUMPTION",
        "TRUE_LOSS_CLUSTER_OR_QUARANTINE_AFTER_QUEUE_CONSUMPTION",
        "TRUE_ORCHESTRATOR_BLOCK_AFTER_QUEUE_CONSUMPTION",
        "TRUE_PAPER_FILL_WRITE_INVARIANT_BLOCK_AFTER_QUEUE_CONSUMPTION",
        "TRUE_RISK_BLOCK_AFTER_QUEUE_CONSUMPTION",
        "TRUE_TRUST_UNSAFE_AFTER_QUEUE_CONSUMPTION",
    }
    if all(reason in true_no_fill_reasons for reason in reasons):
        return "MIXED_TRUE_NO_FILL_AFTER_QUEUE_CONSUMPTION", reasons
    return None, reasons


def _paper_exploration_canonical_exact_no_fill_reason(
    reason: Any,
) -> str | None:
    mapping = {
        "ALL_CURRENT_ROWS_MARKET_INTEGRITY_BLOCKED": "ALL_ROWS_MARKET_INTEGRITY_BLOCKED",
        "ALL_CURRENT_ROWS_PAPER_PERFORMANCE_CIRCUIT_BREAKER_BLOCKED": "ALL_ROWS_TRUE_PERFORMANCE_CIRCUIT_BLOCKED",
        "ALL_CURRENT_ROWS_TRUE_BUCKET_QUARANTINE": "ALL_ROWS_TRUE_BUCKET_QUARANTINE",
        "ALL_CURRENT_ROWS_TRUE_RISK_BLOCKED": "ALL_ROWS_TRUE_RISK_BLOCKED",
        "ALL_CURRENT_ROWS_TRUE_ORCHESTRATOR_BLOCKED": "ALL_ROWS_TRUE_ORCHESTRATOR_BLOCKED",
        "ALL_CURRENT_ROWS_TRUE_ALLOCATOR_BLOCKED": "ALL_ROWS_TRUE_ALLOCATOR_BLOCKED",
        "ALL_CURRENT_ROWS_TRUE_TRUST_UNSAFE": "ALL_ROWS_TRUE_TRUST_UNSAFE",
        "ALL_CURRENT_ROWS_EXPLORATION_POLICY_REVALIDATION_BLOCKED": "ALL_ROWS_TRUE_TRUST_UNSAFE",
        "ALL_CURRENT_ROWS_TRUE_ENTRY_GATE_BLOCKED": "ALL_ROWS_TRUE_TRUST_UNSAFE",
        "TRUE_ENTRY_GATE_BLOCKED_PREQUEUE": "ALL_ROWS_TRUE_TRUST_UNSAFE",
        "TRUE_MARKET_INTEGRITY_BLOCKED_PREQUEUE": "ALL_ROWS_MARKET_INTEGRITY_BLOCKED",
    }
    if reason in (None, ""):
        return None
    return mapping.get(str(reason), str(reason))


def _paper_exploration_prequeue_exact_no_fill_reason(
    prequeue_reason_counts: Mapping[str, int],
) -> tuple[str | None, list[str]]:
    raw_reasons = sorted(str(reason) for reason, count in prequeue_reason_counts.items() if count)
    if not raw_reasons:
        return None, []

    classified_reasons: list[str] = []
    for reason in raw_reasons:
        upper = reason.upper()
        if "SELECTED_SIDE_ECONOMICS_CONFLICT" in upper:
            classified_reasons.append("TRUE_SELECTED_SIDE_ECONOMICS_CONFLICT_PREQUEUE")
        elif "EXPECTED_MOVE_NOT_FAVORABLE_FOR_SIDE" in upper:
            classified_reasons.append("TRUE_ENTRY_GATE_EXPECTED_MOVE_NOT_FAVORABLE_PREQUEUE")
        elif (
            "ACTIVE_BUCKET_QUARANTINE" in upper
            or "BUCKET_QUARANTINE" in upper
            or "LOSS_CLUSTER" in upper
            or "QUARANTINE" in upper
        ):
            classified_reasons.append("TRUE_BUCKET_QUARANTINE_PREQUEUE")
        elif "MARKET_INTEGRITY" in upper or any(
            token in upper
            for token in (
                "PRICE",
                "ORDERBOOK",
                "KLINE",
                "SPREAD",
                "SLIPPAGE",
                "MICROSTRUCTURE_TRUST_MISSING",
            )
        ):
            classified_reasons.append("TRUE_MARKET_INTEGRITY_BLOCKED_PREQUEUE")
        elif (
            "SOURCE_TIME_AFTER_ACCEPTED_AT" in upper
            or "SOURCE_STALE" in upper
            or "SOURCE_TIME_MISSING" in upper
            or "ACCEPTED_AT_INVALID" in upper
            or "TEMPORAL" in upper
        ):
            classified_reasons.append("TEMPORAL_INTEGRITY_BLOCKED_PREQUEUE")
        elif "RISK" in upper:
            classified_reasons.append("TRUE_RISK_BLOCKED_PREQUEUE")
        elif "ORCHESTRATOR" in upper:
            classified_reasons.append("TRUE_ORCHESTRATOR_BLOCKED_PREQUEUE")
        elif "ALLOCATOR" in upper:
            classified_reasons.append("TRUE_ALLOCATOR_BLOCKED_PREQUEUE")
        elif "ENTRY_GATE" in upper or "NO_TRADE_ENTRY_EVIDENCE" in upper:
            classified_reasons.append("TRUE_ENTRY_GATE_BLOCKED_PREQUEUE")
        else:
            classified_reasons.append("UNCLASSIFIED_PREQUEUE_BLOCKER")

    classified = sorted(set(classified_reasons))
    if len(classified) == 1:
        only_reason = classified[0]
        if only_reason == "TRUE_BUCKET_QUARANTINE_PREQUEUE":
            return "ALL_CURRENT_ROWS_TRUE_BUCKET_QUARANTINE", raw_reasons
        if only_reason == "TRUE_MARKET_INTEGRITY_BLOCKED_PREQUEUE":
            return "ALL_CURRENT_ROWS_MARKET_INTEGRITY_BLOCKED", raw_reasons
        if only_reason == "TRUE_RISK_BLOCKED_PREQUEUE":
            return "ALL_CURRENT_ROWS_TRUE_RISK_BLOCKED", raw_reasons
        if only_reason == "TRUE_ORCHESTRATOR_BLOCKED_PREQUEUE":
            return "ALL_CURRENT_ROWS_TRUE_ORCHESTRATOR_BLOCKED", raw_reasons
        if only_reason == "TRUE_ALLOCATOR_BLOCKED_PREQUEUE":
            return "ALL_CURRENT_ROWS_TRUE_ALLOCATOR_BLOCKED", raw_reasons
        if only_reason == "TRUE_SELECTED_SIDE_ECONOMICS_CONFLICT_PREQUEUE":
            return "ALL_CURRENT_ROWS_SELECTED_SIDE_ECONOMICS_CONFLICT", raw_reasons
        return only_reason, raw_reasons

    true_prequeue_reasons = {
        "TEMPORAL_INTEGRITY_BLOCKED_PREQUEUE",
        "TRUE_ALLOCATOR_BLOCKED_PREQUEUE",
        "TRUE_BUCKET_QUARANTINE_PREQUEUE",
        "TRUE_ENTRY_GATE_BLOCKED_PREQUEUE",
        "TRUE_ENTRY_GATE_EXPECTED_MOVE_NOT_FAVORABLE_PREQUEUE",
        "TRUE_MARKET_INTEGRITY_BLOCKED_PREQUEUE",
        "TRUE_ORCHESTRATOR_BLOCKED_PREQUEUE",
        "TRUE_RISK_BLOCKED_PREQUEUE",
        "TRUE_SELECTED_SIDE_ECONOMICS_CONFLICT_PREQUEUE",
    }
    if all(reason in true_prequeue_reasons for reason in classified):
        return "MIXED_TRUE_PREQUEUE_BLOCKERS", raw_reasons
    return "UNCLASSIFIED_PREQUEUE_BLOCKERS", raw_reasons


def _paper_exploration_materialization_queue_cycle_status(
    r,
    *,
    now: datetime,
    generated_utc: str,
    continuous_edge_guardian_gate: dict[str, Any] | None = None,
) -> dict[str, Any]:
    guardian_context = _continuous_edge_guardian_gate_public_context(continuous_edge_guardian_gate)
    raw_queue_payload = (
        _read_json_key(r, PAPER_EXPLORATION_MATERIALIZATION_QUEUE_KEY) if r is not None else {}
    )
    raw_rows = _read_paper_exploration_materialization_queue(r)
    prior_queue_status = (
        _read_json_key(r, PAPER_EXPLORATION_MATERIALIZATION_QUEUE_STATUS_KEY)
        if r is not None
        else {}
    )
    preserved_prequeue_status = {
        key: prior_queue_status[key]
        for key in (
            "prequeue_rejected_count",
            "prequeue_counterfactual_count",
            "prequeue_counterfactual_key",
            "prequeue_rejected_reason_counts",
            "prequeue_rejected_rows",
        )
        if key in prior_queue_status
    }
    if preserved_prequeue_status:
        preserved_prequeue_status["prequeue_status_preserved_from_inventory_generated_utc"] = (
            prior_queue_status.get("generated_utc")
        )
    active_rows: list[dict[str, Any]] = []
    pending_source_rows: list[dict[str, Any]] = []
    expired_rows: list[dict[str, Any]] = []
    unsafe_rows: list[dict[str, Any]] = []
    active_signals: list[dict[str, Any]] = []
    counterfactual_rows: list[dict[str, Any]] = []
    max_accept_to_attempt_ms = 0
    queue_published_at = (
        _first_present(
            raw_queue_payload.get("queue_published_at"),
            raw_queue_payload.get("generated_utc"),
        )
        if isinstance(raw_queue_payload, Mapping)
        else None
    )
    inventory_generated_utc = (
        raw_queue_payload.get("inventory_generated_utc")
        if isinstance(raw_queue_payload, Mapping)
        else None
    )
    accepted_at_semantics = (
        raw_queue_payload.get("accepted_at_semantics")
        if isinstance(raw_queue_payload, Mapping)
        else None
    )

    for row in raw_rows:
        safety = build_paper_exploration_safety_truth(_paper_exploration_queue_signal(row))
        exit_plan = build_paper_exploration_exit_plan(
            row,
            generated_utc=_first_present(row.get("accepted_at"), generated_utc),
        )
        expires_at = _parse_strategy_time(row.get("expires_at"))
        accepted_at = _parse_strategy_time(row.get("accepted_at"))
        if accepted_at is not None:
            max_accept_to_attempt_ms = max(
                max_accept_to_attempt_ms,
                int(round((now - accepted_at).total_seconds() * 1000.0)),
            )
        row_with_status = {
            **row,
            **guardian_context,
            "exit_plan": _first_present(row.get("exit_plan"), exit_plan),
            "paper_only": True,
            "routes_to_live": False,
            "places_real_order": False,
            "live_order": False,
            "test_order": False,
            "order_submitted": False,
            "test_order_submitted": False,
            "leverage_mutated": False,
            "margin_mutated": False,
            "counts_as_A_plus": False,
            "counts_as_final_A_plus": False,
            "counts_as_final_a_plus": False,
            "counts_as_live_ready": False,
            "raw_safety_fields": safety["raw_fields"],
            "invariant_checks": safety["invariant_checks"],
            "raw_routes_to_live": safety["raw_routes_to_live"],
            "routes_to_live_false": safety["routes_to_live_false"],
            "raw_places_real_order": safety["raw_places_real_order"],
            "places_real_order_false": safety["places_real_order_false"],
            "raw_counts_as_A_plus": safety["raw_counts_as_A_plus"],
            "counts_as_A_plus_false": safety["counts_as_A_plus_false"],
            "raw_counts_as_live_ready": safety["raw_counts_as_live_ready"],
            "counts_as_live_ready_false": safety["counts_as_live_ready_false"],
            "paper_loop_materialization_attempt_at": generated_utc,
        }
        if safety["hard_fail"]:
            row_with_status["materialization_queue_result"] = "UNSAFE_RAW_SAFETY_FIELD_BLOCKED"
            row_with_status["materialization_no_fill_reason"] = "UNSAFE_RAW_SAFETY_FIELD"
            unsafe_rows.append(row_with_status)
            counterfactual_rows.append(
                _paper_exploration_queue_counterfactual(
                    row_with_status,
                    generated_utc=generated_utc,
                    reason="UNSAFE_RAW_SAFETY_FIELD",
                )
            )
            continue
        if expires_at is None or expires_at < now:
            row_with_status["materialization_queue_result"] = "EXPIRED_BEFORE_PAPER_LOOP"
            row_with_status["materialization_no_fill_reason"] = "EXPIRED_BEFORE_PAPER_LOOP"
            expired_rows.append(row_with_status)
            counterfactual_rows.append(
                _paper_exploration_queue_counterfactual(
                    row_with_status,
                    generated_utc=generated_utc,
                    reason="EXPIRED_BEFORE_PAPER_LOOP",
                )
            )
            continue
        earliest_eligible = _parse_strategy_time(
            _first_present(
                row.get("earliest_eligible_decision_time"),
                row.get("source_freshness_time"),
            )
        )
        if (
            row.get("source_freshness_pending") is True
            and earliest_eligible is not None
            and earliest_eligible > now
        ):
            row_with_status["materialization_queue_result"] = "PENDING_SOURCE_TIME_NEXT_CYCLE"
            row_with_status["materialization_no_fill_reason"] = "PENDING_SOURCE_TIME_NEXT_CYCLE"
            row_with_status["paper_loop_earliest_eligible_decision_time"] = (
                earliest_eligible.astimezone(timezone.utc)
                .isoformat(timespec="milliseconds")
                .replace("+00:00", "Z")
            )
            pending_source_rows.append(row_with_status)
            continue
        row_with_status["materialization_queue_result"] = "ACTIVE_FOR_THIS_CYCLE"
        active_rows.append(row_with_status)
        active_signals.append(_paper_exploration_queue_signal(row_with_status))

    status = {
        "schema_version": "paper_exploration_materialization_queue_status_v1",
        "generated_utc": generated_utc,
        "source_queue_generated_utc": (
            raw_queue_payload.get("generated_utc")
            if isinstance(raw_queue_payload, Mapping)
            else None
        ),
        "queue_published_at": queue_published_at,
        "inventory_generated_utc": inventory_generated_utc,
        "accepted_at_semantics": accepted_at_semantics,
        "queue_key": PAPER_EXPLORATION_MATERIALIZATION_QUEUE_KEY,
        "queue_status_key": PAPER_EXPLORATION_MATERIALIZATION_QUEUE_STATUS_KEY,
        "queue_rows_seen": len(raw_rows),
        "queued_count": len(active_rows) + len(pending_source_rows),
        "active_count": len(active_rows),
        "pending_source_time_count": len(pending_source_rows),
        "expired_count": len(expired_rows),
        "unsafe_count": len(unsafe_rows),
        "counterfactual_count": len(counterfactual_rows),
        "same_cycle_candidate_count": len(active_rows),
        "same_cycle_exploration_accepted_count": 0,
        "same_cycle_materialized_count": 0,
        "max_accept_to_materialization_ms": max_accept_to_attempt_ms,
        "active_rows": _compact_rows_for_state(active_rows[:25]),
        "pending_source_rows": _compact_rows_for_state(pending_source_rows[:25]),
        "expired_rows": _compact_rows_for_state(expired_rows[:25]),
        "unsafe_rows": _compact_rows_for_state(unsafe_rows[:25]),
        "paper_only": True,
        "routes_to_live": False,
        "places_real_order": False,
        "live_gate": LIVE_GATE_BLOCKED,
        **guardian_context,
        "hard_fail": bool(unsafe_rows),
        "hard_fail_reasons": sorted(
            {reason for row in unsafe_rows for reason in row.get("safety_hard_fail_reasons") or []}
        ),
        **preserved_prequeue_status,
        "_active_queue_rows": active_rows,
        "_active_signal_rows": active_signals,
        "_pending_source_rows": pending_source_rows,
        "_counterfactual_rows": counterfactual_rows,
    }
    if r is not None:
        queue_payload = {
            "schema_version": "paper_exploration_materialization_queue_v1",
            "generated_utc": generated_utc,
            "source_queue_generated_utc": (
                raw_queue_payload.get("generated_utc")
                if isinstance(raw_queue_payload, Mapping)
                else None
            ),
            "queue_published_at": queue_published_at,
            "inventory_generated_utc": inventory_generated_utc,
            "accepted_at_semantics": accepted_at_semantics,
            "rows": [*active_rows, *pending_source_rows],
            "pending_source_rows": pending_source_rows,
            "expired_rows": expired_rows,
            "unsafe_rows": unsafe_rows,
            "paper_only": True,
            "routes_to_live": False,
            "places_real_order": False,
            **guardian_context,
        }
        _safe_write(
            r,
            PAPER_EXPLORATION_MATERIALIZATION_QUEUE_KEY,
            json.dumps(queue_payload, default=str),
            ex=2 * 60 * 60,
        )
        if counterfactual_rows:
            merged_counterfactual_rows = _merge_paper_exploration_counterfactual_feedback_rows(
                r,
                counterfactual_rows,
            )
            _safe_write(
                r,
                PAPER_EXPLORATION_MATERIALIZATION_COUNTERFACTUAL_KEY,
                json.dumps(merged_counterfactual_rows, default=str),
                ex=PAPER_TRAINING_EVIDENCE_TTL_SECONDS,
            )
        status_for_redis = _paper_exploration_public_queue_status(status)
        _safe_write(
            r,
            PAPER_EXPLORATION_MATERIALIZATION_QUEUE_STATUS_KEY,
            json.dumps(status_for_redis, default=str),
            ex=2 * 60 * 60,
        )
    return status


def _paper_exploration_materialization_summary_fields(
    queue_status: Mapping[str, Any],
) -> dict[str, Any]:
    def _count(field: str) -> int:
        value = _coerce_float(queue_status.get(field))
        if value is None or value <= 0:
            return 0
        return int(value)

    same_cycle_candidates = _count("same_cycle_candidate_count")
    same_cycle_accepted = _count("same_cycle_exploration_accepted_count")
    same_cycle_materialized = _count("same_cycle_materialized_count")
    queued_count = _count("queued_count")
    active_count = _count("active_count")
    pending_source_time_count = _count("pending_source_time_count")
    expired_count = _count("expired_count")
    queue_counterfactual_count = (
        _count("queue_counterfactual_count")
        if "queue_counterfactual_count" in queue_status
        else _count("counterfactual_count")
    )
    rejected_after_queue_counterfactual_count = _count("rejected_after_queue_counterfactual_count")
    rejected_after_queue_count = _count("rejected_after_queue_count")
    after_queue_exact_no_fill_reason, after_queue_no_fill_reasons = (
        _paper_exploration_exact_no_fill_reason(
            queue_status.get("rejected_after_queue_reason_counts")
            if isinstance(queue_status.get("rejected_after_queue_reason_counts"), Mapping)
            else {}
        )
    )
    prequeue_rejected_count = _count("prequeue_rejected_count")
    prequeue_counterfactual_count = _count("prequeue_counterfactual_count")
    prequeue_exact_no_fill_reason, prequeue_no_fill_reasons = (
        _paper_exploration_prequeue_exact_no_fill_reason(
            queue_status.get("prequeue_rejected_reason_counts")
            if isinstance(queue_status.get("prequeue_rejected_reason_counts"), Mapping)
            else {}
        )
    )
    counterfactual_count = (
        queue_counterfactual_count
        + rejected_after_queue_counterfactual_count
        + prequeue_counterfactual_count
    )
    max_accept_ms = _count("max_accept_to_materialization_ms")

    if same_cycle_materialized > 0:
        exact_no_fill_reason = None
    elif pending_source_time_count > 0 and prequeue_rejected_count > 0:
        exact_no_fill_reason = "MIXED_PENDING_SOURCE_AND_TRUE_PREQUEUE_BLOCKERS"
    elif pending_source_time_count > 0 and queued_count == pending_source_time_count:
        exact_no_fill_reason = "PAPER_EXPLORATION_PENDING_SOURCE_TIME_NEXT_CYCLE"
    elif rejected_after_queue_count > 0 and prequeue_rejected_count > 0:
        matching_all_current_reasons = {
            "ALL_CURRENT_ROWS_MARKET_INTEGRITY_BLOCKED",
            "ALL_CURRENT_ROWS_TRUE_ALLOCATOR_BLOCKED",
            "ALL_CURRENT_ROWS_TRUE_BUCKET_QUARANTINE",
            "ALL_CURRENT_ROWS_TRUE_ORCHESTRATOR_BLOCKED",
            "ALL_CURRENT_ROWS_TRUE_RISK_BLOCKED",
        }
        if (
            after_queue_exact_no_fill_reason == prequeue_exact_no_fill_reason
            and after_queue_exact_no_fill_reason in matching_all_current_reasons
        ):
            exact_no_fill_reason = after_queue_exact_no_fill_reason
        else:
            exact_no_fill_reason = "MIXED_TRUE_PREQUEUE_AND_AFTER_QUEUE_BLOCKERS"
    elif rejected_after_queue_count > 0:
        exact_no_fill_reason = (
            after_queue_exact_no_fill_reason or "PAPER_EXPLORATION_QUEUE_REVALIDATION_BLOCKED"
        )
    elif prequeue_rejected_count > 0 and queued_count == 0:
        exact_no_fill_reason = (
            prequeue_exact_no_fill_reason or "ALL_CURRENT_ROWS_PREQUEUE_BLOCKED_WITH_EXACT_REASONS"
        )
    elif expired_count > 0 and queued_count == 0:
        exact_no_fill_reason = "ALL_QUEUE_ROWS_EXPIRED_BEFORE_PAPER_LOOP"
    elif same_cycle_candidates == 0 and queued_count == 0:
        exact_no_fill_reason = "NO_CURRENT_EXPLORATION_CANDIDATES"
    elif active_count > 0 or queued_count > 0:
        exact_no_fill_reason = "PAPER_EXPLORATION_ACTIVE_REVALIDATION_IN_PROGRESS"
    else:
        exact_no_fill_reason = "PAPER_EXPLORATION_NOT_MATERIALIZED_THIS_CYCLE"

    if same_cycle_materialized > 0:
        queue_resolution_state = "MATERIALIZED"
    elif active_count > 0 or (queued_count > 0 and pending_source_time_count == 0):
        queue_resolution_state = "ACTIVE_REVALIDATION_IN_PROGRESS"
    elif pending_source_time_count > 0:
        queue_resolution_state = "PENDING_SOURCE_TIME"
    elif rejected_after_queue_count > 0 or prequeue_rejected_count > 0:
        queue_resolution_state = "RESOLVED_NO_FILL"
    elif expired_count > 0:
        queue_resolution_state = "EXPIRED"
    else:
        queue_resolution_state = "NO_CURRENT_QUEUE_ROWS"

    return {
        "same_cycle_candidate_count": same_cycle_candidates,
        "same_cycle_exploration_accepted_count": same_cycle_accepted,
        "same_cycle_materialized_count": same_cycle_materialized,
        "queued_count": queued_count,
        "active_count": active_count,
        "pending_source_time_count": pending_source_time_count,
        "expired_count": expired_count,
        "counterfactual_count": counterfactual_count,
        "queue_counterfactual_count": queue_counterfactual_count,
        "rejected_after_queue_counterfactual_count": (rejected_after_queue_counterfactual_count),
        "rejected_after_queue_count": rejected_after_queue_count,
        "after_queue_no_fill_reasons": after_queue_no_fill_reasons,
        "after_queue_exact_no_fill_reason": after_queue_exact_no_fill_reason,
        "prequeue_rejected_count": prequeue_rejected_count,
        "prequeue_counterfactual_count": prequeue_counterfactual_count,
        "prequeue_no_fill_reasons": prequeue_no_fill_reasons,
        "max_accept_to_materialization_ms": max_accept_ms,
        "exact_no_fill_reason": exact_no_fill_reason,
        "canonical_exact_no_fill_reason": (
            _paper_exploration_canonical_exact_no_fill_reason(
                exact_no_fill_reason,
            )
        ),
        "queue_resolution_state": queue_resolution_state,
        "order_submitted": False,
        "test_order_submitted": False,
        "leverage_mutated": False,
        "margin_mutated": False,
    }


def _paper_exploration_public_queue_status(
    queue_status: Mapping[str, Any],
) -> dict[str, Any]:
    public_status = {
        key: value for key, value in queue_status.items() if not str(key).startswith("_")
    }
    return {
        **public_status,
        **_paper_exploration_materialization_summary_fields(public_status),
    }


def _paper_exploration_last_cycle_rejected_rows_count(
    queue_public_status: Mapping[str, Any],
    *,
    blocked_queue_ids: set[str] | None = None,
) -> int:
    after_queue_count = int(
        _coerce_float(queue_public_status.get("rejected_after_queue_count")) or 0
    )
    if after_queue_count <= 0 and blocked_queue_ids:
        after_queue_count = len(blocked_queue_ids)
    return (
        after_queue_count
        + int(_coerce_float(queue_public_status.get("prequeue_rejected_count")) or 0)
        + int(_coerce_float(queue_public_status.get("expired_count")) or 0)
        + int(_coerce_float(queue_public_status.get("unsafe_count")) or 0)
    )


# Price provenance markers. Source strings are quoted verbatim into the
# v2:paper:positions and v2:paper:ledger payloads so the
# position_price_tracking_recorder and operator dashboards can audit
# which V2-owned input the fill price came from. NEVER fabricate a
# price; NEVER use legacy Redis as current truth; NEVER substitute a
# static sample value.
ENTRY_PRICE_SOURCE_V2_MARKET = "V2_MARKET_PRICES_TICKER_24HR_LAST_PRICE"
ENTRY_PRICE_SOURCE_V2_FEATURES = "V2_FEATURES_LATEST_FRESH_CLOSE_PRICE"
ENTRY_PRICE_BLOCKER_MISSING_FILL = "MISSING_V2_MARKET_PRICE_FOR_FILL"
EXIT_PRICE_BLOCKER_MISSING_EXIT = "MISSING_V2_MARKET_PRICE_FOR_EXIT"
REALIZED_EXIT_NOT_RECORDED = "REALIZED_EXIT_NOT_RECORDED_IN_V2_INPUTS"
ENTRY_SPREAD_SOURCE_V2_ORDERBOOK = "V2_MARKET_ORDERBOOK_TOP_OF_BOOK"
MARK_INDEX_SOURCE_V2_FUNDING = "V2_MARKET_FUNDING_PREMIUM_INDEX"
PAPER_IMMEDIATE_FILL_TAKER_SOURCE = "PAPER_MARKETABLE_SINGLE_FILL_FROM_OBSERVED_SPREAD_AND_V2_PRICE"


def _coerce_float(value) -> float | None:
    if isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        try:
            v = float(value)
        except (TypeError, ValueError):
            return None
        return v if v == v and v not in (float("inf"), float("-inf")) else None
    if isinstance(value, str):
        try:
            v = float(value)
        except (TypeError, ValueError):
            return None
        return v if v == v else None
    return None


def _iso_from_epoch_ms(value: Any) -> str | None:
    parsed = _coerce_float(value)
    if parsed is None or parsed <= 0:
        return None
    if parsed < 10_000_000_000:
        parsed *= 1000.0
    try:
        parsed_dt = datetime.fromtimestamp(parsed / 1000.0, tz=timezone.utc)
        return parsed_dt.isoformat(timespec="seconds").replace("+00:00", "Z")
    except (OverflowError, OSError, ValueError):
        return None


def _iso_from_time_value(value: Any) -> str | None:
    parsed_epoch = _iso_from_epoch_ms(value)
    if parsed_epoch is not None:
        return parsed_epoch
    parsed_dt = _strict_aware_utc_time(value)
    if parsed_dt is None:
        return None
    return (
        parsed_dt.astimezone(timezone.utc).isoformat(timespec="milliseconds").replace("+00:00", "Z")
    )


def _best_level_price(levels: Any) -> float | None:
    if not isinstance(levels, list) or not levels:
        return None
    first = levels[0]
    if isinstance(first, (list, tuple)) and first:
        return _coerce_float(first[0])
    if isinstance(first, dict):
        return _coerce_float(first.get("price") or first.get("p"))
    return _coerce_float(first)


def _level_price_quantity(row: Any) -> tuple[float | None, float | None]:
    if isinstance(row, (list, tuple)) and len(row) > 1:
        return _coerce_float(row[0]), _coerce_float(row[1])
    if isinstance(row, dict):
        return (
            _coerce_float(row.get("price") or row.get("p")),
            _coerce_float(row.get("quantity") or row.get("qty") or row.get("q")),
        )
    return None, None


def _top_depth_levels(levels: Any, *, depth: int = 5) -> list[dict[str, float]]:
    if not isinstance(levels, list) or not levels:
        return []
    normalized: list[dict[str, float]] = []
    for row in levels[:depth]:
        price, quantity = _level_price_quantity(row)
        if price is None or quantity is None or price <= 0.0 or quantity <= 0.0:
            continue
        normalized.append({"price": float(price), "quantity": float(quantity)})
    return normalized


def _top_depth_quantity(levels: Any, *, depth: int = 5) -> float | None:
    if not isinstance(levels, list) or not levels:
        return None
    total = 0.0
    seen = 0
    for row in levels[:depth]:
        _price, qty = _level_price_quantity(row)
        if qty is None:
            continue
        total += max(0.0, qty)
        seen += 1
    return total if seen else None


def _top_depth_notional_usd(levels: Any, *, depth: int = 5) -> float | None:
    if not isinstance(levels, list) or not levels:
        return None
    total = 0.0
    seen = 0
    for row in levels[:depth]:
        price, qty = _level_price_quantity(row)
        if price is None or qty is None or price <= 0 or qty <= 0:
            continue
        total += price * qty
        seen += 1
    return total if seen else None


def _read_v2_orderbook_microstructure(r, symbol: str) -> dict[str, Any]:
    """Read V2-owned top-of-book spread evidence for paper entry telemetry.

    The returned timestamp is the market-data ``entry_spread_available_at``.
    The paper fill/allocation decision remains the current loop execution time.
    """
    if r is None or not symbol:
        return {}
    normalized = str(symbol).upper()
    trust_decision_time = _utc_iso()
    trust_evidence = _read_v2_microstructure_trust(
        r,
        normalized,
        decision_time=trust_decision_time,
    )
    for key in (
        f"{V2_REDIS_PREFIX}orderbook:features:binance:{normalized}",
        f"{V2_REDIS_PREFIX}orderbook:depth:binance:{normalized}",
        f"{V2_REDIS_PREFIX}orderbook:top:binance:{normalized}",
        f"{V2_REDIS_PREFIX}orderbook:features:kucoin:{normalized}",
        f"{V2_REDIS_PREFIX}orderbook:depth:kucoin:{normalized}",
        f"{V2_REDIS_PREFIX}orderbook:top:kucoin:{normalized}",
        f"{V2_REDIS_PREFIX}market:orderbook:{normalized}",
        f"{V2_REDIS_PREFIX}market:orderbook:binance:{normalized}",
    ):
        try:
            raw = r.get(key)
        except Exception:
            raw = None
        if not raw:
            continue
        try:
            payload = json.loads(raw)
        except (TypeError, ValueError):
            continue
        if not isinstance(payload, dict):
            continue
        spread_bps = _coerce_float(payload.get("spread_bps") or payload.get("bid_ask_spread_bps"))
        bid = _coerce_float(
            payload.get("best_bid") or payload.get("bid") or payload.get("bidPrice")
        )
        ask = _coerce_float(
            payload.get("best_ask") or payload.get("ask") or payload.get("askPrice")
        )
        if bid is None:
            bid = _best_level_price(payload.get("bids") or payload.get("b"))
        if ask is None:
            ask = _best_level_price(payload.get("asks") or payload.get("a"))
        mid = _coerce_float(
            payload.get("mid") or payload.get("mid_price") or payload.get("midPrice")
        )
        if mid is None and bid is not None and ask is not None:
            mid = (bid + ask) / 2.0
        if spread_bps is None and bid is not None and ask is not None and mid and mid > 0:
            spread_bps = abs(ask - bid) / mid * 10_000.0
        if spread_bps is None:
            continue
        bids = payload.get("bids") or payload.get("b")
        asks = payload.get("asks") or payload.get("a")
        bid_levels_top5 = _top_depth_levels(bids)
        ask_levels_top5 = _top_depth_levels(asks)
        bid_qty = _top_depth_quantity(bids)
        ask_qty = _top_depth_quantity(asks)
        bid_depth_usd = _coerce_float(
            _first_present(
                _top_depth_notional_usd(bids),
                payload.get("top_book_bid_depth_usd"),
                payload.get("bid_depth_usd"),
                payload.get("depth_5_bid_usd"),
                payload.get("best_bid_depth_usd"),
            )
        )
        ask_depth_usd = _coerce_float(
            _first_present(
                _top_depth_notional_usd(asks),
                payload.get("top_book_ask_depth_usd"),
                payload.get("ask_depth_usd"),
                payload.get("depth_5_ask_usd"),
                payload.get("best_ask_depth_usd"),
            )
        )
        market_depth_usd = _coerce_float(
            _first_present(
                payload.get("market_depth_usd"),
                payload.get("orderbook_depth_usd"),
                payload.get("microstructure_liquidity_depth"),
                min(
                    _coerce_float(payload.get("depth_20_bid_usd")),
                    _coerce_float(payload.get("depth_20_ask_usd")),
                )
                if _coerce_float(payload.get("depth_20_bid_usd")) is not None
                and _coerce_float(payload.get("depth_20_ask_usd")) is not None
                else None,
                min(
                    _coerce_float(payload.get("depth_50_bid_usd")),
                    _coerce_float(payload.get("depth_50_ask_usd")),
                )
                if _coerce_float(payload.get("depth_50_bid_usd")) is not None
                and _coerce_float(payload.get("depth_50_ask_usd")) is not None
                else None,
            )
        )
        generic_depth_candidates = [
            value for value in (bid_depth_usd, ask_depth_usd) if value is not None and value > 0
        ]
        top_depth_usd = (
            market_depth_usd
            if market_depth_usd is not None and market_depth_usd > 0
            else min(generic_depth_candidates)
            if generic_depth_candidates
            else None
        )
        depth_source = None
        if top_depth_usd is not None:
            depth_source = (
                f"{key}:precomputed_orderbook_depth_usd"
                if market_depth_usd is not None and market_depth_usd > 0
                else f"{key}:top5_notional_usd"
            )
        imbalance = None
        if bid_qty is not None and ask_qty is not None and (bid_qty + ask_qty) > 0:
            imbalance = (bid_qty - ask_qty) / (bid_qty + ask_qty)
        available_at = _iso_from_time_value(
            _first_present(
                payload.get("available_at"),
                payload.get("received_at"),
                payload.get("fetched_utc"),
            )
        )
        event_time = _iso_from_time_value(
            _first_present(
                payload.get("event_time"),
                payload.get("E"),
                payload.get("T"),
                payload.get("time"),
            )
        )
        generated_at = _iso_from_time_value(
            _first_present(
                payload.get("generated_at"),
                payload.get("generated_utc"),
                payload.get("generated_at_ms"),
            )
        )
        captured_at = _utc_iso()
        depth_impact_bps = _coerce_float(
            _first_present(
                payload.get("depth_derived_price_impact_bps"),
                payload.get("depth_price_impact_bps"),
                payload.get("estimated_price_impact_bps"),
            )
        )
        return {
            "source": f"{ENTRY_SPREAD_SOURCE_V2_ORDERBOOK}:{key}",
            "bid_ask_spread_bps": round(float(spread_bps), 8),
            "best_bid": bid,
            "best_ask": ask,
            "mid_price": mid,
            "bid_levels_top5": bid_levels_top5,
            "ask_levels_top5": ask_levels_top5,
            "orderbook_imbalance": imbalance,
            "bid_depth_usd": round(float(bid_depth_usd), 8) if bid_depth_usd is not None else None,
            "ask_depth_usd": round(float(ask_depth_usd), 8) if ask_depth_usd is not None else None,
            "orderbook_depth_usd": round(float(top_depth_usd), 8)
            if top_depth_usd is not None
            else None,
            "top_of_book_depth_usd": round(float(top_depth_usd), 8)
            if top_depth_usd is not None
            else None,
            "market_depth_usd": round(float(top_depth_usd), 8)
            if top_depth_usd is not None
            else None,
            "orderbook_depth_source": depth_source,
            "depth_derived_price_impact_bps": round(float(depth_impact_bps), 8)
            if depth_impact_bps is not None
            else None,
            "depth_price_impact_bps": round(float(depth_impact_bps), 8)
            if depth_impact_bps is not None
            else None,
            "depth_price_impact_source": f"{key}:estimated_price_impact_bps"
            if depth_impact_bps is not None
            else None,
            "depth_price_impact_model": "DIRECT_ORDERBOOK_FEATURE_ESTIMATE"
            if depth_impact_bps is not None
            else None,
            "entry_spread_available_at": available_at,
            "entry_spread_event_time": event_time,
            "entry_spread_generated_at": generated_at,
            "entry_spread_captured_at": captured_at,
            "entry_spread_decision_time": captured_at,
            "entry_spread_source_hash": _altdata_feature_hash(
                {"redis_key": key, "payload": payload}
            ),
            "entry_spread_source_hash_contract": (
                "REDIS_KEY_AND_FULL_CANONICAL_SOURCE_PAYLOAD_SHA256_V1"
            ),
            **trust_evidence,
        }
    return {}


def _read_v2_microstructure_trust(
    r,
    symbol: str,
    *,
    decision_time: Any = None,
    timeframe: Any = None,
) -> dict[str, Any]:
    if r is None or not symbol:
        return {}
    normalized = str(symbol).upper()
    requested_timeframe = str(timeframe or "").strip()
    timeframe_candidates = [
        requested_timeframe,
        "1m",
        "5m",
        "15m",
    ]
    lookup_timeframes = [
        item for item in dict.fromkeys(timeframe_candidates) if item in {"1m", "5m", "15m"}
    ]
    lookup_keys = [
        f"{V2_REDIS_PREFIX}microstructure:trust_score:{normalized}:{timeframe}"
        for timeframe in lookup_timeframes
    ]
    decision_dt = _strict_aware_utc_time(decision_time)
    if decision_dt is None:
        return {
            "microstructure_trust_status": (
                "REJECTED_MICROSTRUCTURE_TRUST_CONSUMER_DECISION_TIME_INVALID"
            ),
            "microstructure_trust_lookup_keys": lookup_keys,
            "microstructure_trust_invalid_contract_keys": [
                {
                    "key": "CONSUMER_DECISION_TIME",
                    "reason": "MISSING_UNPARSEABLE_OR_NAIVE",
                    "decision_time": decision_time,
                }
            ],
        }
    rejected_future_payload: dict[str, Any] | None = None
    invalid_contract_keys: list[dict[str, Any]] = []
    for key, key_timeframe in zip(lookup_keys, lookup_timeframes):
        try:
            raw = r.get(key)
        except Exception:
            raw = None
        if not raw:
            continue
        try:
            payload = json.loads(raw)
        except (TypeError, ValueError):
            continue
        if not isinstance(payload, dict):
            continue
        contract_reasons: list[str] = []
        if payload.get("schema_version") != MICROSTRUCTURE_TRUST_SCHEMA_VERSION:
            contract_reasons.append("SCHEMA_VERSION_MISMATCH")
        if str(payload.get("symbol") or "").upper() != normalized:
            contract_reasons.append("SYMBOL_MISMATCH")
        if str(payload.get("timeframe") or "").strip() != key_timeframe:
            contract_reasons.append("TIMEFRAME_MISMATCH")
        if contract_reasons:
            invalid_contract_keys.append(
                {
                    "key": key,
                    "reasons": contract_reasons,
                    "schema_version": payload.get("schema_version"),
                    "symbol": payload.get("symbol"),
                    "timeframe": payload.get("timeframe"),
                }
            )
            continue
        available_at = payload.get("available_at")
        generated_at = payload.get("generated_at")
        available_dt = _strict_aware_utc_time(available_at)
        generated_dt = _strict_aware_utc_time(generated_at)
        invalid_clock_contract = (
            available_dt is None or generated_dt is None or generated_dt > available_dt
        )
        if invalid_clock_contract or (
            decision_dt is not None and (available_dt > decision_dt or generated_dt > decision_dt)
        ):
            rejected_future_payload = {
                "microstructure_trust_source": key,
                "microstructure_trust_status": "REJECTED_MICROSTRUCTURE_TRUST_AFTER_DECISION",
                "microstructure_trust_lookup_keys": lookup_keys,
                "microstructure_available_at": available_at,
                "microstructure_generated_at": generated_at,
                "microstructure_trust_decision_time": decision_time,
                "microstructure_trust_clock_contract_invalid": (invalid_clock_contract),
                "post_sweep_reversal_probability": None,
                "fakeout_reversal_probability": None,
            }
            continue
        return {
            "microstructure_trust_source": key,
            "public_orderbook_trust_score": payload.get("public_orderbook_trust_score"),
            "composite_microstructure_trust_score": payload.get(
                "composite_microstructure_trust_score"
            ),
            "microstructure_trust_score": payload.get("microstructure_trust_score"),
            "microstructure_adaptive_minimum": payload.get("adaptive_minimum"),
            "orderbook_trust_score": payload.get("orderbook_trust_score"),
            "orderbook_trust_tier": payload.get("orderbook_trust_tier"),
            "microstructure_action": payload.get("microstructure_action"),
            "final_a_plus_min_composite_trust": payload.get("final_a_plus_min_composite_trust"),
            "final_a_plus_eligible": payload.get("final_a_plus_eligible"),
            "final_a_plus_requires_composite_trust": payload.get(
                "final_a_plus_requires_composite_trust"
            ),
            "non_book_confirmation_pass": payload.get("non_book_confirmation_pass"),
            "composite_confirmation_passes": payload.get("composite_confirmation_passes"),
            "composite_confirmation_missing_fields": payload.get(
                "composite_confirmation_missing_fields"
            ),
            "feed_integrity_pass": payload.get("feed_integrity_pass"),
            "sequence_gap_free": payload.get("sequence_gap_free"),
            "latency_within_bound": payload.get("latency_within_bound"),
            "trade_tape_confirmation_pass": payload.get("trade_tape_confirmation_pass"),
            "cross_venue_confirmation_pass": payload.get("cross_venue_confirmation_pass"),
            "liquidation_sweep_risk_acceptable": payload.get("liquidation_sweep_risk_acceptable"),
            "oi_funding_long_short_confirmation_pass": payload.get(
                "oi_funding_long_short_confirmation_pass"
            ),
            "real_spread_depth_cost_evidence_pass": payload.get(
                "real_spread_depth_cost_evidence_pass"
            ),
            "reduced_size_bootstrap_tier": payload.get("reduced_size_bootstrap_tier"),
            "reduced_size_counts_as_final_a_plus": payload.get(
                "reduced_size_counts_as_final_a_plus"
            ),
            "reduced_size_routes_to_live": payload.get("reduced_size_routes_to_live"),
            "reduced_size_paper_only": payload.get("reduced_size_paper_only"),
            "bootstrap_reduced_size_paper_only": payload.get("bootstrap_reduced_size_paper_only"),
            "orderbook_latency_ms": payload.get("orderbook_latency_ms")
            or payload.get("feed_latency_ms"),
            "book_sequence_gap": payload.get("book_sequence_gap")
            if payload.get("book_sequence_gap") is not None
            else bool(payload.get("sequence_gap_flag")),
            "book_depth_persistence_score": payload.get("book_depth_persistence_score")
            or payload.get("depth_persistence"),
            "book_cancel_pressure_score": payload.get("book_cancel_pressure_score")
            or payload.get("cancel_pressure"),
            "trade_tape_confirmation_score": payload.get("trade_tape_confirmation_score"),
            "cross_venue_confirmation_score": payload.get("cross_venue_confirmation_score")
            or payload.get("cross_venue_confirmation"),
            "liquidation_zone_risk_score": payload.get("liquidation_zone_risk_score"),
            "sweep_risk_score": payload.get("sweep_risk_score") or payload.get("sweep_risk"),
            "post_sweep_reversal_probability": payload.get("post_sweep_reversal_probability"),
            "fakeout_reversal_probability": payload.get("post_sweep_reversal_probability"),
            "microstructure_missing_components": payload.get("missing_components"),
            "microstructure_source_decision_time": payload.get("decision_time"),
            "microstructure_decision_time": decision_time,
            "microstructure_available_at": available_at,
            "microstructure_generated_at": generated_at,
            "microstructure_source_hash": _altdata_feature_hash(
                {"redis_key": key, "payload": payload}
            ),
            "microstructure_source_hash_contract": (
                "REDIS_KEY_AND_FULL_CANONICAL_SOURCE_PAYLOAD_SHA256_V1"
            ),
            "microstructure_trust_status": "MICROSTRUCTURE_TRUST_SCORE_FOUND",
            "microstructure_trust_lookup_keys": lookup_keys,
        }
    if rejected_future_payload is not None:
        return rejected_future_payload
    if invalid_contract_keys:
        return {
            "microstructure_trust_status": ("REJECTED_MICROSTRUCTURE_TRUST_CONTRACT_INVALID"),
            "microstructure_trust_lookup_keys": lookup_keys,
            "microstructure_trust_invalid_contract_keys": invalid_contract_keys,
            "microstructure_trust_required_schema_version": (MICROSTRUCTURE_TRUST_SCHEMA_VERSION),
        }
    return {
        "microstructure_trust_status": "MISSING_MICROSTRUCTURE_TRUST_SCORE",
        "microstructure_trust_missing_reason": "NO_V2_MICROSTRUCTURE_TRUST_SCORE_REDIS_PAYLOAD",
        "microstructure_trust_lookup_keys": lookup_keys,
    }


def _read_v2_advanced_indicator_context(
    r,
    symbol: str,
    *,
    timeframe: Any = None,
    decision_time: Any = None,
) -> dict[str, Any]:
    if r is None or not symbol:
        return {}
    normalized = str(symbol).upper()
    tf = str(timeframe or "").strip() or "5m"
    lookup_keys = [
        f"{V2_REDIS_PREFIX}market:fvg:{normalized}:{tf}",
        f"{V2_REDIS_PREFIX}market:structure:{normalized}:{tf}",
        f"{V2_REDIS_PREFIX}market:liquidity_zones:{normalized}",
        f"{V2_REDIS_PREFIX}market:sweep_risk:{normalized}:{tf}",
        f"{V2_REDIS_PREFIX}market:vwap:{normalized}:{tf}",
        f"{V2_REDIS_PREFIX}market:volume_profile:{normalized}:{tf}",
        f"{V2_REDIS_PREFIX}market:cvd:{normalized}:{tf}",
        f"{V2_REDIS_PREFIX}market:trade_tape_features:{normalized}",
    ]
    decision_dt = _parse_strategy_time(decision_time)
    merged: dict[str, Any] = {}
    used_keys: list[str] = []
    rejected_future_keys: list[dict[str, Any]] = []
    invalid_contract_keys: list[dict[str, Any]] = []
    missing_keys: list[str] = []
    used_available_times: list[datetime] = []
    used_generated_times: list[datetime] = []
    used_event_times: list[datetime] = []
    used_source_decision_times: list[datetime] = []
    used_payload_lineage: list[dict[str, str]] = []
    for key in lookup_keys:
        try:
            raw = r.get(key)
        except Exception:
            raw = None
        if not raw:
            missing_keys.append(key)
            continue
        try:
            payload = json.loads(raw)
        except (TypeError, ValueError):
            missing_keys.append(key)
            continue
        if not isinstance(payload, dict):
            missing_keys.append(key)
            continue
        available_at = payload.get("available_at")
        event_time = payload.get("event_time")
        payload_decision_time = payload.get("decision_time")
        generated_at = payload.get("generated_at") or payload.get("generated_utc")
        event_dt = _strict_aware_utc_time(event_time)
        available_dt = _strict_aware_utc_time(available_at)
        source_decision_dt = _strict_aware_utc_time(payload_decision_time)
        generated_dt = _strict_aware_utc_time(generated_at)
        missing_contract_fields = [
            field
            for field, value in (
                ("event_time", event_time),
                ("available_at", available_at),
                ("decision_time", payload_decision_time),
                ("generated_at", generated_at),
            )
            if value in (None, "")
        ]
        missing_consumers = [
            field
            for field in (
                "trainer_consumes",
                "risk_consumes",
                "orchestrator_consumes",
                "allocator_consumes",
                "paper_consumes",
                "live_dry_run_consumes",
                "frontend_consumes",
                "ios_consumes",
            )
            if payload.get(field) is not True
        ]
        invalid_time_fields = [
            field
            for field, parsed in (
                ("event_time", event_dt),
                ("available_at", available_dt),
                ("decision_time", source_decision_dt),
                ("generated_at", generated_dt),
            )
            if parsed is None
        ]
        invalid_order = []
        if event_dt is not None and available_dt is not None and event_dt > available_dt:
            invalid_order.append("event_time>available_at")
        if (
            available_dt is not None
            and source_decision_dt is not None
            and available_dt > source_decision_dt
        ):
            invalid_order.append("available_at>decision_time")
        if (
            source_decision_dt is not None
            and generated_dt is not None
            and source_decision_dt > generated_dt
        ):
            invalid_order.append("decision_time>generated_at")
        if missing_contract_fields or missing_consumers or invalid_time_fields or invalid_order:
            invalid_contract_keys.append(
                {
                    "key": key,
                    "missing_contract_fields": missing_contract_fields,
                    "missing_consumers": missing_consumers,
                    "invalid_or_naive_time_fields": invalid_time_fields,
                    "invalid_time_order": invalid_order,
                    "event_time": event_time,
                    "available_at": available_at,
                    "decision_time": payload_decision_time,
                    "generated_at": generated_at,
                }
            )
            continue
        if (
            available_dt > decision_dt
            or source_decision_dt > decision_dt
            or generated_dt > decision_dt
        ):
            rejected_future_keys.append(
                {
                    "key": key,
                    "event_time": event_time,
                    "available_at": available_at,
                    "decision_time": payload_decision_time,
                    "generated_at": generated_at,
                }
            )
            continue
        used_keys.append(key)
        used_event_times.append(event_dt)
        used_available_times.append(available_dt)
        used_source_decision_times.append(source_decision_dt)
        used_generated_times.append(generated_dt)
        used_payload_lineage.append(
            {
                "key": key,
                "payload_hash": _altdata_feature_hash(payload) or "",
            }
        )
        merged.update(
            {
                field: payload.get(field)
                for field in ADVANCED_CONTEXT_FIELDS
                if payload.get(field) not in (None, "")
            }
        )
        family = payload.get("feature_family")
        if family:
            merged.setdefault("advanced_indicator_feature_families", [])
            if family not in merged["advanced_indicator_feature_families"]:
                merged["advanced_indicator_feature_families"].append(family)
    if invalid_contract_keys:
        computed_context = _compute_and_publish_v2_advanced_indicator_context(
            r,
            normalized,
            timeframe=tf,
            decision_time=decision_time,
        )
        if computed_context:
            computed_context["advanced_indicator_invalid_contract_keys_repaired"] = (
                invalid_contract_keys
            )
            return computed_context
    if not used_keys:
        computed_context = _compute_and_publish_v2_advanced_indicator_context(
            r,
            normalized,
            timeframe=tf,
            decision_time=decision_time,
        )
        if computed_context:
            return computed_context
        return {
            "advanced_indicator_status": (
                "ADVANCED_INDICATOR_CONTEXT_REJECTED_AFTER_DECISION"
                if rejected_future_keys
                else "ADVANCED_INDICATOR_CONTEXT_MISSING"
            ),
            "advanced_indicator_lookup_keys": lookup_keys,
            "advanced_indicator_missing_keys": missing_keys,
            "advanced_indicator_rejected_future_keys": rejected_future_keys,
            "advanced_indicator_invalid_contract_keys": invalid_contract_keys,
        }
    merged.update(
        {
            "advanced_indicator_status": (
                "ADVANCED_INDICATOR_CONTEXT_PARTIAL_INVALID_CONTRACT"
                if invalid_contract_keys
                else "ADVANCED_INDICATOR_CONTEXT_FOUND"
            ),
            "advanced_indicator_lookup_keys": lookup_keys,
            "advanced_indicator_source_keys": used_keys,
            "advanced_indicator_missing_keys": missing_keys,
            "advanced_indicator_rejected_future_keys": rejected_future_keys,
            "advanced_indicator_invalid_contract_keys": invalid_contract_keys,
            "advanced_indicator_decision_time": decision_time,
            "advanced_indicator_source_decision_time": (
                max(used_source_decision_times).isoformat().replace("+00:00", "Z")
                if used_source_decision_times
                else None
            ),
            "advanced_indicator_event_time": (
                max(used_event_times).isoformat().replace("+00:00", "Z")
                if used_event_times
                else None
            ),
            "advanced_indicator_available_at": (
                max(used_available_times).isoformat().replace("+00:00", "Z")
                if used_available_times
                else None
            ),
            "advanced_indicator_generated_at": (
                max(used_generated_times).isoformat().replace("+00:00", "Z")
                if used_generated_times
                else None
            ),
            "advanced_indicator_source_hash": hashlib.sha256(
                json.dumps(
                    used_payload_lineage,
                    sort_keys=True,
                    separators=(",", ":"),
                ).encode("utf-8")
            ).hexdigest(),
            "advanced_indicator_source_hash_contract": (
                "ORDERED_SOURCE_KEY_AND_FULL_CANONICAL_PAYLOAD_SHA256_V1"
            ),
        }
    )
    return merged


def _load_closed_candle_dict_rows_for_advanced_indicators(
    r,
    symbol: str,
    timeframe: str,
) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for key in (
        f"{V2_REDIS_PREFIX}market:ohlcv_closed:binance:{symbol}:{timeframe}",
        f"{V2_REDIS_PREFIX}market:ohlcv:binance:{symbol}:{timeframe}",
    ):
        try:
            raw = r.get(key)
        except Exception:
            raw = None
        if not raw:
            continue
        try:
            payload = json.loads(raw)
        except (TypeError, ValueError):
            continue
        candidates = payload if isinstance(payload, list) else [payload]
        for item in candidates:
            if not isinstance(item, dict):
                continue
            if not (
                item.get("candle_closed_confirmed") is True or item.get("closed_candle") is True
            ):
                continue
            # A candle close/event clock is not evidence of consumer
            # availability.  Rows without an explicit, aware availability
            # clock cannot participate in an on-demand decision feature.
            if _strict_aware_utc_time(item.get("available_at")) is None:
                continue
            rows.append(item)
        if rows:
            break
    return rows


def _load_trade_tape_dict_rows_for_advanced_indicators(
    r,
    symbol: str,
    *,
    max_rows: int = 1000,
) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for key in (
        f"{V2_REDIS_PREFIX}market:agg_trades:{symbol}",
        f"{V2_REDIS_PREFIX}market:trades:{symbol}",
        f"{V2_REDIS_PREFIX}trades:{symbol}",
    ):
        try:
            raw = r.get(key)
        except Exception:
            raw = None
        if not raw:
            continue
        try:
            payload = json.loads(raw)
        except (TypeError, ValueError):
            continue
        payload_availability = None
        if isinstance(payload, dict):
            payload_availability = payload.get("available_at")
            candidates = []
            for field in ("trades", "rows", "data", "items"):
                values = payload.get(field)
                if isinstance(values, list):
                    candidates = values
                    break
            if not candidates:
                candidates = [payload]
        elif isinstance(payload, list):
            candidates = payload
        else:
            candidates = []
        for item in candidates[-max_rows:]:
            if not isinstance(item, dict):
                continue
            row = dict(item)
            price = _first_present(row.get("price"), row.get("p"))
            if row.get("price") in (None, "") and price not in (None, ""):
                row["price"] = price
            quantity = _first_present(row.get("quantity"), row.get("qty"), row.get("q"))
            if row.get("quantity") in (None, "") and quantity not in (None, ""):
                row["quantity"] = quantity
            side = _first_present(row.get("side"), row.get("aggressor_side"))
            if side in (None, "") and "m" in row:
                maker_flag = row.get("m")
                if isinstance(maker_flag, bool):
                    side = "sell" if maker_flag else "buy"
                else:
                    maker_text = str(maker_flag).strip().lower()
                    if maker_text in {"true", "1", "yes"}:
                        side = "sell"
                    elif maker_text in {"false", "0", "no"}:
                        side = "buy"
            if row.get("side") in (None, "") and side not in (None, ""):
                row["side"] = side
            event_time = _first_present(
                row.get("event_time"),
                row.get("T"),
                row.get("E"),
                row.get("timestamp"),
                row.get("time"),
            )
            if row.get("event_time") in (None, "") and event_time not in (None, ""):
                row["event_time"] = event_time
            available_at = _first_present(
                row.get("available_at"),
                payload_availability,
            )
            if _strict_aware_utc_time(available_at) is None:
                continue
            if row.get("available_at") in (None, ""):
                row["available_at"] = available_at
            rows.append(row)
        if rows:
            break
    return rows


def _compute_and_publish_v2_advanced_indicator_context(
    r,
    symbol: str,
    *,
    timeframe: str,
    decision_time: Any = None,
) -> dict[str, Any]:
    if r is None:
        return {}
    candles = _load_closed_candle_dict_rows_for_advanced_indicators(r, symbol, timeframe)
    if len(candles) < 3:
        return {}
    decision_dt = _strict_aware_utc_time(decision_time)
    if decision_dt is None:
        return {
            "advanced_indicator_status": "ADVANCED_INDICATOR_COMPUTE_DECISION_TIME_INVALID",
            "advanced_indicator_invalid_contract_keys": [
                {
                    "key": "COMPUTE_DECISION_TIME",
                    "reason": "MISSING_UNPARSEABLE_OR_NAIVE",
                    "decision_time": decision_time,
                }
            ],
        }
    price, _price_source, price_available_at = _read_v2_market_price(r, symbol)
    price_available_dt = _strict_aware_utc_time(price_available_at)
    if price_available_dt is None or price_available_dt > decision_dt:
        price = None
    if price is None:
        price = _coerce_float(_first_present(candles[-1].get("close"), candles[-1].get("c")))
    if price is None:
        return {}
    payloads_by_key: dict[str, dict[str, Any]] = {}
    trades = _load_trade_tape_dict_rows_for_advanced_indicators(r, symbol)
    tape = compute_trade_tape_features(
        symbol=symbol,
        timeframe=timeframe,
        trades=trades,
        decision_time=decision_dt,
    )
    liquidity = compute_liquidity_zones(
        symbol=symbol,
        timeframe=timeframe,
        candles=candles,
        price=price,
        trade_tape=tape,
        decision_time=decision_dt,
    )
    payloads_by_key[f"{V2_REDIS_PREFIX}market:liquidity_zones:{symbol}"] = liquidity
    payloads_by_key[f"{V2_REDIS_PREFIX}market:fvg:{symbol}:{timeframe}"] = compute_fvg(
        symbol=symbol,
        timeframe=timeframe,
        candles=candles,
        price=price,
        liquidity_zones=liquidity,
        trade_tape=tape,
        decision_time=decision_dt,
    )
    payloads_by_key[f"{V2_REDIS_PREFIX}market:structure:{symbol}:{timeframe}"] = compute_structure(
        symbol=symbol,
        timeframe=timeframe,
        candles=candles,
        price=price,
        decision_time=decision_dt,
    )
    payloads_by_key[f"{V2_REDIS_PREFIX}market:sweep_risk:{symbol}:{timeframe}"] = liquidity
    payloads_by_key[f"{V2_REDIS_PREFIX}market:vwap:{symbol}:{timeframe}"] = compute_vwap_features(
        symbol=symbol,
        timeframe=timeframe,
        candles=candles,
        price=price,
        decision_time=decision_dt,
    )
    payloads_by_key[f"{V2_REDIS_PREFIX}market:volume_profile:{symbol}:{timeframe}"] = (
        compute_volume_profile(
            symbol=symbol,
            timeframe=timeframe,
            candles=candles,
            price=price,
            decision_time=decision_dt,
        )
    )
    payloads_by_key[f"{V2_REDIS_PREFIX}market:cvd:{symbol}:{timeframe}"] = compute_cvd_features(
        symbol=symbol,
        timeframe=timeframe,
        candles=candles,
        price=price,
        decision_time=decision_dt,
    )
    context: dict[str, Any] = {}
    published_keys: list[str] = []
    publish_errors: list[str] = []
    available_times: list[datetime] = []
    generated_times: list[datetime] = []
    event_times: list[datetime] = []
    source_decision_times: list[datetime] = []
    payload_lineage: list[dict[str, str]] = []
    invalid_payloads: list[dict[str, Any]] = []
    for key, payload in payloads_by_key.items():
        event_dt = _strict_aware_utc_time(payload.get("event_time"))
        available_dt = _strict_aware_utc_time(payload.get("available_at"))
        source_decision_dt = _strict_aware_utc_time(payload.get("decision_time"))
        generated_dt = _strict_aware_utc_time(
            _first_present(payload.get("generated_at"), payload.get("generated_utc"))
        )
        invalid_fields = [
            field
            for field, parsed in (
                ("event_time", event_dt),
                ("available_at", available_dt),
                ("decision_time", source_decision_dt),
                ("generated_at", generated_dt),
            )
            if parsed is None
        ]
        invalid_order = []
        if event_dt is not None and available_dt is not None and event_dt > available_dt:
            invalid_order.append("event_time>available_at")
        if (
            available_dt is not None
            and source_decision_dt is not None
            and available_dt > source_decision_dt
        ):
            invalid_order.append("available_at>decision_time")
        if (
            source_decision_dt is not None
            and generated_dt is not None
            and source_decision_dt > generated_dt
        ):
            invalid_order.append("decision_time>generated_at")
        if invalid_fields or invalid_order:
            invalid_payloads.append(
                {
                    "key": key,
                    "invalid_or_naive_time_fields": invalid_fields,
                    "invalid_time_order": invalid_order,
                }
            )
            continue
        event_times.append(event_dt)
        available_times.append(available_dt)
        source_decision_times.append(source_decision_dt)
        generated_times.append(generated_dt)
        payload_lineage.append(
            {
                "key": key,
                "payload_hash": _altdata_feature_hash(payload) or "",
            }
        )
        for field in ADVANCED_CONTEXT_FIELDS:
            if payload.get(field) not in (None, ""):
                context[field] = payload[field]
        try:
            r.set(key, json.dumps(payload))
            published_keys.append(key)
        except Exception as exc:  # noqa: BLE001
            publish_errors.append(f"{key}:{type(exc).__name__}")
    if invalid_payloads:
        return {
            "advanced_indicator_status": "ADVANCED_INDICATOR_COMPUTED_CONTRACT_INVALID",
            "advanced_indicator_invalid_contract_keys": invalid_payloads,
            "advanced_indicator_source_keys": list(payloads_by_key),
        }
    if not context:
        return {}
    context.update(
        {
            "advanced_indicator_status": "ADVANCED_INDICATOR_CONTEXT_COMPUTED_FROM_CLOSED_CANDLES",
            "advanced_indicator_source_keys": published_keys,
            "advanced_indicator_publish_errors": publish_errors,
            "advanced_indicator_feature_families": [
                "FAIR_VALUE_GAP",
                "BOS_CHOCH",
                "LIQUIDITY_SWEEP",
                "VWAP_DEVIATION",
                "VOLUME_PROFILE",
                "CVD",
            ],
            "advanced_indicator_decision_time": decision_time,
            "advanced_indicator_source_decision_time": (
                max(source_decision_times).isoformat().replace("+00:00", "Z")
                if source_decision_times
                else None
            ),
            "advanced_indicator_event_time": (
                max(event_times).isoformat().replace("+00:00", "Z") if event_times else None
            ),
            "advanced_indicator_available_at": (
                max(available_times).isoformat().replace("+00:00", "Z") if available_times else None
            ),
            "advanced_indicator_generated_at": (
                max(generated_times).isoformat().replace("+00:00", "Z") if generated_times else None
            ),
            "advanced_indicator_source_hash": hashlib.sha256(
                json.dumps(
                    payload_lineage,
                    sort_keys=True,
                    separators=(",", ":"),
                ).encode("utf-8")
            ).hexdigest(),
            "advanced_indicator_source_hash_contract": (
                "ORDERED_SOURCE_KEY_AND_FULL_CANONICAL_PAYLOAD_SHA256_V1"
            ),
        }
    )
    return context


def _attach_advanced_indicator_context(
    intent: dict[str, Any],
    *,
    snapshot_features: Mapping[str, Any] | None = None,
    runtime_context: dict[str, Any] | None = None,
) -> None:
    context: dict[str, Any] = {}
    if isinstance(snapshot_features, Mapping):
        for field in ADVANCED_CONTEXT_FIELDS:
            value = snapshot_features.get(field)
            if value not in (None, ""):
                context[field] = value
    if isinstance(runtime_context, dict):
        for field in ADVANCED_CONTEXT_FIELDS:
            value = runtime_context.get(field)
            if value not in (None, ""):
                context[field] = value
        for field in (
            "advanced_indicator_status",
            "advanced_indicator_lookup_keys",
            "advanced_indicator_source_keys",
            "advanced_indicator_missing_keys",
            "advanced_indicator_rejected_future_keys",
            "advanced_indicator_invalid_contract_keys",
            "advanced_indicator_invalid_contract_keys_repaired",
            "advanced_indicator_feature_families",
            "advanced_indicator_input_cutoff",
            "advanced_indicator_decision_time",
            "advanced_indicator_source_decision_time",
            "advanced_indicator_event_time",
            "advanced_indicator_available_at",
            "advanced_indicator_generated_at",
            "advanced_indicator_source_hash",
            "advanced_indicator_source_hash_contract",
            "advanced_indicator_lookup_observed_at",
        ):
            if runtime_context.get(field) not in (None, ""):
                intent[field] = runtime_context[field]
    if context:
        intent["advanced_indicator_context"] = context
        for field, value in context.items():
            intent.setdefault(field, value)
    else:
        intent.setdefault("advanced_indicator_status", "ADVANCED_INDICATOR_CONTEXT_MISSING")


def _read_v2_market_price(r, symbol: str) -> tuple[float | None, str, str | None]:
    """Read the last price for ``symbol`` from V2-owned market data.

    Search order is strict and V2-only:

    1. ``v2:market:prices:{symbol}.ticker_24hr.lastPrice``
    2. ``v2:features:latest:{symbol}:1m.features.close_price`` only when
       the snapshot's ``feature_freshness_state`` is ``CURRENT``.

    Returns ``(price, source_label, source_available_at)``. A producer
    generation clock is not silently re-labelled as availability. When neither
    source is available, returns ``(None, MISSING blocker, None)`` so
    the caller can attach the explicit MISSING marker to the paper
    payload instead of fabricating a price.
    """
    if r is None or not symbol:
        return None, ENTRY_PRICE_BLOCKER_MISSING_FILL, None
    try:
        raw = r.get(f"{V2_REDIS_PREFIX}market:prices:{symbol}")
    except Exception:
        raw = None
    if raw:
        try:
            payload = json.loads(raw)
        except (ValueError, TypeError):
            payload = None
        if isinstance(payload, dict):
            ticker = (
                payload.get("ticker_24hr") if isinstance(payload.get("ticker_24hr"), dict) else None
            )
            if isinstance(ticker, dict):
                px = _coerce_float(ticker.get("lastPrice"))
                if px is not None and px > 0:
                    return (
                        px,
                        ENTRY_PRICE_SOURCE_V2_MARKET,
                        _first_present(
                            payload.get("available_at"),
                            payload.get("fetched_utc"),
                        ),
                    )
    try:
        raw = r.get(f"{V2_REDIS_PREFIX}features:latest:{symbol}:1m")
    except Exception:
        raw = None
    if raw:
        try:
            payload = json.loads(raw)
        except (ValueError, TypeError):
            payload = None
        if isinstance(payload, dict) and payload.get("feature_freshness_state") == "CURRENT":
            feats = payload.get("features") if isinstance(payload.get("features"), dict) else {}
            for key in ("close_price", "last_price", "lastPrice"):
                px = _coerce_float(feats.get(key))
                if px is not None and px > 0:
                    return (
                        px,
                        ENTRY_PRICE_SOURCE_V2_FEATURES,
                        _first_present(
                            payload.get("available_at"),
                            payload.get("source_available_time"),
                        ),
                    )
    return None, ENTRY_PRICE_BLOCKER_MISSING_FILL, None


def _timestamp_to_utc_iso(value: Any) -> str | None:
    if value in (None, ""):
        return None
    parsed_epoch = _iso_from_epoch_ms(value)
    if parsed_epoch is not None:
        return parsed_epoch
    parsed = _strict_aware_utc_time(value)
    if parsed is None:
        return None
    return parsed.isoformat(timespec="milliseconds").replace("+00:00", "Z")


def _read_v2_mark_index_evidence(r, symbol: str) -> dict[str, Any]:
    """Read Binance premium-index mark/index evidence from V2-owned keys."""
    if r is None or not symbol:
        return {}
    normalized = str(symbol).upper()
    for key in (
        f"{V2_REDIS_PREFIX}market:mark_price:{normalized}",
        f"{V2_REDIS_PREFIX}market:funding:{normalized}",
        f"{V2_REDIS_PREFIX}market:prices:{normalized}",
    ):
        payload = _read_json_key(r, key)
        if not payload:
            continue
        source_payload = (
            payload.get("funding") if isinstance(payload.get("funding"), dict) else payload
        )
        selected_path = "funding" if source_payload is not payload else "root"
        if not isinstance(source_payload, dict):
            continue
        mark = _coerce_float(
            _first_present(source_payload.get("markPrice"), source_payload.get("mark_price"))
        )
        index = _coerce_float(
            _first_present(source_payload.get("indexPrice"), source_payload.get("index_price"))
        )
        if mark is None or index is None or mark <= 0.0 or index <= 0.0:
            continue
        divergence = (mark - index) / index
        event_time = _timestamp_to_utc_iso(
            _first_present(
                source_payload.get("time"),
                source_payload.get("timestamp"),
                source_payload.get("binance_time_ms"),
                source_payload.get("E"),
                source_payload.get("event_time"),
            )
        )
        available_at = _timestamp_to_utc_iso(
            _first_present(
                source_payload.get("available_at"),
                payload.get("available_at"),
                payload.get("fetched_utc"),
            )
        )
        generated_at = _timestamp_to_utc_iso(
            _first_present(
                source_payload.get("generated_at"),
                source_payload.get("generated_utc"),
                payload.get("generated_at"),
                payload.get("generated_utc"),
            )
        )
        event_dt = _strict_aware_utc_time(event_time)
        generated_dt = _strict_aware_utc_time(generated_at)
        available_dt = _strict_aware_utc_time(available_at)
        observed_at = _utc_iso()
        observed_dt = _strict_aware_utc_time(observed_at)
        if (
            event_dt is None
            or generated_dt is None
            or available_dt is None
            or observed_dt is None
            or event_dt > generated_dt
            or generated_dt > available_dt
            or available_dt > observed_dt
        ):
            # A partial earlier key must not hide a complete later source.
            continue
        explicit_cadence_seconds = _coerce_float(
            _first_present(
                source_payload.get("expected_update_interval_seconds"),
                source_payload.get("refresh_interval_seconds"),
                payload.get("expected_update_interval_seconds"),
                payload.get("refresh_interval_seconds"),
            )
        )
        if explicit_cadence_seconds is not None and explicit_cadence_seconds > 0.0:
            cadence_seconds = explicit_cadence_seconds
            cadence_source = "PRODUCER_DECLARED_EXPECTED_UPDATE_INTERVAL"
        elif key.endswith(f"market:funding:{normalized}"):
            # Binance premium-index evidence is a rapid market-data contract;
            # this immutable PIT safety cadence is not a trading threshold.
            cadence_seconds = 5.0
            cadence_source = "BINANCE_PREMIUM_INDEX_PIT_SAFETY_CONTRACT"
        else:
            continue
        freshness_budget_seconds = cadence_seconds * PAPER_SIGNAL_ADAPTIVE_STALE_CANDLE_MULTIPLIER
        evidence_age_seconds = max(
            0.0,
            (observed_dt - event_dt).total_seconds(),
        )
        if evidence_age_seconds > freshness_budget_seconds:
            continue
        resolved_field_sources = {
            "mark_price": f"{selected_path}.markPrice|mark_price",
            "index_price": f"{selected_path}.indexPrice|index_price",
            "event_time": f"{selected_path}.time|timestamp|E|event_time",
            "available_at": (f"{selected_path}.available_at|root.available_at|root.fetched_utc"),
            "generated_at": (
                f"{selected_path}.generated_at|generated_utc|" "root.generated_at|generated_utc"
            ),
        }
        source_material = {
            "redis_key": key,
            "outer_payload": payload,
            "selected_path": selected_path,
            "selected_payload": source_payload,
            "resolved_field_sources": resolved_field_sources,
        }
        return {
            "mark_price": mark,
            "index_price": index,
            "mark_index_divergence": round(divergence, 12),
            "mark_index_divergence_bps": round(divergence * 10_000.0, 8),
            "mark_index_source": f"{MARK_INDEX_SOURCE_V2_FUNDING}:{key}",
            "mark_index_event_time": event_time,
            "mark_index_available_at": available_at,
            "mark_index_generated_at": generated_at,
            "mark_index_observed_at": observed_at,
            "mark_index_source_material": source_material,
            "mark_index_source_hash": _altdata_feature_hash(source_material),
            "mark_index_source_hash_contract": (
                "REDIS_KEY_OUTER_SELECTED_PATH_PAYLOAD_AND_FIELD_MAP_SHA256_V2"
            ),
            "mark_index_expected_cadence_seconds": cadence_seconds,
            "mark_index_expected_cadence_source": cadence_source,
            "mark_index_freshness_budget_seconds": freshness_budget_seconds,
            "mark_index_evidence_age_seconds": evidence_age_seconds,
            "mark_index_freshness_state": "CURRENT",
        }
    return {}


def _read_v2_long_short_ratio_evidence(r, symbol: str) -> dict[str, Any]:
    """Read V2-owned global long/short account-ratio telemetry."""
    if r is None or not symbol:
        return {}
    normalized = str(symbol).upper()
    key = f"{V2_REDIS_PREFIX}market:long_short:{normalized}"
    payload = _read_json_key(r, key)
    if not payload:
        return {}
    ratio = _coerce_float(
        _first_present(payload.get("long_short_ratio"), payload.get("longShortRatio"))
    )
    if ratio is None or ratio <= 0.0:
        return {}
    long_account = _coerce_float(
        _first_present(payload.get("long_account_ratio"), payload.get("longAccount"))
    )
    short_account = _coerce_float(
        _first_present(payload.get("short_account_ratio"), payload.get("shortAccount"))
    )
    source_event_time = _timestamp_to_utc_iso(
        _first_present(
            payload.get("timestamp"),
            payload.get("time"),
            payload.get("event_time"),
            payload.get("E"),
        )
    )
    available_at = _timestamp_to_utc_iso(
        _first_present(
            payload.get("available_at"),
            payload.get("fetched_utc"),
        )
    )
    source_material = {"redis_key": key, "payload": payload}
    return {
        "long_short_ratio": ratio,
        "long_account_ratio": long_account,
        "short_account_ratio": short_account,
        "long_short_period": payload.get("period"),
        "long_short_source": f"{payload.get('source') or 'v2_market_long_short'}:{key}",
        "long_short_event_time": source_event_time,
        "long_short_available_at": available_at,
        "long_short_captured_at": _utc_iso(),
        "long_short_source_material": source_material,
        "long_short_source_hash": _altdata_feature_hash(source_material),
        "long_short_source_hash_contract": (
            "REDIS_KEY_AND_FULL_CANONICAL_SOURCE_PAYLOAD_SHA256_V1"
        ),
    }


def _attach_long_short_ratio_context(
    intent: dict[str, Any], evidence: dict[str, Any] | None
) -> None:
    """Attach strictly ordered long/short evidence used by adaptive B sizing."""
    if not isinstance(evidence, dict) or evidence.get("long_short_ratio") in (None, ""):
        intent["long_short_ratio_status"] = "MISSING_V2_LONG_SHORT_RATIO"
        return

    # This evidence is read for the later B-grade floor/budget decision.  Its
    # consumer decision is therefore the runtime capture boundary, not the
    # older model/feature decision carried by the candidate.
    decision_time = evidence.get("long_short_captured_at")
    available_at = evidence.get("long_short_available_at")
    event_time = evidence.get("long_short_event_time")
    decision_dt = _strict_aware_utc_time(decision_time)
    available_dt = _strict_aware_utc_time(available_at)
    event_dt = _strict_aware_utc_time(event_time)

    def _record_rejected_long_short_evidence() -> None:
        intent["long_short_ratio_decision_effect"] = (
            "REJECTED_PIT_RAISES_ADAPTIVE_B_GRADE_CONFIDENCE_FLOOR"
        )
        for source_field, rejected_field in (
            ("long_short_period", "rejected_long_short_period"),
            ("long_short_source", "rejected_long_short_source"),
            ("long_short_event_time", "rejected_long_short_event_time"),
            ("long_short_available_at", "rejected_long_short_available_at"),
            ("long_short_captured_at", "rejected_long_short_captured_at"),
        ):
            value = evidence.get(source_field)
            if value not in (None, ""):
                intent[rejected_field] = value
        if decision_time not in (None, ""):
            intent["rejected_long_short_decision_time"] = decision_time

    if decision_dt is None:
        intent["long_short_ratio_status"] = "REJECTED_LONG_SHORT_DECISION_TIME_UNPROVEN"
        _record_rejected_long_short_evidence()
        return
    if available_dt is None:
        intent["long_short_ratio_status"] = "REJECTED_LONG_SHORT_AVAILABLE_AT_UNPROVEN"
        _record_rejected_long_short_evidence()
        return
    if event_dt is None:
        intent["long_short_ratio_status"] = "REJECTED_LONG_SHORT_EVENT_TIME_UNPROVEN"
        _record_rejected_long_short_evidence()
        return
    if event_dt > available_dt:
        intent["long_short_ratio_status"] = "REJECTED_LONG_SHORT_EVENT_AFTER_AVAILABLE"
        _record_rejected_long_short_evidence()
        return
    if available_dt > decision_dt:
        intent["long_short_ratio_status"] = "REJECTED_LONG_SHORT_AVAILABLE_AFTER_DECISION"
        _record_rejected_long_short_evidence()
        return
    cadence_seconds = _paper_signal_timeframe_duration_seconds(evidence.get("long_short_period"))
    evidence_age_seconds = (decision_dt - event_dt).total_seconds()
    freshness_budget_seconds = (
        cadence_seconds * PAPER_SIGNAL_ADAPTIVE_STALE_CANDLE_MULTIPLIER
        if cadence_seconds is not None
        else None
    )
    if cadence_seconds is None or freshness_budget_seconds is None:
        intent["long_short_ratio_status"] = "REJECTED_LONG_SHORT_SOURCE_CADENCE_UNPROVEN"
        _record_rejected_long_short_evidence()
        return
    if evidence_age_seconds < 0.0 or evidence_age_seconds > freshness_budget_seconds:
        intent["long_short_ratio_status"] = "REJECTED_LONG_SHORT_EVIDENCE_STALE"
        intent["rejected_long_short_evidence_age_seconds"] = evidence_age_seconds
        intent["rejected_long_short_freshness_budget_seconds"] = freshness_budget_seconds
        _record_rejected_long_short_evidence()
        return
    if (
        not _paper_valid_sha256(evidence.get("long_short_source_hash"))
        or evidence.get("long_short_source_hash_contract")
        != "REDIS_KEY_AND_FULL_CANONICAL_SOURCE_PAYLOAD_SHA256_V1"
    ):
        intent["long_short_ratio_status"] = "REJECTED_LONG_SHORT_SOURCE_HASH_INVALID"
        _record_rejected_long_short_evidence()
        return
    for field in (
        "long_short_ratio",
        "long_account_ratio",
        "short_account_ratio",
        "long_short_period",
        "long_short_source",
        "long_short_event_time",
        "long_short_available_at",
        "long_short_captured_at",
        "long_short_source_material",
        "long_short_source_hash",
        "long_short_source_hash_contract",
    ):
        if evidence.get(field) not in (None, ""):
            intent[field] = evidence.get(field)
    intent["long_short_decision_time"] = decision_time
    intent["long_short_expected_cadence_seconds"] = cadence_seconds
    intent["long_short_freshness_budget_seconds"] = freshness_budget_seconds
    intent["long_short_evidence_age_seconds"] = evidence_age_seconds
    intent["long_short_freshness_state"] = "CURRENT"
    intent["long_short_ratio_status"] = "V2_LONG_SHORT_RATIO_ATTACHED"
    intent["long_short_ratio_decision_effect"] = (
        "PIT_VALID_INPUT_TO_ADAPTIVE_B_GRADE_CONFIDENCE_AND_BUDGET"
    )


def _validated_v2_feature_snapshot_payload(
    payload: Any,
    *,
    redis_key: str,
    decision_time: str,
    expected_feature_snapshot_id: str | None = None,
    expected_symbol: str | None = None,
    expected_timeframe: str | None = None,
) -> dict[str, Any]:
    try:
        parsed_payload = json.loads(payload) if isinstance(payload, str) else payload
    except (TypeError, ValueError):
        return {
            "features": {},
            "unavailable_reason": "INVALID_V2_FEATURE_SNAPSHOT_JSON",
            "redis_key": redis_key,
        }
    if not isinstance(parsed_payload, dict):
        return {
            "features": {},
            "unavailable_reason": "INVALID_V2_FEATURE_SNAPSHOT_PAYLOAD",
            "redis_key": redis_key,
        }
    payload = parsed_payload
    snapshot_id = _first_present(payload.get("feature_snapshot_id"), payload.get("snapshot_id"))
    if expected_feature_snapshot_id and str(snapshot_id or "") != str(expected_feature_snapshot_id):
        return {
            "features": {},
            "unavailable_reason": "FEATURE_SNAPSHOT_ID_MISMATCH",
            "redis_key": redis_key,
            "expected_feature_snapshot_id": expected_feature_snapshot_id,
            "feature_snapshot_id": snapshot_id,
        }
    if expected_symbol and str(payload.get("symbol") or "").upper() != str(expected_symbol).upper():
        return {
            "features": {},
            "unavailable_reason": "FEATURE_SNAPSHOT_SYMBOL_MISMATCH",
            "redis_key": redis_key,
            "expected_symbol": str(expected_symbol).upper(),
            "symbol": payload.get("symbol"),
        }
    if expected_timeframe and str(payload.get("timeframe") or "") != str(expected_timeframe):
        return {
            "features": {},
            "unavailable_reason": "FEATURE_SNAPSHOT_TIMEFRAME_MISMATCH",
            "redis_key": redis_key,
            "expected_timeframe": str(expected_timeframe),
            "timeframe": payload.get("timeframe"),
        }
    if str(payload.get("feature_freshness_state") or "").upper() != "CURRENT":
        return {
            "features": {},
            "unavailable_reason": "NON_CURRENT_V2_FEATURE_SNAPSHOT",
            "feature_freshness_state": payload.get("feature_freshness_state"),
            "redis_key": redis_key,
        }
    if payload.get("candle_closed_confirmed") is not True:
        return {
            "features": {},
            "unavailable_reason": "UNFINISHED_CANDLE_FEATURE_SNAPSHOT_REJECTED",
            "redis_key": redis_key,
        }
    if payload.get("latest_unclosed_kline_excluded") is not True:
        return {
            "features": {},
            "unavailable_reason": "LATEST_UNCLOSED_KLINE_EXCLUSION_UNPROVEN",
            "redis_key": redis_key,
        }
    available_at = payload.get("available_at")
    generated_at = _first_present(
        payload.get("generated_at"),
        payload.get("generated_utc"),
    )
    available_dt = _strict_aware_utc_time(available_at)
    generated_dt = _strict_aware_utc_time(generated_at)
    decision_dt = _strict_aware_utc_time(decision_time)
    if available_dt is None or decision_dt is None:
        return {
            "features": {},
            "unavailable_reason": "FEATURE_SNAPSHOT_TIME_UNPARSEABLE",
            "available_at": available_at,
            "decision_time": decision_time,
            "redis_key": redis_key,
        }
    if generated_dt is None:
        return {
            "features": {},
            "unavailable_reason": "FEATURE_SNAPSHOT_GENERATED_AT_MISSING_OR_UNPARSEABLE",
            "generated_at": generated_at,
            "decision_time": decision_time,
            "redis_key": redis_key,
        }
    if available_dt > decision_dt:
        return {
            "features": {},
            "unavailable_reason": "FEATURE_AVAILABLE_AT_AFTER_DECISION_TIME",
            "available_at": available_at,
            "decision_time": decision_time,
            "redis_key": redis_key,
        }
    feature_cutoff = payload.get("feature_cutoff")
    feature_cutoff_dt = _strict_aware_utc_time(feature_cutoff)
    if feature_cutoff_dt is None:
        return {
            "features": {},
            "unavailable_reason": "FEATURE_CUTOFF_MISSING_OR_UNPARSEABLE",
            "feature_cutoff": feature_cutoff,
            "decision_time": decision_time,
            "redis_key": redis_key,
        }
    candle_close_time = payload.get("candle_close_time")
    candle_close_dt = _strict_aware_utc_time(candle_close_time)
    if candle_close_dt is None:
        return {
            "features": {},
            "unavailable_reason": "CANDLE_CLOSE_TIME_MISSING_OR_UNPARSEABLE",
            "candle_close_time": candle_close_time,
            "decision_time": decision_time,
            "redis_key": redis_key,
        }
    if candle_close_dt > feature_cutoff_dt:
        return {
            "features": {},
            "unavailable_reason": "CANDLE_CLOSE_TIME_AFTER_FEATURE_CUTOFF",
            "candle_close_time": candle_close_time,
            "feature_cutoff": feature_cutoff,
            "redis_key": redis_key,
        }
    if feature_cutoff_dt > decision_dt:
        return {
            "features": {},
            "unavailable_reason": "FEATURE_CUTOFF_AFTER_DECISION_TIME",
            "feature_cutoff": feature_cutoff,
            "decision_time": decision_time,
            "redis_key": redis_key,
        }
    if feature_cutoff_dt > available_dt:
        return {
            "features": {},
            "unavailable_reason": "FEATURE_CUTOFF_AFTER_AVAILABLE_AT",
            "feature_cutoff": feature_cutoff,
            "available_at": available_at,
            "redis_key": redis_key,
        }
    if generated_dt > available_dt:
        return {
            "features": {},
            "unavailable_reason": "FEATURE_GENERATED_AT_AFTER_AVAILABLE_AT",
            "available_at": available_at,
            "generated_at": generated_at,
            "redis_key": redis_key,
        }
    if generated_dt > decision_dt:
        return {
            "features": {},
            "unavailable_reason": "FEATURE_GENERATED_AT_AFTER_DECISION_TIME",
            "generated_at": generated_at,
            "decision_time": decision_time,
            "redis_key": redis_key,
        }
    features = payload.get("features") if isinstance(payload.get("features"), dict) else {}
    if not features:
        return {
            "features": {},
            "unavailable_reason": "EMPTY_V2_FEATURE_SNAPSHOT",
            "redis_key": redis_key,
        }
    return {
        "features": features,
        "redis_key": redis_key,
        "feature_snapshot_id": snapshot_id,
        "symbol": payload.get("symbol"),
        "timeframe": payload.get("timeframe"),
        "feature_freshness_state": payload.get("feature_freshness_state"),
        "available_at": available_at,
        "generated_at": generated_at,
        "feature_cutoff": feature_cutoff,
        "source_available_time": payload.get("source_available_time"),
        "candle_close_time": payload.get("candle_close_time"),
        "candle_closed_confirmed": payload.get("candle_closed_confirmed"),
        "latest_unclosed_kline_excluded": payload.get("latest_unclosed_kline_excluded"),
        "source_hashes": payload.get("source_hashes"),
    }


def _read_v2_feature_snapshot_by_id(
    r,
    feature_snapshot_id: Any,
    *,
    decision_time: str,
    symbol: str | None = None,
    timeframe: str | None = None,
) -> dict[str, Any]:
    if r is None or feature_snapshot_id in (None, ""):
        return {"features": {}, "unavailable_reason": "MISSING_FEATURE_SNAPSHOT_ID_OR_REDIS"}
    snapshot_id = str(feature_snapshot_id)
    key = f"{V2_REDIS_PREFIX}features:snapshot:{snapshot_id}"
    try:
        raw = r.get(key)
    except Exception:
        raw = None
    if not raw:
        return {
            "features": {},
            "unavailable_reason": "MISSING_V2_FEATURE_SNAPSHOT",
            "redis_key": key,
        }
    return _validated_v2_feature_snapshot_payload(
        raw,
        redis_key=key,
        decision_time=decision_time,
        expected_feature_snapshot_id=snapshot_id,
        expected_symbol=symbol,
        expected_timeframe=timeframe,
    )


def _entry_feature_snapshot_evidence(snapshot: dict[str, Any]) -> dict[str, Any] | None:
    features = snapshot.get("features") if isinstance(snapshot.get("features"), dict) else {}
    if not features:
        return None
    evidence = {
        "feature_snapshot_id": snapshot.get("feature_snapshot_id"),
        "symbol": snapshot.get("symbol"),
        "timeframe": snapshot.get("timeframe"),
        "available_at": snapshot.get("available_at"),
        "generated_at": snapshot.get("generated_at"),
        "feature_cutoff": snapshot.get("feature_cutoff"),
        "source_available_time": snapshot.get("source_available_time"),
        "candle_close_time": snapshot.get("candle_close_time"),
        "candle_closed_confirmed": snapshot.get("candle_closed_confirmed"),
        "latest_unclosed_kline_excluded": snapshot.get("latest_unclosed_kline_excluded"),
        "feature_freshness_state": snapshot.get("feature_freshness_state"),
        "source_hashes": snapshot.get("source_hashes"),
        "features": dict(features),
    }
    return {key: value for key, value in evidence.items() if value not in (None, "", {}, [])}


def _read_v2_feature_snapshot(
    r,
    symbol: str,
    timeframe: str | None,
    *,
    decision_time: str,
) -> dict[str, Any]:
    if r is None or not symbol:
        return {"features": {}, "unavailable_reason": "MISSING_SYMBOL_OR_REDIS"}
    normalized_symbol = str(symbol).upper()
    if timeframe in (None, ""):
        return {
            "features": {},
            "unavailable_reason": MISSING_THESIS_TIMEFRAME_BLOCK_REASON,
            "symbol": normalized_symbol,
        }
    normalized_timeframe = str(timeframe).strip()
    if not normalized_timeframe:
        return {
            "features": {},
            "unavailable_reason": MISSING_THESIS_TIMEFRAME_BLOCK_REASON,
            "symbol": normalized_symbol,
        }
    key = f"{V2_REDIS_PREFIX}features:latest:{normalized_symbol}:{normalized_timeframe}"
    try:
        raw = r.get(key)
    except Exception:
        raw = None
    if not raw:
        return {
            "features": {},
            "unavailable_reason": "MISSING_V2_FEATURE_SNAPSHOT",
            "redis_key": key,
        }
    return _validated_v2_feature_snapshot_payload(
        raw,
        redis_key=key,
        decision_time=decision_time,
        expected_symbol=normalized_symbol,
        expected_timeframe=normalized_timeframe,
    )


def _read_v2_feature_snapshot_for_signal(
    r,
    feature_snapshot_id: Any,
    *,
    decision_time: str,
    symbol: str | None = None,
    timeframe: str | None = None,
) -> dict[str, Any]:
    """Resolve the PIT feature snapshot for a signal without trusting stale IDs.

    Strategy-supply materialization rows can carry legacy ``snap_*`` identifiers
    that are not stored in the canonical V2 feature-snapshot namespace. Falling
    back to ``features:latest:{symbol}:{timeframe}`` is safe only when the same
    validator proves symbol/timeframe match, closed-candle state, freshness, and
    available_at/feature_cutoff <= decision_time.
    """
    by_id = _read_v2_feature_snapshot_by_id(
        r,
        feature_snapshot_id,
        decision_time=decision_time,
        symbol=symbol,
        timeframe=timeframe,
    )
    if by_id.get("features"):
        resolved = dict(by_id)
        resolved["requested_feature_snapshot_id"] = feature_snapshot_id
        resolved["feature_snapshot_fallback_used"] = False
        resolved["feature_snapshot_resolution_status"] = "FEATURE_SNAPSHOT_ID_PIT_VALID"
        return resolved

    by_id_reason = by_id.get("unavailable_reason")
    if by_id_reason not in {"MISSING_V2_FEATURE_SNAPSHOT", "MISSING_FEATURE_SNAPSHOT_ID_OR_REDIS"}:
        by_id["requested_feature_snapshot_id"] = feature_snapshot_id
        by_id["feature_snapshot_fallback_used"] = False
        by_id["feature_snapshot_resolution_status"] = "FEATURE_SNAPSHOT_ID_REJECTED_NO_FALLBACK"
        return by_id

    fallback = _read_v2_feature_snapshot(
        r,
        str(symbol or ""),
        timeframe,
        decision_time=decision_time,
    )
    resolved = dict(fallback)
    resolved["requested_feature_snapshot_id"] = feature_snapshot_id
    resolved["feature_snapshot_unavailable_reason_before_fallback"] = by_id_reason
    resolved["feature_snapshot_requested_redis_key"] = by_id.get("redis_key")
    if fallback.get("features"):
        resolved["feature_snapshot_fallback_used"] = True
        resolved["feature_snapshot_resolution_status"] = (
            "FEATURE_SNAPSHOT_LATEST_FALLBACK_PIT_VALID_AFTER_MISSING_ID"
        )
    else:
        resolved["feature_snapshot_fallback_used"] = False
        resolved["feature_snapshot_resolution_status"] = (
            "FEATURE_SNAPSHOT_MISSING_ID_AND_LATEST_FALLBACK_UNAVAILABLE"
        )
    return resolved


def _attach_entry_price_provenance(
    intent: dict,
    price: float | None,
    source: str,
    source_available_at: str | None,
) -> None:
    """Attach the observed paper price and its observation provenance.

    Price observation precedes final paper admission.  ``fill_price_utc`` is
    retained as a legacy observation-time alias; actual ``entry_time`` and
    ``execution_time`` are stamped only at the accepted-list materialization
    boundary by :func:`_paper_stamp_fill_materialization_time`.
    """
    now = _utc_iso()
    if price is not None and price > 0:
        intent["entry_price"] = float(price)
        intent["entry_price_source"] = source
        intent["entry_price_utc"] = now
        # The price reader proves observability, not producer generation.
        # Never duplicate one clock under two semantic names.
        intent["entry_price_source_generated_utc"] = None
        intent["entry_price_source_available_at"] = source_available_at
        intent["fill_price"] = float(price)
        intent["fill_price_source"] = source
        intent["fill_price_utc"] = now
        intent["fill_price_observed_at"] = now
        intent["latest_price"] = float(price)
        intent["latest_price_source"] = source
        intent["latest_price_utc"] = now
        intent["entry_price_provenance_present"] = True
        intent["entry_price_blocker"] = None
    else:
        intent["entry_price"] = None
        intent["entry_price_source"] = source or ENTRY_PRICE_BLOCKER_MISSING_FILL
        intent["entry_price_utc"] = None
        intent["entry_price_source_generated_utc"] = None
        intent["entry_price_source_available_at"] = None
        intent["fill_price"] = None
        intent["fill_price_source"] = source or ENTRY_PRICE_BLOCKER_MISSING_FILL
        intent["fill_price_utc"] = None
        intent["fill_price_observed_at"] = None
        intent["latest_price"] = None
        intent["latest_price_source"] = source or ENTRY_PRICE_BLOCKER_MISSING_FILL
        intent["latest_price_utc"] = None
        intent["entry_price_provenance_present"] = False
        intent["entry_price_blocker"] = ENTRY_PRICE_BLOCKER_MISSING_FILL


def _attach_paper_execution_evidence(
    intent: dict[str, Any],
    mark_index: dict[str, Any] | None = None,
) -> None:
    """Attach paper-only execution evidence known before any outcome label."""
    fill_time = _first_present(
        intent.get("fill_price_utc"), intent.get("entry_price_utc"), intent.get("generated_utc")
    )
    fill_dt = _parse_strategy_time(fill_time)
    decision_time = None
    decision_dt = None
    for candidate_time in (
        intent.get("entry_feature_decision_time"),
        intent.get("decision_time"),
        intent.get("entry_spread_decision_time"),
        intent.get("generated_at"),
        intent.get("generated_utc"),
    ):
        parsed = _parse_strategy_time(candidate_time)
        if parsed is None:
            continue
        if fill_dt is not None and parsed > fill_dt:
            continue
        decision_time = candidate_time
        decision_dt = parsed
        break
    if (
        intent.get("latency_ms") in (None, "")
        and fill_dt is not None
        and decision_dt is not None
        and fill_dt >= decision_dt
    ):
        latency_ms = round((fill_dt - decision_dt).total_seconds() * 1000.0, 3)
        intent["latency_ms"] = latency_ms
        intent["decision_latency_ms"] = latency_ms
        intent["paper_fill_latency_ms"] = latency_ms
        intent["fill_latency_ms"] = latency_ms
        intent["execution_latency_ms"] = latency_ms
        intent["simulated_latency_ms"] = latency_ms
        intent["latency_source"] = "PAPER_DECISION_TO_FILL_RUNTIME_TIMESTAMPS"

    spread = _coerce_float(intent.get("actual_observed_spread_entry_bps"))
    fill_price = _coerce_float(_first_present(intent.get("fill_price"), intent.get("entry_price")))
    if (
        intent.get("maker_probability") in (None, "")
        and intent.get("taker_probability") in (None, "")
        and intent.get("entry_price_provenance_present") is True
        and spread is not None
        and fill_price is not None
        and fill_price > 0.0
    ):
        intent["maker_probability"] = 0.0
        intent["taker_probability"] = 1.0
        intent["maker_taker_probability"] = 1.0
        intent["maker_taker_probabilities"] = {"maker": 0.0, "taker": 1.0}
        intent["maker_taker_probability_source"] = PAPER_IMMEDIATE_FILL_TAKER_SOURCE

    quantity = _coerce_float(_first_present(intent.get("quantity"), intent.get("target_quantity")))
    notional = _coerce_float(
        _first_present(
            intent.get("notional"),
            intent.get("notional_usdt"),
            intent.get("gross_notional_usd"),
            intent.get("target_notional_usdt"),
        )
    )
    if notional is None and quantity is not None and fill_price is not None:
        notional = quantity * fill_price
    partial_rows = (
        intent.get("partial_fills") if isinstance(intent.get("partial_fills"), list) else []
    )
    existing_partial = partial_rows[0] if partial_rows and isinstance(partial_rows[0], dict) else {}
    existing_partial_quantity = _coerce_float(existing_partial.get("quantity"))
    existing_partial_price = _coerce_float(existing_partial.get("price"))
    existing_partial_notional = _coerce_float(existing_partial.get("notional_usd"))
    quantity_changed = quantity is not None and (
        existing_partial_quantity is None
        or abs(existing_partial_quantity - quantity) > max(1e-12, abs(quantity) * 1e-9)
    )
    price_changed = fill_price is not None and (
        existing_partial_price is None
        or abs(existing_partial_price - fill_price) > max(1e-12, abs(fill_price) * 1e-9)
    )
    notional_changed = notional is not None and (
        existing_partial_notional is None
        or abs(existing_partial_notional - notional) > max(1e-8, abs(notional) * 1e-9)
    )
    if (
        quantity is not None
        and quantity > 0.0
        and fill_price is not None
        and fill_price > 0.0
        and (
            intent.get("partial_fill_count") in (None, "")
            or not partial_rows
            or quantity_changed
            or price_changed
            or notional_changed
        )
    ):
        partial = {
            "fill_sequence": 1,
            "quantity": quantity,
            "price": fill_price,
            "notional_usd": round(float(notional), 8) if notional is not None else None,
            "fill_time": fill_time,
            "source": "PAPER_SINGLE_FILL_LEDGER_RECORD",
            "paper_only": True,
            "places_real_order": False,
        }
        intent["partial_fill_count"] = 1
        intent["fill_count"] = 1
        intent["partial_fills"] = [partial]
        intent["all_partial_fills"] = [partial]
        intent["partial_fill_plan"] = {
            "model": "PAPER_SINGLE_IMMEDIATE_FILL",
            "expected_fill_count": 1,
            "source": "PAPER_LEDGER_ACCEPTED_FILL",
        }

    mark_index = mark_index if isinstance(mark_index, dict) else {}
    mark = _coerce_float(mark_index.get("mark_price"))
    index = _coerce_float(mark_index.get("index_price"))
    if mark is not None and index is not None and mark > 0.0 and index > 0.0:
        intent["mark_price"] = mark
        intent["index_price"] = index
        intent["mark_index_divergence"] = mark_index.get("mark_index_divergence")
        intent["mark_index_divergence_bps"] = mark_index.get("mark_index_divergence_bps")
        intent["mark_index_source"] = mark_index.get("mark_index_source")
        for field in (
            "mark_index_event_time",
            "mark_index_available_at",
            "mark_index_generated_at",
            "mark_index_observed_at",
            "mark_index_source_material",
            "mark_index_source_hash",
            "mark_index_source_hash_contract",
            "mark_index_expected_cadence_seconds",
            "mark_index_expected_cadence_source",
            "mark_index_freshness_budget_seconds",
            "mark_index_evidence_age_seconds",
            "mark_index_freshness_state",
        ):
            intent[field] = mark_index.get(field)


def _depth_vwap_for_quantity(
    levels: list[dict[str, float]],
    quantity: float,
) -> tuple[float | None, float, bool]:
    if quantity <= 0.0:
        return None, 0.0, False
    remaining = float(quantity)
    filled = 0.0
    notional = 0.0
    for level in levels:
        price = _coerce_float(level.get("price"))
        available = _coerce_float(level.get("quantity"))
        if price is None or available is None or price <= 0.0 or available <= 0.0:
            continue
        take = min(remaining, available)
        filled += take
        notional += take * price
        remaining -= take
        if remaining <= 1e-12:
            break
    if filled <= 0.0:
        return None, 0.0, False
    return notional / filled, filled, remaining <= 1e-12


def _attach_depth_price_impact_evidence(
    intent: dict[str, Any],
    market_microstructure: dict[str, Any] | None,
) -> None:
    if intent.get("depth_price_impact_bps") not in (None, ""):
        return
    market_microstructure = market_microstructure if isinstance(market_microstructure, dict) else {}
    side = str(_first_present(intent.get("side"), intent.get("selected_action")) or "").lower()
    if side not in {"long", "short"}:
        return
    quantity = _coerce_float(_first_present(intent.get("quantity"), intent.get("target_quantity")))
    fill_price = _coerce_float(_first_present(intent.get("fill_price"), intent.get("entry_price")))
    notional = _coerce_float(
        _first_present(
            intent.get("notional"),
            intent.get("notional_usdt"),
            intent.get("gross_notional_usd"),
            intent.get("target_notional_usdt"),
        )
    )
    if quantity is None and notional is not None and fill_price is not None and fill_price > 0.0:
        quantity = abs(notional / fill_price)
    if notional is None and quantity is not None and fill_price is not None and fill_price > 0.0:
        notional = abs(quantity * fill_price)
    if quantity is None or quantity <= 0.0:
        return

    levels_key = "ask_levels_top5" if side == "long" else "bid_levels_top5"
    levels = market_microstructure.get(levels_key)
    if not isinstance(levels, list):
        levels = []
    levels = [
        {"price": float(level["price"]), "quantity": float(level["quantity"])}
        for level in levels
        if isinstance(level, dict)
        and _coerce_float(level.get("price")) is not None
        and _coerce_float(level.get("quantity")) is not None
        and float(level["price"]) > 0.0
        and float(level["quantity"]) > 0.0
    ]
    if not levels:
        return
    vwap, filled_quantity, fill_complete = _depth_vwap_for_quantity(levels, quantity)
    if vwap is None or filled_quantity <= 0.0:
        return
    touch = _coerce_float(market_microstructure.get("best_ask" if side == "long" else "best_bid"))
    if touch is None:
        touch = levels[0]["price"]
    mid = _coerce_float(market_microstructure.get("mid_price"))
    if mid is None or mid <= 0.0:
        best_bid = _coerce_float(market_microstructure.get("best_bid"))
        best_ask = _coerce_float(market_microstructure.get("best_ask"))
        if best_bid is not None and best_ask is not None and best_bid > 0.0 and best_ask > 0.0:
            mid = (best_bid + best_ask) / 2.0
    if mid is None or mid <= 0.0 or touch <= 0.0:
        return

    if side == "long":
        impact_bps = max(0.0, ((vwap - touch) / mid) * 10_000.0)
    else:
        impact_bps = max(0.0, ((touch - vwap) / mid) * 10_000.0)
    side_depth_field = "ask_depth_usd" if side == "long" else "bid_depth_usd"
    side_depth = _coerce_float(market_microstructure.get(side_depth_field))
    if side_depth is not None and side_depth > 0.0:
        intent.setdefault("entry_orderbook_depth_usd", round(float(side_depth), 8))
        intent.setdefault("entry_orderbook_depth_side", "ask" if side == "long" else "bid")
    if notional is not None and side_depth is not None and side_depth > 0.0:
        intent["depth_utilization_pct"] = round(float(notional) / float(side_depth), 10)
    intent["depth_price_impact_bps"] = round(float(impact_bps), 8)
    intent["depth_price_impact_source"] = (
        f"{market_microstructure.get('source') or ENTRY_SPREAD_SOURCE_V2_ORDERBOOK}:"
        f"{levels_key}:top5_vwap_vs_touch"
    )
    intent["depth_price_impact_model"] = "ORDERBOOK_TOP5_VWAP_VS_TOUCH"
    intent["depth_price_impact_side"] = "ask" if side == "long" else "bid"
    intent["depth_price_impact_quantity"] = round(float(quantity), 12)
    intent["depth_price_impact_filled_quantity"] = round(float(filled_quantity), 12)
    intent["depth_price_impact_fill_complete"] = bool(fill_complete)
    intent["depth_price_impact_vwap"] = round(float(vwap), 12)
    intent["depth_price_impact_touch_price"] = round(float(touch), 12)


def _runtime_cost_capture_no_order_reason(intent: dict[str, Any]) -> str | None:
    size = _coerce_float(
        _first_present(
            intent.get("order_size"),
            intent.get("order_size_usd"),
            intent.get("gross_notional_usd"),
            intent.get("target_notional_usdt"),
            intent.get("notional_usdt"),
            intent.get("notional"),
        )
    )
    if size is not None and size > 0.0:
        return None

    tier = (
        str(
            _first_present(
                intent.get("paper_opportunity_tier"),
                intent.get("paper_execution_tier"),
                intent.get("opportunity_tier"),
                intent.get("candidate_tier"),
            )
            or ""
        )
        .strip()
        .upper()
    )
    allocator_decision = str(intent.get("allocator_decision") or "").strip().upper()
    paper_fill_allowed = intent.get("paper_fill_allowed")

    if tier == PAPER_TIER_NO_TRADE:
        return "NO_TRADE_ZERO_SIZE_PAPER_INTENT"
    if tier in NON_EXECUTABLE_PAPER_TIERS:
        return f"{tier}_ZERO_SIZE_NON_EXECUTABLE_PAPER_INTENT"
    if allocator_decision.startswith("BLOCK_"):
        return "ADAPTIVE_ALLOCATOR_ZERO_SIZE_BLOCKED_PAPER_INTENT"
    if paper_fill_allowed is False:
        return "PAPER_FILL_NOT_ALLOWED_ZERO_SIZE_INTENT"
    return None


def _runtime_cost_capture_source_family(cost_source: Any) -> tuple[str | None, bool]:
    if cost_source in (None, ""):
        return None, False
    source_prefix = str(cost_source).strip().split(":", 1)[0].strip()
    if not source_prefix:
        return None, False
    source_family = RUNTIME_COST_CAPTURE_ALLOWED_COST_SOURCE_PREFIX_FAMILIES.get(source_prefix)
    return (
        source_family,
        source_family in RUNTIME_COST_CAPTURE_ALLOWED_COST_SOURCE_FAMILIES,
    )


def _attach_runtime_cost_capture_contract(
    intent: dict[str, Any],
    market_microstructure: dict[str, Any] | None = None,
    *,
    signal: dict[str, Any] | None = None,
    prediction: dict[str, Any] | None = None,
) -> None:
    """Attach the pre-outcome challenger paper cost-capture contract."""
    market_microstructure = market_microstructure if isinstance(market_microstructure, dict) else {}
    signal = signal if isinstance(signal, dict) else {}
    prediction = prediction if isinstance(prediction, dict) else {}
    allocation_context = (
        intent.get("adaptive_allocation")
        if isinstance(intent.get("adaptive_allocation"), dict)
        else {}
    )

    candidate_id = _first_present(
        intent.get("candidate_id"),
        prediction.get("candidate_id"),
        signal.get("candidate_id"),
        CHALLENGER_V2_ACTIVE_CUDA_CANDIDATE_ID,
    )
    policy_fingerprint = _first_present(
        intent.get("policy_fingerprint"),
        intent.get("selector_policy_fingerprint"),
        prediction.get("policy_fingerprint"),
        prediction.get("selector_policy_fingerprint"),
        signal.get("policy_fingerprint"),
        CHALLENGER_V2_ACTIVE_CUDA_POLICY_FINGERPRINT,
    )
    model_source = _first_present(
        intent.get("model_source"),
        prediction.get("model_source"),
        signal.get("model_source"),
        CHALLENGER_V2_MODEL_SOURCE,
    )
    policy_owner = str(
        _first_present(
            intent.get("paper_policy_owner"),
            prediction.get("paper_policy_owner"),
            signal.get("paper_policy_owner"),
            PAPER_POLICY_OWNER_CHALLENGER_V2,
        )
    )
    policy_id = _first_present(
        intent.get("policy_id"),
        prediction.get("policy_id"),
        signal.get("policy_id"),
        candidate_id,
    )
    if policy_owner == PAPER_POLICY_OWNER_CHALLENGER_V2:
        deprecated_candidate_ids = {
            CHALLENGER_V2_FROZEN_CANDIDATE_ID,
            CHALLENGER_V2_PREVIOUS_ACTIVE_CUDA_CANDIDATE_ID,
        }
        if candidate_id in deprecated_candidate_ids:
            candidate_id = CHALLENGER_V2_ACTIVE_CUDA_CANDIDATE_ID
        if policy_id in deprecated_candidate_ids:
            policy_id = CHALLENGER_V2_ACTIVE_CUDA_CANDIDATE_ID
        if policy_fingerprint in (
            None,
            "",
            OUT_OF_SAMPLE_REVERIFY_SELECTOR_POLICY_FINGERPRINT,
            CHALLENGER_V2_PREVIOUS_ACTIVE_CUDA_POLICY_FINGERPRINT,
        ):
            policy_fingerprint = CHALLENGER_V2_ACTIVE_CUDA_POLICY_FINGERPRINT
    intent["candidate_id"] = candidate_id
    intent["policy_id"] = policy_id
    intent["paper_policy_owner"] = policy_owner
    intent["policy_fingerprint"] = policy_fingerprint
    intent.setdefault(
        "selector_policy_fingerprint", OUT_OF_SAMPLE_REVERIFY_SELECTOR_POLICY_FINGERPRINT
    )
    intent.setdefault(
        "frozen_selector_fingerprint", OUT_OF_SAMPLE_REVERIFY_SELECTOR_POLICY_FINGERPRINT
    )
    intent["model_source"] = model_source
    model_decision_time = _first_present(
        intent.get("model_decision_time"),
        intent.get("entry_feature_decision_time"),
        intent.get("decision_time"),
        prediction.get("decision_time"),
        signal.get("decision_time"),
    )
    if model_decision_time is not None:
        intent["model_decision_time"] = model_decision_time
    intent["snapshot_id"] = _first_present(
        intent.get("snapshot_id"),
        intent.get("entry_feature_snapshot_id"),
        intent.get("feature_snapshot_id"),
        intent.get("mtf_snapshot_id"),
        prediction.get("feature_snapshot_id"),
    )
    intent["predicted_direction"] = _first_present(
        intent.get("predicted_direction"),
        intent.get("side"),
        intent.get("selected_action"),
        prediction.get("selected_action"),
        signal.get("selected_action"),
    )
    predicted_move = _first_present(
        intent.get("predicted_move"),
        intent.get("predicted_move_bps"),
        intent.get("expected_move_bps"),
        prediction.get("expected_move_bps"),
        signal.get("expected_move_bps"),
    )
    intent["predicted_move"] = predicted_move
    intent["predicted_move_bps"] = predicted_move
    intent["score"] = _first_present(
        intent.get("score"),
        intent.get("selected_action_probability"),
        intent.get("confidence_calibrated"),
        prediction.get("score"),
        prediction.get("selected_action_probability"),
        prediction.get("confidence_calibrated"),
        signal.get("score"),
        signal.get("confidence_calibrated"),
    )
    intent["challenger_canary_id"] = CHALLENGER_B_GRADE_PAPER_CANARY
    intent["challenger_canary_profile"] = CHALLENGER_B_GRADE_PAPER_CANARY
    intent["paper_canary_profile"] = CHALLENGER_B_GRADE_PAPER_CANARY
    intent["paper_canary_adaptive_sizing_required"] = True
    intent["paper_canary_fixed_notional_allowed"] = False
    intent["paper_canary_live_routing_allowed"] = False
    intent["routes_to_live"] = False
    intent["paper_only"] = True
    intent["places_real_order"] = False
    intent["live_order"] = False
    intent["test_order"] = False
    intent["counts_as_a_grade_evidence"] = False
    intent["a_grade_promotion_allowed"] = False

    order_size = _coerce_float(
        _first_present(
            intent.get("notional_usdt"),
            intent.get("notional"),
            intent.get("gross_notional_usd"),
            intent.get("target_notional_usdt"),
            intent.get("order_size"),
            intent.get("order_size_usd"),
        )
    )
    if order_size is not None:
        order_size = abs(float(order_size))
        intent["order_size"] = order_size
        intent["order_size_usd"] = order_size
        intent.setdefault("gross_notional_usd", order_size)

    observed_bid = _coerce_float(
        _first_present(
            intent.get("observed_bid"),
            intent.get("best_bid"),
            market_microstructure.get("best_bid"),
        )
    )
    observed_ask = _coerce_float(
        _first_present(
            intent.get("observed_ask"),
            intent.get("best_ask"),
            market_microstructure.get("best_ask"),
        )
    )
    observed_spread = _coerce_float(
        _first_present(
            intent.get("observed_spread_bps"),
            intent.get("actual_observed_spread_entry_bps"),
            intent.get("observed_bid_ask_spread_bps"),
            market_microstructure.get("bid_ask_spread_bps"),
        )
    )
    if (
        observed_spread is None
        and observed_bid
        and observed_ask
        and observed_bid > 0
        and observed_ask > 0
    ):
        mid = (observed_bid + observed_ask) / 2.0
        if mid > 0.0:
            observed_spread = abs(observed_ask - observed_bid) / mid * 10_000.0
    if observed_bid is not None:
        intent["observed_bid"] = observed_bid
        intent.setdefault("best_bid", observed_bid)
    if observed_ask is not None:
        intent["observed_ask"] = observed_ask
        intent.setdefault("best_ask", observed_ask)
    if observed_spread is not None:
        intent["observed_spread_bps"] = observed_spread
        intent["actual_observed_spread_entry_bps"] = observed_spread
        intent.setdefault("observed_bid_ask_spread_bps", observed_spread)

    top_bid_depth = _coerce_float(
        _first_present(
            intent.get("top_book_bid_depth_usd"),
            intent.get("bid_depth_usd"),
            market_microstructure.get("bid_depth_usd"),
        )
    )
    top_ask_depth = _coerce_float(
        _first_present(
            intent.get("top_book_ask_depth_usd"),
            intent.get("ask_depth_usd"),
            market_microstructure.get("ask_depth_usd"),
        )
    )
    market_depth = _coerce_float(
        _first_present(
            intent.get("market_depth_usd"),
            intent.get("orderbook_depth_usd"),
            market_microstructure.get("market_depth_usd"),
            market_microstructure.get("orderbook_depth_usd"),
            min(top_bid_depth, top_ask_depth)
            if top_bid_depth is not None and top_ask_depth is not None
            else None,
        )
    )
    if top_bid_depth is not None:
        intent["top_book_bid_depth_usd"] = top_bid_depth
        intent.setdefault("bid_depth_usd", top_bid_depth)
    if top_ask_depth is not None:
        intent["top_book_ask_depth_usd"] = top_ask_depth
        intent.setdefault("ask_depth_usd", top_ask_depth)
    if market_depth is not None:
        intent["market_depth_usd"] = market_depth
        intent.setdefault("orderbook_depth_usd", market_depth)
        intent.setdefault("top_of_book_depth_usd", market_depth)

    for field in (
        "microstructure_trust_source",
        "public_orderbook_trust_score",
        "composite_microstructure_trust_score",
        "microstructure_trust_score",
        "microstructure_adaptive_minimum",
        "orderbook_trust_score",
        "orderbook_trust_tier",
        "microstructure_action",
        "final_a_plus_min_composite_trust",
        "final_a_plus_eligible",
        "final_a_plus_requires_composite_trust",
        "non_book_confirmation_pass",
        "composite_confirmation_passes",
        "composite_confirmation_missing_fields",
        "feed_integrity_pass",
        "sequence_gap_free",
        "latency_within_bound",
        "trade_tape_confirmation_pass",
        "cross_venue_confirmation_pass",
        "liquidation_sweep_risk_acceptable",
        "oi_funding_long_short_confirmation_pass",
        "real_spread_depth_cost_evidence_pass",
        "reduced_size_bootstrap_tier",
        "reduced_size_counts_as_final_a_plus",
        "reduced_size_routes_to_live",
        "reduced_size_paper_only",
        "bootstrap_reduced_size_paper_only",
        "orderbook_latency_ms",
        "book_sequence_gap",
        "book_depth_persistence_score",
        "book_cancel_pressure_score",
        "trade_tape_confirmation_score",
        "cross_venue_confirmation_score",
        "liquidation_zone_risk_score",
        "sweep_risk_score",
        "microstructure_missing_components",
        "microstructure_decision_time",
        "microstructure_available_at",
    ):
        value = _first_present(intent.get(field), market_microstructure.get(field))
        if value not in (None, ""):
            intent[field] = value

    no_order_reason = _runtime_cost_capture_no_order_reason(intent)
    if no_order_reason is not None and order_size is None:
        order_size = 0.0
        intent["order_size"] = 0.0
        intent["order_size_usd"] = 0.0
        intent.setdefault("gross_notional_usd", 0.0)

    depth_impact = _coerce_float(
        _first_present(
            intent.get("depth_derived_price_impact_bps"),
            intent.get("depth_price_impact_bps"),
            market_microstructure.get("depth_derived_price_impact_bps"),
            market_microstructure.get("depth_price_impact_bps"),
            market_microstructure.get("estimated_price_impact_bps"),
        )
    )
    if depth_impact is not None and intent.get("depth_price_impact_source") in (None, ""):
        intent["depth_price_impact_source"] = _first_present(
            market_microstructure.get("depth_price_impact_source"),
            "V2_MARKET_MICROSTRUCTURE_PAYLOAD:depth_price_impact_bps",
        )
    if depth_impact is not None and intent.get("depth_price_impact_model") in (None, ""):
        intent["depth_price_impact_model"] = _first_present(
            market_microstructure.get("depth_price_impact_model"),
            "DIRECT_ORDERBOOK_FEATURE_ESTIMATE",
        )
    if depth_impact is None and no_order_reason is not None:
        depth_impact = 0.0
        intent["depth_price_impact_source"] = "NO_ORDER_ZERO_SIZE_NO_MARKET_IMPACT"
        intent["depth_price_impact_model"] = "EXPLICIT_ZERO_SIZE_NO_ORDER"
    if depth_impact is not None:
        intent["depth_derived_price_impact_bps"] = depth_impact
        intent["depth_price_impact_bps"] = depth_impact

    maker_probability = _coerce_float(intent.get("maker_probability"))
    taker_probability = _coerce_float(intent.get("taker_probability"))
    maker_taker_probability = _coerce_float(intent.get("maker_taker_probability"))
    maker_taker_assumption = _first_present(intent.get("maker_taker_assumption"))
    if (
        maker_taker_assumption is None
        and maker_probability is not None
        and taker_probability is not None
    ):
        maker_taker_assumption = "maker" if maker_probability > taker_probability else "taker"
    if maker_taker_probability is None and maker_taker_assumption == "maker":
        maker_taker_probability = maker_probability
    if maker_taker_probability is None and maker_taker_assumption == "taker":
        maker_taker_probability = taker_probability
    if maker_taker_assumption is not None:
        intent["maker_taker_assumption"] = str(maker_taker_assumption)
    if maker_taker_probability is not None:
        intent["maker_taker_probability"] = maker_taker_probability
    if maker_probability is not None or taker_probability is not None:
        intent["maker_taker_probability_detail"] = {
            "maker": maker_probability,
            "taker": taker_probability,
        }

    fee_bps = _coerce_float(intent.get("fee_bps"))
    fee_source = _first_present(intent.get("fee_bps_source"), intent.get("fee_schedule_source"))
    if fee_bps is not None:
        intent["fee_schedule"] = {
            "fee_bps": fee_bps,
            "source": fee_source,
            "maker_taker_assumption": intent.get("maker_taker_assumption"),
            "readonly_schedule": bool(intent.get("fee_bps_readonly_schedule")),
            "configured_schedule": bool(intent.get("fee_bps_configured_schedule")),
        }

    expected_funding_bps = _coerce_float(intent.get("expected_funding_bps"))
    funding_rate = _coerce_float(intent.get("funding_rate"))
    if funding_rate is None and expected_funding_bps is not None:
        funding_rate = expected_funding_bps / 10_000.0
        intent["funding_rate"] = funding_rate
    if expected_funding_bps is None and funding_rate is not None:
        expected_funding_bps = funding_rate * 10_000.0
        intent["expected_funding_bps"] = expected_funding_bps
    if expected_funding_bps is not None:
        intent["holding_period_funding_bps"] = expected_funding_bps
        intent["holding_period_funding_source"] = _first_present(
            intent.get("expected_funding_bps_source"),
            intent.get("funding_rate_source"),
            "expected_funding_bps",
        )

    latency_ms = _coerce_float(intent.get("latency_ms"))
    latency_reserve = _coerce_float(
        _first_present(intent.get("latency_reserve_bps"), intent.get("execution_uncertainty_bps"))
    )
    if latency_reserve is None and latency_ms is not None:
        latency_reserve = 0.0
        intent["latency_reserve_source"] = "PAPER_IMMEDIATE_FILL_OBSERVED_LATENCY_ZERO_LIVE_RESERVE"
    elif latency_reserve is not None:
        intent["latency_reserve_source"] = _first_present(
            intent.get("latency_reserve_source"),
            "ADAPTIVE_ALLOCATOR_EXECUTION_UNCERTAINTY_BPS",
        )
    if latency_reserve is not None:
        intent["latency_reserve_bps"] = latency_reserve

    partial_fill_count = _coerce_float(intent.get("partial_fill_count"))
    if partial_fill_count is not None and partial_fill_count > 0:
        expected_fill_count = int(partial_fill_count)
    else:
        expected_fill_count = 1
    if intent.get("partial_fill_estimate") in (None, ""):
        intent["partial_fill_estimate"] = {
            "model": "PAPER_SINGLE_IMMEDIATE_FILL",
            "expected_fill_count": expected_fill_count,
            "expected_fill_probability": 1.0,
            "partial_fill_adjustment_bps": 0.0,
            "source": "PAPER_RUNTIME_FILL_LEDGER_ESTIMATE",
        }
    intent.setdefault("partial_fill_probability", 1.0)
    intent.setdefault("execution_probability", 1.0)
    intent.setdefault("partial_fill_adjustment_bps", 0.0)

    cost_source = _first_present(
        intent.get("cost_source"),
        intent.get("entry_spread_source"),
        market_microstructure.get("source"),
    )
    source_timestamp = _first_present(
        intent.get("cost_source_timestamp"),
        intent.get("source_timestamp"),
        intent.get("entry_spread_available_at"),
        market_microstructure.get("entry_spread_available_at"),
    )
    decision_timestamp = _first_present(
        intent.get("entry_feature_decision_time"),
        intent.get("decision_time"),
        intent.get("generated_at"),
        intent.get("generated_utc"),
    )
    if cost_source is not None:
        intent["cost_source"] = cost_source
    if source_timestamp is not None:
        intent["cost_source_timestamp"] = source_timestamp
        intent["source_timestamp"] = source_timestamp

    temporal_reject_reasons: list[str] = []
    source_reject_reasons: list[str] = []
    cost_source_family, cost_source_allowed = _runtime_cost_capture_source_family(cost_source)
    if cost_source not in (None, ""):
        if cost_source_family is not None:
            intent["cost_source_family"] = cost_source_family
        intent["cost_source_allowed"] = cost_source_allowed
        if not cost_source_allowed:
            source_reject_reasons.append("DISALLOWED_COST_SOURCE")
    source_dt = _parse_strategy_time(source_timestamp)
    runtime_decision_timestamp = _first_present(
        intent.get("paper_admission_decision_time"),
        intent.get("runtime_cost_capture_decision_time"),
        decision_timestamp,
    )
    decision_dt = _parse_strategy_time(runtime_decision_timestamp)
    if source_timestamp is not None and source_dt is None:
        temporal_reject_reasons.append("UNPARSEABLE_COST_SOURCE_TIMESTAMP")
    if source_dt is not None and decision_dt is not None:
        freshness_ms = round((decision_dt - source_dt).total_seconds() * 1000.0, 3)
        intent["cost_evidence_freshness_ms"] = freshness_ms
        if freshness_ms < 0:
            temporal_reject_reasons.append("COST_SOURCE_TIMESTAMP_AFTER_DECISION_TIME")
        elif _coerce_float(intent.get("orderbook_latency_ms")) is None and cost_source_allowed:
            intent["orderbook_latency_ms"] = freshness_ms
            intent["orderbook_latency_source"] = (
                "DERIVED_FROM_COST_SOURCE_TIMESTAMP_AND_RUNTIME_DECISION_TIME"
            )
    microstructure_action = str(intent.get("microstructure_action") or "").upper()
    microstructure_trust_score = _coerce_float(intent.get("microstructure_trust_score"))
    microstructure_minimum_value = intent.get("microstructure_adaptive_minimum")
    microstructure_minimum = _coerce_float(microstructure_minimum_value)
    microstructure_minimum_invalid = bool(
        microstructure_minimum_value not in (None, "")
        and (microstructure_minimum is None or not 0.0 < microstructure_minimum <= 1.0)
    )
    if microstructure_minimum is not None and (
        not math.isfinite(microstructure_minimum) or not 0.0 < microstructure_minimum <= 1.0
    ):
        microstructure_minimum = None
    if no_order_reason is not None and microstructure_trust_score is None:
        intent["microstructure_trust_score"] = 0.0
        intent["microstructure_adaptive_minimum"] = microstructure_minimum
        intent["orderbook_trust_tier"] = "UNTRUSTED_NO_TRADE"
        intent["microstructure_action"] = "NO_TRADE"
        intent["orderbook_latency_ms"] = 0.0
        intent["book_sequence_gap"] = False
        intent["book_depth_persistence_score"] = 0.0
        intent["book_cancel_pressure_score"] = 0.0
        intent["trade_tape_confirmation_score"] = 0.0
        intent["cross_venue_confirmation_score"] = 0.0
        intent["sweep_risk_score"] = 0.0
        intent["microstructure_trust_source"] = "NO_ORDER_ZERO_SIZE_EXPLICIT_NO_TRADE"
        microstructure_action = "NO_TRADE"
        microstructure_trust_score = 0.0
    if no_order_reason is None:
        if microstructure_action in {"NO_TRADE", "SHADOW_ONLY", "CLOSE_OR_REDUCE_ONLY"}:
            source_reject_reasons.append(f"MICROSTRUCTURE_ACTION_{microstructure_action}")
        elif microstructure_action not in {"ALLOW", "REDUCE_SIZE"}:
            source_reject_reasons.append("MICROSTRUCTURE_ACTION_MISSING_OR_UNKNOWN")
        if microstructure_minimum is None:
            source_reject_reasons.append(
                "MICROSTRUCTURE_ADAPTIVE_MINIMUM_INVALID"
                if microstructure_minimum_invalid
                else "MICROSTRUCTURE_ADAPTIVE_MINIMUM_MISSING"
            )
        elif (
            microstructure_trust_score is not None
            and microstructure_trust_score < microstructure_minimum
        ):
            intent["microstructure_below_adaptive_minimum"] = True
            if microstructure_action == "REDUCE_SIZE":
                intent["runtime_cost_capture_microstructure_trust_policy"] = (
                    "REDUCE_SIZE_BELOW_ADAPTIVE_MINIMUM"
                )
            else:
                source_reject_reasons.append("MICROSTRUCTURE_TRUST_BELOW_ADAPTIVE_MINIMUM")
    intent["microstructure_gate_allows_a_grade"] = bool(
        microstructure_trust_score is not None
        and microstructure_minimum is not None
        and microstructure_trust_score >= microstructure_minimum
        and microstructure_action in {"ALLOW", "REDUCE_SIZE"}
    )
    if decision_timestamp is not None:
        intent["model_decision_time"] = decision_timestamp
    if runtime_decision_timestamp is not None:
        intent["runtime_cost_capture_decision_time"] = runtime_decision_timestamp
        intent.setdefault("decision_time", runtime_decision_timestamp)
    if intent.get("feature_cutoff") in (None, ""):
        feature_cutoff = _first_present(
            intent.get("entry_feature_cutoff"),
            intent.get("feature_cutoff"),
            intent.get("mtf_feature_cutoff"),
            prediction.get("feature_cutoff"),
            signal.get("feature_cutoff"),
        )
        if feature_cutoff not in (None, ""):
            intent["feature_cutoff"] = feature_cutoff
    if intent.get("available_at") in (None, ""):
        available_at = _first_present(
            intent.get("entry_feature_available_at"),
            intent.get("available_at"),
            intent.get("generated_at"),
            intent.get("generated_utc"),
            prediction.get("available_at"),
            signal.get("available_at"),
        )
        if available_at not in (None, ""):
            intent["available_at"] = available_at
    if intent.get("strategy_id") in (None, ""):
        strategy_id = _first_present(
            intent.get("strategy_selected_mode"),
            intent.get("strategy_family"),
            allocation_context.get("strategy_id"),
            allocation_context.get("strategy"),
            prediction.get("strategy_id"),
            signal.get("strategy_id"),
        )
        if strategy_id not in (None, ""):
            intent["strategy_id"] = strategy_id
    if order_size is not None:
        intent.setdefault("gross_notional_usd", order_size)
    allocated_margin = _coerce_float(
        _first_present(
            intent.get("allocated_margin_usd"),
            intent.get("selected_allocated_margin_usd"),
            allocation_context.get("allocated_margin_usd"),
            allocation_context.get("selected_allocated_margin_usd"),
        )
    )
    recommended_leverage = _coerce_float(
        _first_present(
            intent.get("recommended_leverage"),
            allocation_context.get("recommended_leverage"),
            allocation_context.get("leverage_target"),
        )
    )
    effective_leverage = _coerce_float(
        _first_present(
            intent.get("effective_leverage"),
            allocation_context.get("effective_leverage"),
            recommended_leverage,
        )
    )
    recommended_margin_mode = _first_present(
        intent.get("recommended_margin_mode"),
        intent.get("selected_margin_mode"),
        allocation_context.get("recommended_margin_mode"),
        allocation_context.get("selected_margin_mode"),
        allocation_context.get("margin_mode"),
    )
    if no_order_reason is not None:
        allocated_margin = 0.0 if allocated_margin is None else allocated_margin
        recommended_leverage = 0.0 if recommended_leverage is None else recommended_leverage
        effective_leverage = 0.0 if effective_leverage is None else effective_leverage
        recommended_margin_mode = _first_present(
            recommended_margin_mode,
            "paper_no_order_no_margin",
        )
    if allocated_margin is not None:
        intent["allocated_margin_usd"] = abs(float(allocated_margin))
    if recommended_leverage is not None:
        intent["recommended_leverage"] = float(recommended_leverage)
    if effective_leverage is not None:
        intent["effective_leverage"] = float(effective_leverage)
    if recommended_margin_mode not in (None, ""):
        intent["recommended_margin_mode"] = str(recommended_margin_mode)

    expected_slippage_bps = _coerce_float(intent.get("expected_slippage_bps"))
    estimated_cost_components = [
        fee_bps,
        expected_slippage_bps,
        expected_funding_bps,
        depth_impact,
        latency_reserve,
        _coerce_float(intent.get("partial_fill_adjustment_bps")),
    ]
    if all(component is not None for component in estimated_cost_components):
        estimated_production_cost_bps = round(
            float(
                sum(component for component in estimated_cost_components if component is not None)
            ),
            8,
        )
        intent["estimated_production_cost_bps"] = estimated_production_cost_bps
        intent["estimated_production_cost"] = estimated_production_cost_bps

    required_fields = PHASE2_RUNTIME_COST_CAPTURE_REQUIRED_FIELDS
    validation_required_fields = tuple(
        field
        for field in required_fields
        if field not in PHASE2_RUNTIME_COST_CAPTURE_DERIVED_FLAG_FIELDS
    )
    positive_fields = {
        "observed_bid",
        "observed_ask",
        "order_size",
        "gross_notional_usd",
        "allocated_margin_usd",
        "recommended_leverage",
        "effective_leverage",
        "top_book_bid_depth_usd",
        "top_book_ask_depth_usd",
        "market_depth_usd",
    }
    no_order_zero_allowed_fields = {
        "order_size",
        "gross_notional_usd",
        "allocated_margin_usd",
        "recommended_leverage",
        "effective_leverage",
    }
    missing: list[str] = []
    for field in validation_required_fields:
        value = intent.get(field)
        if field == "fee_schedule":
            if (
                not isinstance(value, dict)
                or _coerce_float(value.get("fee_bps")) is None
                or not value.get("source")
            ):
                missing.append(field)
            continue
        if field == "partial_fill_estimate":
            if not isinstance(value, dict):
                missing.append(field)
            continue
        numeric = _coerce_float(value)
        if field in positive_fields:
            if (
                field in no_order_zero_allowed_fields
                and no_order_reason is not None
                and numeric == 0.0
            ):
                continue
            if numeric is None or numeric <= 0.0:
                missing.append(field)
        elif field in {
            "observed_spread_bps",
            "depth_derived_price_impact_bps",
            "maker_taker_probability",
            "fee_bps",
            "expected_funding_bps",
            "expected_slippage_bps",
            "latency_reserve_bps",
            "mark_index_divergence_bps",
            "cost_evidence_freshness_ms",
            "microstructure_trust_score",
            "orderbook_latency_ms",
            "book_depth_persistence_score",
            "book_cancel_pressure_score",
            "trade_tape_confirmation_score",
            "cross_venue_confirmation_score",
            "sweep_risk_score",
        }:
            if numeric is None:
                missing.append(field)
        elif value in (None, ""):
            missing.append(field)

    explained_missing_fields: list[str] = []
    if no_order_reason is not None:
        explained_missing_fields = list(missing)
    unexplained_missing_fields = [
        field for field in missing if field not in set(explained_missing_fields)
    ]

    component_fallback = any(
        intent.get(field) is True
        for field in (
            "bid_ask_spread_bps_fallback",
            "expected_slippage_bps_fallback",
            "fee_bps_fallback",
            "expected_funding_bps_fallback",
        )
    )
    fallback = bool(
        missing or temporal_reject_reasons or source_reject_reasons or component_fallback
    )
    intent["runtime_cost_capture_required_fields"] = list(required_fields)
    intent["runtime_cost_capture_missing_fields"] = sorted(set(missing))
    intent["runtime_cost_capture_explained_missing_fields"] = sorted(set(explained_missing_fields))
    intent["runtime_cost_capture_unexplained_missing_fields"] = sorted(
        set(unexplained_missing_fields)
    )
    intent["runtime_cost_capture_order_cost_applicable"] = no_order_reason is None
    intent["runtime_cost_capture_no_order_reason"] = no_order_reason
    intent["runtime_cost_capture_temporal_reject_reasons"] = sorted(set(temporal_reject_reasons))
    intent["runtime_cost_capture_source_reject_reasons"] = sorted(set(source_reject_reasons))
    intent["runtime_cost_capture_source"] = "V2_PAPER_RUNTIME_DECISION_TIME_COST_CAPTURE"
    intent["runtime_cost_capture_status"] = (
        "PRODUCTION_GRADE_COST_CAPTURE" if not fallback else "FALLBACK_OR_INCOMPLETE_COST_CAPTURE"
    )
    intent["fallback_cost_flag"] = fallback
    intent["fallback"] = fallback
    intent["production_grade_cost_flag"] = not fallback
    intent["production_grade_cost_evidence"] = not fallback
    intent["counts_as_production_grade_training_evidence"] = bool(
        not fallback and no_order_reason is None
    )
    intent["cost_evidence_source_fields"] = {
        "spread": intent.get("entry_spread_source"),
        "depth": intent.get("orderbook_depth_source"),
        "depth_impact": intent.get("depth_price_impact_source"),
        "fee": intent.get("fee_bps_source"),
        "funding": intent.get("expected_funding_bps_source"),
        "latency": intent.get("latency_reserve_source"),
        "microstructure_trust": intent.get("microstructure_trust_source"),
        "microstructure_action": intent.get("microstructure_action"),
        "microstructure_adaptive_minimum": intent.get("microstructure_adaptive_minimum"),
        "partial_fill": (
            intent.get("partial_fill_estimate", {}).get("source")
            if isinstance(intent.get("partial_fill_estimate"), dict)
            else None
        ),
        "mark_index": intent.get("mark_index_source"),
        "cost_source_family": intent.get("cost_source_family"),
        "cost_source_allowed": intent.get("cost_source_allowed"),
    }

    allocation = intent.get("adaptive_allocation")
    if isinstance(allocation, dict):
        for field in RUNTIME_COST_CAPTURE_CONTRACT_FIELDS:
            if intent.get(field) is not None:
                allocation[field] = intent.get(field)


def _active_challenger_runtime_owner_rejection_reasons(intent: dict[str, Any]) -> list[str]:
    expected_fields = (
        ("paper_policy_owner", PAPER_POLICY_OWNER_CHALLENGER_V2),
        ("candidate_id", CHALLENGER_V2_ACTIVE_CUDA_CANDIDATE_ID),
        ("policy_id", CHALLENGER_V2_ACTIVE_CUDA_CANDIDATE_ID),
        ("policy_fingerprint", CHALLENGER_V2_ACTIVE_CUDA_POLICY_FINGERPRINT),
        ("model_source", CHALLENGER_V2_MODEL_SOURCE),
    )
    reasons: list[str] = []
    for field, expected in expected_fields:
        value = intent.get(field)
        if value in (None, ""):
            reasons.append(f"{field}_missing")
        elif str(value) != str(expected):
            reasons.append(f"{field}_mismatch:{value}")
    if intent.get("routes_to_live") is not False:
        reasons.append("routes_to_live_not_false")
    if intent.get("places_real_order") is not False:
        reasons.append("places_real_order_not_false")
    return reasons


def _paper_risk_controller_exploration_owner_rejection_reasons(
    intent: dict[str, Any],
) -> list[str]:
    reasons: list[str] = []
    if (
        str(intent.get("paper_opportunity_tier") or "").strip().upper()
        != PAPER_TIER_RISK_CONTROLLER_EXPLORATION
    ):
        reasons.append("paper_opportunity_tier_not_risk_controller_exploration")
    if intent.get("paper_risk_controller_exploration") is not True:
        reasons.append("paper_risk_controller_exploration_flag_missing")
    if intent.get("paper_only") is not True:
        reasons.append("paper_only_not_true")
    for field in ("routes_to_live", "places_real_order", "live_order", "test_order"):
        if intent.get(field) is True:
            reasons.append(f"{field}_not_false")
    for field in ("counts_as_A_plus", "counts_as_final_a_plus", "counts_as_live_ready"):
        if intent.get(field) is not False:
            reasons.append(f"{field}_not_false")

    risk_decision = str(intent.get("risk_decision") or "").upper()
    if not intent.get("risk_decision_id") or not risk_decision:
        reasons.append("risk_controller_evidence_missing")
    elif any(token in risk_decision for token in ("BLOCK", "NO_TRADE", "REJECT")):
        reasons.append(f"risk_controller_hard_block:{risk_decision}")

    orchestrator_decision = str(intent.get("orchestrator_decision") or "").upper()
    if not intent.get("orchestrator_decision_id") or not orchestrator_decision:
        reasons.append("orchestrator_evidence_missing")
    elif any(token in orchestrator_decision for token in ("BLOCK", "NO_TRADE", "REJECT")):
        reasons.append(f"orchestrator_hard_block:{orchestrator_decision}")

    allocator_decision = str(intent.get("allocator_decision") or "").upper()
    if not intent.get("allocator_decision_id") or not allocator_decision:
        reasons.append("allocator_evidence_missing")
    elif allocator_decision not in {"PASS", "ALLOW_WITH_SIZE", "REDUCE_SIZE"}:
        reasons.append(
            f"allocator_decision_not_exploration_fill_eligible:{allocator_decision or 'MISSING'}"
        )
    if intent.get("production_grade_cost_flag") is not True:
        reasons.append("production_grade_cost_evidence_missing")

    required_numeric_fields = (
        "expected_net_pnl_usd",
        "expected_max_loss_usd",
        "recommended_notional_usd",
        "recommended_leverage",
        "liquidation_buffer_usd",
    )
    for field in required_numeric_fields:
        if _coerce_float(intent.get(field)) is None:
            reasons.append(f"{field}_missing")
    if not str(intent.get("recommended_margin_mode") or "").strip():
        reasons.append("recommended_margin_mode_missing")
    if not str(intent.get("feature_vector_hash") or "").strip():
        reasons.append("feature_vector_hash_missing")
    provider_hashes = intent.get("provider_hashes")
    if not isinstance(provider_hashes, dict) or not provider_hashes:
        reasons.append("provider_hashes_missing")
    exit_plan = intent.get("exit_plan")
    if not isinstance(exit_plan, dict) or not exit_plan:
        reasons.append("exit_plan_missing")

    risk_fraction = _coerce_float(intent.get("risk_budget_fraction_of_normal_adaptive"))
    if risk_fraction is None:
        reasons.append("risk_budget_fraction_missing")
    elif risk_fraction > PAPER_RISK_CONTROLLER_EXPLORATION_MAX_RISK_FRACTION_OF_NORMAL:
        reasons.append("risk_budget_fraction_above_paper_risk_controller_exploration_cap")
    return sorted(set(reasons))


def _positive_edge_probation_owner_rejection_reasons(
    intent: dict[str, Any],
) -> list[str]:
    reasons: list[str] = []
    if (
        str(intent.get("paper_opportunity_tier") or "").strip().upper()
        != PAPER_TIER_POSITIVE_EDGE_PROBATION
    ):
        return reasons
    if intent.get("positive_edge_probation_paper") is not True:
        reasons.append("positive_edge_probation_paper_flag_missing")
    if intent.get("paper_only") is not True:
        reasons.append("paper_only_not_true")
    for field in (
        "routes_to_live",
        "places_real_order",
        "live_order",
        "test_order",
        "order_submitted",
        "test_order_submitted",
        "leverage_mutated",
        "margin_mutated",
    ):
        if intent.get(field) is True:
            reasons.append(f"{field}_not_false")
    for field in ("counts_as_A_plus", "counts_as_final_a_plus", "counts_as_live_ready"):
        if intent.get(field) is not False:
            reasons.append(f"{field}_not_false")
    if intent.get("production_grade_cost_flag") is not True:
        reasons.append("production_grade_cost_evidence_missing")

    exit_plan = intent.get("exit_plan")
    if not isinstance(exit_plan, dict) or not exit_plan:
        exit_plan = build_paper_exploration_exit_plan(intent)
        if isinstance(exit_plan, dict) and exit_plan:
            intent["exit_plan"] = exit_plan
            if _coerce_float(intent.get("expected_max_loss_usd")) is None:
                intent["expected_max_loss_usd"] = exit_plan.get("max_loss_usd")
    if not isinstance(exit_plan, dict) or not exit_plan:
        reasons.append("exit_plan_missing")

    for field in (
        "expected_net_pnl_usd",
        "expected_max_loss_usd",
        "recommended_notional_usd",
        "recommended_leverage",
    ):
        if _coerce_float(intent.get(field)) is None:
            reasons.append(f"{field}_missing")
    if not str(
        _first_present(intent.get("recommended_margin_mode"), intent.get("margin_mode")) or ""
    ).strip():
        reasons.append("recommended_margin_mode_missing")
    if not str(
        _first_present(
            intent.get("feature_vector_hash"),
            intent.get("feature_snapshot_id"),
            intent.get("entry_feature_snapshot_id"),
        )
        or ""
    ).strip():
        reasons.append("feature_hash_missing")
    provider_hashes = _first_present(
        intent.get("provider_hashes"),
        intent.get("provider_feature_hashes"),
        intent.get("source_hashes"),
        intent.get("cost_evidence_source_fields"),
    )
    if not isinstance(provider_hashes, dict) or not provider_hashes:
        reasons.append("provider_lineage_missing")
    preemptive_edge_control = (
        intent.get("preemptive_edge_control")
        if isinstance(intent.get("preemptive_edge_control"), dict)
        else {}
    )
    if not _first_present(
        intent.get("preemptive_decision_id"),
        preemptive_edge_control.get("preemptive_decision_id"),
        intent.get("preemptive_decision"),
    ):
        reasons.append("preemptive_decision_missing")
    if not _first_present(intent.get("risk_decision_id"), intent.get("risk_decision")):
        reasons.append("risk_controller_evidence_missing")
    if not _first_present(
        intent.get("orchestrator_decision_id"),
        intent.get("orchestrator_decision"),
    ):
        reasons.append("orchestrator_evidence_missing")
    return sorted(set(reasons))


def _paper_materialization_queue_owner_rejection_reasons(
    intent: dict[str, Any],
) -> list[str]:
    reasons: list[str] = []
    lifecycle_or_no_trade_strategy_reasons = _paper_lifecycle_or_no_trade_strategy_reasons(
        signal={}, intent=intent
    )
    if lifecycle_or_no_trade_strategy_reasons:
        intent["materialization_queue_entry_evidence_status"] = (
            "REJECTED_LIFECYCLE_OR_NO_TRADE_STRATEGY"
        )
        intent["lifecycle_or_no_trade_strategy_reasons"] = lifecycle_or_no_trade_strategy_reasons
        intent["no_trade_strategy_reasons"] = lifecycle_or_no_trade_strategy_reasons
        reasons.append("LIFECYCLE_OR_NO_TRADE_STRATEGY_NOT_ENTRY_EVIDENCE")
        reasons.extend(
            f"no_trade_entry_evidence:{reason}" for reason in lifecycle_or_no_trade_strategy_reasons
        )
    if not intent.get("materialization_queue_id"):
        reasons.append("materialization_queue_id_missing")
    if intent.get("paper_only") is not True:
        reasons.append("paper_only_not_true")
    for field in (
        "routes_to_live",
        "places_real_order",
        "live_order",
        "test_order",
        "order_submitted",
        "test_order_submitted",
        "leverage_mutated",
        "margin_mutated",
    ):
        if intent.get(field) is True:
            reasons.append(f"{field}_not_false")
    for field in ("counts_as_A_plus", "counts_as_final_a_plus", "counts_as_live_ready"):
        if intent.get(field) is not False:
            reasons.append(f"{field}_not_false")

    risk_decision = str(intent.get("risk_decision") or "").upper()
    if not intent.get("risk_decision_id") or not risk_decision:
        reasons.append("risk_controller_evidence_missing")
    elif any(token in risk_decision for token in ("BLOCK", "NO_TRADE", "REJECT")):
        reasons.append(f"risk_controller_hard_block:{risk_decision}")

    orchestrator_decision = str(intent.get("orchestrator_decision") or "").upper()
    if not intent.get("orchestrator_decision_id") or not orchestrator_decision:
        reasons.append("orchestrator_evidence_missing")
    elif any(token in orchestrator_decision for token in ("BLOCK", "NO_TRADE", "REJECT")):
        reasons.append(f"orchestrator_hard_block:{orchestrator_decision}")

    allocator_decision = str(intent.get("allocator_decision") or "").upper()
    if not intent.get("allocator_decision_id") or not allocator_decision:
        reasons.append("allocator_evidence_missing")
    elif allocator_decision not in {"PASS", "ALLOW_WITH_SIZE", "REDUCE_SIZE"}:
        reasons.append(
            f"allocator_decision_not_exploration_fill_eligible:{allocator_decision or 'MISSING'}"
        )

    for field in (
        "expected_net_pnl_usd",
        "expected_max_loss_usd",
        "recommended_notional_usd",
        "recommended_leverage",
        "liquidation_buffer_usd",
    ):
        if _coerce_float(intent.get(field)) is None:
            reasons.append(f"{field}_missing")
    if not str(intent.get("recommended_margin_mode") or "").strip():
        reasons.append("recommended_margin_mode_missing")
    if not str(intent.get("feature_vector_hash") or "").strip():
        reasons.append("feature_vector_hash_missing")
    provider_hashes = intent.get("provider_hashes")
    if not isinstance(provider_hashes, dict) or not provider_hashes:
        reasons.append("provider_hashes_missing")
    exit_plan = intent.get("exit_plan")
    if not isinstance(exit_plan, dict) or not exit_plan:
        exit_plan = build_paper_exploration_exit_plan(intent)
        if isinstance(exit_plan, dict) and exit_plan:
            intent["exit_plan"] = exit_plan
    if not isinstance(exit_plan, dict) or not exit_plan:
        reasons.append("exit_plan_missing")
    return sorted(set(reasons))


def _restore_materialization_queue_expected_economics(
    *,
    intent: dict[str, Any],
    signal: Mapping[str, Any],
    allocation: dict[str, Any],
) -> None:
    """Record queued economics as historical telemetry, never current truth.

    A queue row was scored at an earlier decision.  Replacing the allocator's
    current expected net PnL with that stale positive value can turn a current
    rejection into an admission.  Current sizing/economics therefore remain
    authoritative; the queued value is bound only as comparison lineage.
    """
    if not intent.get("materialization_queue_id"):
        return
    queue_expected_net = _coerce_float(
        _first_present(
            signal.get("expected_net_pnl_usd"),
            intent.get("materialization_queue_expected_net_pnl_usd"),
        )
    )
    current_expected_net = _coerce_float(intent.get("expected_net_pnl_usd"))
    observed_at = _utc_iso()
    receipt = {
        "schema_version": "materialization_queue_expected_economics_receipt_v1",
        "materialization_queue_id": intent.get("materialization_queue_id"),
        "candidate_id": _first_present(
            signal.get("candidate_id"),
            intent.get("candidate_id"),
        ),
        "queued_expected_net_pnl_usd": queue_expected_net,
        "current_allocator_expected_net_pnl_usd": current_expected_net,
        "feature_cutoff": signal.get("feature_cutoff"),
        "available_at": signal.get("available_at"),
        "decision_time": signal.get("decision_time"),
        "observed_at": observed_at,
        "authority": "HISTORICAL_QUEUE_TELEMETRY_ONLY",
    }
    receipt["receipt_hash"] = _paper_canonical_sha256(receipt)
    intent["materialization_queue_expected_economics_receipt"] = receipt
    intent["materialization_queue_expected_economics_receipt_hash"] = receipt["receipt_hash"]
    allocation["materialization_queue_expected_economics_receipt"] = dict(receipt)
    if queue_expected_net is None or queue_expected_net <= 0.0:
        intent["paper_materialization_queue_expected_net_restore_skipped_reason"] = (
            "QUEUE_EXPECTED_NET_PNL_USD_NOT_POSITIVE"
        )
        return
    side = str(_first_present(intent.get("side"), signal.get("side")) or "").lower()
    expected_edge = _coerce_float(intent.get("expected_move_after_cost_bps"))
    if not expected_move_after_cost_favorable_for_side(
        side=side,
        expected_move_after_cost_bps=expected_edge,
    ):
        intent["materialization_queue_expected_net_pnl_usd"] = round(
            queue_expected_net,
            8,
        )
        intent["paper_materialization_queue_expected_net_restore_skipped_reason"] = (
            f"CURRENT_SIGNED_EDGE_NOT_FAVORABLE_FOR_SIDE:{side}:{expected_edge}"
        )
        return
    intent["materialization_queue_expected_net_pnl_usd"] = round(queue_expected_net, 8)
    allocation["materialization_queue_expected_net_pnl_usd"] = round(
        queue_expected_net,
        8,
    )
    intent["paper_materialization_queue_expected_net_restore_applied"] = False
    allocation["paper_materialization_queue_expected_net_restore_applied"] = False
    intent["paper_materialization_queue_expected_net_restore_skipped_reason"] = (
        "STALE_QUEUE_ECONOMICS_NEVER_OVERRIDE_CURRENT_ALLOCATOR_ECONOMICS"
    )


def _paper_policy_owner_open_rejection_reasons(intent: dict[str, Any]) -> list[str]:
    owner = str(intent.get("paper_policy_owner") or "")
    if owner == PAPER_POLICY_OWNER_OLD_POLICY:
        intent["paper_policy_owner_open_allowed"] = False
        intent["paper_policy_owner_open_block_reason"] = (
            "OLD_POLICY_NEW_ECONOMIC_PAPER_OPENS_DISABLED"
        )
        intent["paper_runtime_owner_rejection_reasons"] = ["paper_policy_owner_old_policy"]
        return ["OLD_POLICY_NEW_ECONOMIC_PAPER_OPENS_DISABLED"]
    if owner == PAPER_POLICY_OWNER_SHADOW_ONLY:
        intent["paper_policy_owner_open_allowed"] = False
        intent["paper_policy_owner_open_block_reason"] = (
            "SHADOW_ONLY_POLICY_OWNER_NOT_ECONOMIC_FILL"
        )
        intent["paper_runtime_owner_rejection_reasons"] = ["paper_policy_owner_shadow_only"]
        return ["SHADOW_ONLY_POLICY_OWNER_NOT_ECONOMIC_FILL"]
    if intent.get("materialization_queue_id"):
        queue_reasons = _paper_materialization_queue_owner_rejection_reasons(intent)
        intent["paper_runtime_owner_rejection_reasons"] = queue_reasons
        if queue_reasons:
            intent["paper_policy_owner_open_allowed"] = False
            intent["paper_policy_owner_open_block_reason"] = queue_reasons[0]
            return queue_reasons
        intent["paper_policy_owner_open_allowed"] = True
        intent["paper_policy_owner_open_block_reason"] = None
        return []
    if (
        str(intent.get("paper_opportunity_tier") or "").strip().upper()
        == PAPER_TIER_RISK_CONTROLLER_EXPLORATION
    ):
        exploration_reasons = _paper_risk_controller_exploration_owner_rejection_reasons(intent)
        intent["paper_runtime_owner_rejection_reasons"] = exploration_reasons
        if exploration_reasons:
            intent["paper_policy_owner_open_allowed"] = False
            intent["paper_policy_owner_open_block_reason"] = (
                "PAPER_RISK_CONTROLLER_EXPLORATION_OWNER_GUARD_BLOCKED"
            )
            return [
                "PAPER_RISK_CONTROLLER_EXPLORATION_OWNER_GUARD_BLOCKED",
                *exploration_reasons,
            ]
        intent["paper_policy_owner_open_allowed"] = True
        intent["paper_policy_owner_open_block_reason"] = None
        return []
    if (
        str(intent.get("paper_opportunity_tier") or "").strip().upper()
        == PAPER_TIER_POSITIVE_EDGE_PROBATION
    ):
        probation_reasons = _positive_edge_probation_owner_rejection_reasons(intent)
        intent["paper_runtime_owner_rejection_reasons"] = probation_reasons
        if probation_reasons:
            intent["paper_policy_owner_open_allowed"] = False
            intent["paper_policy_owner_open_block_reason"] = (
                "POSITIVE_EDGE_PROBATION_OWNER_GUARD_BLOCKED"
            )
            return [
                "POSITIVE_EDGE_PROBATION_OWNER_GUARD_BLOCKED",
                *probation_reasons,
            ]
        intent["paper_policy_owner_open_allowed"] = True
        intent["paper_policy_owner_open_block_reason"] = None
        return []
    owner_reasons = _active_challenger_runtime_owner_rejection_reasons(intent)
    intent["paper_runtime_owner_rejection_reasons"] = owner_reasons
    if owner_reasons:
        intent["paper_policy_owner_open_allowed"] = False
        intent["paper_policy_owner_open_block_reason"] = PAPER_RUNTIME_OWNER_BLOCK_REASON
        return [PAPER_RUNTIME_OWNER_BLOCK_REASON, *owner_reasons]
    if (
        owner == PAPER_POLICY_OWNER_CHALLENGER_V2
        and intent.get("production_grade_cost_flag") is not True
    ):
        missing = [
            f"missing:{field}"
            for field in (intent.get("runtime_cost_capture_missing_fields") or [])
        ]
        temporal = [
            f"temporal:{reason}"
            for reason in (intent.get("runtime_cost_capture_temporal_reject_reasons") or [])
        ]
        source = [
            f"source:{reason}"
            for reason in (intent.get("runtime_cost_capture_source_reject_reasons") or [])
        ]
        intent["paper_policy_owner_open_allowed"] = False
        intent["paper_policy_owner_open_block_reason"] = (
            "CHALLENGER_COST_CAPTURE_NOT_PRODUCTION_GRADE"
        )
        return [
            "CHALLENGER_COST_CAPTURE_NOT_PRODUCTION_GRADE",
            *missing,
            *temporal,
            *source,
        ]
    intent["paper_policy_owner_open_allowed"] = True
    intent["paper_policy_owner_open_block_reason"] = None
    return []


def _read_held_by_paper_fill_gate(r) -> list[dict]:
    """Read symbols the orchestrator held back due to the strict P0.2F
    paper-fill gate. These rows carry the gate block reasons and are NOT
    fills; they exist so the paper-intent layer / comparator / frontend
    can surface the exact block reason without changing gate behavior.
    """
    if r is None:
        return []
    raw = r.get(f"{V2_REDIS_PREFIX}orchestrator:decisions")
    if not raw:
        return []
    try:
        data = json.loads(raw)
    except (ValueError, TypeError):
        return []
    if not isinstance(data, dict):
        return []
    held = data.get("held_by_paper_fill_gate") or []
    return [h for h in held if isinstance(h, dict)]


