def _copy_present_fields(source: dict[str, Any], fields: tuple[str, ...]) -> dict[str, Any]:
    return {
        field: source[field]
        for field in fields
        if field not in COMPACT_ACCEPTED_FILL_OMITTED_FIELDS and source.get(field) not in (None, "")
    }


def _first_numeric_value_from_payloads(
    *payload_fields: tuple[Mapping[str, Any] | None, str],
) -> float | None:
    for payload, field in payload_fields:
        if not isinstance(payload, Mapping):
            continue
        parsed = _coerce_float(payload.get(field))
        if parsed is not None:
            return parsed
    return None


def _set_contract_backfilled(compact: dict[str, Any], field: str, source: str) -> None:
    sources = compact.setdefault("adaptive_allocation_contract_backfill_sources", {})
    if isinstance(sources, dict):
        sources[field] = source
    compact["adaptive_allocation_contract_backfilled"] = True


def _normalize_compact_adaptive_allocation_contract(
    compact: dict[str, Any],
    source: Mapping[str, Any],
    *,
    row_context: Mapping[str, Any] | None = None,
) -> None:
    """Backfill current allocation contract fields for legacy compacted rows.

    This only derives missing presentation/evidence fields from immutable
    accepted-fill economics already present in state. It does not change the
    sizing decision, paper admission gate, or any exchange-facing behavior.
    """

    row = row_context if isinstance(row_context, Mapping) else {}
    model_inputs = (
        compact.get("model_inputs")
        if isinstance(compact.get("model_inputs"), Mapping)
        else source.get("model_inputs")
        if isinstance(source.get("model_inputs"), Mapping)
        else {}
    )
    target_notional = _first_numeric_value_from_payloads(
        (source, "target_notional_usdt"),
        (compact, "target_notional_usdt"),
        (source, "gross_notional_usd"),
        (compact, "gross_notional_usd"),
        (row, "gross_notional_usd"),
        (row, "notional"),
        (row, "notional_usdt"),
        (source, "target_notional_usd"),
        (compact, "target_notional_usd"),
    )
    if target_notional is not None and target_notional > 0.0:
        normalized_target = round(target_notional, 8)
        if compact.get("target_notional_usdt") in (None, ""):
            compact["target_notional_usdt"] = normalized_target
            _set_contract_backfilled(
                compact,
                "target_notional_usdt",
                "derived_from_gross_notional_or_notional",
            )
        if _coerce_float(compact.get("target_notional_usd")) != normalized_target:
            compact["target_notional_usd"] = normalized_target
            _set_contract_backfilled(
                compact,
                "target_notional_usd",
                "normalized_to_target_notional_usdt",
            )
        if compact.get("gross_notional_usd") in (None, ""):
            compact["gross_notional_usd"] = normalized_target
            _set_contract_backfilled(
                compact,
                "gross_notional_usd",
                "derived_from_target_notional_usdt",
            )

    gross_notional = _first_numeric_value_from_payloads(
        (compact, "gross_notional_usd"),
        (compact, "target_notional_usdt"),
    )
    expected_fees = (
        _first_numeric_value_from_payloads(
            (compact, "expected_fees_usd"), (source, "expected_fees_usd")
        )
        or 0.0
    )
    expected_slippage = (
        _first_numeric_value_from_payloads(
            (compact, "expected_slippage_usd"), (source, "expected_slippage_usd")
        )
        or 0.0
    )
    expected_funding = (
        _first_numeric_value_from_payloads(
            (compact, "expected_funding_usd"), (source, "expected_funding_usd")
        )
        or 0.0
    )
    stop_distance_bps = _first_numeric_value_from_payloads(
        (compact, "stop_distance_bps"),
        (source, "stop_distance_bps"),
    )
    max_loss = _first_numeric_value_from_payloads(
        (compact, "max_loss_if_stop_hit"),
        (source, "max_loss_if_stop_hit"),
    )
    if (
        max_loss is None
        and gross_notional is not None
        and gross_notional > 0.0
        and stop_distance_bps is not None
    ):
        modeled_stop_loss = gross_notional * max(0.0, stop_distance_bps) / 10000.0
        max_loss = modeled_stop_loss + expected_fees + expected_slippage + expected_funding
        compact["max_loss_if_stop_hit"] = round(max_loss, 8)
        _set_contract_backfilled(
            compact,
            "max_loss_if_stop_hit",
            "derived_from_stop_distance_and_cost_fields",
        )

    expected_net = _first_numeric_value_from_payloads(
        (compact, "expected_net_pnl_usd"),
        (source, "expected_net_pnl_usd"),
    )
    if (
        compact.get("risk_reward") in (None, "")
        and expected_net is not None
        and max_loss is not None
        and max_loss > 0.0
    ):
        compact["risk_reward"] = round(expected_net / max_loss, 8)
        _set_contract_backfilled(
            compact,
            "risk_reward",
            "derived_from_expected_net_pnl_and_max_loss",
        )

    total_exposure = _first_numeric_value_from_payloads(
        (source, "total_exposure_usdt"),
        (compact, "total_exposure_usdt"),
        (row, "total_exposure_usdt"),
        (row, "total_exposure"),
    )
    if (
        compact.get("portfolio_exposure_after_trade") in (None, "")
        and gross_notional is not None
        and gross_notional > 0.0
    ):
        exposure_base = 0.0 if total_exposure is None else max(0.0, total_exposure)
        compact["portfolio_exposure_after_trade"] = round(exposure_base + gross_notional, 8)
        _set_contract_backfilled(
            compact,
            "portfolio_exposure_after_trade",
            "derived_from_total_exposure_and_gross_notional"
            if total_exposure is not None
            else "derived_from_self_notional_only",
        )

    equity = _first_numeric_value_from_payloads(
        (source, "equity"),
        (compact, "equity"),
        (model_inputs, "equity"),
        (row, "equity"),
        (row, "portfolio_equity_usdt"),
        (row, "current_session_equity"),
        (row, "starting_equity_usd"),
        (row, "initial_capital"),
    )
    correlation_exposure = (
        _first_numeric_value_from_payloads(
            (source, "correlation_exposure_pct"),
            (compact, "correlation_exposure_pct"),
            (model_inputs, "correlation_exposure_pct"),
            (row, "correlation_exposure_pct"),
        )
        or 0.0
    )
    if compact.get("correlation_exposure_after_trade") in (None, ""):
        notional_fraction = 0.0
        if (
            equity is not None
            and equity > 0.0
            and gross_notional is not None
            and gross_notional > 0.0
        ):
            notional_fraction = gross_notional / equity
        compact["correlation_exposure_after_trade"] = round(
            _clamp_float(max(0.0, correlation_exposure) + notional_fraction, 0.0, 1.0),
            8,
        )
        _set_contract_backfilled(
            compact,
            "correlation_exposure_after_trade",
            "derived_from_correlation_exposure_and_equity"
            if equity is not None and equity > 0.0
            else "derived_from_correlation_exposure_without_equity",
        )

    if compact.get("risk_of_ruin_contribution") in (None, "") and max_loss is not None:
        drawdown_bps = (
            _first_numeric_value_from_payloads(
                (source, "drawdown_bps"),
                (compact, "drawdown_bps"),
                (model_inputs, "drawdown_bps"),
                (row, "drawdown_bps"),
                (row, "current_drawdown_bps"),
            )
            or 0.0
        )
        if equity is not None and equity > 0.0:
            risk_of_ruin = (
                (max(0.0, max_loss) / equity)
                * (
                    1.0
                    + max(0.0, drawdown_bps)
                    / max(1.0, ADAPTIVE_ALLOCATOR_CONTRACT_DEFAULT_MAX_DAILY_DRAWDOWN_PCT * 10000.0)
                )
                * (
                    1.0
                    + max(0.0, correlation_exposure)
                    / max(1e-9, ADAPTIVE_ALLOCATOR_CONTRACT_DEFAULT_MAX_CORRELATION_EXPOSURE_PCT)
                )
            )
        else:
            risk_of_ruin = 0.0
        compact["risk_of_ruin_contribution"] = round(_clamp_float(risk_of_ruin, 0.0, 1.0), 8)
        _set_contract_backfilled(
            compact,
            "risk_of_ruin_contribution",
            "derived_from_max_loss_equity_drawdown_and_correlation"
            if equity is not None and equity > 0.0
            else "derived_as_zero_without_equity",
        )


def _compact_adaptive_allocation_for_state(
    value: Any,
    *,
    row_context: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    if not isinstance(value, dict):
        return {}
    compact = _copy_present_fields(value, COMPACT_ACCEPTED_FILL_ALLOCATION_FIELDS)
    model_inputs = value.get("model_inputs") if isinstance(value.get("model_inputs"), dict) else {}
    compact_model_inputs = _copy_present_fields(
        model_inputs,
        tuple(
            dict.fromkeys(
                (
                    *PERSISTENT_ACCEPTED_FILL_MODEL_INPUT_FIELDS,
                    "selected_leverage",
                    "leverage_target",
                    "raw_leverage_target",
                    "leverage_selection_reason",
                    "selected_margin_mode",
                    "margin_mode_selection_reason",
                    "selected_hedge_budget_pct_of_risk",
                    "hedge_budget_selection_reason",
                    "paper_opportunity_tier",
                    "expected_slippage_bps",
                    "observed_spread_bps",
                    "depth_price_impact_bps",
                )
            )
        ),
    )
    if compact_model_inputs:
        compact["model_inputs"] = compact_model_inputs
    _normalize_compact_adaptive_allocation_contract(
        compact,
        value,
        row_context=row_context,
    )
    return compact


def _compact_accepted_fill_for_state(row: dict[str, Any]) -> dict[str, Any]:
    compact = _copy_present_fields(row, COMPACT_ACCEPTED_FILL_FIELDS)
    allocation = _compact_adaptive_allocation_for_state(
        row.get("adaptive_allocation"),
        row_context=row,
    )
    if allocation:
        compact["adaptive_allocation"] = allocation
    compact["accepted_fill_state_compacted"] = True
    compact["entry_feature_snapshot_omitted_from_state"] = bool(row.get("entry_feature_snapshot"))
    return compact


def _compact_rows_for_state(rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
    return [_compact_accepted_fill_for_state(row) for row in rows if isinstance(row, dict)]


def _sample_rows(
    rows: list[dict[str, Any]], limit: int = PAPER_REDIS_LEDGER_ROW_SAMPLE_LIMIT
) -> list[dict[str, Any]]:
    if limit <= 0:
        return []
    if len(rows) <= limit:
        return rows
    return rows[-limit:]


HEAVY_REDIS_STATUS_ROW_KEYS = frozenset(
    {
        "buckets",
        "candidate_allocations",
        "closed_outcomes",
        "held_by_paper_fill_gate",
        "persistent_shadow_observations",
        "sample_a_grade_rows",
        "sample_allocations",
        "sample_b_grade_exploration_fills",
        "sample_blocked_fills",
        "sample_canary_candidates",
        "sample_canary_intents",
        "sample_canary_pending_rows",
        "sample_near_a_grade_rows",
        "sample_paper_only_label_collection_priority_fills",
        "sample_rejected_forward_canary_outcomes",
        "sample_valid_forward_canary_outcomes",
        "shadow_observations",
    }
)


def _compact_status_for_redis(value: Any) -> Any:
    if isinstance(value, dict):
        compact: dict[str, Any] = {}
        omitted: list[str] = []
        for key, item in value.items():
            if key in HEAVY_REDIS_STATUS_ROW_KEYS and isinstance(item, list):
                compact[f"{key}_count"] = len(item)
                omitted.append(key)
                continue
            compact[key] = _compact_status_for_redis(item)
        if omitted:
            compact["sample_rows_omitted_from_redis_status"] = True
            compact["omitted_redis_status_row_fields"] = sorted(omitted)
        return compact
    if isinstance(value, list):
        return [_compact_status_for_redis(item) for item in value]
    return value


def _write_compact_public_status(payload: dict[str, Any], path: Path) -> None:
    """Write the same bounded operator projection used for Redis status.

    ``run_once`` retains full paper evidence in memory for lifecycle and audit
    work.  The top-level CLI status is an operator heartbeat, not a canonical
    evidence store, so publishing that full object can duplicate retained rows
    into a very large JSON file every cycle.
    """

    write_payload(_compact_status_for_redis(payload), path)


def _paper_runtime_cost_capture_summary(rows: list[dict[str, Any]]) -> dict[str, Any]:
    intent_rows = [row for row in rows if isinstance(row, dict)]
    order_applicable_rows = [
        row
        for row in intent_rows
        if row.get("runtime_cost_capture_order_cost_applicable") is not False
    ]
    production_grade_cost_rows = sum(
        1
        for row in intent_rows
        if row.get("production_grade_cost_flag") is True
        or row.get("production_grade_cost_evidence") is True
    )
    production_grade_cost_order_applicable_rows = sum(
        1
        for row in order_applicable_rows
        if row.get("production_grade_cost_flag") is True
        or row.get("production_grade_cost_evidence") is True
    )
    no_order_explained_rows = sum(
        1 for row in intent_rows if row.get("runtime_cost_capture_order_cost_applicable") is False
    )
    unexplained_missing_cost_rows = sum(
        1
        for row in order_applicable_rows
        if len(row.get("runtime_cost_capture_unexplained_missing_fields") or []) > 0
    )
    no_order_missing_cost_rows = sum(
        1
        for row in intent_rows
        if row.get("runtime_cost_capture_order_cost_applicable") is False
        and (
            len(row.get("runtime_cost_capture_missing_fields") or []) > 0
            or len(row.get("runtime_cost_capture_unexplained_missing_fields") or []) > 0
        )
    )
    paper_fill_allowed_rows = sum(1 for row in intent_rows if row.get("paper_fill_allowed") is True)
    routes_to_live_rows = sum(1 for row in intent_rows if row.get("routes_to_live") is True)
    places_real_order_rows = sum(1 for row in intent_rows if row.get("places_real_order") is True)
    total_row_cost_coverage = production_grade_cost_rows / len(intent_rows) if intent_rows else 0.0
    if order_applicable_rows:
        cost_coverage = production_grade_cost_order_applicable_rows / len(order_applicable_rows)
        cost_coverage_basis = "order_applicable_rows"
    else:
        cost_coverage = total_row_cost_coverage
        cost_coverage_basis = "all_intent_rows_no_order_applicable"
    return {
        "schema_version": "v2_paper_runtime_cost_capture_summary_v1",
        "source": "v2_trade_management_paper_loop:intents",
        "paper_intent_rows": len(intent_rows),
        "order_cost_applicable_rows": len(order_applicable_rows),
        "production_grade_cost_rows": production_grade_cost_rows,
        "production_grade_cost_order_applicable_rows": production_grade_cost_order_applicable_rows,
        "production_grade_cost_coverage": cost_coverage,
        "production_grade_cost_coverage_basis": cost_coverage_basis,
        "production_grade_cost_total_row_coverage": total_row_cost_coverage,
        "no_order_explained_rows": no_order_explained_rows,
        "unexplained_missing_cost_rows": unexplained_missing_cost_rows,
        "no_order_missing_cost_rows": no_order_missing_cost_rows,
        "paper_fill_allowed_rows": paper_fill_allowed_rows,
        "routes_to_live_rows": routes_to_live_rows,
        "places_real_order_rows": places_real_order_rows,
        "paper_only": True,
        "routes_to_live": False,
        "places_real_order": False,
    }


def _paper_candidate_cost_field_coverage(rows: list[dict[str, Any]]) -> dict[str, Any]:
    intent_rows = [row for row in rows if isinstance(row, dict)]
    order_applicable_rows = [
        row
        for row in intent_rows
        if row.get("runtime_cost_capture_order_cost_applicable") is not False
    ]

    def present(row: dict[str, Any], field: str) -> bool:
        missing_fields = set(row.get("runtime_cost_capture_missing_fields") or [])
        if field in missing_fields:
            return False
        value = row.get(field)
        if field in PHASE2_RUNTIME_COST_CAPTURE_DERIVED_FLAG_FIELDS:
            return value in (True, False)
        return value not in (None, "")

    field_rows: list[dict[str, Any]] = []
    all_present_cells = 0
    all_required_cells = len(intent_rows) * len(PHASE2_RUNTIME_COST_CAPTURE_REQUIRED_FIELDS)
    order_present_cells = 0
    order_required_cells = len(order_applicable_rows) * len(
        PHASE2_RUNTIME_COST_CAPTURE_REQUIRED_FIELDS
    )
    unexplained_missing_by_field: dict[str, int] = {}

    for field in PHASE2_RUNTIME_COST_CAPTURE_REQUIRED_FIELDS:
        all_present = sum(1 for row in intent_rows if present(row, field))
        order_present = sum(1 for row in order_applicable_rows if present(row, field))
        unexplained_missing = sum(
            1
            for row in order_applicable_rows
            if field in set(row.get("runtime_cost_capture_unexplained_missing_fields") or [])
        )
        if unexplained_missing:
            unexplained_missing_by_field[field] = unexplained_missing
        all_present_cells += all_present
        order_present_cells += order_present
        field_rows.append(
            {
                "field": field,
                "present_rows": all_present,
                "total_rows": len(intent_rows),
                "coverage": all_present / len(intent_rows) if intent_rows else 0.0,
                "order_applicable_present_rows": order_present,
                "order_applicable_rows": len(order_applicable_rows),
                "order_applicable_coverage": (
                    order_present / len(order_applicable_rows) if order_applicable_rows else 0.0
                ),
                "unexplained_missing_order_applicable_rows": unexplained_missing,
            }
        )

    order_applicable_field_coverage = (
        order_present_cells / order_required_cells if order_required_cells else 0.0
    )
    all_row_field_coverage = all_present_cells / all_required_cells if all_required_cells else 0.0
    unexplained_missing_order_applicable_rows = sum(
        1
        for row in order_applicable_rows
        if row.get("runtime_cost_capture_unexplained_missing_fields")
    )
    return {
        "schema_version": "candidate_cost_field_coverage_v1",
        "source": "v2_trade_management_paper_loop:intents",
        "required_fields": list(PHASE2_RUNTIME_COST_CAPTURE_REQUIRED_FIELDS),
        "candidate_rows": len(intent_rows),
        "order_applicable_rows": len(order_applicable_rows),
        "all_row_field_coverage": all_row_field_coverage,
        "order_applicable_field_coverage": order_applicable_field_coverage,
        "unexplained_missing_order_applicable_rows": unexplained_missing_order_applicable_rows,
        "unexplained_missing_by_field": unexplained_missing_by_field,
        "fields": field_rows,
        "pass_conditions": {
            "unexplained_missing_order_applicable_rows_zero": (
                unexplained_missing_order_applicable_rows == 0
            ),
            "order_applicable_field_coverage_complete": (
                order_required_cells > 0 and order_present_cells == order_required_cells
            ),
        },
        "paper_only": True,
        "routes_to_live": False,
        "places_real_order": False,
    }


def _accepted_fill_identity(row: dict[str, Any]) -> str:
    return str(
        _first_present(
            row.get("fill_id"),
            row.get("ledger_row_id"),
            row.get("intent_id"),
            row.get("signal_id"),
            row.get("prediction_id"),
            row.get("source_prediction_id"),
            row.get("source_intent_id"),
            f"{row.get('symbol')}:{row.get('timeframe')}:{row.get('side')}",
        )
    )


def _index_accepted_fill_rows(rows: list[Any]) -> dict[str, dict]:
    out: dict[str, dict] = {}
    for row in rows:
        if not isinstance(row, dict):
            continue
        identity = _accepted_fill_identity(row)
        if identity:
            out[identity] = row
    return out


def _paper_exploration_liquidation_buffer_usd(
    row: dict[str, Any],
) -> tuple[float | None, str | None]:
    existing = _coerce_float(
        _first_present(
            row.get("liquidation_buffer_usd"),
            row.get("expected_liquidation_buffer_usd"),
        )
    )
    if existing is not None:
        return round(abs(existing), 8), "liquidation_buffer_usd"

    notional = _coerce_float(
        _first_present(
            row.get("gross_notional_usd"),
            row.get("notional_usd"),
            row.get("notional_usdt"),
            row.get("notional"),
            row.get("target_notional_usd"),
            row.get("recommended_notional_usd"),
        )
    )
    buffer_bps = _coerce_float(row.get("liquidation_buffer_bps"))
    if notional is not None and notional > 0 and buffer_bps is not None:
        return (
            round(abs(notional) * abs(buffer_bps) / 10_000.0, 8),
            "liquidation_buffer_bps_x_notional_usd",
        )

    entry_price = _coerce_float(_first_present(row.get("entry_price"), row.get("fill_price")))
    liquidation_price = _coerce_float(row.get("liquidation_price_estimate"))
    quantity = _coerce_float(
        _first_present(row.get("quantity"), row.get("order_size"), row.get("net_quantity"))
    )
    if (
        entry_price is not None
        and liquidation_price is not None
        and quantity is not None
        and quantity > 0
    ):
        return (
            round(abs(liquidation_price - entry_price) * abs(quantity), 8),
            "liquidation_price_distance_x_quantity",
        )

    return None, None


def _ensure_paper_exploration_lifecycle_public_fields(item: dict[str, Any]) -> dict[str, Any]:
    if not _is_paper_risk_controller_exploration_row(item):
        return item

    position_id_source = None
    position_id = item.get("position_id")
    for field in ("fill_id", "ledger_row_id", "paper_fill_id", "materialization_queue_id"):
        if position_id not in (None, ""):
            break
        value = item.get(field)
        if value not in (None, ""):
            position_id = str(value)
            position_id_source = field
    if position_id not in (None, ""):
        item["position_id"] = str(position_id)
        if position_id_source:
            item["position_id_backfilled_from"] = position_id_source
            item["paper_exploration_position_id_repair_applied"] = True

    if _coerce_float(item.get("liquidation_buffer_usd")) is None:
        liquidation_buffer_usd, source = _paper_exploration_liquidation_buffer_usd(item)
        if liquidation_buffer_usd is not None:
            item["liquidation_buffer_usd"] = liquidation_buffer_usd
            item["liquidation_buffer_usd_source"] = source

    hedge_plan = item.get("hedge_plan")
    hedge_state = (
        str(_first_present(item.get("hedge_state"), item.get("hedge_status")) or "").strip().upper()
    )
    hedge_required = item.get("hedge_required")
    if not isinstance(hedge_plan, dict) and (
        hedge_state in {"NO_HEDGE", "NO_HEDGE_REQUIRED", "NOT_REQUIRED"} or hedge_required is False
    ):
        item["hedge_plan"] = {
            "hedge_required": False,
            "status": "NO_HEDGE_REQUIRED",
            "reason": _first_present(item.get("hedge_reason"), hedge_state, "NO_HEDGE_CONTEXT"),
            "paper_only": True,
            "routes_to_live": False,
            "places_real_order": False,
        }
        item["hedge_plan_backfilled_from"] = "hedge_state"
    elif isinstance(hedge_plan, dict):
        hedge_plan.setdefault("paper_only", True)
        hedge_plan.setdefault("routes_to_live", False)
        hedge_plan.setdefault("places_real_order", False)
        item["hedge_plan"] = hedge_plan

    return item


def _file_size_bytes(path: Path) -> int | None:
    try:
        return int(path.stat().st_size)
    except OSError:
        return None


def _state_file_skip_status(path: Path, *, max_bytes: int) -> dict[str, Any] | None:
    size = _file_size_bytes(path)
    if size is None or size <= max_bytes:
        return None
    return {
        "path": str(path),
        "size_bytes": size,
        "max_bytes": int(max_bytes),
        "skipped_reason": "STATE_FILE_EXCEEDS_BOUNDED_RUNTIME_READ_CAP",
    }


def _read_json_file_payload(path: Path, *, max_bytes: int | None = None) -> dict[str, Any]:
    if max_bytes is not None and _state_file_skip_status(path, max_bytes=max_bytes):
        return {}
    try:
        raw = path.read_text(encoding="utf-8")
    except OSError:
        return {}
    try:
        payload = json.loads(raw)
    except (TypeError, ValueError):
        return {}
    return payload if isinstance(payload, dict) else {}


def _redis_string_length(r, key: str) -> int | None:
    strlen = getattr(r, "strlen", None)
    if callable(strlen):
        try:
            return int(strlen(key))
        except Exception:
            return None
    return None


def _read_json_redis_key_if_small(
    r,
    key: str,
    *,
    max_bytes: int | None = PAPER_REDIS_HISTORY_READ_MAX_BYTES,
) -> dict[str, Any]:
    if r is None or not key.startswith(V2_REDIS_PREFIX):
        return {}
    size = _redis_string_length(r, key)
    if max_bytes is not None and size is not None and size > max_bytes:
        return {}
    try:
        raw = r.get(key)
    except Exception:
        return {}
    if not raw:
        return {}
    if max_bytes is not None and size is None:
        try:
            raw_size = len(raw.encode("utf-8")) if isinstance(raw, str) else len(raw)
        except Exception:
            raw_size = None
        if raw_size is not None and raw_size > max_bytes:
            return {}
    try:
        payload = json.loads(raw)
    except (TypeError, ValueError):
        return {}
    return payload if isinstance(payload, dict) else {}


def _read_json_list_redis_key_if_small(
    r,
    key: str,
    *,
    max_bytes: int | None = PAPER_REDIS_HISTORY_READ_MAX_BYTES,
) -> list[dict[str, Any]]:
    if r is None or not key.startswith(V2_REDIS_PREFIX):
        return []
    size = _redis_string_length(r, key)
    if max_bytes is not None and size is not None and size > max_bytes:
        return []
    try:
        raw = r.get(key)
    except Exception:
        return []
    if not raw:
        return []
    if max_bytes is not None and size is None:
        try:
            raw_size = len(raw.encode("utf-8")) if isinstance(raw, str) else len(raw)
        except Exception:
            raw_size = None
        if raw_size is not None and raw_size > max_bytes:
            return []
    try:
        payload = json.loads(raw)
    except (TypeError, ValueError):
        return []
    if not isinstance(payload, list):
        return []
    return [dict(row) for row in payload if isinstance(row, dict)]


def _accepted_fill_from_open_position(row: dict[str, Any]) -> dict[str, Any]:
    item = dict(row)
    source_fill_ids = (
        row.get("source_fill_ids") if isinstance(row.get("source_fill_ids"), list) else []
    )
    fill_id = _first_present(
        row.get("fill_id"),
        row.get("ledger_row_id"),
        row.get("position_id"),
        source_fill_ids[0] if source_fill_ids else None,
        f"{row.get('symbol')}:{row.get('timeframe')}:{row.get('side')}",
    )
    if fill_id:
        item.setdefault("fill_id", str(fill_id))
        item.setdefault("ledger_row_id", str(fill_id))
    quantity = _coerce_float(
        _first_present(row.get("quantity"), row.get("net_quantity"), row.get("order_size"))
    )
    if quantity is not None and quantity > 0:
        item.setdefault("quantity", abs(quantity))
        item.setdefault("order_size", abs(quantity))
    price = _coerce_float(
        _first_present(row.get("fill_price"), row.get("entry_price"), row.get("avg_entry_price"))
    )
    if price is not None and price > 0:
        item.setdefault("fill_price", price)
        item.setdefault("entry_price", price)
        item.setdefault("mark_price_at_fill", price)
    notional = _coerce_float(
        _first_present(row.get("notional"), row.get("notional_usdt"), row.get("gross_notional_usd"))
    )
    if notional is None and quantity is not None and price is not None:
        notional = abs(quantity * price)
    if notional is not None and notional > 0:
        item.setdefault("notional", abs(notional))
        item.setdefault("notional_usdt", abs(notional))
        item.setdefault("gross_notional_usd", abs(notional))
    allocation = (
        item.get("adaptive_allocation") if isinstance(item.get("adaptive_allocation"), dict) else {}
    )
    if item.get("allocation_id") in (None, "") and allocation.get("allocation_id") not in (
        None,
        "",
    ):
        item["allocation_id"] = allocation.get("allocation_id")
    if item.get("allocator_decision_id") in (None, "") and allocation.get(
        "allocator_decision_id"
    ) not in (None, ""):
        item["allocator_decision_id"] = allocation.get("allocator_decision_id")
        item["allocator_decision_id_source"] = "adaptive_allocation.allocator_decision_id"
    if item.get("allocator_decision_id") in (None, "") and item.get("allocation_id") not in (
        None,
        "",
    ):
        item["allocator_decision_id"] = item.get("allocation_id")
        item["allocator_decision_id_source"] = "adaptive_allocation.allocation_id"
    source_hashes = item.get("source_hashes") if isinstance(item.get("source_hashes"), dict) else {}
    if item.get("feature_vector_hash") in (None, "") and source_hashes.get(
        "feature_vector_hash"
    ) not in (None, ""):
        item["feature_vector_hash"] = source_hashes.get("feature_vector_hash")
    if not isinstance(item.get("provider_hashes"), dict) and source_hashes:
        provider_hashes = {
            key: value
            for key, value in source_hashes.items()
            if key not in {"feature_vector_hash", "prediction_hash", "source_lineage_hash"}
            and value not in (None, "")
        }
        if provider_hashes:
            item["provider_hashes"] = provider_hashes
    tier = str(item.get("paper_opportunity_tier") or "").strip().upper()
    candidate_id = _first_present(
        item.get("candidate_id"),
        item.get("prediction_id"),
        item.get("signal_id"),
        item.get("source_prediction_id"),
    )
    if (
        tier == PAPER_TIER_RISK_CONTROLLER_EXPLORATION
        and item.get("materialization_queue_id") in (None, "")
        and candidate_id not in (None, "")
    ):
        item["materialization_queue_id"] = f"paper_exploration_materialize_{candidate_id}"
        item["materialization_queue_id_reconstructed_from_candidate_id"] = True
        item["materialization_queue_lineage_repair_reason"] = (
            "OPEN_POSITION_REPLAY_LOST_QUEUE_ID_BEFORE_LINEAGE_DURABILITY_REPAIR"
        )
    if tier == PAPER_TIER_RISK_CONTROLLER_EXPLORATION:
        item.setdefault("tier", PAPER_TIER_RISK_CONTROLLER_EXPLORATION)
        item.setdefault("exploration_tier", PAPER_TIER_RISK_CONTROLLER_EXPLORATION)
        item.setdefault("paper_exploration_tier", PAPER_TIER_RISK_CONTROLLER_EXPLORATION)
        item.setdefault("explicit_paper_opportunity_tier", PAPER_TIER_RISK_CONTROLLER_EXPLORATION)
        preemptive_id = _first_present(
            item.get("preemptive_decision_id"),
            item.get("runtime_revalidated_preemptive_decision_id"),
        )
        if preemptive_id not in (None, ""):
            item["preemptive_decision_id"] = preemptive_id
    item.setdefault("routes_to_live", False)
    item.setdefault("live_order", False)
    item.setdefault("test_order", False)
    item.setdefault("order_submitted", False)
    item.setdefault("test_order_submitted", False)
    item.setdefault("leverage_mutated", False)
    item.setdefault("margin_mutated", False)
    item.setdefault("counts_as_A_plus", False)
    item.setdefault("counts_as_final_A_plus", False)
    item.setdefault("counts_as_final_a_plus", False)
    item.setdefault("counts_as_live_ready", False)
    item.setdefault(
        "raw_safety_fields",
        {
            "paper_only": True,
            "routes_to_live": False,
            "places_real_order": False,
            "test_order": False,
            "live_order": False,
            "counts_as_A_plus": False,
            "counts_as_final_A_plus": False,
            "counts_as_live_ready": False,
            "order_submitted": False,
            "test_order_submitted": False,
            "leverage_mutated": False,
            "margin_mutated": False,
        },
    )
    item.setdefault(
        "invariant_checks",
        {
            "paper_only_is_true": True,
            "routes_to_live_is_false": True,
            "places_real_order_is_false": True,
            "test_order_is_false": True,
            "live_order_is_false": True,
            "counts_as_A_plus_is_false": True,
            "counts_as_final_A_plus_is_false": True,
            "counts_as_live_ready_is_false": True,
            "order_submitted_is_false": True,
            "test_order_submitted_is_false": True,
            "leverage_mutated_is_false": True,
            "margin_mutated_is_false": True,
        },
    )
    item.setdefault("paper_fill_persistence_status", "OPEN_POSITION_COMPACT_STATE_REPLAY")
    item.setdefault("fill_price_immutable", True)
    item.setdefault("paper_only", True)
    item.setdefault("places_real_order", False)
    item = _ensure_paper_exploration_lifecycle_public_fields(item)
    return _bind_challenger_b_grade_canary_metadata(
        item,
        binding_source="OPEN_POSITION_REPLAY",
    )


def _accepted_fill_rows_from_open_positions(rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
    return [
        _accepted_fill_from_open_position(row)
        for row in rows
        if isinstance(row, dict) and row.get("symbol")
    ]


