def _count_list_values(rows: list[dict[str, Any]], key: str) -> dict[str, int]:
    counts: dict[str, int] = {}
    for row in rows:
        values = row.get(key) if isinstance(row, dict) else None
        if not isinstance(values, list):
            continue
        for value in values:
            label = str(value or "missing")
            counts[label] = counts.get(label, 0) + 1
    return counts


def _count_first_present_values(
    rows: list[dict[str, Any]],
    fields: tuple[str, ...],
) -> dict[str, int]:
    counts: dict[str, int] = {}
    for row in rows:
        if not isinstance(row, dict):
            continue
        value = _first_present(*(row.get(field) for field in fields))
        label = str(value or "missing")
        counts[label] = counts.get(label, 0) + 1
    return dict(sorted(counts.items()))


def _expected_move_bps_sign(row: dict[str, Any]) -> str:
    move = _coerce_float(
        _first_present(
            row.get("expected_move_bps"),
            row.get("predicted_move_bps"),
            row.get("price_target_bps"),
        )
    )
    if move is None:
        return "missing"
    if move > 0.0:
        return "positive"
    if move < 0.0:
        return "negative"
    return "zero"


def _selected_action_expected_move_sign_counts(
    rows: list[dict[str, Any]],
) -> dict[str, int]:
    counts: dict[str, int] = {}
    for row in rows:
        if not isinstance(row, dict):
            continue
        action = (
            str(
                _first_present(row.get("selected_action"), row.get("action"), row.get("side"))
                or "missing"
            )
            .strip()
            .lower()
            or "missing"
        )
        sign = _expected_move_bps_sign(row)
        label = f"{action}:{sign}"
        counts[label] = counts.get(label, 0) + 1
    return dict(sorted(counts.items()))


def _hold_with_directional_expected_move_bps_count(
    rows: list[dict[str, Any]],
    *,
    require_zero_after_cost: bool = False,
) -> int:
    total = 0
    for row in rows:
        if not isinstance(row, dict):
            continue
        action = (
            str(
                _first_present(row.get("selected_action"), row.get("action"), row.get("side")) or ""
            )
            .strip()
            .lower()
        )
        if action != "hold":
            continue
        if _expected_move_bps_sign(row) not in {"positive", "negative"}:
            continue
        if require_zero_after_cost:
            after_cost = _coerce_float(row.get("expected_move_after_cost_bps"))
            if after_cost != 0.0:
                continue
        total += 1
    return total


def _clamp_float(value: float, lower: float, upper: float) -> float:
    return max(lower, min(upper, value))


def _explicit_paper_opportunity_tier(row: dict[str, Any]) -> str | None:
    raw = _first_present(
        row.get("paper_opportunity_tier"),
        row.get("paper_execution_tier"),
        row.get("opportunity_tier"),
        row.get("calibrated_opportunity_tier"),
    )
    if raw is None:
        return None
    tier = str(raw).strip().upper()
    if tier in PAPER_OPPORTUNITY_TIERS:
        return tier
    return None


def _read_continuous_edge_guardian_gate(r) -> dict[str, Any]:
    payload = None
    if r is not None:
        try:
            payload = r.get(CONTINUOUS_EDGE_GUARDIAN_GATE_REDIS_KEY)
        except Exception:
            payload = None
    if payload:
        try:
            decoded = json.loads(payload)
        except (TypeError, json.JSONDecodeError):
            decoded = None
        if isinstance(decoded, dict):
            return decoded
    try:
        decoded = json.loads(CONTINUOUS_EDGE_GUARDIAN_GATE_PATH.read_text(encoding="utf-8"))
    except Exception:
        return {}
    return decoded if isinstance(decoded, dict) else {}


def _continuous_edge_guardian_gate_context(gate: dict[str, Any] | None) -> dict[str, Any]:
    if not isinstance(gate, dict) or not gate:
        return {}
    context: dict[str, Any] = {}
    if gate.get("status") not in (None, ""):
        context["continuous_edge_guardian_status"] = gate.get("status")
    if gate.get("a_grade_new_entries_allowed") is not None:
        context["continuous_edge_guardian_new_entries_allowed"] = gate.get(
            "a_grade_new_entries_allowed"
        )
    if gate.get("failure_reasons") not in (None, ""):
        context["continuous_edge_guardian_block_reasons"] = gate.get("failure_reasons")
    if gate.get("allowed_runtime_actions") not in (None, ""):
        context["continuous_edge_guardian_allowed_runtime_actions"] = gate.get(
            "allowed_runtime_actions"
        )
    return context


def _continuous_edge_guardian_gate_public_context(
    gate: dict[str, Any] | None,
) -> dict[str, Any]:
    context = _continuous_edge_guardian_gate_context(gate)
    if not context:
        return {}
    public_context = dict(context)
    guardian_status = context.get("continuous_edge_guardian_status")
    if guardian_status not in (None, ""):
        public_context["guardian_status"] = guardian_status
    guardian_new_entries_allowed = context.get("continuous_edge_guardian_new_entries_allowed")
    if guardian_new_entries_allowed is not None:
        public_context["guardian_new_entries_allowed"] = guardian_new_entries_allowed
    guardian_block_reasons = context.get("continuous_edge_guardian_block_reasons")
    if guardian_block_reasons not in (None, ""):
        public_context["guardian_block_reasons"] = guardian_block_reasons
    guardian_allowed_actions = context.get("continuous_edge_guardian_allowed_runtime_actions")
    if guardian_allowed_actions not in (None, ""):
        public_context["guardian_allowed_runtime_actions"] = guardian_allowed_actions
    return public_context


def _continuous_edge_guardian_allows_new_entries(gate: dict[str, Any] | None) -> bool:
    if not isinstance(gate, dict) or not gate:
        return False
    status = str(gate.get("status") or gate.get("state") or "").upper()
    if any(token in status for token in ("HALTED", "BLOCKED", "SHADOW_ONLY")):
        return False
    for field in (
        "a_grade_new_entries_allowed",
        "new_entries_allowed",
        "guardian_new_entries_allowed",
    ):
        if gate.get(field) is not None:
            return gate.get(field) is True
    return False


def _high_confidence_loss_cluster_gate(
    circuit_breaker_status: dict[str, Any] | None,
) -> dict[str, Any]:
    """Extract the admission-facing high-confidence loss cluster gate.

    Fail-closed: a missing/malformed circuit-breaker payload is treated as an
    active cluster with no bucket detail, so nothing can claim cluster-clear
    admission without evidence.
    """
    cluster = None
    if isinstance(circuit_breaker_status, dict) and circuit_breaker_status:
        cluster = circuit_breaker_status.get("recovery_high_confidence_loss_cluster_status")
    if not isinstance(cluster, dict) or not cluster:
        return {
            "cluster_detected": True,
            "cluster_evidence_missing": True,
            "affected_symbols": [],
            "quarantined_sides": [],
            "quarantined_timeframes": [],
            "quarantined_strategy_modes": [],
            "bucket_specific_recovery_enabled": False,
        }
    return {
        "cluster_detected": cluster.get("cluster_detected") is True,
        "cluster_evidence_missing": False,
        "high_confidence_loss_count": cluster.get("high_confidence_loss_count"),
        "affected_symbols": [
            str(sym).strip().upper() for sym in cluster.get("affected_symbols") or []
        ],
        "quarantined_sides": [
            str(side).strip().lower() for side in cluster.get("quarantined_sides") or []
        ],
        "quarantined_timeframes": [
            str(tf).strip().lower() for tf in cluster.get("quarantined_timeframes") or []
        ],
        "quarantined_strategy_modes": [
            str(mode).strip().lower() for mode in cluster.get("quarantined_strategy_modes") or []
        ],
        "bucket_specific_recovery_enabled": (
            cluster.get("bucket_specific_recovery_enabled") is True
        ),
    }


def _high_confidence_loss_cluster_bucket_match_reasons(
    cluster_gate: dict[str, Any] | None,
    *,
    symbol: Any,
    timeframe: Any,
    side: Any,
    strategy_mode: Any,
) -> list[str]:
    """Return why a candidate belongs to a cluster-quarantined bucket.

    Empty list means the candidate's bucket is unrelated to the active
    cluster (or no cluster is active). When cluster evidence itself is
    missing, every candidate matches — fail-closed — with an explicit reason.
    """
    if not isinstance(cluster_gate, dict) or not cluster_gate:
        return ["HIGH_CONFIDENCE_LOSS_CLUSTER_GATE_MISSING_FAIL_CLOSED"]
    if not cluster_gate.get("cluster_detected"):
        return []
    if cluster_gate.get("cluster_evidence_missing"):
        return ["HIGH_CONFIDENCE_LOSS_CLUSTER_EVIDENCE_MISSING_FAIL_CLOSED"]
    if not cluster_gate.get("bucket_specific_recovery_enabled"):
        return ["HIGH_CONFIDENCE_LOSS_CLUSTER_ACTIVE_BUCKET_RECOVERY_DISABLED"]
    reasons: list[str] = []
    symbol_key = str(symbol or "").strip().upper()
    if symbol_key and symbol_key in (cluster_gate.get("affected_symbols") or []):
        reasons.append("HIGH_CONFIDENCE_LOSS_CLUSTER_SYMBOL_QUARANTINED")
    side_key = str(side or "").strip().lower()
    if side_key and side_key in (cluster_gate.get("quarantined_sides") or []):
        reasons.append("HIGH_CONFIDENCE_LOSS_CLUSTER_SIDE_QUARANTINED")
    timeframe_key = str(timeframe or "").strip().lower()
    if timeframe_key and timeframe_key in (cluster_gate.get("quarantined_timeframes") or []):
        reasons.append("HIGH_CONFIDENCE_LOSS_CLUSTER_TIMEFRAME_QUARANTINED")
    mode_key = str(strategy_mode or "").strip().lower()
    if mode_key and mode_key in (cluster_gate.get("quarantined_strategy_modes") or []):
        reasons.append("HIGH_CONFIDENCE_LOSS_CLUSTER_STRATEGY_MODE_QUARANTINED")
    return reasons


def _paper_exploration_specific_high_confidence_loss_cluster_reason(
    reason: str,
) -> bool:
    normalized = str(reason or "").strip().upper()
    return normalized not in {
        "HIGH_CONFIDENCE_LOSS_CLUSTER_SIDE_QUARANTINED",
        "HIGH_CONFIDENCE_LOSS_CLUSTER_TIMEFRAME_QUARANTINED",
    }


def _apply_continuous_edge_guardian_gate(
    classification: dict[str, Any],
    gate: dict[str, Any] | None,
) -> dict[str, Any]:
    if classification.get("paper_opportunity_tier") != PAPER_TIER_A_GRADE_EXECUTION:
        return classification
    if not isinstance(gate, dict) or not gate:
        return classification
    if gate.get("a_grade_new_entries_allowed") is not False:
        return classification
    blocked = dict(classification)
    blocked["pre_guardian_paper_opportunity_tier"] = PAPER_TIER_A_GRADE_EXECUTION
    blocked["pre_guardian_paper_opportunity_tier_reason"] = classification.get(
        "paper_opportunity_tier_reason"
    )
    blocked["pre_guardian_paper_fill_allowed_source"] = classification.get(
        "paper_fill_allowed_source"
    )
    blocked["continuous_edge_guardian_forced_shadow_only"] = True
    blocked["counts_as_a_grade_evidence"] = False
    blocked["paper_opportunity_tier"] = PAPER_TIER_SHADOW_ONLY
    blocked["paper_opportunity_tier_reason"] = "CONTINUOUS_EDGE_GUARDIAN_A_GRADE_HALTED"
    blocked["paper_fill_allowed_source"] = "CONTINUOUS_EDGE_GUARDIAN_BLOCKED_NEW_A_GRADE_ENTRIES"
    blocked["continuous_edge_guardian_status"] = gate.get("status")
    blocked["continuous_edge_guardian_new_entries_allowed"] = gate.get(
        "a_grade_new_entries_allowed"
    )
    blocked["continuous_edge_guardian_block_reasons"] = gate.get("failure_reasons") or []
    blocked["continuous_edge_guardian_allowed_runtime_actions"] = gate.get(
        "allowed_runtime_actions"
    ) or ["reduce", "close"]
    blocked["paper_only"] = True
    blocked["places_real_order"] = False
    return blocked


def _paper_capital_class_for_tier(tier: Any) -> str | None:
    normalized = str(tier or "").strip().upper()
    if normalized == PAPER_TIER_A_GRADE_EXECUTION:
        return "A_GRADE_EXECUTION_FULL_BUDGET"
    if normalized == PAPER_TIER_B_GRADE_EXPLORATION:
        return "B_GRADE_EXPLORATION_FRACTIONAL_BUDGET"
    if normalized == PAPER_TIER_RISK_CONTROLLER_EXPLORATION:
        return "PAPER_RISK_CONTROLLER_EXPLORATION_TINY_BUDGET"
    if normalized == PAPER_TIER_SHADOW_ONLY:
        return "SHADOW_ONLY_ZERO_SIZE"
    if normalized == PAPER_TIER_NO_TRADE:
        return "NO_TRADE_ZERO_SIZE"
    return None


def _paper_source_tier_guardian_context(classification: dict[str, Any]) -> dict[str, Any]:
    tier = str(classification.get("paper_opportunity_tier") or "").strip().upper()
    context: dict[str, Any] = {}
    if tier in PAPER_OPPORTUNITY_TIERS:
        context["source_tier"] = tier
        context["policy_tier"] = tier
        capital_class = _paper_capital_class_for_tier(tier)
        if capital_class is not None:
            context["capital_class"] = capital_class

    pre_guardian_tier = (
        str(classification.get("pre_guardian_paper_opportunity_tier") or "").strip().upper()
    )
    if pre_guardian_tier in PAPER_OPPORTUNITY_TIERS:
        context["pre_guardian_source_tier"] = pre_guardian_tier
        context["pre_guardian_policy_tier"] = pre_guardian_tier

    guardian_status = classification.get("continuous_edge_guardian_status")
    if guardian_status not in (None, ""):
        context["guardian_status"] = guardian_status
    guardian_new_entries_allowed = classification.get(
        "continuous_edge_guardian_new_entries_allowed"
    )
    if guardian_new_entries_allowed is not None:
        context["guardian_new_entries_allowed"] = guardian_new_entries_allowed
    guardian_block_reasons = classification.get("continuous_edge_guardian_block_reasons")
    if guardian_block_reasons not in (None, ""):
        context["guardian_block_reasons"] = guardian_block_reasons
    guardian_allowed_actions = classification.get(
        "continuous_edge_guardian_allowed_runtime_actions"
    )
    if guardian_allowed_actions not in (None, ""):
        context["guardian_allowed_runtime_actions"] = guardian_allowed_actions
    return context


