def _block_non_executable_paper_tier(
    *,
    intent: dict[str, Any],
    allocation: dict[str, Any],
) -> bool:
    tier = str(intent.get("paper_opportunity_tier") or "").strip().upper()
    if tier not in NON_EXECUTABLE_PAPER_TIERS:
        return False

    original_tier_reason = _first_present(
        intent.get("paper_opportunity_tier_reason"),
        allocation.get("paper_opportunity_tier_reason"),
    )
    tier_block_reason = f"NON_EXECUTABLE_PAPER_TIER:{tier}"
    original_decision = allocation.get("allocator_decision")
    existing_gate_reasons = {
        str(reason)
        for reason in (
            list(intent.get("paper_fill_gate_block_reasons") or [])
            + list(allocation.get("paper_fill_gate_block_reasons") or [])
            + list(intent.get("local_block_reasons") or [])
            + list(allocation.get("local_block_reasons") or [])
            + [
                intent.get("paper_fill_block_reason"),
                allocation.get("paper_fill_block_reason"),
                intent.get("paper_allocation_block_reason"),
                allocation.get("paper_allocation_block_reason"),
            ]
        )
        if str(reason).strip()
    }
    performance_circuit_already_blocked = (
        intent.get("paper_performance_circuit_breaker_blocked") is True
        or allocation.get("paper_performance_circuit_breaker_blocked") is True
        or PAPER_PERFORMANCE_CIRCUIT_BREAKER_BLOCK_REASON in existing_gate_reasons
        or PAPER_PERFORMANCE_CIRCUIT_BREAKER_HALT_REASON in existing_gate_reasons
        or any("PAPER_PERFORMANCE_CIRCUIT" in reason.upper() for reason in existing_gate_reasons)
    )
    original_decision_text = str(original_decision or "").strip().upper()
    existing_allocator_decision_blocked = original_decision_text.startswith(
        "BLOCK"
    ) and original_decision_text not in {
        "BLOCK_NON_EXECUTABLE_PAPER_TIER",
        "BLOCK_PAPER_PERFORMANCE_CIRCUIT_BREAKER",
    }
    existing_allocator_block_reason = _first_present(
        intent.get("paper_allocation_block_reason"),
        allocation.get("paper_allocation_block_reason"),
        intent.get("paper_fill_block_reason"),
        allocation.get("paper_fill_block_reason"),
        original_decision,
    )
    preserve_existing_allocator_block = (
        existing_allocator_decision_blocked
        and existing_allocator_block_reason not in {None, ""}
        and not performance_circuit_already_blocked
    )
    primary_block_reason = (
        PAPER_PERFORMANCE_CIRCUIT_BREAKER_BLOCK_REASON
        if performance_circuit_already_blocked
        else (
            str(existing_allocator_block_reason)
            if preserve_existing_allocator_block
            else tier_block_reason
        )
    )
    for target in (allocation, intent):
        target["non_executable_paper_tier_block_reason"] = (
            primary_block_reason if performance_circuit_already_blocked else tier_block_reason
        )
        target["non_executable_paper_tier_primary_block_reason"] = primary_block_reason
        target["non_executable_paper_tier_secondary_to_existing_block"] = (
            preserve_existing_allocator_block
        )
    if original_tier_reason not in {None, ""} and original_tier_reason not in {
        primary_block_reason,
        tier_block_reason,
    }:
        for target in (allocation, intent):
            target.setdefault("pre_non_executable_paper_tier", tier)
            target.setdefault("pre_non_executable_paper_tier_reason", original_tier_reason)

    if original_decision not in {None, ""}:
        allocation.setdefault(
            "original_allocator_decision_before_paper_tier_block",
            original_decision,
        )
        intent.setdefault(
            "original_allocator_decision_before_paper_tier_block",
            original_decision,
        )

    for field in (
        "risk_budget_usd",
        "gross_notional_usd",
        "allocated_margin_usd",
        "target_notional_usdt",
        "target_quantity",
        "expected_net_pnl_usd",
        "expected_shortfall_usd",
        "hedge_budget_usd",
    ):
        value = allocation.get(field)
        if value not in {None, ""}:
            allocation.setdefault(f"pre_paper_tier_block_{field}", value)
            intent.setdefault(f"pre_paper_tier_block_{field}", value)
        allocation[field] = 0.0
        if field in intent:
            intent[field] = 0.0

    allocator_block_decision = (
        "BLOCK_PAPER_PERFORMANCE_CIRCUIT_BREAKER"
        if performance_circuit_already_blocked
        else (
            str(original_decision)
            if preserve_existing_allocator_block
            else "BLOCK_NON_EXECUTABLE_PAPER_TIER"
        )
    )
    allocation["allocator_decision"] = allocator_block_decision
    allocation["final_size_reason"] = primary_block_reason
    allocation["capital_allocation_reason"] = primary_block_reason
    allocation["non_executable_paper_tier_blocked"] = True
    allocation["paper_only"] = True
    allocation["places_real_order"] = False
    allocation["live_order"] = False
    intent["allocator_decision"] = allocator_block_decision
    intent["allocator_reason"] = primary_block_reason
    intent["capital_allocation_reason"] = primary_block_reason
    intent["paper_allocation_block_reason"] = (
        intent.get("paper_allocation_block_reason") or primary_block_reason
    )
    # Preserve earlier high-priority block reasons (P0 gate, strategy mode collapse, etc.).
    intent["paper_fill_block_reason"] = (
        intent.get("paper_fill_block_reason") or primary_block_reason
    )
    intent["paper_sizing_source"] = "NON_EXECUTABLE_PAPER_TIER_BLOCK"
    intent["paper_sizing_complete"] = False
    intent["paper_fill_allowed"] = False
    intent["paper_tier_local_fill_allowed"] = False
    intent["strict_paper_fill_allowed_upstream"] = False
    intent["places_real_order"] = False
    intent["live_order"] = False
    intent["paper_only"] = True
    if performance_circuit_already_blocked:
        intent["local_block_reasons"] = sorted(
            set(
                list(intent.get("local_block_reasons") or [])
                + [f"paper_performance_circuit_breaker:{primary_block_reason}"]
            )
        )
    elif preserve_existing_allocator_block:
        intent["local_block_reasons"] = sorted(
            set(
                list(intent.get("local_block_reasons") or [])
                + [f"existing_allocator_block:{primary_block_reason}"]
            )
        )
    else:
        intent["local_block_reasons"] = sorted(
            set(list(intent.get("local_block_reasons") or []) + [f"paper_tier:{tier_block_reason}"])
        )
    intent["paper_fill_gate_block_reasons"] = sorted(
        set(list(intent.get("paper_fill_gate_block_reasons") or []) + [primary_block_reason])
    )
    return True


def _shadow_observation_from_blocked_directional_candidate(
    *,
    intent: dict[str, Any],
    signal: dict[str, Any] | None = None,
    integrity_gate: dict[str, Any] | None = None,
    observation_source: str,
    observation_reason: Any,
) -> dict[str, Any] | None:
    """Build a non-fill shadow observation for a valid blocked candidate.

    This is only for counterfactual no-trade outcome analysis. It must not
    change paper admission, accepted fills, PnL, A-grade evidence, or live
    routing.
    """
    signal = signal if isinstance(signal, dict) else {}
    side = _normalized_directional_side(
        _first_present(
            intent.get("side"),
            intent.get("selected_action"),
            intent.get("action"),
            signal.get("side"),
            signal.get("selected_action"),
            signal.get("action"),
        )
    )
    if side not in {"long", "short"}:
        return None
    if intent.get("paper_only") is not True:
        return None
    if intent.get("places_real_order") is True or intent.get("live_order") is True:
        return None
    if intent.get("entry_price_provenance_present") is not True:
        return None
    entry_price = _coerce_float(intent.get("entry_price"))
    if entry_price is None or entry_price <= 0.0:
        return None
    if integrity_gate is not None and integrity_gate.get("allowed") is not True:
        return None
    if intent.get("valid_for_paper") is False:
        return None
    if intent.get("market_state_reject_reasons"):
        return None
    if intent.get("paper_signal_temporal_rejection_reasons"):
        return None
    if intent.get("paper_pre_fill_market_evidence_rejection_reasons"):
        return None
    if _paper_lifecycle_or_no_trade_strategy_reasons(signal=signal, intent=intent):
        return None

    shadow_intent = dict(intent)
    shadow_intent["decision"] = "SHADOW_OBSERVATION_ONLY"
    shadow_intent["side"] = side
    shadow_intent["shadow_observation_source"] = observation_source
    shadow_intent["shadow_observation_reason"] = str(
        observation_reason
        or intent.get("paper_fill_block_reason")
        or "BLOCKED_DIRECTIONAL_CANDIDATE"
    )
    shadow_intent["shadow_observation_selected_before_outcome"] = True
    shadow_intent["shadow_outcome_observation_only"] = True
    shadow_intent["paper_fill_allowed"] = False
    shadow_intent["paper_tier_local_fill_allowed"] = False
    shadow_intent["strict_paper_fill_allowed_upstream"] = False
    shadow_intent["places_real_order"] = False
    shadow_intent["live_order"] = False
    shadow_intent["counted_as_accepted_position"] = False
    shadow_intent["counted_as_fill"] = False
    shadow_intent["counted_as_open_position"] = False
    shadow_intent["affects_pnl_ledger"] = False
    shadow_intent["counts_as_a_grade_evidence"] = False
    shadow_intent["a_grade_promotion_allowed"] = False
    shadow_intent["live_ready_implication"] = False
    shadow_intent["entry_price_provenance_observed"] = True
    shadow_intent["candidate_selected_after_outcome"] = False
    shadow_intent["future_labels_used_as_features"] = False
    return shadow_intent


SHADOW_OBSERVATION_ENTRY_FIELDS = (
    "entry_price",
    "entry_price_source",
    "entry_price_utc",
    "entry_price_source_generated_utc",
    "entry_price_source_available_at",
    "fill_price",
    "fill_price_source",
    "fill_price_utc",
    "latest_price",
    "latest_price_source",
    "latest_price_utc",
)


def _shadow_observation_history_key(row: dict[str, Any]) -> str:
    stable_id = _first_present(
        row.get("prediction_id"),
        row.get("source_prediction_id"),
        row.get("signal_id"),
        row.get("intent_id"),
        row.get("source_intent_id"),
    )
    symbol = str(row.get("symbol") or "").upper()
    side = str(row.get("side") or row.get("selected_action") or "").lower()
    timeframe = str(row.get("timeframe") or "")
    source = str(row.get("shadow_observation_source") or "")
    reason = str(
        _first_present(
            row.get("shadow_observation_reason"),
            row.get("paper_fill_block_reason"),
            row.get("paper_opportunity_tier_reason"),
        )
        or ""
    )
    if stable_id not in (None, ""):
        return "|".join(("id", str(stable_id), symbol, side, timeframe, source, reason))
    return "|".join(
        (
            "fallback",
            symbol,
            side,
            timeframe,
            source,
            reason,
            str(row.get("entry_price_utc") or row.get("generated_utc") or ""),
        )
    )


def _shadow_observation_entry_time(row: dict[str, Any]) -> datetime | None:
    return _parse_strategy_time(
        _first_present(
            row.get("entry_price_utc"),
            row.get("shadow_observation_first_seen_utc"),
            row.get("generated_utc"),
        )
    )


def _normalize_shadow_observation_history_row(
    row: dict[str, Any],
    *,
    now_utc: str,
) -> dict[str, Any] | None:
    if not isinstance(row, dict):
        return None
    if row.get("decision") != "SHADOW_OBSERVATION_ONLY":
        return None
    normalized = dict(row)
    normalized["decision"] = "SHADOW_OBSERVATION_ONLY"
    normalized["paper_fill_allowed"] = False
    normalized["paper_tier_local_fill_allowed"] = False
    normalized["strict_paper_fill_allowed_upstream"] = False
    normalized["places_real_order"] = False
    normalized["live_order"] = False
    normalized["counted_as_accepted_position"] = False
    normalized["counted_as_fill"] = False
    normalized["counted_as_open_position"] = False
    normalized["affects_pnl_ledger"] = False
    normalized["counts_as_a_grade_evidence"] = False
    normalized["a_grade_promotion_allowed"] = False
    normalized["live_ready_implication"] = False
    normalized["shadow_observation_history_persisted"] = True
    normalized["shadow_observation_first_seen_utc"] = _first_present(
        normalized.get("shadow_observation_first_seen_utc"),
        normalized.get("entry_price_utc"),
        now_utc,
    )
    normalized["shadow_observation_last_seen_utc"] = _first_present(
        normalized.get("shadow_observation_last_seen_utc"),
        normalized.get("generated_utc"),
        now_utc,
    )
    seen_count = int(_coerce_float(normalized.get("shadow_observation_seen_count")) or 1)
    normalized["shadow_observation_seen_count"] = max(1, seen_count)
    return normalized


def _merge_shadow_observation_history(
    existing_rows: list[dict[str, Any]],
    current_rows: list[dict[str, Any]],
    *,
    now_utc: str | None = None,
    max_rows: int = SHADOW_OBSERVATION_HISTORY_MAX_ROWS,
) -> list[dict[str, Any]]:
    """Merge current-cycle shadow rows with prior V2 shadow history.

    The current paper loop rebuilds intents every cycle. Without this bounded
    merge, each non-fill shadow entry receives a new timestamp and can never
    mature to the counterfactual outcome horizon.
    """
    now_utc = now_utc or _utc_iso()
    now_dt = _parse_strategy_time(now_utc) or datetime.now(timezone.utc)
    by_key: dict[str, dict[str, Any]] = {}

    for raw in existing_rows:
        row = _normalize_shadow_observation_history_row(raw, now_utc=now_utc)
        if row is None:
            continue
        entry_dt = _shadow_observation_entry_time(row)
        if (
            entry_dt is not None
            and (now_dt - entry_dt).total_seconds() > SHADOW_OBSERVATION_HISTORY_TTL_SECONDS
        ):
            continue
        by_key[_shadow_observation_history_key(row)] = row

    for raw in current_rows:
        row = _normalize_shadow_observation_history_row(raw, now_utc=now_utc)
        if row is None:
            continue
        key = _shadow_observation_history_key(row)
        existing = by_key.get(key)
        if existing is not None:
            merged = dict(row)
            for field in SHADOW_OBSERVATION_ENTRY_FIELDS:
                if existing.get(field) not in (None, ""):
                    merged[field] = existing[field]
            merged["shadow_observation_first_seen_utc"] = _first_present(
                existing.get("shadow_observation_first_seen_utc"),
                existing.get("entry_price_utc"),
                row.get("entry_price_utc"),
                now_utc,
            )
            merged["shadow_observation_seen_count"] = (
                int(_coerce_float(existing.get("shadow_observation_seen_count")) or 1) + 1
            )
        else:
            merged = row
        merged["shadow_observation_last_seen_utc"] = now_utc
        merged["shadow_observation_history_persisted"] = True
        by_key[key] = merged

    rows = list(by_key.values())
    rows.sort(
        key=lambda row: (
            _shadow_observation_entry_time(row) or datetime.min.replace(tzinfo=timezone.utc),
            _shadow_observation_history_key(row),
        )
    )
    if max_rows > 0 and len(rows) > max_rows:
        rows = rows[-max_rows:]
    return rows


def _paper_reallocate_for_reduced_risk_budget(
    *,
    intent: dict[str, Any],
    allocation_input: Any,
    normal_allocation: Mapping[str, Any],
    envelope: Any,
    redis_client: Any,
    security_context: Any | None,
    allocation_decision_time: datetime,
    allocate_fn: Any,
    risk_budget_fraction_of_normal_adaptive: Any,
) -> tuple[dict[str, Any], dict[str, Any]]:
    """Rerun the allocator for a reduced paper risk budget.

    Quantity, notional, margin, fees, loss, exchange minimums, and step-size
    quantization are coupled.  Multiplying a completed allocation field-by-field
    breaks those invariants, so every reduced tier returns to the allocator with
    the reduced budget before quantization and maintenance-bracket selection.
    """

    fraction = _coerce_float(risk_budget_fraction_of_normal_adaptive) or 0.0
    fraction = _clamp_float(
        fraction,
        0.0,
        B_GRADE_EXPLORATION_MAX_RISK_FRACTION_OF_NORMAL,
    )
    if not math.isfinite(fraction) or fraction <= 0.0:
        reduced_input = replace(
            allocation_input,
            risk_veto=True,
            risk_veto_reason="INVALID_REDUCED_PAPER_RISK_BUDGET_FRACTION",
        )
    else:
        base_fraction = _coerce_float(getattr(allocation_input, "paper_risk_budget_fraction", 1.0))
        if (
            base_fraction is None
            or not math.isfinite(base_fraction)
            or not 0.0 < base_fraction <= 1.0
        ):
            reduced_input = replace(
                allocation_input,
                risk_veto=True,
                risk_veto_reason="INVALID_BASE_PAPER_RISK_BUDGET_FRACTION",
            )
        else:
            reduced_input = replace(
                allocation_input,
                paper_risk_budget_fraction=base_fraction * fraction,
            )

    allocation_result, _, bracket_context = _paper_allocate_with_bracket_evidence(
        allocation_input=reduced_input,
        envelope=envelope,
        redis_client=redis_client,
        security_context=security_context,
        allocation_decision_time=allocation_decision_time,
        allocate_fn=allocate_fn,
    )
    allocation = allocation_result.to_payload()
    fraction_rounded = round(fraction, 8)
    normal_model_inputs = (
        normal_allocation.get("model_inputs")
        if isinstance(normal_allocation.get("model_inputs"), Mapping)
        else {}
    )
    model_inputs = (
        allocation.get("model_inputs") if isinstance(allocation.get("model_inputs"), dict) else {}
    )
    allocation["model_inputs"] = model_inputs
    for field in B_GRADE_EXPLORATION_SCALABLE_ALLOCATION_FIELDS:
        value = normal_allocation.get(field)
        if value not in (None, ""):
            normal_field = f"normal_adaptive_{field}"
            allocation[normal_field] = value
            intent[normal_field] = value
    allocation["normal_adaptive_allocation_id"] = normal_allocation.get("allocation_id")
    intent["normal_adaptive_allocation_id"] = normal_allocation.get("allocation_id")
    if normal_model_inputs.get("selected_allocated_margin_usd") not in (None, ""):
        model_inputs["normal_adaptive_selected_allocated_margin_usd"] = normal_model_inputs.get(
            "selected_allocated_margin_usd"
        )
    for target in (intent, allocation, model_inputs):
        target["b_grade_exploration_budget_cap_applied"] = True
        target["risk_budget_fraction_of_normal_adaptive"] = fraction_rounded
        target["paper_reduced_budget_allocator_recomputed"] = True
        target["mandatory_size_haircut"] = True
        target["counts_as_a_grade_evidence"] = False
        target["counts_as_A_plus"] = False
        target["counts_as_final_a_plus"] = False
        target["counts_as_live_ready"] = False
        target["no_static_dollar_notional"] = True
        target["no_leverage_increase_to_compensate_for_lower_trust"] = True
        target["paper_reduced_budget_recompute_mode"] = (
            "ALLOCATOR_PRE_QUANTIZATION_WITH_FRESH_BOUND_BRACKET_EVIDENCE"
        )
        target["paper_only"] = True
        target["places_real_order"] = False
    intent["routes_to_live"] = False
    allocation["routes_to_live"] = False
    model_inputs["normal_adaptive_risk_budget_usd"] = normal_allocation.get("risk_budget_usd")
    model_inputs["normal_adaptive_gross_notional_usd"] = normal_allocation.get("gross_notional_usd")
    return allocation, bracket_context


def _paper_exploration_tier_status(
    *,
    accepted_rows: list[dict[str, Any]],
    current_accepted_rows: list[dict[str, Any]] | None = None,
    blocked_rows: list[dict[str, Any]],
    shadow_rows: list[dict[str, Any]],
    held_rows: list[dict[str, Any]],
) -> dict[str, Any]:
    persistent_accepted_rows = accepted_rows
    current_accepted_rows = (
        current_accepted_rows if current_accepted_rows is not None else accepted_rows
    )
    rows = current_accepted_rows + blocked_rows + shadow_rows + held_rows
    b_grade_accepted = [
        row
        for row in current_accepted_rows
        if row.get("paper_opportunity_tier") == PAPER_TIER_B_GRADE_EXPLORATION
    ]
    a_plus_bootstrap_accepted = [
        row for row in current_accepted_rows if _is_a_plus_reduced_size_bootstrap_row(row)
    ]
    persistent_b_grade_accepted = [
        row
        for row in persistent_accepted_rows
        if row.get("paper_opportunity_tier") == PAPER_TIER_B_GRADE_EXPLORATION
    ]
    persistent_a_plus_bootstrap_accepted = [
        row for row in persistent_accepted_rows if _is_a_plus_reduced_size_bootstrap_row(row)
    ]
    priority_rows = [row for row in rows if row.get("paper_only_label_collection_priority") is True]
    priority_b_grade_accepted = [
        row for row in b_grade_accepted if row.get("paper_only_label_collection_priority") is True
    ]
    persistent_priority_b_grade_accepted = [
        row
        for row in persistent_b_grade_accepted
        if row.get("paper_only_label_collection_priority") is True
    ]
    fractions = [
        value
        for value in (
            _coerce_float(row.get("risk_budget_fraction_of_normal_adaptive"))
            for row in b_grade_accepted
        )
        if value is not None
    ]
    b_grade_operator = _paper_status_operator_row_collection(
        b_grade_accepted,
        source_collection="paper_exploration_tier_status.b_grade_accepted",
        authoritative_source="paper_loop:current_cycle_b_grade_accepted_rows",
    )
    priority_b_grade_operator = _paper_status_operator_row_collection(
        priority_b_grade_accepted,
        source_collection=("paper_exploration_tier_status.priority_b_grade_accepted"),
        authoritative_source=("paper_loop:current_cycle_priority_b_grade_accepted_rows"),
    )
    blocked_operator = _paper_status_operator_row_collection(
        blocked_rows,
        source_collection="paper_exploration_tier_status.blocked",
        authoritative_source="paper_loop:current_cycle_blocked_rows",
    )
    return {
        "status": "ACTIVE",
        "paper_only": True,
        "live_path_changed": False,
        "tiers": list(PAPER_OPPORTUNITY_TIERS),
        "tier_counts": _count_paper_opportunity_tiers(rows),
        "accepted_tier_counts": _count_paper_opportunity_tiers(current_accepted_rows),
        "accepted_tier_counts_scope": "current_cycle_accepted_fills_only",
        "persistent_accepted_fill_count": len(persistent_accepted_rows),
        "persistent_accepted_tier_counts": _count_paper_opportunity_tiers(persistent_accepted_rows),
        "blocked_tier_counts": _count_paper_opportunity_tiers(blocked_rows),
        "blocked_final_reason_counts": _count_first_present_values(
            blocked_rows,
            (
                "non_executable_paper_tier_block_reason",
                "paper_fill_block_reason",
                "paper_allocation_block_reason",
                "allocator_reason",
                "paper_opportunity_tier_reason",
            ),
        ),
        "blocked_upstream_tier_reason_counts": _count_first_present_values(
            blocked_rows,
            (
                "pre_non_executable_paper_tier_reason",
                "original_paper_opportunity_tier_reason_before_publication_block",
            ),
        ),
        "blocked_local_block_reason_counts": _count_list_values(
            blocked_rows, "local_block_reasons"
        ),
        "blocked_fill_gate_reason_counts": _count_list_values(
            blocked_rows, "paper_fill_gate_block_reasons"
        ),
        "blocked_runtime_market_evidence_rejection_counts": _count_list_values(
            blocked_rows,
            "paper_runtime_market_evidence_rejection_reasons",
        ),
        "blocked_pre_fill_market_evidence_rejection_counts": _count_list_values(
            blocked_rows,
            "paper_pre_fill_market_evidence_rejection_reasons",
        ),
        "blocked_post_fill_market_evidence_rejection_counts": _count_list_values(
            blocked_rows,
            "paper_post_fill_market_evidence_rejection_reasons",
        ),
        "blocked_lifecycle_or_no_trade_strategy_reason_counts": _count_list_values(
            blocked_rows,
            "lifecycle_or_no_trade_strategy_reasons",
        ),
        "shadow_tier_counts": _count_paper_opportunity_tiers(shadow_rows),
        "held_tier_counts": _count_paper_opportunity_tiers(held_rows),
        "legacy_unclassified_tier_count": _missing_paper_opportunity_tier_count(rows),
        "legacy_accepted_without_tier_count": _missing_paper_opportunity_tier_count(
            current_accepted_rows
        ),
        "persistent_legacy_accepted_without_tier_count": _missing_paper_opportunity_tier_count(
            persistent_accepted_rows
        ),
        "blocked_without_tier_count": _missing_paper_opportunity_tier_count(blocked_rows),
        "shadow_without_tier_count": _missing_paper_opportunity_tier_count(shadow_rows),
        "held_without_tier_count": _missing_paper_opportunity_tier_count(held_rows),
        "b_grade_exploration_accepted_count": len(b_grade_accepted),
        "b_grade_exploration_accepted_count_scope": "current_cycle_accepted_fills_only",
        "persistent_b_grade_exploration_accepted_count": len(persistent_b_grade_accepted),
        "a_plus_reduced_size_bootstrap_accepted_count": len(a_plus_bootstrap_accepted),
        "a_plus_reduced_size_bootstrap_accepted_count_scope": ("current_cycle_accepted_fills_only"),
        "persistent_a_plus_reduced_size_bootstrap_accepted_count": len(
            persistent_a_plus_bootstrap_accepted
        ),
        "a_plus_reduced_size_bootstrap_paper_only": True,
        "a_plus_reduced_size_bootstrap_counts_as_final_a_plus": False,
        "a_plus_reduced_size_bootstrap_routes_to_live": False,
        "b_grade_exploration_max_risk_fraction_of_normal_adaptive": (
            B_GRADE_EXPLORATION_MAX_RISK_FRACTION_OF_NORMAL
        ),
        "b_grade_exploration_observed_max_risk_fraction": (
            round(max(fractions), 8) if fractions else 0.0
        ),
        "b_grade_exploration_budget_cap_applied_count": sum(
            1
            for row in b_grade_accepted
            if row.get("b_grade_exploration_budget_cap_applied") is True
        ),
        "paper_only_label_collection_priority_candidate_count": len(priority_rows),
        "paper_only_label_collection_priority_b_grade_accepted_count": (
            len(priority_b_grade_accepted)
        ),
        "persistent_paper_only_label_collection_priority_b_grade_accepted_count": (
            len(persistent_priority_b_grade_accepted)
        ),
        "paper_only_label_collection_priority_reason_counts": _count_first_present_values(
            priority_rows,
            (
                "paper_opportunity_tier_reason",
                "paper_only_label_collection_priority_reason",
            ),
        ),
        "paper_only_label_collection_priority_live_routing_blocked": all(
            row.get("paper_only") is True
            and row.get("places_real_order") is False
            and row.get("counts_as_a_grade_evidence") is False
            for row in priority_rows
        ),
        "b_grade_exploration_live_routing_blocked": all(
            row.get("paper_only") is True and row.get("places_real_order") is False
            for row in b_grade_accepted
        ),
        "calibration_label_purpose": "B_GRADE_EXPLORATION_OUTCOME_LABEL",
        "sample_b_grade_exploration_fills": b_grade_operator["operator_rows"],
        "sample_b_grade_exploration_fills_operator_contract": (b_grade_operator["contract"]),
        "sample_paper_only_label_collection_priority_fills": (
            priority_b_grade_operator["operator_rows"]
        ),
        "sample_paper_only_label_collection_priority_fills_operator_contract": (
            priority_b_grade_operator["contract"]
        ),
        "sample_blocked_fills": blocked_operator["operator_rows"],
        "sample_blocked_fills_operator_contract": blocked_operator["contract"],
        "generated_utc": _utc_iso(),
    }


def _paper_canary_score(row: dict[str, Any]) -> float | None:
    return _coerce_float(
        _first_present(
            row.get("confidence_calibrated"),
            row.get("score"),
            row.get("selected_action_probability"),
            row.get("confidence_raw"),
            row.get("strategy_router_confidence"),
        )
    )


def _paper_canary_edge_favorable(row: dict[str, Any]) -> bool:
    side = _normalized_directional_side(
        _first_present(row.get("side"), row.get("selected_action"), row.get("action"))
    )
    edge = _coerce_float(
        _first_present(
            row.get("expected_move_after_cost_bps"),
            row.get("expected_net_edge_bps"),
            row.get("paper_allocation_signed_expected_move_after_cost_bps"),
        )
    )
    if side not in {"long", "short"} or edge is None:
        return False
    return expected_move_after_cost_favorable_for_side(
        side=side,
        expected_move_after_cost_bps=edge,
    )


def _paper_canary_liquidity_pass(row: dict[str, Any]) -> bool:
    reason_text = " ".join(
        str(value or "")
        for value in (
            row.get("paper_opportunity_tier_reason"),
            row.get("paper_fill_block_reason"),
            row.get("paper_allocation_block_reason"),
            row.get("allocator_reason"),
        )
    ).upper()
    list_reasons = " ".join(
        str(reason or "")
        for field in (
            "paper_fill_gate_block_reasons",
            "local_block_reasons",
            "paper_runtime_market_evidence_rejection_reasons",
            "paper_pre_fill_market_evidence_rejection_reasons",
            "paper_post_fill_market_evidence_rejection_reasons",
        )
        for reason in (row.get(field) or [])
    ).upper()
    return not any(
        token in f"{reason_text} {list_reasons}"
        for token in ("SPREAD", "SLIPPAGE", "LIQUIDITY", "LIQUIDATION")
    )


def _paper_canary_integrity_pass(row: dict[str, Any]) -> bool:
    if row.get("valid_for_paper") is False:
        return False
    reason = str(row.get("paper_opportunity_tier_reason") or "").upper()
    if "INTEGRITY" in reason:
        return False
    if row.get("market_state_reject_reasons"):
        return False
    return True


def _paper_canary_risk_pass(row: dict[str, Any]) -> bool:
    if not row.get("risk_decision_id"):
        return False
    joined = " ".join(
        str(reason or "")
        for field in ("paper_fill_gate_block_reasons", "local_block_reasons")
        for reason in (row.get(field) or [])
    ).upper()
    return not any(
        token in joined for token in ("RISK", "DRAWDOWN", "EXPOSURE", "CAP", "LIQUIDATION")
    )


def _paper_canary_pre_tier_allocator_pass(row: dict[str, Any]) -> bool:
    gross_notional = _coerce_float(
        _first_present(
            row.get("pre_paper_tier_block_gross_notional_usd"),
            row.get("normal_adaptive_gross_notional_usd"),
            row.get("gross_notional_usd"),
            row.get("target_notional_usdt"),
        )
    )
    risk_budget = _coerce_float(
        _first_present(
            row.get("pre_paper_tier_block_risk_budget_usd"),
            row.get("normal_adaptive_risk_budget_usd"),
            row.get("risk_budget_usd"),
        )
    )
    return (
        gross_notional is not None
        and gross_notional > 0.0
        and risk_budget is not None
        and risk_budget > 0.0
    )


def _paper_canary_adaptive_sizing_pass(row: dict[str, Any]) -> bool:
    if row.get("paper_canary_fixed_notional_allowed") is True:
        return False
    if row.get("paper_canary_live_routing_allowed") is True:
        return False
    allocation = row.get("adaptive_allocation")
    adaptive_policy = str(row.get("adaptive_capital_policy_version") or "")
    has_adaptive_allocator_evidence = (
        adaptive_policy.startswith("ADAPTIVE_CAPITAL_ALLOCATOR")
        or isinstance(allocation, dict)
        or row.get("paper_canary_adaptive_sizing_required") is True
    )
    return has_adaptive_allocator_evidence and _paper_canary_pre_tier_allocator_pass(row)


def _paper_b_grade_lifecycle_canary_row(row: dict[str, Any]) -> bool:
    return (
        row.get("paper_opportunity_tier") == PAPER_TIER_B_GRADE_EXPLORATION
        and _paper_forward_canary_challenger_owned(row)
        and _paper_challenger_b_grade_canary_identity_bound(row)
        and row.get("paper_fill_allowed") is True
        and row.get("paper_only") is True
        and not _paper_forward_canary_live_route_unsafe(row)
        and row.get("counts_as_a_grade_evidence") is not True
        and _paper_forward_canary_production_cost_pass(row)
        and _paper_canary_score(row) is not None
        and _paper_canary_edge_favorable(row)
        and _paper_canary_liquidity_pass(row)
        and _paper_canary_integrity_pass(row)
        and _paper_canary_risk_pass(row)
        and bool(row.get("orchestrator_decision_id"))
        and _paper_canary_adaptive_sizing_pass(row)
    )


def _paper_b_grade_canary_supply_status(
    rows: list[dict[str, Any]],
    *,
    accepted_rows: list[dict[str, Any]] | None = None,
    open_position_rows: list[dict[str, Any]] | None = None,
    closed_rows: list[dict[str, Any]] | None = None,
) -> dict[str, Any]:
    """Summarize current paper-only B-grade canary supply without admitting fills."""
    accepted_rows = list(accepted_rows or [])
    open_position_rows = list(open_position_rows or [])
    closed_rows = list(closed_rows or [])
    canary_intent_rows = [
        row for row in rows if row.get("paper_opportunity_tier") == PAPER_TIER_B_GRADE_EXPLORATION
    ]
    canary_pending_rows = [
        row
        for row in canary_intent_rows
        if row.get("paper_fill_allowed") is True
        and row.get("paper_only") is True
        and row.get("places_real_order") is not True
    ]

    predicate_rows: list[dict[str, Any]] = []
    near_miss_strategy_rows: list[dict[str, Any]] = []
    root_causes = {
        "score_below_threshold": 0,
        "expected_edge_below_cost": 0,
        "production_grade_cost_missing": 0,
        "challenger_owner_missing": 0,
        "liquidity_failed": 0,
        "integrity_failed": 0,
        "risk_failed": 0,
        "orchestrator_failed": 0,
        "strategy_failed": 0,
        "allocator_failed": 0,
        "canary_identity_missing": 0,
        "distribution_drift": 0,
        "point_in_time_long_short_unavailable": 0,
        "unsafe_live_route_flags": 0,
    }
    predicate_counts = {
        "score_threshold_pass_rows": 0,
        "expected_edge_after_cost_favorable_rows": 0,
        "production_grade_cost_rows": 0,
        "challenger_owner_rows": 0,
        "liquidity_pass_rows": 0,
        "integrity_pass_rows": 0,
        "risk_gateway_decision_rows": 0,
        "risk_pass_rows": 0,
        "orchestrator_rows": 0,
        "strategy_entry_evidence_rows": 0,
        "allocator_pre_tier_size_rows": 0,
        "canary_identity_bound_rows": 0,
        "long_short_point_in_time_rows": 0,
        "paper_only_safety_rows": 0,
    }

    for row in rows:
        score = _paper_canary_score(row)
        score_pass = score is not None and score >= B_GRADE_EXPLORATION_MIN_CONFIDENCE
        edge_pass = _paper_canary_edge_favorable(row)
        production_cost_pass = row.get("production_grade_cost_flag") is True
        challenger_owner_pass = _paper_forward_canary_challenger_owned(row)
        liquidity_pass = _paper_canary_liquidity_pass(row)
        integrity_pass = _paper_canary_integrity_pass(row)
        risk_gateway_decision = bool(row.get("risk_decision_id"))
        risk_pass = _paper_canary_risk_pass(row)
        orchestrator_pass = bool(row.get("orchestrator_decision_id"))
        strategy_reasons = _paper_lifecycle_or_no_trade_strategy_reasons(
            signal={},
            intent=row,
        )
        strategy_pass = not strategy_reasons
        allocator_pass = _paper_canary_pre_tier_allocator_pass(row)
        canary_identity_bound = _paper_challenger_b_grade_canary_identity_bound(row)
        long_short_status = str(row.get("long_short_ratio_status") or "")
        long_short_pass = long_short_status == "V2_LONG_SHORT_RATIO_ATTACHED" or row.get(
            "long_short_ratio"
        ) not in (None, "")
        paper_only_safety = (
            row.get("paper_only") is True
            and row.get("routes_to_live") is not True
            and row.get("places_real_order") is not True
            and row.get("live_order") is not True
            and row.get("test_order") is not True
            and row.get("counts_as_a_grade_evidence") is not True
            and row.get("paper_canary_adaptive_sizing_required") is True
            and row.get("paper_canary_fixed_notional_allowed") is False
            and row.get("paper_canary_live_routing_allowed") is False
        )

        predicate_counts["score_threshold_pass_rows"] += int(score_pass)
        predicate_counts["expected_edge_after_cost_favorable_rows"] += int(edge_pass)
        predicate_counts["production_grade_cost_rows"] += int(production_cost_pass)
        predicate_counts["challenger_owner_rows"] += int(challenger_owner_pass)
        predicate_counts["liquidity_pass_rows"] += int(liquidity_pass)
        predicate_counts["integrity_pass_rows"] += int(integrity_pass)
        predicate_counts["risk_gateway_decision_rows"] += int(risk_gateway_decision)
        predicate_counts["risk_pass_rows"] += int(risk_pass)
        predicate_counts["orchestrator_rows"] += int(orchestrator_pass)
        predicate_counts["strategy_entry_evidence_rows"] += int(strategy_pass)
        predicate_counts["allocator_pre_tier_size_rows"] += int(allocator_pass)
        predicate_counts["canary_identity_bound_rows"] += int(canary_identity_bound)
        predicate_counts["long_short_point_in_time_rows"] += int(long_short_pass)
        predicate_counts["paper_only_safety_rows"] += int(paper_only_safety)

        if not score_pass:
            root_causes["score_below_threshold"] += 1
        if not edge_pass:
            root_causes["expected_edge_below_cost"] += 1
        if not production_cost_pass:
            root_causes["production_grade_cost_missing"] += 1
        if not challenger_owner_pass:
            root_causes["challenger_owner_missing"] += 1
        if not liquidity_pass:
            root_causes["liquidity_failed"] += 1
        if not integrity_pass:
            root_causes["integrity_failed"] += 1
        if not risk_pass:
            root_causes["risk_failed"] += 1
        if not orchestrator_pass:
            root_causes["orchestrator_failed"] += 1
        if not strategy_pass:
            root_causes["strategy_failed"] += 1
        if not allocator_pass:
            root_causes["allocator_failed"] += 1
        if _paper_b_grade_canary_binding_eligible(row) and not canary_identity_bound:
            root_causes["canary_identity_missing"] += 1
        drift_reasons = row.get("paper_signal_temporal_rejection_reasons") or []
        if row.get("distribution_drift") or any(
            "DRIFT" in str(reason).upper() for reason in drift_reasons
        ):
            root_causes["distribution_drift"] += 1
        if long_short_status.startswith("REJECTED_LONG_SHORT"):
            root_causes["point_in_time_long_short_unavailable"] += 1
        if not paper_only_safety:
            root_causes["unsafe_live_route_flags"] += 1

        candidate_predicates_pass = all(
            (
                score_pass,
                edge_pass,
                production_cost_pass,
                challenger_owner_pass,
                liquidity_pass,
                integrity_pass,
                risk_pass,
                orchestrator_pass,
                strategy_pass,
                allocator_pass,
                canary_identity_bound,
                paper_only_safety,
            )
        )
        if candidate_predicates_pass:
            predicate_rows.append(row)
        elif (
            all(
                (
                    score_pass,
                    edge_pass,
                    production_cost_pass,
                    challenger_owner_pass,
                    liquidity_pass,
                    integrity_pass,
                    risk_pass,
                    orchestrator_pass,
                    allocator_pass,
                    canary_identity_bound,
                    paper_only_safety,
                )
            )
            and not strategy_pass
        ):
            near_miss_strategy_rows.append(row)

    canary_binding_eligible_rows = [
        row
        for row in rows + accepted_rows + open_position_rows + closed_rows
        if _paper_b_grade_canary_binding_eligible(row)
    ]
    canary_binding_identity_bound_rows = [
        row
        for row in canary_binding_eligible_rows
        if _paper_challenger_b_grade_canary_identity_bound(row)
    ]
    canary_binding_missing_rows = len(canary_binding_eligible_rows) - len(
        canary_binding_identity_bound_rows
    )
    lifecycle_accepted_rows = [
        row for row in accepted_rows if _paper_b_grade_lifecycle_canary_row(row)
    ]
    lifecycle_open_rows = [
        row for row in open_position_rows if _paper_b_grade_lifecycle_canary_row(row)
    ]
    lifecycle_closed_outcome_rows = [
        row
        for row in closed_rows
        if row.get("paper_opportunity_tier") == PAPER_TIER_B_GRADE_EXPLORATION
        and not _paper_forward_canary_row_rejection_reasons(row)
    ]
    combined_canary_candidates = len(predicate_rows) or len(lifecycle_accepted_rows)
    combined_canary_intents = len(canary_intent_rows) or len(lifecycle_accepted_rows)
    combined_canary_pending_rows = len(canary_pending_rows) or len(lifecycle_open_rows)
    if canary_pending_rows:
        status = "B_GRADE_CANARY_PENDING_SUPPLY_PRESENT"
    elif lifecycle_open_rows:
        status = "B_GRADE_CANARY_LIFECYCLE_SUPPLY_PRESENT_CURRENT_CYCLE_BLOCKED"
    else:
        status = "BLOCKED_ZERO_B_GRADE_CANARY_SUPPLY"

    return {
        "schema_version": "paper_b_grade_canary_supply_status_v1",
        "status": status,
        "canary_id": CHALLENGER_B_GRADE_PAPER_CANARY,
        "paper_only": True,
        "routes_to_live": False,
        "places_real_order": False,
        "counts_as_a_grade_evidence": False,
        "adaptive_sizing_required": True,
        "production_grade_cost_required": True,
        "risk_gateway_required": True,
        "orchestrator_required": True,
        "market_integrity_required": True,
        "liquidity_pass_required": True,
        "rows": len(rows),
        "canary_candidates": combined_canary_candidates,
        "canary_intents": combined_canary_intents,
        "canary_pending_rows": combined_canary_pending_rows,
        "current_cycle_canary_candidates": len(predicate_rows),
        "current_cycle_canary_intents": len(canary_intent_rows),
        "current_cycle_canary_pending_rows": len(canary_pending_rows),
        "lifecycle_accepted_canary_rows": len(lifecycle_accepted_rows),
        "lifecycle_open_canary_rows": len(lifecycle_open_rows),
        "lifecycle_closed_canary_outcome_rows": len(lifecycle_closed_outcome_rows),
        "canary_binding_eligible_rows": len(canary_binding_eligible_rows),
        "canary_binding_identity_bound_rows": len(canary_binding_identity_bound_rows),
        "canary_binding_missing_rows": canary_binding_missing_rows,
        "near_miss_strategy_blocked_rows": len(near_miss_strategy_rows),
        "predicate_counts": predicate_counts,
        "root_cause_counts": root_causes,
        "dominant_runtime_reasons": _count_first_present_values(
            rows,
            (
                "pre_non_executable_paper_tier_reason",
                "paper_opportunity_tier_reason",
                "paper_fill_block_reason",
                "paper_allocation_block_reason",
                "allocator_reason",
            ),
        ),
        "pass_conditions": {
            "canary_candidates_gt_zero": combined_canary_candidates > 0,
            "canary_intents_gt_zero": combined_canary_intents > 0,
            "canary_pending_rows_gt_zero": combined_canary_pending_rows > 0,
            "canary_identity_preserved": canary_binding_missing_rows == 0,
        },
        "current_cycle_pass_conditions": {
            "canary_candidates_gt_zero": len(predicate_rows) > 0,
            "canary_intents_gt_zero": len(canary_intent_rows) > 0,
            "canary_pending_rows_gt_zero": len(canary_pending_rows) > 0,
            "canary_identity_preserved": root_causes["canary_identity_missing"] == 0,
        },
        "sample_canary_candidates": _compact_rows_for_state(
            _sample_rows(predicate_rows or lifecycle_accepted_rows, 10)
        ),
        "sample_canary_pending_rows": _compact_rows_for_state(
            _sample_rows(canary_pending_rows or lifecycle_open_rows, 10)
        ),
        "sample_lifecycle_closed_canary_outcomes": _paper_forward_canary_compact_sample(
            _sample_rows(lifecycle_closed_outcome_rows, 10)
        ),
        "sample_near_miss_strategy_blocked_rows": _compact_rows_for_state(
            _sample_rows(near_miss_strategy_rows, 10)
        ),
        "live_path_changed": False,
        "generated_utc": _utc_iso(),
    }


def _paper_adaptive_threshold_runtime_status(rows: list[dict[str, Any]]) -> dict[str, Any]:
    floor_rows: list[dict[str, Any]] = []
    evaluated_rows = 0
    static_pass_rows = 0
    adaptive_pass_rows = 0
    adaptive_block_rows = 0
    raised_floor_rows = 0
    never_below_static_rows = 0
    floor_values: list[float] = []
    penalty_counts = {
        "drawdown_pressure": 0,
        "cost_edge_pressure": 0,
        "depth_pressure": 0,
        "long_short_point_in_time_pressure": 0,
    }
    signal_stale_policy_rows = 0
    signal_stale_never_above_static_rows = 0
    signal_stale_stricter_rows = 0
    signal_stale_threshold_values: list[int] = []
    drawdown_recovery_policy_rows = 0
    drawdown_recovery_never_below_static_rows = 0
    drawdown_recovery_tightened_rows = 0
    drawdown_recovery_floor_values: list[float] = []
    directional_policy_rows = 0
    directional_never_looser_rows = 0
    directional_tightened_rows = 0
    directional_adaptive_min_side_values: list[int] = []
    directional_adaptive_share_values: list[float] = []
    for row in rows:
        directional_guard = row.get("paper_directional_collapse_guard")
        directional_policy = (
            directional_guard.get("adaptive_policy")
            if isinstance(directional_guard, dict)
            else None
        )
        if isinstance(directional_policy, dict):
            directional_policy_rows += 1
            directional_never_looser_rows += int(
                directional_policy.get("adaptive_never_looser_than_static") is True
            )
            adaptive_min_side = _coerce_float(
                directional_policy.get("adaptive_minimum_side_trades")
            )
            static_min_side = _coerce_float(directional_policy.get("static_minimum_side_trades"))
            adaptive_share = _coerce_float(
                directional_policy.get("adaptive_major_side_share_threshold")
            )
            static_share = _coerce_float(
                directional_policy.get("static_major_side_share_threshold")
            )
            if adaptive_min_side is not None:
                directional_adaptive_min_side_values.append(int(adaptive_min_side))
            if adaptive_share is not None:
                directional_adaptive_share_values.append(adaptive_share)
            if (
                adaptive_min_side is not None
                and static_min_side is not None
                and adaptive_min_side > static_min_side
            ) or (
                adaptive_share is not None
                and static_share is not None
                and adaptive_share < static_share
            ):
                directional_tightened_rows += 1

        stale_policy = row.get("paper_signal_adaptive_stale_policy")
        if not isinstance(stale_policy, dict):
            stale_policy = _paper_signal_adaptive_stale_policy(row)
        signal_stale_policy_rows += 1
        adaptive_stale_seconds = _coerce_float(stale_policy.get("adaptive_stale_seconds"))
        static_stale_seconds = _coerce_float(stale_policy.get("static_operator_max_seconds"))
        if adaptive_stale_seconds is not None and static_stale_seconds is not None:
            signal_stale_threshold_values.append(int(adaptive_stale_seconds))
            signal_stale_never_above_static_rows += int(
                adaptive_stale_seconds <= static_stale_seconds
            )
            signal_stale_stricter_rows += int(adaptive_stale_seconds < static_stale_seconds)
        drawdown_guard = row.get("paper_drawdown_recovery_guard")
        drawdown_policy = (
            drawdown_guard.get("adaptive_confidence_policy")
            if isinstance(drawdown_guard, dict)
            else None
        )
        if isinstance(drawdown_policy, dict):
            drawdown_recovery_policy_rows += 1
            dynamic_floor = _coerce_float(drawdown_policy.get("dynamic_floor"))
            static_floor = _coerce_float(drawdown_policy.get("static_floor"))
            if dynamic_floor is not None:
                drawdown_recovery_floor_values.append(dynamic_floor)
                if static_floor is not None:
                    drawdown_recovery_never_below_static_rows += int(dynamic_floor >= static_floor)
                    drawdown_recovery_tightened_rows += int(dynamic_floor > static_floor)

        confidence = _paper_canary_score(row)
        if confidence is None:
            continue
        evaluated_rows += 1
        budget = _b_grade_exploration_budget_fraction(
            confidence_calibrated=confidence,
            drawdown_bps=_first_present(
                row.get("drawdown_bps"),
                row.get("drawdown_at_entry"),
                row.get("portfolio_drawdown_bps"),
            ),
            expected_move_after_cost_bps=_first_present(
                row.get("expected_move_after_cost_bps"),
                row.get("expected_net_edge_bps"),
                row.get("paper_allocation_signed_expected_move_after_cost_bps"),
            ),
            observed_spread_bps=_first_present(
                row.get("actual_observed_spread_entry_bps"),
                row.get("observed_spread_bps"),
                row.get("bid_ask_spread_bps"),
            ),
            expected_slippage_bps=row.get("expected_slippage_bps"),
            fee_bps=row.get("fee_bps"),
            depth_utilization_pct=row.get("depth_utilization_pct"),
            long_short_ratio_status=row.get("long_short_ratio_status"),
        )
        static_floor = _coerce_float(budget.get("b_grade_exploration_static_confidence_floor"))
        adaptive_floor = _coerce_float(budget.get("b_grade_exploration_adaptive_confidence_floor"))
        if static_floor is None or adaptive_floor is None:
            continue
        floor_values.append(adaptive_floor)
        static_pass = confidence >= static_floor
        adaptive_pass = confidence >= adaptive_floor
        static_pass_rows += int(static_pass)
        adaptive_pass_rows += int(adaptive_pass)
        adaptive_block_rows += int(static_pass and not adaptive_pass)
        raised_floor_rows += int(adaptive_floor > static_floor)
        never_below_static_rows += int(adaptive_floor >= static_floor)
        penalties = budget.get("b_grade_exploration_floor_penalties")
        if isinstance(penalties, dict):
            for key in penalty_counts:
                penalty_counts[key] += int((_coerce_float(penalties.get(key)) or 0.0) > 0.0)
        floor_rows.append(
            {
                "symbol": row.get("symbol"),
                "timeframe": row.get("timeframe"),
                "side": row.get("side"),
                "paper_opportunity_tier": row.get("paper_opportunity_tier"),
                "confidence_calibrated": round(float(confidence), 8),
                "static_floor": round(float(static_floor), 8),
                "adaptive_floor": round(float(adaptive_floor), 8),
                "static_floor_pass": static_pass,
                "adaptive_floor_pass": adaptive_pass,
                "long_short_ratio_status": row.get("long_short_ratio_status"),
                "paper_only": row.get("paper_only"),
                "routes_to_live": row.get("routes_to_live"),
                "places_real_order": row.get("places_real_order"),
            }
        )
    floor_min = min(floor_values) if floor_values else None
    floor_max = max(floor_values) if floor_values else None
    floor_avg = sum(floor_values) / len(floor_values) if floor_values else None
    stale_min = min(signal_stale_threshold_values) if signal_stale_threshold_values else None
    stale_max = max(signal_stale_threshold_values) if signal_stale_threshold_values else None
    drawdown_recovery_floor_min = (
        min(drawdown_recovery_floor_values) if drawdown_recovery_floor_values else None
    )
    drawdown_recovery_floor_max = (
        max(drawdown_recovery_floor_values) if drawdown_recovery_floor_values else None
    )
    directional_adaptive_min_side_min = (
        min(directional_adaptive_min_side_values) if directional_adaptive_min_side_values else None
    )
    directional_adaptive_min_side_max = (
        max(directional_adaptive_min_side_values) if directional_adaptive_min_side_values else None
    )
    directional_adaptive_share_min = (
        min(directional_adaptive_share_values) if directional_adaptive_share_values else None
    )
    directional_adaptive_share_max = (
        max(directional_adaptive_share_values) if directional_adaptive_share_values else None
    )
    remaining_static_threshold_blockers = [
        "directional_collapse_guard",
        "strategy_mode_collapse_guard",
        "standalone_1m_gate",
        "audit_blocked_allowed_entry_timeframes",
        "outcome_memory_degradation_thresholds",
        "leverage_recommendation_tiers",
        "alpha_liquidity_risk_config",
        "microstructure_toxicity_threshold",
    ]
    if directional_policy_rows > 0 and directional_never_looser_rows == directional_policy_rows:
        remaining_static_threshold_blockers = [
            blocker
            for blocker in remaining_static_threshold_blockers
            if blocker != "directional_collapse_guard"
        ]
    return {
        "schema_version": "paper_adaptive_threshold_runtime_status_v1",
        "status": (
            "PARTIAL_B_GRADE_SIGNAL_STALE_AND_DRAWDOWN_RECOVERY_ADAPTIVE_FAIL_CLOSED_"
            "STATIC_THRESHOLDS_REMAIN"
        ),
        "adaptive_threshold_id": (
            "b_grade_confidence_floor,paper_signal_stale_seconds,"
            "paper_drawdown_recovery_min_confidence,directional_collapse_guard"
        ),
        "adaptive_threshold_scope": (
            "paper_only_b_grade_exploration_signal_freshness_and_drawdown_recovery"
        ),
        "runtime_behavior_changed": True,
        "strategy_or_risk_logic_changed": False,
        "paper_admission_changed": True,
        "threshold_lowering_to_force_trades": False,
        "static_confidence_floor": B_GRADE_EXPLORATION_MIN_CONFIDENCE,
        "adaptive_confidence_floor_max": B_GRADE_EXPLORATION_ADAPTIVE_CONFIDENCE_FLOOR_MAX,
        "evaluated_rows": evaluated_rows,
        "static_floor_pass_rows": static_pass_rows,
        "adaptive_floor_pass_rows": adaptive_pass_rows,
        "adaptive_floor_block_rows": adaptive_block_rows,
        "raised_floor_rows": raised_floor_rows,
        "adaptive_floor_never_below_static_rows": never_below_static_rows,
        "floor_stats": {
            "min": round(floor_min, 8) if floor_min is not None else None,
            "max": round(floor_max, 8) if floor_max is not None else None,
            "avg": round(floor_avg, 8) if floor_avg is not None else None,
        },
        "penalty_counts": penalty_counts,
        "adaptive_signal_stale_threshold": {
            "threshold_id": "paper_signal_stale_seconds",
            "operator_min_seconds": PAPER_SIGNAL_ADAPTIVE_STALE_OPERATOR_MIN_SECONDS,
            "operator_max_seconds": PAPER_SIGNAL_STALE_SECONDS,
            "timeframe_candle_multiplier": PAPER_SIGNAL_ADAPTIVE_STALE_CANDLE_MULTIPLIER,
            "evaluated_rows": signal_stale_policy_rows,
            "adaptive_never_above_static_rows": signal_stale_never_above_static_rows,
            "adaptive_stricter_than_static_rows": signal_stale_stricter_rows,
            "threshold_seconds_min": stale_min,
            "threshold_seconds_max": stale_max,
            "threshold_lowering_to_force_trades": False,
            "mode": "TIMEFRAME_CONTEXTUAL_FAIL_CLOSED_NEVER_ABOVE_STATIC",
        },
        "adaptive_drawdown_recovery_confidence_floor": {
            "threshold_id": "paper_drawdown_recovery_min_confidence",
            "static_floor": PAPER_DRAWDOWN_RECOVERY_MIN_CONFIDENCE,
            "operator_max_floor": PAPER_DRAWDOWN_RECOVERY_MAX_CONFIDENCE,
            "evaluated_rows": drawdown_recovery_policy_rows,
            "dynamic_never_below_static_rows": drawdown_recovery_never_below_static_rows,
            "dynamic_tightened_rows": drawdown_recovery_tightened_rows,
            "dynamic_floor_min": (
                round(drawdown_recovery_floor_min, 8)
                if drawdown_recovery_floor_min is not None
                else None
            ),
            "dynamic_floor_max": (
                round(drawdown_recovery_floor_max, 8)
                if drawdown_recovery_floor_max is not None
                else None
            ),
            "threshold_lowering_to_force_trades": False,
            "mode": "DRAWDOWN_AND_EDGE_CONTEXTUAL_FAIL_CLOSED_NEVER_BELOW_STATIC",
        },
        "adaptive_directional_collapse_guard": {
            "threshold_id": "directional_collapse_guard",
            "static_minimum_closed_trades": DIRECTIONAL_COLLAPSE_MIN_CLOSED_TRADES,
            "static_minimum_side_trades": DIRECTIONAL_COLLAPSE_MIN_SIDE_TRADES,
            "static_major_side_share_threshold": DIRECTIONAL_COLLAPSE_MAJOR_SIDE_SHARE,
            "evaluated_rows": directional_policy_rows,
            "adaptive_never_looser_than_static_rows": directional_never_looser_rows,
            "adaptive_tightened_rows": directional_tightened_rows,
            "adaptive_minimum_side_trades_min": directional_adaptive_min_side_min,
            "adaptive_minimum_side_trades_max": directional_adaptive_min_side_max,
            "adaptive_major_side_share_threshold_min": (
                round(directional_adaptive_share_min, 8)
                if directional_adaptive_share_min is not None
                else None
            ),
            "adaptive_major_side_share_threshold_max": (
                round(directional_adaptive_share_max, 8)
                if directional_adaptive_share_max is not None
                else None
            ),
            "threshold_lowering_to_force_trades": False,
            "mode": "SAMPLE_SIZE_CONTEXTUAL_FAIL_CLOSED_NEVER_LOOSER_THAN_STATIC",
        },
        "remaining_static_threshold_blockers": remaining_static_threshold_blockers,
        "pass_conditions": {
            "adaptive_floor_evaluated_rows_gt_zero": evaluated_rows > 0,
            "adaptive_floor_never_below_static": never_below_static_rows == evaluated_rows,
            "adaptive_signal_stale_threshold_evaluated_rows_gt_zero": signal_stale_policy_rows > 0,
            "adaptive_signal_stale_threshold_never_above_static": (
                signal_stale_never_above_static_rows == signal_stale_policy_rows
            ),
            "adaptive_drawdown_recovery_threshold_never_below_static": (
                drawdown_recovery_policy_rows == 0
                or drawdown_recovery_never_below_static_rows == drawdown_recovery_policy_rows
            ),
            "adaptive_directional_collapse_guard_evaluated_rows_gt_zero": (
                directional_policy_rows > 0
            ),
            "adaptive_directional_collapse_guard_never_looser_than_static": (
                directional_policy_rows > 0
                and directional_never_looser_rows == directional_policy_rows
            ),
            "threshold_not_lowered_to_force_trades": True,
            "paper_only": True,
            "routes_to_live_false": True,
            "places_real_order_false": True,
            "ready_allowed": False,
        },
        "sample_rows": _sample_rows(floor_rows, 10),
        "paper_only": True,
        "routes_to_live": False,
        "places_real_order": False,
        "counts_as_a_grade_evidence": False,
        "live_path_changed": False,
        "generated_utc": _utc_iso(),
    }


def _paper_churn_first_number(row: dict[str, Any], *fields: str) -> float | None:
    for field in fields:
        value = _coerce_float(row.get(field))
        if value is not None:
            return value
    return None


def _paper_churn_economic_trade_identity(row: dict[str, Any]) -> str | None:
    for field in (
        "close_id",
        "paper_close_id",
        "close_event_id",
        "outcome_label_id",
        "trainer_feedback_id",
        "paper_trade_id",
        "paper_fill_id",
        "fill_id",
        "ledger_row_id",
    ):
        value = row.get(field)
        if value not in (None, ""):
            return f"{field}:{value}"
    source_fill_ids = row.get("source_fill_ids")
    if isinstance(source_fill_ids, list) and source_fill_ids:
        joined = "|".join(str(value) for value in source_fill_ids if value not in (None, ""))
        if joined:
            return f"source_fill_ids:{joined}"
    symbol = str(row.get("symbol") or "").upper()
    side = _normalized_directional_side(_first_present(row.get("side"), row.get("action")))
    entry_time = _first_present(
        row.get("entry_time"),
        row.get("policy_activated_at"),
        row.get("fill_price_utc"),
        row.get("opened_at"),
        row.get("opened_est"),
        row.get("decision_time"),
    )
    exit_time = _first_present(
        row.get("exit_time"),
        row.get("closed_at"),
        row.get("exit_price_utc"),
        row.get("execution_time"),
        row.get("generated_utc"),
    )
    if symbol and side and entry_time not in (None, "") and exit_time not in (None, ""):
        return f"composite:{symbol}:{side}:{entry_time}:{exit_time}"
    return None


def _paper_churn_requires_economic_identity(row: dict[str, Any]) -> bool:
    if str(row.get("symbol") or "").strip():
        return True
    if row.get("position_id") not in (None, ""):
        return True
    if row.get("prediction_id") not in (None, ""):
        return True
    if row.get("signal_id") not in (None, ""):
        return True
    return any(
        row.get(field) not in (None, "")
        for field in (
            "close_id",
            "paper_close_id",
            "close_event_id",
            "outcome_label_id",
            "trainer_feedback_id",
            "paper_trade_id",
            "paper_fill_id",
            "fill_id",
            "ledger_row_id",
        )
    )


def _paper_churn_entry_time(row: dict[str, Any]) -> datetime | None:
    return _parse_strategy_time(
        _first_present(
            row.get("policy_activated_at"),
            row.get("entry_time"),
            row.get("fill_price_utc"),
            row.get("opened_at"),
            row.get("opened_est"),
            row.get("decision_time"),
            row.get("generated_utc"),
        )
    )


def _paper_churn_same_candle_key(row: dict[str, Any]) -> str | None:
    symbol = str(row.get("symbol") or "").upper()
    timeframe = str(_first_present(row.get("timeframe"), row.get("thesis_timeframe")) or "")
    side = _normalized_directional_side(_first_present(row.get("side"), row.get("action")))
    candle = _first_present(
        row.get("entry_feature_cutoff"),
        row.get("feature_cutoff"),
        row.get("candle_close_time"),
    )
    if symbol and timeframe and side and candle not in (None, ""):
        return f"{symbol}:{timeframe}:{side}:{candle}"
    return None


def _paper_churn_duplicate_count(rows: list[dict[str, Any]], field: str) -> int:
    counts: dict[str, int] = {}
    for row in rows:
        value = _first_present(row.get(field), row.get(f"source_{field}"))
        if value in (None, ""):
            continue
        key = str(value)
        counts[key] = counts.get(key, 0) + 1
    return sum(max(0, count - 1) for count in counts.values())


def _paper_churn_same_candle_duplicate_count(rows: list[dict[str, Any]]) -> int:
    counts: dict[str, int] = {}
    for row in rows:
        key = _paper_churn_same_candle_key(row)
        if key is None:
            continue
        counts[key] = counts.get(key, 0) + 1
    return sum(max(0, count - 1) for count in counts.values())


def _paper_churn_current_entry_rejection_reasons(
    candidate: dict[str, Any],
    prior_current_accepted_rows: list[dict[str, Any]],
) -> list[str]:
    reasons: list[str] = []
    prediction_id = _first_present(
        candidate.get("prediction_id"), candidate.get("source_prediction_id")
    )
    signal_id = _first_present(candidate.get("signal_id"), candidate.get("source_signal_id"))
    same_candle_key = _paper_churn_same_candle_key(candidate)
    for prior in prior_current_accepted_rows:
        if prediction_id not in (None, "") and prediction_id == _first_present(
            prior.get("prediction_id"),
            prior.get("source_prediction_id"),
        ):
            reasons.append("DUPLICATE_CURRENT_CYCLE_PREDICTION")
        if signal_id not in (None, "") and signal_id == _first_present(
            prior.get("signal_id"),
            prior.get("source_signal_id"),
        ):
            reasons.append("DUPLICATE_CURRENT_CYCLE_SIGNAL")
        if same_candle_key is not None and same_candle_key == _paper_churn_same_candle_key(prior):
            reasons.append("SAME_CANDLE_REENTRY_CURRENT_CYCLE")
    return sorted(set(reasons))


def _paper_apply_churn_equity_bleed_rejection(
    intent: dict[str, Any],
    reasons: list[str],
) -> None:
    if not reasons:
        return
    intent["paper_churn_equity_bleed_governor_block_reasons"] = sorted(
        set(
            list(intent.get("paper_churn_equity_bleed_governor_block_reasons") or [])
            + list(reasons)
        )
    )
    intent["paper_fill_block_reason"] = (
        intent.get("paper_fill_block_reason") or PAPER_CHURN_EQUITY_BLEED_BLOCK_REASON
    )
    intent["paper_fill_gate_block_reasons"] = sorted(
        set(
            list(intent.get("paper_fill_gate_block_reasons") or [])
            + [PAPER_CHURN_EQUITY_BLEED_BLOCK_REASON]
            + list(reasons)
        )
    )
    intent["local_block_reasons"] = sorted(
        set(
            list(intent.get("local_block_reasons") or [])
            + [f"churn_equity_bleed_governor:{reason}" for reason in reasons]
        )
    )
    intent["paper_fill_allowed"] = False
    intent["paper_churn_equity_bleed_governor_allowed"] = False


def _paper_filter_post_backfill_current_churn_duplicates(
    accepted_for_ledger: list[dict[str, Any]],
    current_accepted_rows: list[dict[str, Any]],
) -> tuple[list[dict[str, Any]], list[dict[str, Any]], list[dict[str, Any]]]:
    current_ids = {_accepted_fill_identity(row) for row in current_accepted_rows}
    post_backfill_current_accepted: list[dict[str, Any]] = []
    filtered_accepted_for_ledger: list[dict[str, Any]] = []
    blocked_duplicates: list[dict[str, Any]] = []
    for row in accepted_for_ledger:
        row_identity = _accepted_fill_identity(row)
        if row_identity in current_ids:
            reasons = _paper_churn_current_entry_rejection_reasons(
                row,
                post_backfill_current_accepted,
            )
            if reasons:
                blocked_row = dict(row)
                _paper_apply_churn_equity_bleed_rejection(blocked_row, reasons)
                blocked_row["paper_churn_equity_bleed_block_stage"] = "POST_BACKFILL_PRE_LIFECYCLE"
                blocked_duplicates.append(blocked_row)
                continue
            post_backfill_current_accepted.append(row)
        filtered_accepted_for_ledger.append(row)
    return filtered_accepted_for_ledger, post_backfill_current_accepted, blocked_duplicates


def _retain_admission_invalidated_positions(
    dropped_positions: list[dict[str, Any]],
    *,
    recorded_utc: str,
    paper_session_id: str | None,
) -> list[dict[str, Any]]:
    """Flag admission-invalidated positions for continued lifecycle management.

    F-0015: a position whose fill fails a later admission re-validation must
    keep being marked-to-market and stop-evaluated until it exits through the
    normal close paths. Removing it from the open set voids its stop and lets
    losses run unbounded (BASUSDT realized -1397bps against a 63bps designed
    stop while in admission limbo).
    """
    retained: list[dict[str, Any]] = []
    for row in dropped_positions:
        if not isinstance(row, dict):
            continue
        retained.append(
            {
                **dict(row),
                "admission_invalidated": True,
                "admission_drop_reason": "OPEN_POSITION_FILL_NO_LONGER_ADMISSION_VALID",
                "admission_drop_recorded_utc": recorded_utc,
                "paper_session_id": row.get("paper_session_id") or paper_session_id,
                "new_entry_admission_eligible": False,
            }
        )
    return retained


def _paper_filter_open_positions_to_accepted_rows(
    open_positions: list[dict[str, Any]],
    accepted_rows: list[dict[str, Any]],
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    """Split open positions into (admission-valid, admission-dropped).

    Positions must never silently vanish: a position whose fill fails a later
    admission re-validation is returned in the dropped list so the caller can
    persist an auditable record (F-0007: BASUSDT position disappeared with no
    close record, no quarantine, no PnL realization).
    """
    allowed_open_position_ids = {_accepted_fill_identity(row) for row in accepted_rows}
    if not allowed_open_position_ids:
        return list(open_positions), []
    kept: list[dict[str, Any]] = []
    dropped: list[dict[str, Any]] = []
    for row in open_positions:
        if (
            _accepted_fill_identity(_accepted_fill_from_open_position(row))
            in allowed_open_position_ids
        ):
            kept.append(row)
        else:
            dropped.append(row)
    return kept, dropped


def _paper_churn_equity_bleed_governor_status(
    *,
    accepted_rows: list[dict[str, Any]],
    open_position_rows: list[dict[str, Any]],
    closed_rows: list[dict[str, Any]],
    current_accepted_rows: list[dict[str, Any]],
    blocked_rows: list[dict[str, Any]] | None = None,
    generated_utc: str | None = None,
) -> dict[str, Any]:
    raw_closed_rows = [row for row in closed_rows if isinstance(row, dict)]
    current_rows = [row for row in current_accepted_rows if isinstance(row, dict)]
    accepted_source_rows = [row for row in accepted_rows if isinstance(row, dict)]
    open_rows = [row for row in open_position_rows if isinstance(row, dict)]
    blocked_source_rows = [row for row in (blocked_rows or []) if isinstance(row, dict)]

    by_identity: dict[str, dict[str, Any]] = {}
    rows_without_identity = 0
    non_compactable_close_records = 0
    for row in raw_closed_rows:
        identity = _paper_churn_economic_trade_identity(row)
        if identity is None:
            if _paper_churn_requires_economic_identity(row):
                rows_without_identity += 1
            else:
                non_compactable_close_records += 1
            continue
        by_identity.setdefault(identity, row)
    compacted_closed_rows = list(by_identity.values())

    fees_usd = 0.0
    slippage_usd = 0.0
    funding_usd = 0.0
    funding_abs_usd = 0.0
    turnover_usd = 0.0
    edge_usd = 0.0
    invalid_cost_rows = 0
    hold_seconds: list[float] = []
    for row in compacted_closed_rows:
        fee = _paper_churn_first_number(row, "fees_usd", "fees", "expected_fees_usd") or 0.0
        slippage = (
            _paper_churn_first_number(
                row,
                "realized_slippage_usd",
                "slippage_usd",
                "slippage",
                "expected_slippage_usd",
            )
            or 0.0
        )
        funding = (
            _paper_churn_first_number(
                row,
                "funding_pnl_usd",
                "funding_usd",
                "funding",
                "expected_funding_usd",
            )
            or 0.0
        )
        turnover = (
            _paper_churn_first_number(
                row,
                "gross_notional_usd",
                "gross_notional",
                "order_size_usd",
                "order_size",
                "notional_usd",
                "notional",
                "notional_usdt",
            )
            or 0.0
        )
        edge = (
            _paper_churn_first_number(
                row,
                "realized_net_pnl_usd",
                "realized_pnl_usd",
                "realized_pnl_usdt",
                "expected_net_pnl_usd",
            )
            or 0.0
        )
        hold = _paper_churn_first_number(
            row,
            "hold_time_seconds",
            "holding_period_seconds",
            "holding_period",
            "position_age_seconds",
        )
        if hold is not None and hold >= 0.0:
            hold_seconds.append(hold)
        if fee < 0.0 or slippage < 0.0:
            invalid_cost_rows += 1
        fees_usd += fee
        slippage_usd += slippage
        funding_usd += funding
        funding_abs_usd += abs(funding)
        turnover_usd += max(0.0, turnover)
        edge_usd += edge

    cost_drag_usd = max(0.0, fees_usd) + max(0.0, slippage_usd) + funding_abs_usd
    cost_drag_pct = (cost_drag_usd / turnover_usd * 100.0) if turnover_usd > 0.0 else None
    edge_to_cost_ratio = (edge_usd / cost_drag_usd) if cost_drag_usd > 0.0 else None
    if hold_seconds:
        ordered_holds = sorted(hold_seconds)
        middle = len(ordered_holds) // 2
        if len(ordered_holds) % 2:
            median_hold_time = ordered_holds[middle]
        else:
            median_hold_time = (ordered_holds[middle - 1] + ordered_holds[middle]) / 2.0
    else:
        median_hold_time = None

    generated_dt = _parse_strategy_time(generated_utc) or datetime.now(timezone.utc)
    recent_cutoff = generated_dt.timestamp() - PAPER_CHURN_EQUITY_BLEED_RECENT_WINDOW_SECONDS
    recent_entries_by_symbol: dict[str, int] = {}
    seen_entry_identities: set[str] = set()
    for row in accepted_source_rows + open_rows + current_rows:
        symbol = str(row.get("symbol") or "").upper()
        if not symbol:
            continue
        entry_identity = _accepted_fill_identity(row)
        if entry_identity in seen_entry_identities:
            continue
        seen_entry_identities.add(entry_identity)
        entry_time = _paper_churn_entry_time(row)
        if entry_time is None:
            continue
        if entry_time.timestamp() >= recent_cutoff:
            recent_entries_by_symbol[symbol] = recent_entries_by_symbol.get(symbol, 0) + 1
    reentries_by_symbol = {
        symbol: max(0, count - 1) for symbol, count in recent_entries_by_symbol.items()
    }
    same_candle_reentry_count = _paper_churn_same_candle_duplicate_count(current_rows)
    same_prediction_duplicate_count = _paper_churn_duplicate_count(current_rows, "prediction_id")
    same_signal_duplicate_count = _paper_churn_duplicate_count(current_rows, "signal_id")
    duplicate_new_entries = max(
        same_candle_reentry_count,
        same_prediction_duplicate_count,
        same_signal_duplicate_count,
    )
    blocked_attempt_rows = [
        row
        for row in blocked_source_rows
        if row.get("paper_churn_equity_bleed_governor_block_reasons")
    ]
    same_candle_reentry_unexplained = same_candle_reentry_count
    economic_trade_count_reconciles = rows_without_identity == 0 and len(
        compacted_closed_rows
    ) <= len(raw_closed_rows)
    cost_drag_within_envelope = invalid_cost_rows == 0 and (
        (cost_drag_pct is None and cost_drag_usd == 0.0)
        or (
            cost_drag_pct is not None
            and 0.0 <= cost_drag_pct <= PAPER_CHURN_COST_DRAG_MAX_PCT_OF_TURNOVER
        )
    )
    if duplicate_new_entries > 0:
        state = "CHURN_HALTED"
    elif same_candle_reentry_unexplained > 0:
        state = "COOLDOWN"
    elif not economic_trade_count_reconciles or not cost_drag_within_envelope:
        state = "SHADOW_ONLY"
    else:
        state = "ACTIVE"
    pass_conditions = {
        "duplicate_new_entries_eq_zero": duplicate_new_entries == 0,
        "same_candle_reentry_unexplained_eq_zero": same_candle_reentry_unexplained == 0,
        "cost_drag_within_envelope": cost_drag_within_envelope,
        "economic_trade_count_reconciles": economic_trade_count_reconciles,
    }
    new_entries_allowed = state == "ACTIVE"
    return {
        "schema_version": "paper_churn_equity_bleed_governor_status_v1",
        "governor": PAPER_CHURN_EQUITY_BLEED_GOVERNOR_NAME,
        "status": state,
        "state": state,
        "enabled": True,
        "paper_only": True,
        "routes_to_live": False,
        "places_real_order": False,
        "live_path_changed": False,
        "new_entries_allowed": new_entries_allowed,
        "raw_close_records": len(raw_closed_rows),
        "compacted_economic_trades": len(compacted_closed_rows),
        "duplicate_close_record_count": max(0, len(raw_closed_rows) - len(compacted_closed_rows)),
        "rows_without_economic_identity": rows_without_identity,
        "non_compactable_close_records": non_compactable_close_records,
        "current_cycle_new_entry_rows": len(current_rows),
        "duplicate_new_entries": duplicate_new_entries,
        "blocked_duplicate_or_churn_attempt_rows": len(blocked_attempt_rows),
        "entries_per_symbol_per_hour": max(recent_entries_by_symbol.values(), default=0),
        "reentries_per_symbol_per_hour": max(reentries_by_symbol.values(), default=0),
        "entries_per_symbol_per_hour_by_symbol": dict(sorted(recent_entries_by_symbol.items())),
        "reentries_per_symbol_per_hour_by_symbol": dict(sorted(reentries_by_symbol.items())),
        "cost_drag_pct": round(cost_drag_pct, 8) if cost_drag_pct is not None else None,
        "cost_drag_bps": round(cost_drag_pct * 100.0, 8) if cost_drag_pct is not None else None,
        "fees_usd": round(fees_usd, 8),
        "slippage_usd": round(slippage_usd, 8),
        "funding_usd": round(funding_usd, 8),
        "funding_abs_usd": round(funding_abs_usd, 8),
        "turnover_usd": round(turnover_usd, 8),
        "edge_to_cost_ratio": (
            round(edge_to_cost_ratio, 8) if edge_to_cost_ratio is not None else None
        ),
        "median_hold_time": round(median_hold_time, 8) if median_hold_time is not None else None,
        "same_candle_reentry_count": same_candle_reentry_count,
        "same_prediction_duplicate_count": same_prediction_duplicate_count,
        "same_signal_duplicate_count": same_signal_duplicate_count,
        "same_candle_reentry_unexplained": same_candle_reentry_unexplained,
        "cost_drag_within_envelope": cost_drag_within_envelope,
        "economic_trade_count_reconciles": economic_trade_count_reconciles,
        "invalid_cost_rows": invalid_cost_rows,
        "cost_drag_max_pct_of_turnover": PAPER_CHURN_COST_DRAG_MAX_PCT_OF_TURNOVER,
        "recent_window_seconds": PAPER_CHURN_EQUITY_BLEED_RECENT_WINDOW_SECONDS,
        "pass_conditions": pass_conditions,
        "sample_blocked_governor_rows": _compact_rows_for_state(
            _sample_rows(blocked_attempt_rows, 10)
        ),
        "sample_compacted_economic_trades": _paper_forward_canary_compact_sample(
            _sample_rows(compacted_closed_rows, 10)
        ),
        "generated_utc": generated_utc or _utc_iso(),
    }


def _paper_performance_first_number(row: dict[str, Any], *fields: str) -> float | None:
    for field in fields:
        value = _coerce_float(row.get(field))
        if value is not None:
            return value
    return None


def _paper_performance_realized_bps(row: dict[str, Any]) -> float | None:
    return _paper_performance_first_number(
        row,
        "realized_net_pnl_bps",
        "realized_pnl_bps",
        "paper_exit_pnl_bps",
        "net_pnl_bps",
        "pnl_bps",
    )


def _paper_performance_realized_usd(row: dict[str, Any]) -> float | None:
    return _paper_performance_first_number(
        row,
        "realized_net_pnl_usd",
        "realized_pnl_usd",
        "realized_pnl_usdt",
        "net_pnl_usd",
        "pnl_usd",
    )


def _paper_performance_has_negative_realized_outcome(row: dict[str, Any]) -> bool:
    realized_fields = (
        "realized_net_pnl_bps",
        "realized_pnl_bps",
        "paper_exit_pnl_bps",
        "net_pnl_bps",
        "pnl_bps",
        "realized_net_pnl_usd",
        "realized_pnl_usd",
        "realized_pnl_usdt",
        "net_pnl_usd",
        "pnl_usd",
    )
    values = [
        value
        for value in (_coerce_float(row.get(field)) for field in realized_fields)
        if value is not None
    ]
    return any(value < 0.0 for value in values)


def _paper_performance_notional_usd(row: dict[str, Any]) -> float:
    return max(
        0.0,
        _paper_performance_first_number(
            row,
            "gross_notional_usd",
            "gross_notional",
            "notional_usd",
            "notional_usdt",
            "target_notional_usd",
            "target_notional_usdt",
            "order_size_usd",
            "order_size",
        )
        or 0.0,
    )


# Paper tiers that are exploration/bootstrap probes by design: they trade loosely
# and are expected to lose a large fraction of the time. Their outcomes are
# explicitly stamped non-strict (counts_as_*_evidence False/None) and must never
# govern the STRICT A+/live performance circuit or bucket quarantine. They remain
# fully available to trainer feedback, counterfactuals, paper-learning analytics,
# strategy-supply scoring, loss-cluster diagnostics, and UI truth because those
# paths read v2:paper:closed_trades directly, not this selector.
_NON_STRICT_GOVERNANCE_TIERS = frozenset(
    tier.upper()
    for tier in (
        PAPER_TIER_RISK_CONTROLLER_EXPLORATION,
        PAPER_TIER_A_PLUS_BOOTSTRAP_REDUCED_SIZE,
    )
)


def _paper_row_governance_tier_markers(row: dict[str, Any]) -> set[str]:
    markers: set[str] = set()
    for field in (
        "paper_opportunity_tier",
        "source_tier",
        "tier",
        "exploration_tier",
        "paper_exploration_tier",
        "paper_fill_allowed_source",
        "preemptive_decision",
    ):
        value = row.get(field)
        if value in (None, ""):
            continue
        text = str(value).strip().upper()
        markers.add(text)
        for tier in _NON_STRICT_GOVERNANCE_TIERS:
            if tier in text:
                markers.add(tier)
    return markers


def _paper_strict_governance_exclusion_reasons(row: dict[str, Any]) -> list[str]:
    if not isinstance(row, dict):
        return ["NOT_A_ROW"]
    reasons: list[str] = []
    tier_markers = _paper_row_governance_tier_markers(row)
    if tier_markers & _NON_STRICT_GOVERNANCE_TIERS:
        reasons.append("NON_STRICT_PAPER_TIER")
    if any(
        row.get(field) is True
        for field in (
            "reconstructed",
            "trust_reconstructed",
            "reconstructed_from_archive",
            "reconstructed_from_artifacts",
            "materialization_queue_id_reconstructed_from_candidate_id",
        )
    ):
        reasons.append("RECONSTRUCTED_OR_ARCHIVE_ROW")
    if row.get("counts_as_strict_preemptive_evidence") is False:
        reasons.append("COUNTS_AS_STRICT_PREEMPTIVE_EVIDENCE_FALSE")
    if row.get("counts_as_a_plus_evidence") is False:
        reasons.append("COUNTS_AS_A_PLUS_EVIDENCE_FALSE")
    return list(dict.fromkeys(reasons))


def _paper_row_excluded_from_strict_governance(row: dict[str, Any]) -> bool:
    """True when a closed paper row must NOT govern strict performance evidence.

    Exclusion triggers (any one):
      - exploration / bootstrap-reduced-size opportunity tier
      - reconstructed-from-artifacts provenance
      - counts_as_strict_preemptive_evidence explicitly False
      - counts_as_a_plus_evidence explicitly False

    Note: counts_as_final_a_plus is deliberately NOT used here. It is a
    near-universal safety default (no current paper trade is a *final* A+ trade),
    so excluding on it would empty the strict set and make the circuit breaker
    permanently permissive. The disciplined POSITIVE_EDGE_PROBATION tier carries
    None for these evidence flags and therefore correctly remains governing.
    """
    return bool(_paper_strict_governance_exclusion_reasons(row))


def _paper_performance_source_rows(
    closed_rows: list[dict[str, Any]],
    *,
    cohort_id: str | None = None,
) -> list[dict[str, Any]]:
    paper_rows = [
        row
        for row in closed_rows
        if isinstance(row, dict)
        and row.get("paper_only") is True
        and _paper_performance_realized_bps(row) is not None
        and not _paper_row_excluded_from_strict_governance(row)
    ]
    if cohort_id is not None:
        # Cohort-scoped governance (Phase 6): a provisional cohort's breaker reads
        # ONLY rows stamped with its exact paper_strategy_cohort_id. A fresh cohort
        # with no completed trades yields an EMPTY set (=> ACTIVE_INSUFFICIENT_
        # COHORT_SAMPLE) and NEVER falls back to the historical global trade sample,
        # so the July losing cohort can never halt the new cohort.
        return [
            row
            for row in paper_rows
            if str(row.get("paper_strategy_cohort_id") or "") == cohort_id
        ]
    if paper_rows:
        return paper_rows
    # No paper_only strict rows: fall back to any strict-governance row with a
    # realized outcome (still excluding non-strict tiers). Never fall back to
    # including exploration/bootstrap/reconstructed rows — re-admitting them is
    # exactly the contamination this exclusion exists to prevent.
    return [
        row
        for row in closed_rows
        if isinstance(row, dict)
        and _paper_performance_realized_bps(row) is not None
        and not _paper_row_excluded_from_strict_governance(row)
    ]


def _paper_performance_safety_signal_rows(
    closed_rows: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    """Rows for strict performance-governor safety detectors.

    Exploration/bootstrap/reconstructed rows remain available to feedback,
    counterfactuals, paper analytics, and UI truth, but they must not trip the
    blocking strict performance governor through cluster or first-loss side
    paths after the tier-exclusion repair.
    """
    return _paper_performance_source_rows(closed_rows)


def _paper_performance_metrics(rows: list[dict[str, Any]]) -> dict[str, Any]:
    realized_bps = [
        value
        for value in (_paper_performance_realized_bps(row) for row in rows)
        if value is not None
    ]
    positive_bps = sum(value for value in realized_bps if value > 0.0)
    negative_bps_abs = abs(sum(value for value in realized_bps if value < 0.0))
    profit_factor, profit_factor_numeric, profit_factor_is_infinite = (
        _paper_quality_profit_factor_payload(positive_bps, negative_bps_abs)
    )
    notional_sum = sum(_paper_performance_notional_usd(row) for row in rows)
    weighted_sum = sum(
        (_paper_performance_realized_bps(row) or 0.0) * _paper_performance_notional_usd(row)
        for row in rows
        if _paper_performance_realized_bps(row) is not None
    )
    usd_values = [
        value
        for value in (_paper_performance_realized_usd(row) for row in rows)
        if value is not None
    ]
    return {
        "closed_outcome_count": len(realized_bps),
        "profit_factor": profit_factor,
        "profit_factor_numeric": (
            profit_factor_numeric
            if profit_factor_numeric is not None and math.isfinite(profit_factor_numeric)
            else None
        ),
        "profit_factor_is_infinite": profit_factor_is_infinite,
        "notional_weighted_expectancy_bps": (
            weighted_sum / notional_sum
            if notional_sum > 0.0
            else (sum(realized_bps) / len(realized_bps) if realized_bps else None)
        ),
        "win_rate": (
            sum(1 for value in realized_bps if value > 0.0) / len(realized_bps)
            if realized_bps
            else None
        ),
        "realized_pnl_usd": sum(usd_values) if usd_values else None,
    }


def _paper_performance_window_metrics(
    rows: list[dict[str, Any]],
    window: int,
) -> dict[str, Any]:
    source_rows = rows[-window:] if window > 0 else rows
    return {"window": window, **_paper_performance_metrics(source_rows)}


def _paper_performance_exit_reason(row: dict[str, Any]) -> str:
    return str(_first_present(row.get("close_reason"), row.get("exit_reason")) or "")


def _paper_performance_is_atr_stop(row: dict[str, Any]) -> bool:
    reason = _paper_performance_exit_reason(row).upper()
    return "ATR" in reason and "STOP" in reason


def _paper_performance_bucket_key(row: dict[str, Any]) -> str:
    bucket = _paper_quality_context_bucket(row)
    return "|".join(
        str(bucket.get(field) or "UNKNOWN")
        for field in ("symbol", "timeframe", "strategy", "regime")
    )


def _paper_performance_known_bucket_value(value: Any) -> bool:
    text = str(value or "").strip()
    return bool(text) and text.upper() != "UNKNOWN"


def _paper_performance_quarantine_group_keys(row: dict[str, Any]) -> dict[str, str]:
    bucket = _paper_quality_context_bucket(row)
    keys = {
        _paper_performance_bucket_key(row): "exact_context",
    }
    side = str(bucket.get("side") or "").lower()
    strategy = str(bucket.get("strategy") or "")
    regime = str(bucket.get("regime") or "")
    timeframe = str(bucket.get("timeframe") or "")
    confidence_bucket = str(bucket.get("confidence_bucket") or "")
    if _paper_performance_known_bucket_value(side):
        keys[f"side:{side}"] = "side"
    if _paper_performance_known_bucket_value(regime):
        keys[f"regime:{regime}"] = "regime"
    if _paper_performance_known_bucket_value(timeframe):
        keys[f"timeframe:{timeframe}"] = "timeframe"
    if _paper_performance_known_bucket_value(side) and _paper_performance_known_bucket_value(
        timeframe
    ):
        keys[f"side_timeframe:{side}|{timeframe}"] = "side_timeframe"
    if _paper_performance_known_bucket_value(strategy) and _paper_performance_known_bucket_value(
        regime
    ):
        keys[f"strategy_regime:{strategy}|{regime}"] = "strategy_regime"
    if (
        _paper_performance_known_bucket_value(strategy)
        and _paper_performance_known_bucket_value(side)
        and _paper_performance_known_bucket_value(timeframe)
    ):
        keys[f"strategy_side_timeframe:{strategy}|{side}|{timeframe}"] = "strategy_side_timeframe"
    if _paper_performance_known_bucket_value(
        confidence_bucket
    ) and _paper_performance_known_bucket_value(regime):
        keys[f"confidence_regime:{confidence_bucket}|{regime}"] = "confidence_regime"
    return keys


def _paper_performance_candidate_quarantine_keys(row: dict[str, Any]) -> set[str]:
    return set(_paper_performance_quarantine_group_keys(row))


def _paper_high_confidence_loss_cluster_matched_keys(
    row: dict[str, Any],
    performance_circuit_breaker_status: dict[str, Any],
) -> list[str]:
    cluster = performance_circuit_breaker_status.get("recovery_high_confidence_loss_cluster_status")
    if not isinstance(cluster, dict) or cluster.get("cluster_detected") is not True:
        return []
    bucket = _paper_quality_context_bucket(row)
    matches: list[str] = []
    symbol = str(bucket.get("symbol") or "").upper()
    side = str(bucket.get("side") or "").lower()
    timeframe = str(bucket.get("timeframe") or "")
    strategy = str(bucket.get("strategy") or "")
    affected_symbols = {
        str(value or "").upper()
        for value in (cluster.get("affected_symbols") or [])
        if value not in (None, "")
    }
    quarantined_sides = {
        str(value or "").lower()
        for value in (cluster.get("quarantined_sides") or [])
        if value not in (None, "")
    }
    quarantined_timeframes = {
        str(value or "")
        for value in (cluster.get("quarantined_timeframes") or [])
        if value not in (None, "")
    }
    quarantined_strategy_modes = {
        str(value or "")
        for value in (cluster.get("quarantined_strategy_modes") or [])
        if value not in (None, "")
    }
    if symbol and symbol in affected_symbols:
        matches.append(f"loss_cluster_symbol:{symbol}")
    if side and side in quarantined_sides:
        matches.append(f"loss_cluster_side:{side}")
    if timeframe and timeframe in quarantined_timeframes:
        matches.append(f"loss_cluster_timeframe:{timeframe}")
    if strategy and strategy in quarantined_strategy_modes:
        matches.append(f"loss_cluster_strategy:{strategy}")
    return sorted(set(matches))


def _paper_exploration_specific_quarantine_key(key: str) -> bool:
    normalized = str(key or "")
    # Single-dimension buckets are useful telemetry, but they are too broad to
    # prove that a paper-only exploration row is in the exact failed bucket.
    # Keep them as size-cap/advisory evidence unless a more specific bucket
    # also matches.
    return not normalized.startswith(("side:", "timeframe:", "regime:"))


def _paper_exploration_specific_loss_cluster_key(key: str) -> bool:
    normalized = str(key or "")
    return not normalized.startswith(("loss_cluster_side:", "loss_cluster_timeframe:"))


A_PLUS_REDISTRIBUTION_CHECKS = (
    "side_bucket_positive",
    "regime_aligned",
    "trade_tape_confirms",
    "microstructure_trust_confirms",
    "allocator_allows",
    "no_quarantine_bucket",
)


def _is_b_grade_row(row: dict[str, Any]) -> bool:
    return (
        str(row.get("paper_opportunity_tier") or "").upper() == PAPER_TIER_B_GRADE_EXPLORATION
        or str(row.get("calibration_label_purpose") or "").upper()
        == B_GRADE_EXPLORATION_OUTCOME_LABEL
    )


def _is_a_plus_reduced_size_bootstrap_row(row: dict[str, Any]) -> bool:
    return (
        str(row.get("paper_opportunity_tier") or row.get("source_tier") or "").upper()
        == PAPER_TIER_A_PLUS_BOOTSTRAP_REDUCED_SIZE
        or row.get("bootstrap_reduced_size_paper_only") is True
        or row.get("a_plus_reduced_size_bootstrap_budget_cap_applied") is True
    )


def _is_a_plus_closed_row(row: dict[str, Any]) -> bool:
    if row.get("counts_as_final_A_plus") is False or row.get("counts_as_final_a_plus") is False:
        return False
    gate = row.get("a_plus_gate")
    return (
        str(row.get("paper_opportunity_tier") or "").upper() == PAPER_TIER_A_GRADE_EXECUTION
        or row.get("counts_as_a_grade_evidence") is True
        or row.get("a_plus") is True
        or (isinstance(gate, dict) and gate.get("a_plus") is True)
    )


def _paper_row_won(row: dict[str, Any]) -> bool:
    realized = _paper_performance_realized_bps(row)
    if realized is not None:
        return realized > 0.0
    realized_usd = _paper_performance_realized_usd(row)
    return realized_usd is not None and realized_usd > 0.0


def _paper_row_lost(row: dict[str, Any]) -> bool:
    realized = _paper_performance_realized_bps(row)
    if realized is not None:
        return realized <= 0.0
    realized_usd = _paper_performance_realized_usd(row)
    return realized_usd is not None and realized_usd <= 0.0


def _paper_row_confidence(row: dict[str, Any]) -> float | None:
    return _coerce_float(
        _first_present(
            row.get("confidence_calibrated"),
            row.get("score"),
            row.get("selected_action_probability"),
            row.get("confidence_raw"),
            row.get("strategy_router_confidence"),
        )
    )


def _a_plus_gate_redistribution_status(
    evaluations: list[dict[str, Any]],
    *,
    generated_utc: str,
    paper_session_id: Any,
) -> dict[str, Any]:
    failed_check_counts: dict[str, int] = {}
    check_counts: dict[str, dict[str, int]] = {}
    failure_reason_counts_by_check: dict[str, dict[str, int]] = {}
    for row in evaluations:
        checks = row.get("checks") if isinstance(row.get("checks"), dict) else {}
        failed_checks = {str(check) for check in row.get("failed_checks") or []}
        for check_name in set(checks) | failed_checks | set(A_PLUS_REDISTRIBUTION_CHECKS):
            check_payload = checks.get(check_name) if isinstance(checks, dict) else None
            bucket = check_counts.setdefault(
                str(check_name),
                {"passed": 0, "failed": 0, "missing_evidence": 0},
            )
            if check_payload is None and check_name not in failed_checks:
                continue
            if isinstance(check_payload, dict) and check_payload.get("passed") is True:
                bucket["passed"] += 1
                continue
            if isinstance(check_payload, dict) and check_payload.get("missing_evidence") is True:
                bucket["missing_evidence"] += 1
            if isinstance(check_payload, dict):
                reason = str(check_payload.get("reason") or "UNSPECIFIED_FAILURE")
                reason_counts = failure_reason_counts_by_check.setdefault(str(check_name), {})
                reason_counts[reason] = reason_counts.get(reason, 0) + 1
            bucket["failed"] += 1
            failed_check_counts[str(check_name)] = failed_check_counts.get(str(check_name), 0) + 1
    evaluated = len(evaluations)
    source_present_100pct_failure_checks = [
        check
        for check, counts in sorted(check_counts.items())
        if evaluated > 0
        and counts.get("failed") == evaluated
        and counts.get("missing_evidence") == 0
    ]

    def _a_plus_safety_reason(reason: str) -> bool:
        upper = str(reason or "").upper()
        return upper.startswith(
            (
                "ALLOCATOR_BLOCKED",
                "CANDIDATE_BUCKET_QUARANTINED",
                "BUCKET_QUARANTINE_STATUS=",
                "FEATURE_FRESHNESS_",
                "MISSING_CRITICAL_FEATURES",
                "STALE_FEATURES",
                "RISK_ALLOWED=FALSE",
                "SIDE_GATE_BLOCKED",
                "SIDE_EXPECTANCY_NOT_POSITIVE",
                "TRUST_SCORE=",
                "RUNTIME_COST_CAPTURE_STATUS=",
            )
        )

    safety_block_100pct_checks = [
        check
        for check in source_present_100pct_failure_checks
        if failure_reason_counts_by_check.get(check)
        and all(_a_plus_safety_reason(reason) for reason in failure_reason_counts_by_check[check])
    ]
    plumbing_bug_suspected_checks = [
        check
        for check in source_present_100pct_failure_checks
        if check not in safety_block_100pct_checks
    ]
    required_check_counts = {
        check: check_counts.get(check, {"passed": 0, "failed": 0, "missing_evidence": 0})
        for check in A_PLUS_REDISTRIBUTION_CHECKS
    }
    return {
        "schema_version": "a_plus_gate_redistribution_status_v1",
        "generated_utc": generated_utc,
        "paper_session_id": paper_session_id,
        "evaluated_candidates": evaluated,
        "a_plus_candidates": sum(1 for row in evaluations if row.get("a_plus") is True),
        "top_failed_checks": [
            {"check": check, "count": count}
            for check, count in sorted(
                failed_check_counts.items(),
                key=lambda item: (-item[1], item[0]),
            )[:12]
        ],
        "failed_check_counts": dict(
            sorted(failed_check_counts.items(), key=lambda item: (-item[1], item[0]))
        ),
        "check_counts": check_counts,
        "failure_reason_counts_by_check": failure_reason_counts_by_check,
        "source_present_100pct_failure_checks": source_present_100pct_failure_checks,
        "safety_block_100pct_checks": safety_block_100pct_checks,
        "required_check_counts": required_check_counts,
        "side_bucket_positive": required_check_counts["side_bucket_positive"],
        "regime_aligned": required_check_counts["regime_aligned"],
        "trade_tape_confirms": required_check_counts["trade_tape_confirms"],
        "microstructure_trust_confirms": required_check_counts["microstructure_trust_confirms"],
        "allocator_allows": required_check_counts["allocator_allows"],
        "no_quarantine_bucket": required_check_counts["no_quarantine_bucket"],
        "plumbing_bug_suspected_checks": plumbing_bug_suspected_checks,
        "plumbing_bug_rule": (
            "If one check fails exactly 100% while source data is present, inspect reader/plumbing."
        ),
        "known_bad_pattern_detected": all(
            evaluated > 0 and required_check_counts[check]["failed"] == evaluated
            for check in (
                "side_bucket_positive",
                "regime_aligned",
                "microstructure_trust_confirms",
                "allocator_allows",
            )
        ),
        "next_inspection_targets": [
            "v2/backend/app/services/a_plus_trade_gate/service.py::load_a_plus_context",
            "v2/backend/app/cli/v2_trade_management_paper_loop.py::_a_plus_context_for",
            "v2:paper:side_performance",
            "v2:regime:gate:{symbol}:{timeframe}",
            "v2:market:trade_tape_features:{symbol}",
            "v2:microstructure:trust_score:{symbol}:{timeframe}",
            "v2:microstructure:trust_score:{symbol}:1m",
            "v2:microstructure:feed_quality:binance:{symbol}",
        ],
        "places_real_order": False,
        "routes_to_live": False,
        "live_path_changed": False,
    }


def _a_plus_source_owner(check: str) -> str:
    if check in {"microstructure_trust_confirms"}:
        return "microstructure_trust"
    if check in {"trade_tape_confirms"}:
        return "trade_tape"
    if check in {"allocator_allows"}:
        return "adaptive_capital_allocator"
    if check in {"risk_allows"}:
        return "risk_gateway"
    if check in {"no_quarantine_bucket", "no_recent_high_confidence_loss_in_bucket"}:
        return "continuous_edge_guardian"
    if check in {"cost_evidence_production_grade"}:
        return "runtime_cost_liquidity_capture"
    if check in {"no_stale_or_missing_critical_feature"}:
        return "feature_pipeline"
    if check in {"regime_aligned", "htf_aligned"}:
        return "strategy_orchestration"
    return "v2_trade_management_paper_loop"


def _a_plus_gate_after_trust_semantics_status(
    *,
    evaluations: list[dict[str, Any]],
    intents: list[dict[str, Any]],
    generated_utc: str,
    paper_session_id: Any,
) -> dict[str, Any]:
    reduced_rows = [row for row in intents if _is_a_plus_reduced_size_bootstrap_row(row)]
    b_grade_rows = [row for row in intents if _is_b_grade_row(row)]
    shadow_rows = [
        row
        for row in intents
        if str(row.get("paper_opportunity_tier") or "").upper() == PAPER_TIER_SHADOW_ONLY
    ]
    no_trade_rows = [
        row
        for row in intents
        if str(row.get("paper_opportunity_tier") or "").upper() == PAPER_TIER_NO_TRADE
    ]
    non_pass_rows = []
    for row in evaluations:
        if row.get("a_plus") is True:
            continue
        failed = [str(check) for check in row.get("failed_checks") or []]
        first = failed[0] if failed else "UNKNOWN_BLOCK"
        non_pass_rows.append(
            {
                "symbol": row.get("symbol"),
                "timeframe": row.get("timeframe"),
                "side": row.get("side"),
                "first_block_reason": first,
                "all_block_reasons": failed,
                "source_owner": _a_plus_source_owner(first),
                "fixable_or_true_block": (
                    "fixable_source_gap"
                    if first
                    in {
                        "microstructure_trust_confirms",
                        "trade_tape_confirms",
                        "cost_evidence_production_grade",
                        "no_stale_or_missing_critical_feature",
                    }
                    else "true_safety_block"
                ),
            }
        )
    return {
        "schema_version": "a_plus_gate_after_trust_semantics_status_v1",
        "generated_utc": generated_utc,
        "paper_session_id": paper_session_id,
        "evaluated_candidates": len(evaluations),
        "final_a_plus_candidates": sum(1 for row in evaluations if row.get("a_plus") is True),
        "reduced_size_bootstrap_candidates": len(reduced_rows),
        "b_grade_candidates": len(b_grade_rows),
        "shadow_only_candidates": len(shadow_rows),
        "no_trade_candidates": len(no_trade_rows),
        "no_blanket_false_trust_block": True,
        "public_book_can_approve_trade_alone": False,
        "reduced_size_counts_as_final_a_plus": False,
        "b_grade_counts_as_final_a_plus": False,
        "non_pass_reasons": non_pass_rows[:50],
        "places_real_order": False,
        "routes_to_live": False,
        "live_path_changed": False,
    }


def _write_jsonl_rows(path: Path, rows: list[dict[str, Any]]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(f"{path.name}.{os.getpid()}.tmp")
    lines = [json.dumps(row, sort_keys=True, default=str, separators=(",", ":")) for row in rows]
    tmp.write_text(("\n".join(lines) + "\n") if lines else "", encoding="utf-8")
    tmp.replace(path)


def _a_plus_reduced_size_bootstrap_hash_chain(
    *,
    pending_rows: list[dict[str, Any]],
    closed_rows: list[dict[str, Any]],
    generated_utc: str,
) -> dict[str, Any]:
    chain = "0" * 64
    entries = []
    for row_type, rows in (("pending", pending_rows), ("closed", closed_rows)):
        for index, row in enumerate(rows):
            canonical = json.dumps(row, sort_keys=True, default=str, separators=(",", ":"))
            row_hash = hashlib.sha256(canonical.encode("utf-8")).hexdigest()
            chain = hashlib.sha256(f"{chain}:{row_hash}".encode("utf-8")).hexdigest()
            entries.append(
                {
                    "row_type": row_type,
                    "index": index,
                    "row_hash": row_hash,
                    "chain_hash": chain,
                }
            )
    metrics = _paper_performance_metrics(closed_rows)
    return {
        "schema_version": "a_plus_reduced_size_bootstrap_hash_chain_v1",
        "generated_utc": generated_utc,
        "pending_rows": len(pending_rows),
        "closed_rows": len(closed_rows),
        "chain_head": chain,
        "entries": entries[-50:],
        "progress_requirements": {
            "minimum_closed_trades_to_claim_progress": 25,
            "minimum_pf_to_claim_progress": 1.0,
            "minimum_closed_trades_to_consider_final_a_plus_promotion": 300,
            "minimum_pf_to_consider_final_a_plus_promotion": 1.25,
            "minimum_notional_weighted_expectancy_bps_to_promote": 5.0,
            "requires_long_and_short": True,
            "requires_20_symbols": True,
            "requires_composite_trust_gte_final_threshold_on_promoted_rows": True,
        },
        "current_metrics": metrics,
        "paper_only": True,
        "places_real_order": False,
        "routes_to_live": False,
    }


def _a_plus_5_trade_gate_runtime_status(
    closed_rows: list[dict[str, Any]],
    *,
    generated_utc: str,
) -> dict[str, Any]:
    a_plus_rows = [row for row in closed_rows if _is_a_plus_closed_row(row)]
    sample_rows = a_plus_rows[:5]
    metrics = _paper_performance_metrics(sample_rows)
    wins = sum(1 for row in sample_rows if _paper_row_won(row))
    losses = [row for row in sample_rows if _paper_row_lost(row)]
    atr_stop_losses = [row for row in losses if _paper_performance_is_atr_stop(row)]
    expectancy_bps = _coerce_float(metrics.get("notional_weighted_expectancy_bps"))
    profit_factor = _coerce_float(metrics.get("profit_factor_numeric"))
    if atr_stop_losses:
        status = "BLOCKED_A_PLUS_ATR_STOP_LOSS"
    elif losses:
        status = "BLOCKED_A_PLUS_5_TRADE_LOSS"
    elif len(sample_rows) < 5:
        status = "WAITING_FOR_5_CLOSED_A_PLUS_TRADES"
    elif (
        (
            metrics.get("profit_factor_is_infinite") is True
            or (profit_factor is not None and profit_factor > 0.0)
        )
        and expectancy_bps is not None
        and expectancy_bps > 0.0
    ):
        status = "PASSED_A_PLUS_5_TRADE_GATE"
    else:
        status = "BLOCKED_A_PLUS_5_TRADE_EDGE_NON_POSITIVE"
    return {
        "schema_version": "a_plus_5_trade_gate_runtime_status_v1",
        "generated_utc": generated_utc,
        "status": status,
        "closed_a_plus_trades_considered": len(sample_rows),
        "total_closed_a_plus_trades_seen": len(a_plus_rows),
        "max_closed_a_plus_trades_considered": 5,
        "required_closed_a_plus_trades": 5,
        "win_count": wins,
        "loss_count": len(losses),
        "requires_5_of_5_wins": True,
        "profit_factor": metrics.get("profit_factor"),
        "profit_factor_numeric": metrics.get("profit_factor_numeric"),
        "expectancy_bps": expectancy_bps,
        "atr_stop_loss_count": len(atr_stop_losses),
        "loss_quarantines_bucket": bool(losses),
        "atr_stop_loss_blocks_further_a_plus_evidence": bool(atr_stop_losses),
        "blocked_bucket_keys": sorted({_paper_performance_bucket_key(row) for row in losses}),
        "sample_a_plus_closed_trades": _compact_rows_for_state(_sample_rows(sample_rows, 5)),
        "places_real_order": False,
        "routes_to_live": False,
        "no_live_mutation": True,
        "live_path_changed": False,
    }


def _b_grade_calibration_safety_status(
    closed_rows: list[dict[str, Any]],
    *,
    churn_status: dict[str, Any] | None,
    generated_utc: str,
) -> dict[str, Any]:
    b_grade_rows = [row for row in closed_rows if _is_b_grade_row(row)]
    metrics = _paper_performance_metrics(b_grade_rows)
    closed_count = int(metrics.get("closed_outcome_count") or 0)
    profit_factor = _coerce_float(metrics.get("profit_factor_numeric"))
    expectancy_bps = _coerce_float(metrics.get("notional_weighted_expectancy_bps"))
    high_confidence_losses = [
        row
        for row in b_grade_rows
        if (_paper_row_confidence(row) or 0.0) >= PAPER_HIGH_CONFIDENCE_QUARANTINE_MIN_SCORE
        and _paper_row_lost(row)
    ]
    churn_status = dict(churn_status or {})
    churn_increased = (
        churn_status.get("new_entries_allowed") is False
        or str(churn_status.get("state") or churn_status.get("status") or "").upper()
        in {"CHURN_HALTED", "COOLDOWN", "SHADOW_ONLY"}
        or int(churn_status.get("duplicate_new_entries") or 0) > 0
        or int(churn_status.get("same_candle_reentry_unexplained") or 0) > 0
    )
    blockers: list[str] = []
    if closed_count >= 5 and profit_factor is not None and profit_factor < 1.0:
        blockers.append("B_GRADE_PROFIT_FACTOR_BELOW_1")
    if closed_count > 0 and expectancy_bps is not None and expectancy_bps <= 0.0:
        blockers.append("B_GRADE_EXPECTANCY_NON_POSITIVE")
    if high_confidence_losses:
        blockers.append("B_GRADE_HIGH_CONFIDENCE_LOSS")
    if churn_increased:
        blockers.append("B_GRADE_CHURN_INCREASED")
    return {
        "schema_version": "b_grade_calibration_safety_status_v1",
        "generated_utc": generated_utc,
        "status": "HALTED_PERFORMANCE" if blockers else "ACTIVE_CALIBRATION",
        "new_b_grade_entries_allowed": not blockers,
        "blockers": sorted(set(blockers)),
        "b_grade_closed_outcome_count": closed_count,
        "profit_factor": metrics.get("profit_factor"),
        "profit_factor_numeric": metrics.get("profit_factor_numeric"),
        "expectancy_bps": expectancy_bps,
        "win_rate": metrics.get("win_rate"),
        "high_confidence_loss_count": len(high_confidence_losses),
        "churn_status": {
            "status": churn_status.get("status"),
            "state": churn_status.get("state"),
            "new_entries_allowed": churn_status.get("new_entries_allowed"),
            "duplicate_new_entries": churn_status.get("duplicate_new_entries"),
            "same_candle_reentry_unexplained": churn_status.get("same_candle_reentry_unexplained"),
        },
        "sample_high_confidence_losses": _compact_rows_for_state(
            _sample_rows(high_confidence_losses, 10)
        ),
        "paper_only": True,
        "places_real_order": False,
        "routes_to_live": False,
        "live_path_changed": False,
    }


def _apply_b_grade_calibration_safety_halt(
    intent: dict[str, Any],
    status: dict[str, Any],
) -> bool:
    if intent.get("paper_opportunity_tier") != PAPER_TIER_B_GRADE_EXPLORATION:
        return False
    if status.get("new_b_grade_entries_allowed") is not False:
        return False
    reason = "B_GRADE_CALIBRATION_SAFETY_HALTED"
    intent["paper_fill_allowed"] = False
    intent["paper_tier_local_fill_allowed"] = False
    intent["paper_fill_block_reason"] = reason
    intent["b_grade_calibration_safety_status"] = status
    intent["paper_fill_gate_block_reasons"] = sorted(
        set(list(intent.get("paper_fill_gate_block_reasons") or []) + [reason])
    )
    intent["local_block_reasons"] = sorted(
        set(list(intent.get("local_block_reasons") or []) + [reason])
    )
    intent["places_real_order"] = False
    intent["routes_to_live"] = False
    intent["counts_as_a_grade_evidence"] = False
    return True


def _b_grade_exploration_resumption_status(
    *,
    intents: list[dict[str, Any]],
    accepted_rows: list[dict[str, Any]],
    closed_rows: list[dict[str, Any]],
    trainer_feedback_rows: list[dict[str, Any]],
    trainer_hybrid_cuda_status: dict[str, Any] | None,
    b_grade_canary_supply_status: dict[str, Any],
    previous_status: dict[str, Any] | None,
    generated_utc: str,
) -> dict[str, Any]:
    b_grade_intents = [row for row in intents if _is_b_grade_row(row)]
    b_grade_accepted = [row for row in accepted_rows if _is_b_grade_row(row)]
    b_grade_closed = [row for row in closed_rows if _is_b_grade_row(row)]
    previous_status = dict(previous_status or {})
    previous_closed = int(previous_status.get("b_grade_closed_outcomes") or 0)
    previous_feedback = int(previous_status.get("trainer_consumable_feedback_rows") or 0)
    previous_zero_streak = int(previous_status.get("accepted_fills_zero_cycle_streak") or 0)
    accepted_zero_streak = previous_zero_streak + 1 if not b_grade_accepted else 0
    confidence_values = [
        value
        for value in (_paper_row_confidence(row) for row in b_grade_intents + b_grade_accepted)
        if value is not None
    ]
    fallback_05_count = sum(1 for value in confidence_values if abs(value - 0.5) <= 1e-9)
    confidence_moves_off_fallback = any(abs(value - 0.5) > 1e-9 for value in confidence_values)
    root_cause_counts = dict(b_grade_canary_supply_status.get("root_cause_counts") or {})
    exact_blocker = None
    if not b_grade_accepted:
        if root_cause_counts:
            exact_blocker = max(root_cause_counts.items(), key=lambda item: item[1])[0]
        else:
            exact_blocker = "NO_B_GRADE_ACCEPTED_FILLS"
    pass_conditions = {
        "b_grade_intents_gt_zero": len(b_grade_intents) > 0,
        "accepted_fills_gt_zero_or_exact_blocker_known": bool(b_grade_accepted)
        or exact_blocker is not None,
        "b_grade_closed_outcomes_increased": len(b_grade_closed) > previous_closed,
        "trainer_consumable_feedback_rows_increased": (
            len(trainer_feedback_rows) > previous_feedback
        ),
        "confidence_calibrated_moves_off_0_5_fallback": confidence_moves_off_fallback,
    }
    return {
        "schema_version": "b_grade_exploration_resumption_status_v1",
        "generated_utc": generated_utc,
        "status": (
            "PASSED_B_GRADE_EXPLORATION_RESUMED"
            if all(pass_conditions.values())
            else "BLOCKED_B_GRADE_EXPLORATION_RESUMPTION"
        ),
        "pass_conditions": pass_conditions,
        "b_grade_intents": len(b_grade_intents),
        "b_grade_accepted_fills": len(b_grade_accepted),
        "b_grade_closed_outcomes": len(b_grade_closed),
        "b_grade_closed_outcomes_delta": len(b_grade_closed) - previous_closed,
        "trainer_consumable_feedback_rows": len(trainer_feedback_rows),
        "trainer_consumable_feedback_rows_delta": (len(trainer_feedback_rows) - previous_feedback),
        "confidence_calibrated_distribution": {
            "count": len(confidence_values),
            "fallback_0_5_count": fallback_05_count,
            "moves_off_0_5_fallback": confidence_moves_off_fallback,
            "min": min(confidence_values) if confidence_values else None,
            "max": max(confidence_values) if confidence_values else None,
        },
        "accepted_fills_zero_cycle_streak": accepted_zero_streak,
        "patch_required": accepted_zero_streak >= 3,
        "patch_target": exact_blocker if accepted_zero_streak >= 3 else None,
        "exact_blocker": exact_blocker,
        "root_cause_counts": root_cause_counts,
        "redis_keys_checked": [
            "v2:paper:intents",
            "v2:paper:accepted_fills",
            "v2:paper:closed_trades",
            "v2:trainer:feedback:outcomes",
            "v2:trainer:hybrid_cuda:status",
        ],
        "trainer_hybrid_cuda_status": trainer_hybrid_cuda_status or {},
        "sample_b_grade_intents": _compact_rows_for_state(_sample_rows(b_grade_intents, 10)),
        "sample_b_grade_accepted_fills": _compact_rows_for_state(
            _sample_rows(b_grade_accepted, 10)
        ),
        "paper_only": True,
        "places_real_order": False,
        "routes_to_live": False,
        "live_path_changed": False,
    }


# A+ goal Phase 1/8: bucket quarantine is bucket-scoped by design ("same bad
# bucket cannot re-enter"). A schema-v2, current, source-bound paper-runtime
# authorization makes the GLOBAL escalation recoverable: buckets whose loss
# evidence all closed BEFORE the repair deployment stay bucket-blocked but stop
# halting every clean bucket; any loss that closes AFTER the repair (or carries
# no parseable exit timestamp — fail closed) escalates globally again. Without
# the exact canonical contract, the original always-escalate behaviour remains.
PAPER_EXIT_REPAIR_DEFAULT_STATUS_PATH = (
    Path(__file__).resolve().parents[4]
    / "goal_state/V2_A_PLUS_LIVE_READY_TRAINER_EDGE_REPAIR_AND_ZERO_TOLERANCE_TRADE_GATE"
    / "atr_stop_cluster_repair_status.json"
)
PAPER_EXIT_REPAIR_STATUS_PATH = PAPER_EXIT_REPAIR_DEFAULT_STATUS_PATH
PAPER_EXIT_REPAIR_LEGACY_STATUS_PATH = (
    Path(__file__).resolve().parents[4]
    / "goal_state/V2_FABLE5_FULL_SYSTEM_A_PLUS_LIVE_READY_1000X_MACHINE_COMPLETION"
    / "atr_stop_cluster_repair_status.json"
)
# Migration-era reference only; never consulted for authorization.


def _paper_parse_utc(value: Any) -> datetime | None:
    if not isinstance(value, str) or not value.strip():
        return None
    try:
        parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError:
        return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc)


def _paper_verified_exit_repair_deployed_utc(*, observed_utc: str | None = None) -> datetime | None:
    # Keep one exact verifier for both paper consumers.  The canonical path is
    # passed explicitly; the legacy goal artifact is never consulted.
    from v2.backend.app.cli.v2_clean_3000_session_edge_recovery import (
        _verified_exit_repair_deployed_utc,
    )

    return _verified_exit_repair_deployed_utc(
        observed_utc=observed_utc,
        status_path=PAPER_EXIT_REPAIR_STATUS_PATH,
    )


def _paper_row_exit_utc(row: dict[str, Any]) -> datetime | None:
    for field in (
        "exit_price_utc",
        "exit_time",
        "close_time",
        "closed_at",
        "generated_utc",
        "generated_at",
    ):
        parsed = _paper_parse_utc(row.get(field))
        if parsed is not None:
            return parsed
    return None


