def _paper_bucket_quarantine_operator_sample(
    row: Mapping[str, Any],
    *,
    source_row_canonical_sha256: str | None,
) -> dict[str, Any]:
    """Return a bounded display projection without nested replay material.

    The source close row remains untouched in the canonical lifecycle/outcome
    stores.  The full-row hash binds this operator sample back to that source
    without recursively embedding prior quarantine samples, preemptive input
    material, feature tensors, or final-admission receipts.
    """

    projection = {
        field: row[field]
        for field in BUCKET_QUARANTINE_OPERATOR_SAMPLE_FIELDS
        if field in row and row[field] not in (None, "")
    }
    projection.update(
        {
            "schema_version": "paper_bucket_quarantine_operator_sample_v1",
            "source_row_canonical_sha256": source_row_canonical_sha256,
            "source_row_hash_status": (
                "BOUND_FULL_SOURCE_ROW"
                if source_row_canonical_sha256 is not None
                else "FULL_SOURCE_ROW_NOT_CANONICALLY_HASHABLE"
            ),
            "operator_projection_only": True,
            "full_source_row_mutated": False,
            "nested_replay_material_omitted": True,
        }
    )
    return projection


def _paper_bucket_has_post_repair_loss(
    rows: list[dict[str, Any]],
    repair_deployed: datetime | None,
) -> bool:
    """True when any losing row closed at/after the repair or lacks a timestamp."""
    if repair_deployed is None:
        return True
    for row in rows:
        if (_paper_performance_realized_bps(row) or 0.0) > 0.0:
            continue
        exit_utc = _paper_row_exit_utc(row)
        if exit_utc is None or exit_utc >= repair_deployed:
            return True
    return False


def _paper_bucket_quarantine_status(
    closed_rows: list[dict[str, Any]],
    *,
    generated_utc: str | None = None,
) -> dict[str, Any]:
    source_rows = _paper_performance_source_rows(closed_rows)
    # A+ goal: bucket-quarantine BLOCKING evidence restarts at the verified
    # exit-repair point (symmetric: pre-repair wins AND losses excluded from
    # the blocking view; rows without a parseable exit timestamp fail closed
    # and stay counted). Buckets whose adverse evidence entirely pre-dates the
    # repair remain LISTED (state PRE_REPAIR_EVIDENCE_ONLY, non-escalating)
    # but stop candidate-blocking; any post-repair loss re-blocks its buckets
    # immediately at the same min counts. Session-level PF/expectancy metrics
    # are NOT filtered.
    exit_repair_deployed = _paper_verified_exit_repair_deployed_utc()
    pre_repair_rows_excluded = 0
    quarantine_rows: list[dict[str, Any]] = []
    if exit_repair_deployed is not None:
        for row in source_rows:
            exit_utc = _paper_row_exit_utc(row)
            if exit_utc is not None and exit_utc < exit_repair_deployed:
                pre_repair_rows_excluded += 1
                continue
            quarantine_rows.append(row)
    else:
        quarantine_rows = list(source_rows)
    post_repair_row_ids = {id(row) for row in quarantine_rows}
    source_row_hash_cache: dict[int, str | None] = {}

    def _source_row_hash(row: dict[str, Any]) -> str | None:
        row_identity = id(row)
        if row_identity not in source_row_hash_cache:
            source_row_hash_cache[row_identity] = _paper_canonical_sha256(row)
        return source_row_hash_cache[row_identity]

    grouped: dict[str, dict[str, Any]] = {}
    for row in source_rows:
        for key, group_type in _paper_performance_quarantine_group_keys(row).items():
            grouped.setdefault(key, {"group_type": group_type, "rows": []})["rows"].append(row)

    quarantined: list[dict[str, Any]] = []

    def _bucket_view(rows: list[dict[str, Any]], group_type: str) -> dict[str, Any]:
        """Quarantine reasons + stats for one bucket over one row view."""
        high_confidence_rows = [
            row
            for row in rows
            if (_paper_canary_score(row) or 0.0) >= PAPER_HIGH_CONFIDENCE_QUARANTINE_MIN_SCORE
        ]
        high_confidence_losses = [
            row
            for row in high_confidence_rows
            if (_paper_performance_realized_bps(row) or 0.0) <= 0.0
        ]
        high_confidence_loss_rate = (
            len(high_confidence_losses) / len(high_confidence_rows)
            if high_confidence_rows
            else None
        )
        atr_stop_rows = [row for row in rows if _paper_performance_is_atr_stop(row)]
        losing_atr_stop_rows = [
            row for row in atr_stop_rows if (_paper_performance_realized_bps(row) or 0.0) <= 0.0
        ]
        metrics = _paper_performance_metrics(rows)
        expectancy_bps = _coerce_float(metrics.get("notional_weighted_expectancy_bps"))
        profit_factor = _paper_quality_profit_factor_numeric(metrics.get("profit_factor"))
        closed_outcome_count = int(metrics.get("closed_outcome_count") or 0)
        reasons: list[str] = []
        # An EARNING bucket (realized PF >= 1 AND positive notional-weighted
        # expectancy on its own record) has paid for its high-confidence
        # losses with bigger wins — that is the adaptive-stop design working
        # (fewer, larger winners with some high-confidence losers), not
        # miscalibration. Quarantining it punished success: observed
        # 2026-07-16 timeframe:1h at PF 3.35 quarantined by loss rate alone,
        # escalating a GLOBAL halt against a winning book. The moment the
        # bucket stops earning (PF < 1 or expectancy <= 0) the loss-rate
        # reason fires again at the same adaptive bound.
        _bucket_is_earning = (
            profit_factor is not None
            and profit_factor >= 1.0
            and expectancy_bps is not None
            and expectancy_bps > 0.0
        )
        if (
            high_confidence_loss_rate is not None
            and len(high_confidence_rows) >= 2
            and high_confidence_loss_rate > PAPER_HIGH_CONFIDENCE_LOSS_RATE_BOUND
            and not _bucket_is_earning
        ):
            reasons.append("HIGH_CONFIDENCE_LOSS_RATE_ABOVE_ADAPTIVE_BOUND")
        if (
            group_type == "exact_context"
            and len(losing_atr_stop_rows) >= PAPER_ATR_STOP_CLUSTER_MIN_COUNT
        ):
            reasons.append("ATR_STOP_LOSS_CLUSTER")
        if (
            group_type in {"side_timeframe", "strategy_side_timeframe"}
            and len(losing_atr_stop_rows) >= PAPER_ATR_STOP_CLUSTER_MIN_COUNT
        ):
            reasons.append(f"ATR_STOP_LOSS_CLUSTER_{group_type.upper()}_BUCKET")
        if (
            group_type != "exact_context"
            and closed_outcome_count >= PAPER_NEGATIVE_BUCKET_QUARANTINE_MIN_COUNT
            and expectancy_bps is not None
            and expectancy_bps <= 0.0
        ):
            reasons.append(f"NEGATIVE_EXPECTANCY_{group_type.upper()}_BUCKET")
        if (
            group_type != "exact_context"
            and closed_outcome_count >= PAPER_NEGATIVE_BUCKET_QUARANTINE_MIN_COUNT
            and profit_factor is not None
            and profit_factor < 1.0
        ):
            reasons.append(f"NEGATIVE_PROFIT_FACTOR_{group_type.upper()}_BUCKET")
        return {
            "reasons": reasons,
            "metrics": metrics,
            "high_confidence_loss_rate": high_confidence_loss_rate,
            "high_confidence_losses": high_confidence_losses,
            "high_confidence_rows": high_confidence_rows,
            "losing_atr_stop_rows": losing_atr_stop_rows,
        }

    def _bucket_candidate_blocking(
        *,
        reasons: list[str],
        group_type: str,
        metrics: dict[str, Any],
    ) -> tuple[bool, str | None]:
        if not reasons:
            return False, None
        reason_set = set(reasons)
        hard_prefixes = (
            "HIGH_CONFIDENCE_LOSS_RATE",
            "ATR_STOP_LOSS_CLUSTER",
            "NEGATIVE_EXPECTANCY",
        )
        if any(any(reason.startswith(prefix) for prefix in hard_prefixes) for reason in reason_set):
            return True, None
        if group_type in {
            "exact_context",
            "side_timeframe",
            "strategy_side_timeframe",
            "strategy_regime",
            "confidence_regime",
        }:
            return True, None
        pf_only = reason_set and all(
            reason.startswith("NEGATIVE_PROFIT_FACTOR") for reason in reason_set
        )
        expectancy_bps = _coerce_float(metrics.get("notional_weighted_expectancy_bps"))
        if pf_only and expectancy_bps is not None and expectancy_bps > 0.0:
            return False, "WATCH_ONLY_POSITIVE_EXPECTANCY_PF_BELOW_1_BROAD_BUCKET"
        return True, None

    blocking_loss_row_ids: set[int] = set()
    for key, group in grouped.items():
        all_rows = list(group.get("rows") or [])
        group_type = str(group.get("group_type") or "exact_context")
        post_rows = [row for row in all_rows if id(row) in post_repair_row_ids]
        post_view = _bucket_view(post_rows, group_type)
        if post_view["reasons"]:
            post_blocking, watch_reason = _bucket_candidate_blocking(
                reasons=list(post_view["reasons"]),
                group_type=group_type,
                metrics=dict(post_view["metrics"]),
            )
            view, rows, state, blocking = (
                post_view,
                post_rows,
                "QUARANTINED" if post_blocking else "WATCH_ONLY_SIZE_CAP",
                post_blocking,
            )
        else:
            full_view = _bucket_view(all_rows, group_type)
            if not full_view["reasons"]:
                continue
            watch_reason = None
            view, rows, state, blocking = full_view, all_rows, "PRE_REPAIR_EVIDENCE_ONLY", False
        high_confidence_rows = view["high_confidence_rows"]
        high_confidence_losses = view["high_confidence_losses"]
        high_confidence_loss_rate = view["high_confidence_loss_rate"]
        losing_atr_stop_rows = view["losing_atr_stop_rows"]
        metrics = view["metrics"]
        reasons = list(view["reasons"])
        if blocking:
            blocking_loss_row_ids.update(
                id(row) for row in rows if (_paper_performance_realized_bps(row) or 0.0) <= 0.0
            )
        # Data-integrity fail-closed: a losing row with no parseable exit
        # timestamp means the capture chain is broken — that escalates at any
        # sample size (unlike statistical thinness, which stays bucket-scoped).
        losing_row_missing_exit_ts = blocking and any(
            (_paper_performance_realized_bps(row) or 0.0) <= 0.0
            and _paper_row_exit_utc(row) is None
            for row in rows
        )
        sample_source_rows = _sample_rows(
            rows,
            BUCKET_QUARANTINE_OPERATOR_SAMPLE_LIMIT,
        )
        sample_source_hashes = [_source_row_hash(row) for row in sample_source_rows]
        sample_rows = [
            _paper_bucket_quarantine_operator_sample(
                row,
                source_row_canonical_sha256=source_hash,
            )
            for row, source_hash in zip(
                sample_source_rows,
                sample_source_hashes,
                strict=True,
            )
        ]
        quarantined.append(
            {
                "bucket_key": key,
                "bucket_type": group_type,
                "state": state,
                "candidate_blocking": blocking,
                "non_blocking_watch_reason": watch_reason,
                "requires_exploration_size_cap": state == "WATCH_ONLY_SIZE_CAP",
                # Global escalation requires material sample size; below the floor
                # the bucket stays candidate_blocking (no re-entry) but returns
                # False here so one thin bucket cannot deadlock the whole book
                # (global freeze would block the evidence that clears it). The
                # fail-closed None pass-through (missing repair artifact/exit
                # timestamps) is preserved for buckets at/above the floor.
                "escalates_global_halt": (
                    (blocking and _paper_bucket_has_post_repair_loss(rows, exit_repair_deployed))
                    if (
                        losing_row_missing_exit_ts
                        or int(metrics.get("closed_outcome_count") or 0)
                        >= PAPER_GLOBAL_HALT_MIN_BUCKET_ROWS
                    )
                    else False
                ),
                "exit_repair_deployed_utc": (
                    exit_repair_deployed.isoformat(timespec="seconds").replace("+00:00", "Z")
                    if exit_repair_deployed
                    else None
                ),
                "block_reasons": sorted(set(reasons)),
                "closed_outcome_count": metrics.get("closed_outcome_count"),
                "profit_factor": metrics.get("profit_factor"),
                "notional_weighted_expectancy_bps": metrics.get("notional_weighted_expectancy_bps"),
                "high_confidence_loss_rate": high_confidence_loss_rate,
                "high_confidence_loss_count": len(high_confidence_losses),
                "high_confidence_outcome_count": len(high_confidence_rows),
                "high_confidence_min_score": PAPER_HIGH_CONFIDENCE_QUARANTINE_MIN_SCORE,
                "adaptive_high_confidence_loss_rate_bound": (PAPER_HIGH_CONFIDENCE_LOSS_RATE_BOUND),
                "ATR_stop_loss_count": len(losing_atr_stop_rows),
                "ATR_stop_cluster_min_count": PAPER_ATR_STOP_CLUSTER_MIN_COUNT,
                "negative_bucket_min_count": PAPER_NEGATIVE_BUCKET_QUARANTINE_MIN_COUNT,
                "sample_rows": sample_rows,
                "sample_rows_source_count": len(rows),
                "sample_rows_projection_count": len(sample_rows),
                "sample_rows_projection_limit": BUCKET_QUARANTINE_OPERATOR_SAMPLE_LIMIT,
                "sample_rows_projection_only": True,
                "sample_rows_full_payload_omitted": True,
                "sample_rows_full_payload_source": (
                    "CANONICAL_CLOSED_ROWS_ARGUMENT_PRESERVED_UNCHANGED"
                ),
                "sample_rows_full_source_hashes": sample_source_hashes,
                "sample_rows_all_full_source_hashes_bound": all(
                    source_hash is not None for source_hash in sample_source_hashes
                ),
            }
        )
    quarantined.sort(
        key=lambda row: (
            -int(row.get("ATR_stop_loss_count") or 0),
            -int(row.get("high_confidence_loss_count") or 0),
            str(row.get("bucket_key") or ""),
        )
    )
    _post_repair_aggregate = _paper_performance_metrics(quarantine_rows)
    _post_repair_pf = _paper_quality_profit_factor_numeric(
        _post_repair_aggregate.get("profit_factor")
    )
    _post_repair_ev = _coerce_float(_post_repair_aggregate.get("notional_weighted_expectancy_bps"))
    _post_repair_aggregate_earning = (
        _post_repair_pf is not None
        and _post_repair_pf >= 1.0
        and _post_repair_ev is not None
        and _post_repair_ev > 0.0
    )
    blocked_bucket_keys = [
        row["bucket_key"] for row in quarantined if row.get("candidate_blocking") is True
    ][:B_GRADE_MODEL_QUALITY_BUCKET_LIMIT]
    return {
        "schema_version": "bucket_quarantine_status_v1",
        "status": "ACTIVE_WITH_QUARANTINES" if quarantined else "ACTIVE_NO_QUARANTINES",
        "enabled": True,
        "paper_only": True,
        "routes_to_live": False,
        "places_real_order": False,
        "adaptive_high_confidence_loss_rate_bound": PAPER_HIGH_CONFIDENCE_LOSS_RATE_BOUND,
        "high_confidence_min_score": PAPER_HIGH_CONFIDENCE_QUARANTINE_MIN_SCORE,
        "ATR_stop_cluster_min_count": PAPER_ATR_STOP_CLUSTER_MIN_COUNT,
        "negative_bucket_min_count": PAPER_NEGATIVE_BUCKET_QUARANTINE_MIN_COUNT,
        "source_closed_rows": len(closed_rows),
        "governed_closed_rows": len(source_rows),
        "quarantine_evidence_rows": len(quarantine_rows),
        "pre_repair_rows_excluded_from_quarantine": pre_repair_rows_excluded,
        "exit_repair_deployed_utc": (
            exit_repair_deployed.isoformat(timespec="seconds").replace("+00:00", "Z")
            if exit_repair_deployed
            else None
        ),
        "quarantined_bucket_count": len(quarantined),
        # Computed over the FULL quarantined list (quarantined_buckets below is
        # truncated for display); fail-closed when the repair artifact is
        # missing or a losing row lacks a parseable exit timestamp.
        "global_halt_required": (
            any(bucket.get("escalates_global_halt") is not False for bucket in quarantined)
            # Systemic breadth: enough DISTINCT losing rows across blocking
            # buckets escalates globally even when each bucket is below the
            # material-sample floor — but ONLY when the same post-repair
            # evidence window is NOT earning in aggregate. Losses inside a
            # winning book (observed: 3 losses in a 13-trade 10W/3L window,
            # aggregate PF > 2) are variance the bucket-scoped blocks already
            # contain; the moment aggregate PF drops below 1 or expectancy
            # goes non-positive, the breadth escalation fires as before.
            or (
                len(blocking_loss_row_ids) >= PAPER_GLOBAL_HALT_MIN_DISTINCT_LOSSES
                and not _post_repair_aggregate_earning
            )
        ),
        "post_repair_aggregate_earning": _post_repair_aggregate_earning,
        "post_repair_aggregate_profit_factor": _post_repair_pf,
        "post_repair_aggregate_expectancy_bps": _post_repair_ev,
        "escalating_bucket_count": sum(
            1 for bucket in quarantined if bucket.get("escalates_global_halt") is not False
        ),
        "global_halt_min_bucket_rows": PAPER_GLOBAL_HALT_MIN_BUCKET_ROWS,
        "global_halt_min_distinct_losses": PAPER_GLOBAL_HALT_MIN_DISTINCT_LOSSES,
        "blocking_distinct_loss_row_count": len(blocking_loss_row_ids),
        "exit_repair_deployed_utc": (
            exit_repair_deployed.isoformat(timespec="seconds").replace("+00:00", "Z")
            if exit_repair_deployed
            else None
        ),
        "blocked_bucket_keys": blocked_bucket_keys,
        "quarantined_buckets": quarantined[:B_GRADE_MODEL_QUALITY_BUCKET_LIMIT],
        "pass_conditions": {
            "quarantine_prevents_same_bad_bucket_reentry": True,
            "paper_only": True,
            "routes_to_live_false": True,
            "places_real_order_false": True,
        },
        "generated_utc": generated_utc or _utc_iso(),
    }


def _paper_first_bootstrap_close_block_status(
    source_rows: list[dict[str, Any]],
) -> dict[str, Any]:
    bootstrap_rows = [
        row
        for row in source_rows
        if str(row.get("paper_opportunity_tier") or row.get("source_tier") or "").upper()
        in {"A_GRADE_BOOTSTRAP_PAPER", PAPER_TIER_A_PLUS_BOOTSTRAP_REDUCED_SIZE}
    ]
    first_bootstrap = bootstrap_rows[0] if bootstrap_rows else None
    first_pnl_bps = (
        _paper_performance_realized_bps(first_bootstrap)
        if isinstance(first_bootstrap, dict)
        else None
    )
    blocked = first_pnl_bps is not None and first_pnl_bps < 0.0
    return {
        "first_bootstrap_close_seen": first_bootstrap is not None,
        "first_bootstrap_close_negative": blocked,
        "first_bootstrap_close_realized_pnl_bps": first_pnl_bps,
        "bootstrap_reopen_allowed": not blocked,
        "candidate_policy_change_required": blocked,
        "root_cause_patch_required": blocked,
        "block_reason": (
            "FIRST_BOOTSTRAP_CLOSE_NEGATIVE_POLICY_CHANGE_REQUIRED" if blocked else None
        ),
    }


def _paper_recovery_high_confidence_loss_cluster_status(
    source_rows: list[dict[str, Any]],
) -> dict[str, Any]:
    def _adaptive_allocation(row: dict[str, Any]) -> dict[str, Any]:
        value = row.get("adaptive_allocation")
        return value if isinstance(value, dict) else {}

    def _strict_loss(row: dict[str, Any]) -> bool:
        return _paper_performance_has_negative_realized_outcome(row)

    # Repair-epoch scoping (same protocol the bucket quarantine already uses):
    # losses that closed BEFORE the verified exit-repair deployment stop
    # feeding the cluster detector; any post-epoch loss (or a loss without a
    # parseable exit timestamp — fail closed) counts immediately. The gate is
    # unchanged: this scopes its EVIDENCE to the current exit policy, it does
    # not raise thresholds or ignore losses under that policy.
    _cluster_repair_epoch = _paper_verified_exit_repair_deployed_utc()

    def _post_epoch_loss(row: dict[str, Any]) -> bool:
        if _cluster_repair_epoch is None:
            return True
        exit_utc = _paper_row_exit_utc(row)
        return exit_utc is None or exit_utc >= _cluster_repair_epoch

    # A cluster is TEMPORAL: losses CONCENTRATING in the recent record. The
    # previous cumulative lifetime count latched a permanent global halt after
    # any 2 post-epoch high-confidence losses (wins never offset, losses never
    # aged out — observed 2026-07-16T22:08Z: 2 losses latched the halt against
    # a 4-win/2-loss post-epoch record). Cluster evidence is now the loss
    # count within the most recent K high-confidence outcomes
    # (K = 2x configured min count): back-to-back high-confidence losses
    # still halt immediately, aggregate profitability still cannot mask them,
    # and subsequent banked wins roll old losses out of the window so the
    # halt self-clears through evidence instead of persisting forever.
    _cluster_window = max(PAPER_RECOVERY_HIGH_CONFIDENCE_LOSS_CLUSTER_MIN_COUNT * 2, 4)
    _post_epoch_rows = [
        row for row in source_rows if _post_epoch_loss(row) or not _strict_loss(row)
    ]
    _recent_high_confidence_rows = sorted(
        (
            row
            for row in _post_epoch_rows
            if (_paper_row_confidence(row) or 0.0) >= PAPER_RECOVERY_HIGH_CONFIDENCE_MIN_SCORE
        ),
        key=lambda row: _paper_row_exit_utc(row) or datetime.min.replace(tzinfo=timezone.utc),
    )[-_cluster_window:]
    high_confidence_loss_rows = [
        row for row in _recent_high_confidence_rows if _strict_loss(row) and _post_epoch_loss(row)
    ]
    _recent_high_confidence_win_count = sum(
        1 for row in _recent_high_confidence_rows if not _strict_loss(row)
    )
    sample_rows = [
        {
            "symbol": row.get("symbol"),
            "side": row.get("side"),
            "timeframe": row.get("timeframe"),
            "strategy_id": row.get("strategy_id"),
            "position_id": row.get("position_id"),
            "paper_session_id": row.get("paper_session_id"),
            "confidence_calibrated": _paper_row_confidence(row),
            "confidence_raw": row.get("confidence_raw"),
            "expected_move_after_cost_bps": row.get("expected_move_after_cost_bps"),
            "realized_pnl_bps": _paper_performance_realized_bps(row),
            "realized_pnl_usd": _paper_performance_realized_usd(row),
            "realized_net_pnl_usd": row.get("realized_net_pnl_usd"),
            "gross_notional_usd": row.get("gross_notional_usd"),
            "exit_reason": row.get("exit_reason") or row.get("close_reason"),
            "exit_price_utc": row.get("exit_price_utc") or row.get("closed_at"),
            "MFE": _first_present(row.get("MFE"), row.get("mfe_bps")),
            "MAE": _first_present(row.get("MAE"), row.get("mae_bps")),
            "microstructure_trust_score": row.get("microstructure_trust_score"),
            "public_orderbook_trust_score": row.get("public_orderbook_trust_score"),
            "composite_microstructure_trust_score": row.get("composite_microstructure_trust_score"),
            "continuous_edge_guardian_status": _first_present(
                row.get("continuous_edge_guardian_status"),
                row.get("guardian_status"),
                _adaptive_allocation(row).get("continuous_edge_guardian_status"),
                _adaptive_allocation(row).get("guardian_status"),
            ),
            "continuous_edge_guardian_new_entries_allowed": _first_present(
                row.get("continuous_edge_guardian_new_entries_allowed"),
                row.get("guardian_new_entries_allowed"),
                _adaptive_allocation(row).get("continuous_edge_guardian_new_entries_allowed"),
                _adaptive_allocation(row).get("guardian_new_entries_allowed"),
            ),
            "candidate_bucket_keys": sorted(_paper_performance_candidate_quarantine_keys(row)),
            "missing_runtime_fields": [
                field
                for field in (
                    "microstructure_trust_score",
                    "public_orderbook_trust_score",
                    "composite_microstructure_trust_score",
                )
                if row.get(field) in (None, "")
            ],
        }
        for row in _sample_rows(high_confidence_loss_rows, 10)
    ]
    cluster = (
        len(high_confidence_loss_rows) >= PAPER_RECOVERY_HIGH_CONFIDENCE_LOSS_CLUSTER_MIN_COUNT
    )

    def _cluster_dimension_counts(*fields: str) -> dict[str, int]:
        counts: dict[str, int] = {}
        for row in high_confidence_loss_rows:
            value = _first_present(*(row.get(field) for field in fields))
            if value is None:
                continue
            key = str(value).strip().lower()
            if key:
                counts[key] = counts.get(key, 0) + 1
        return counts

    affected_symbols = sorted(
        {
            str(row.get("symbol")).strip().upper()
            for row in high_confidence_loss_rows
            if row.get("symbol")
        }
    )
    side_counts = _cluster_dimension_counts("side")
    timeframe_counts = _cluster_dimension_counts("timeframe")
    strategy_mode_counts = _cluster_dimension_counts("strategy_selected_mode", "strategy_mode")
    dimension_min = PAPER_HIGH_CONFIDENCE_CLUSTER_DIMENSION_QUARANTINE_MIN_COUNT
    return {
        "schema_version": "paper_recovery_high_confidence_loss_cluster_status_v2",
        "status": "BLOCKED_HIGH_CONFIDENCE_LOSS_CLUSTER" if cluster else "CLEAR",
        "cluster_detected": cluster,
        "high_confidence_min_score": PAPER_RECOVERY_HIGH_CONFIDENCE_MIN_SCORE,
        "cluster_min_loss_count": PAPER_RECOVERY_HIGH_CONFIDENCE_LOSS_CLUSTER_MIN_COUNT,
        "cluster_rolling_window_rows": _cluster_window,
        "recent_high_confidence_win_count": _recent_high_confidence_win_count,
        "high_confidence_loss_count": len(high_confidence_loss_rows),
        "sample_high_confidence_losses": sample_rows,
        # Bucket-specific quarantine: exact symbols with any high-confidence loss
        # always quarantine; side/timeframe/strategy_mode dimensions quarantine only
        # when the dimension accumulates >= dimension_min cluster losses, so an
        # unrelated bucket is not blocked by another bucket's cluster.
        "affected_symbols": affected_symbols,
        "affected_dimension_counts": {
            "side": side_counts,
            "timeframe": timeframe_counts,
            "strategy_mode": strategy_mode_counts,
        },
        "dimension_quarantine_min_count": dimension_min,
        "quarantined_sides": sorted(k for k, v in side_counts.items() if v >= dimension_min),
        "quarantined_timeframes": sorted(
            k for k, v in timeframe_counts.items() if v >= dimension_min
        ),
        "quarantined_strategy_modes": sorted(
            k for k, v in strategy_mode_counts.items() if v >= dimension_min
        ),
        "bucket_specific_recovery_enabled": True,
        "paper_only": True,
        "routes_to_live": False,
        "places_real_order": False,
        "live_path_changed": False,
    }


