def _paper_strategy_mode_clock_iso(value: Any) -> str | None:
    parsed = _strict_aware_utc_time(value)
    if parsed is None:
        return None
    return parsed.isoformat(timespec="milliseconds").replace("+00:00", "Z")


def _paper_strategy_mode_opportunity_row_material(
    row: Mapping[str, Any],
) -> dict[str, Any]:
    return {field: row.get(field) for field in _STRATEGY_MODE_OPPORTUNITY_ROW_FIELDS}


def _paper_strategy_mode_opportunity_supply_material(
    evidence: Mapping[str, Any],
) -> dict[str, Any]:
    return {
        "schema_version": evidence.get("schema_version"),
        "policy_version": evidence.get("policy_version"),
        "source_hash_contract": evidence.get("source_hash_contract"),
        "paper_only": evidence.get("paper_only"),
        "live_path_changed": evidence.get("live_path_changed"),
        "routes_to_exchange": evidence.get("routes_to_exchange"),
        "source_scope": evidence.get("source_scope"),
        "minimum_opportunity_count": evidence.get("minimum_opportunity_count"),
        "window_started_at": evidence.get("window_started_at"),
        "window_ended_at": evidence.get("window_ended_at"),
        "generated_at": evidence.get("generated_at"),
        "available_at": evidence.get("available_at"),
        "expires_at": evidence.get("expires_at"),
        "opportunity_count": evidence.get("opportunity_count"),
        "opportunity_mode_counts": evidence.get("opportunity_mode_counts"),
        "opportunity_mode_shares": evidence.get("opportunity_mode_shares"),
        "source_rows": evidence.get("source_rows"),
    }


def _paper_strategy_mode_pit_opportunity_row(
    *,
    source_id: Any,
    signal: Mapping[str, Any],
    prediction: Mapping[str, Any],
    strategy_mode: Any,
    strategy_trade_allowed: bool,
    market_state_integrity_allowed: bool,
    strategy_temporal_contract_status: Any,
    strategy_feature_cutoff: Any,
    strategy_available_at: Any,
    strategy_decision_time: Any,
    signal_temporal_rejection_reasons: list[str],
    future_cutoff_offender_count: int,
    adaptive_stale_seconds: Any,
    observed_at: Any,
) -> tuple[dict[str, Any] | None, list[str]]:
    """Return one current-cycle opportunity only when every PIT clock is valid."""

    reasons = list(signal_temporal_rejection_reasons or [])
    mode = _normalized_strategy_mode(strategy_mode)
    if mode is None or mode == "no_trade_mode":
        reasons.append("OPPORTUNITY_STRATEGY_MODE_NOT_ACTIONABLE")
    if not strategy_trade_allowed:
        reasons.append("OPPORTUNITY_STRATEGY_ROUTER_NOT_TRADEABLE")
    if not market_state_integrity_allowed:
        reasons.append("OPPORTUNITY_MARKET_STATE_INTEGRITY_NOT_ALLOWED")
    if strategy_temporal_contract_status != "PASS":
        reasons.append("OPPORTUNITY_STRATEGY_TEMPORAL_CONTRACT_NOT_PASS")
    if future_cutoff_offender_count > 0:
        reasons.append("OPPORTUNITY_FUTURE_CUTOFF_OFFENDER_PRESENT")

    feature_cutoff = _strict_aware_utc_time(strategy_feature_cutoff)
    available_at = _strict_aware_utc_time(strategy_available_at)
    decision_time = _strict_aware_utc_time(strategy_decision_time)
    consumer_observed_at = _strict_aware_utc_time(observed_at)
    source_generated_at = _strict_aware_utc_time(
        _first_present(
            signal.get("generated_utc"),
            signal.get("generated_at"),
            signal.get("available_at"),
            prediction.get("generated_utc"),
            prediction.get("generated_at"),
            prediction.get("available_at"),
        )
    )
    for field, parsed in (
        ("FEATURE_CUTOFF", feature_cutoff),
        ("AVAILABLE_AT", available_at),
        ("DECISION_TIME", decision_time),
        ("SOURCE_GENERATED_AT", source_generated_at),
        ("CONSUMER_OBSERVED_AT", consumer_observed_at),
    ):
        if parsed is None:
            reasons.append(f"OPPORTUNITY_{field}_UNPARSEABLE_OR_NAIVE")
    if feature_cutoff is not None and available_at is not None and feature_cutoff > available_at:
        reasons.append("OPPORTUNITY_FEATURE_CUTOFF_AFTER_AVAILABLE_AT")
    if available_at is not None and decision_time is not None and available_at > decision_time:
        reasons.append("OPPORTUNITY_AVAILABLE_AT_AFTER_DECISION_TIME")
    if (
        decision_time is not None
        and consumer_observed_at is not None
        and (decision_time > consumer_observed_at)
    ):
        reasons.append("OPPORTUNITY_DECISION_TIME_AFTER_OBSERVATION")
    if (
        source_generated_at is not None
        and consumer_observed_at is not None
        and (source_generated_at > consumer_observed_at)
    ):
        reasons.append("OPPORTUNITY_SOURCE_GENERATED_AFTER_OBSERVATION")
    if (
        isinstance(adaptive_stale_seconds, bool)
        or not isinstance(adaptive_stale_seconds, int)
        or adaptive_stale_seconds <= 0
    ):
        reasons.append("OPPORTUNITY_ADAPTIVE_STALE_SECONDS_INVALID")
        source_expires_at = None
    elif source_generated_at is None:
        source_expires_at = None
    else:
        source_expires_at = source_generated_at + timedelta(seconds=adaptive_stale_seconds)
        if consumer_observed_at is not None and consumer_observed_at >= source_expires_at:
            reasons.append("OPPORTUNITY_SOURCE_STALE_AT_OBSERVATION")
    if reasons:
        return None, sorted(set(str(reason) for reason in reasons))
    assert feature_cutoff is not None
    assert available_at is not None
    assert decision_time is not None
    assert source_generated_at is not None
    assert source_expires_at is not None
    return {
        "source_id": str(source_id or ""),
        "signal_id": str(signal.get("signal_id") or ""),
        "prediction_id": str(
            _first_present(signal.get("prediction_id"), prediction.get("prediction_id")) or ""
        ),
        "symbol": str(_first_present(signal.get("symbol"), prediction.get("symbol")) or "").upper(),
        "timeframe": str(
            _first_present(signal.get("timeframe"), prediction.get("timeframe")) or ""
        ).lower(),
        "strategy_mode": mode,
        "feature_cutoff": _paper_strategy_mode_clock_iso(feature_cutoff),
        "available_at": _paper_strategy_mode_clock_iso(available_at),
        "decision_time": _paper_strategy_mode_clock_iso(decision_time),
        "source_generated_at": _paper_strategy_mode_clock_iso(source_generated_at),
        "source_expires_at": _paper_strategy_mode_clock_iso(source_expires_at),
        "adaptive_stale_seconds": adaptive_stale_seconds,
    }, []


def _paper_strategy_mode_opportunity_supply_evidence(
    rows: list[dict[str, Any]],
    *,
    generated_at: Any,
    available_at: Any | None = None,
) -> dict[str, Any]:
    """Build a hash-bound in-cycle PIT opportunity-supply distribution."""

    canonical_rows: list[dict[str, Any]] = []
    for raw in rows:
        if not isinstance(raw, Mapping):
            continue
        stale_seconds = raw.get("adaptive_stale_seconds")
        if isinstance(stale_seconds, bool):
            normalized_stale_seconds: int | None = None
        else:
            try:
                normalized_stale_seconds = int(stale_seconds)
            except (TypeError, ValueError):
                normalized_stale_seconds = None
        material = {
            "source_id": str(raw.get("source_id") or ""),
            "signal_id": str(raw.get("signal_id") or ""),
            "prediction_id": str(raw.get("prediction_id") or ""),
            "symbol": str(raw.get("symbol") or "").upper(),
            "timeframe": str(raw.get("timeframe") or "").lower(),
            "strategy_mode": _normalized_strategy_mode(raw.get("strategy_mode")),
            "feature_cutoff": _paper_strategy_mode_clock_iso(raw.get("feature_cutoff")),
            "available_at": _paper_strategy_mode_clock_iso(raw.get("available_at")),
            "decision_time": _paper_strategy_mode_clock_iso(raw.get("decision_time")),
            "source_generated_at": _paper_strategy_mode_clock_iso(raw.get("source_generated_at")),
            "source_expires_at": _paper_strategy_mode_clock_iso(raw.get("source_expires_at")),
            "adaptive_stale_seconds": normalized_stale_seconds,
        }
        canonical_rows.append(
            {
                **material,
                "source_row_hash": _paper_canonical_sha256(material),
            }
        )
    canonical_rows.sort(
        key=lambda row: (
            str(row.get("decision_time") or ""),
            str(row.get("source_id") or ""),
            str(row.get("strategy_mode") or ""),
        )
    )
    counts = _strategy_mode_counts_for_rows(
        [{"strategy_selected_mode": row.get("strategy_mode")} for row in canonical_rows]
    )
    opportunity_count = len(canonical_rows)
    shares = {
        mode: count / opportunity_count
        for mode, count in sorted(counts.items())
        if opportunity_count > 0
    }
    decision_times = [
        str(row["decision_time"])
        for row in canonical_rows
        if row.get("decision_time") not in (None, "")
    ]
    source_expiries = [
        str(row["source_expires_at"])
        for row in canonical_rows
        if row.get("source_expires_at") not in (None, "")
    ]
    normalized_generated_at = _paper_strategy_mode_clock_iso(generated_at)
    normalized_available_at = _paper_strategy_mode_clock_iso(
        available_at if available_at is not None else generated_at
    )
    evidence: dict[str, Any] = {
        "schema_version": STRATEGY_MODE_COLLAPSE_OPPORTUNITY_SUPPLY_SCHEMA_VERSION,
        "policy_version": STRATEGY_MODE_COLLAPSE_ADAPTIVE_POLICY_VERSION,
        "source_hash_contract": (STRATEGY_MODE_COLLAPSE_OPPORTUNITY_SOURCE_HASH_CONTRACT),
        "paper_only": True,
        "live_path_changed": False,
        "routes_to_exchange": False,
        "source_scope": "CURRENT_CYCLE_PIT_ELIGIBLE_ROUTED_OPPORTUNITIES",
        # This is the existing immutable closed-policy evidence floor, reused
        # for the paired supply sample rather than introducing a market knob.
        "minimum_opportunity_count": STRATEGY_MODE_COLLAPSE_MIN_CLOSED_TRADES,
        "window_started_at": min(decision_times) if decision_times else None,
        "window_ended_at": max(decision_times) if decision_times else None,
        "generated_at": normalized_generated_at,
        "available_at": normalized_available_at,
        "expires_at": min(source_expiries) if source_expiries else None,
        "opportunity_count": opportunity_count,
        "opportunity_mode_counts": dict(sorted(counts.items())),
        "opportunity_mode_shares": shares,
        "source_rows": canonical_rows,
    }
    evidence["source_hash"] = _paper_canonical_sha256(
        _paper_strategy_mode_opportunity_supply_material(evidence)
    )
    return evidence


def _paper_strategy_mode_opportunity_supply_rejection_reasons(
    evidence: Mapping[str, Any] | None,
    *,
    observed_at: Any,
) -> list[str]:
    reasons: list[str] = []
    if not isinstance(evidence, Mapping):
        return ["OPPORTUNITY_SUPPLY_EVIDENCE_MISSING"]
    if evidence.get("schema_version") != (STRATEGY_MODE_COLLAPSE_OPPORTUNITY_SUPPLY_SCHEMA_VERSION):
        reasons.append("OPPORTUNITY_SUPPLY_SCHEMA_VERSION_INVALID")
    if evidence.get("policy_version") != (STRATEGY_MODE_COLLAPSE_ADAPTIVE_POLICY_VERSION):
        reasons.append("OPPORTUNITY_SUPPLY_POLICY_VERSION_INVALID")
    if evidence.get("source_hash_contract") != (
        STRATEGY_MODE_COLLAPSE_OPPORTUNITY_SOURCE_HASH_CONTRACT
    ):
        reasons.append("OPPORTUNITY_SUPPLY_SOURCE_HASH_CONTRACT_INVALID")
    if evidence.get("paper_only") is not True:
        reasons.append("OPPORTUNITY_SUPPLY_NOT_PAPER_ONLY")
    if evidence.get("live_path_changed") is not False:
        reasons.append("OPPORTUNITY_SUPPLY_LIVE_PATH_CHANGE_NOT_FALSE")
    if evidence.get("routes_to_exchange") is not False:
        reasons.append("OPPORTUNITY_SUPPLY_EXCHANGE_ROUTE_NOT_FALSE")
    if evidence.get("source_scope") != ("CURRENT_CYCLE_PIT_ELIGIBLE_ROUTED_OPPORTUNITIES"):
        reasons.append("OPPORTUNITY_SUPPLY_SOURCE_SCOPE_INVALID")
    if evidence.get("minimum_opportunity_count") != (STRATEGY_MODE_COLLAPSE_MIN_CLOSED_TRADES):
        reasons.append("OPPORTUNITY_SUPPLY_MINIMUM_COUNT_POLICY_INVALID")

    source_rows = evidence.get("source_rows")
    if not isinstance(source_rows, list):
        source_rows = []
        reasons.append("OPPORTUNITY_SUPPLY_SOURCE_ROWS_INVALID")
    canonical_rows: list[dict[str, Any]] = []
    for index, row in enumerate(source_rows):
        if not isinstance(row, Mapping):
            reasons.append(f"OPPORTUNITY_SUPPLY_ROW_INVALID:{index}")
            continue
        material = _paper_strategy_mode_opportunity_row_material(row)
        canonical_rows.append(dict(row))
        expected_row_hash = _paper_canonical_sha256(material)
        if (
            not _paper_valid_sha256(row.get("source_row_hash"))
            or row.get("source_row_hash") != expected_row_hash
        ):
            reasons.append(f"OPPORTUNITY_SUPPLY_ROW_HASH_INVALID:{index}")
        mode = _normalized_strategy_mode(row.get("strategy_mode"))
        if mode is None or mode == "no_trade_mode":
            reasons.append(f"OPPORTUNITY_SUPPLY_ROW_MODE_INVALID:{index}")
        if not str(row.get("source_id") or ""):
            reasons.append(f"OPPORTUNITY_SUPPLY_ROW_SOURCE_ID_MISSING:{index}")
        cutoff = _strict_aware_utc_time(row.get("feature_cutoff"))
        available = _strict_aware_utc_time(row.get("available_at"))
        decision = _strict_aware_utc_time(row.get("decision_time"))
        source_generated = _strict_aware_utc_time(row.get("source_generated_at"))
        source_expires = _strict_aware_utc_time(row.get("source_expires_at"))
        for field, parsed in (
            ("FEATURE_CUTOFF", cutoff),
            ("AVAILABLE_AT", available),
            ("DECISION_TIME", decision),
            ("SOURCE_GENERATED_AT", source_generated),
            ("SOURCE_EXPIRES_AT", source_expires),
        ):
            if parsed is None:
                reasons.append(f"OPPORTUNITY_SUPPLY_ROW_{field}_UNPARSEABLE_OR_NAIVE:{index}")
        if cutoff is not None and available is not None and cutoff > available:
            reasons.append(f"OPPORTUNITY_SUPPLY_ROW_FEATURE_CUTOFF_AFTER_AVAILABLE_AT:{index}")
        if available is not None and decision is not None and available > decision:
            reasons.append(f"OPPORTUNITY_SUPPLY_ROW_AVAILABLE_AT_AFTER_DECISION_TIME:{index}")
        stale_seconds = row.get("adaptive_stale_seconds")
        if (
            isinstance(stale_seconds, bool)
            or not isinstance(stale_seconds, int)
            or stale_seconds <= 0
        ):
            reasons.append(f"OPPORTUNITY_SUPPLY_ROW_ADAPTIVE_STALE_SECONDS_INVALID:{index}")
        elif source_generated is not None and source_expires is not None:
            expected_expiry = source_generated + timedelta(seconds=stale_seconds)
            if source_expires != expected_expiry:
                reasons.append(f"OPPORTUNITY_SUPPLY_ROW_EXPIRY_BINDING_INVALID:{index}")

    opportunity_count = evidence.get("opportunity_count")
    if isinstance(opportunity_count, bool) or not isinstance(opportunity_count, int):
        reasons.append("OPPORTUNITY_SUPPLY_COUNT_INVALID")
        opportunity_count = len(canonical_rows)
    if opportunity_count != len(canonical_rows):
        reasons.append("OPPORTUNITY_SUPPLY_COUNT_SOURCE_ROWS_MISMATCH")
    if opportunity_count < STRATEGY_MODE_COLLAPSE_MIN_CLOSED_TRADES:
        reasons.append("OPPORTUNITY_SUPPLY_SAMPLE_BELOW_CLOSED_POLICY_MINIMUM")

    expected_counts = _strategy_mode_counts_for_rows(
        [{"strategy_selected_mode": row.get("strategy_mode")} for row in canonical_rows]
    )
    supplied_counts = evidence.get("opportunity_mode_counts")
    if not isinstance(supplied_counts, Mapping) or dict(supplied_counts) != dict(
        sorted(expected_counts.items())
    ):
        reasons.append("OPPORTUNITY_SUPPLY_MODE_COUNTS_INVALID")
    if sum(expected_counts.values()) != opportunity_count:
        reasons.append("OPPORTUNITY_SUPPLY_MODE_COUNTS_TOTAL_MISMATCH")
    expected_shares = {
        mode: count / opportunity_count
        for mode, count in sorted(expected_counts.items())
        if opportunity_count > 0
    }
    supplied_shares = evidence.get("opportunity_mode_shares")
    if not isinstance(supplied_shares, Mapping) or set(supplied_shares) != set(expected_shares):
        reasons.append("OPPORTUNITY_SUPPLY_MODE_SHARES_INVALID")
    else:
        for mode, expected_share in expected_shares.items():
            supplied_share = _coerce_float(supplied_shares.get(mode))
            if supplied_share is None or not math.isclose(
                supplied_share,
                expected_share,
                rel_tol=0.0,
                abs_tol=1e-12,
            ):
                reasons.append(f"OPPORTUNITY_SUPPLY_MODE_SHARE_VALUE_INVALID:{mode}")

    generated = _strict_aware_utc_time(evidence.get("generated_at"))
    available = _strict_aware_utc_time(evidence.get("available_at"))
    expires = _strict_aware_utc_time(evidence.get("expires_at"))
    observed = _strict_aware_utc_time(observed_at)
    window_started = _strict_aware_utc_time(evidence.get("window_started_at"))
    window_ended = _strict_aware_utc_time(evidence.get("window_ended_at"))
    for field, parsed in (
        ("GENERATED_AT", generated),
        ("AVAILABLE_AT", available),
        ("EXPIRES_AT", expires),
        ("CONSUMER_OBSERVED_AT", observed),
        ("WINDOW_STARTED_AT", window_started),
        ("WINDOW_ENDED_AT", window_ended),
    ):
        if parsed is None:
            reasons.append(f"OPPORTUNITY_SUPPLY_{field}_UNPARSEABLE_OR_NAIVE")
    row_decisions = [
        parsed
        for parsed in (_strict_aware_utc_time(row.get("decision_time")) for row in canonical_rows)
        if parsed is not None
    ]
    row_expiries = [
        parsed
        for parsed in (
            _strict_aware_utc_time(row.get("source_expires_at")) for row in canonical_rows
        )
        if parsed is not None
    ]
    if row_decisions:
        if window_started != min(row_decisions):
            reasons.append("OPPORTUNITY_SUPPLY_WINDOW_START_BINDING_INVALID")
        if window_ended != max(row_decisions):
            reasons.append("OPPORTUNITY_SUPPLY_WINDOW_END_BINDING_INVALID")
    if row_expiries and expires != min(row_expiries):
        reasons.append("OPPORTUNITY_SUPPLY_EXPIRY_BINDING_INVALID")
    if window_started is not None and window_ended is not None and window_started > window_ended:
        reasons.append("OPPORTUNITY_SUPPLY_WINDOW_ORDER_INVALID")
    if window_ended is not None and generated is not None and window_ended > generated:
        reasons.append("OPPORTUNITY_SUPPLY_WINDOW_END_AFTER_GENERATED_AT")
    if generated is not None and available is not None and generated > available:
        reasons.append("OPPORTUNITY_SUPPLY_GENERATED_AT_AFTER_AVAILABLE_AT")
    if available is not None and observed is not None and available > observed:
        reasons.append("OPPORTUNITY_SUPPLY_AVAILABLE_AT_AFTER_OBSERVED_AT")
    if observed is not None and expires is not None and observed >= expires:
        reasons.append("OPPORTUNITY_SUPPLY_STALE_AT_OBSERVATION")
    if generated is not None:
        for index, row in enumerate(canonical_rows):
            row_decision = _strict_aware_utc_time(row.get("decision_time"))
            row_generated = _strict_aware_utc_time(row.get("source_generated_at"))
            if row_decision is not None and row_decision > generated:
                reasons.append(f"OPPORTUNITY_SUPPLY_ROW_DECISION_AFTER_EVIDENCE_GENERATED:{index}")
            if row_generated is not None and row_generated > generated:
                reasons.append(f"OPPORTUNITY_SUPPLY_ROW_GENERATED_AFTER_EVIDENCE_GENERATED:{index}")

    expected_source_hash = _paper_canonical_sha256(
        _paper_strategy_mode_opportunity_supply_material(evidence)
    )
    if (
        not _paper_valid_sha256(evidence.get("source_hash"))
        or evidence.get("source_hash") != expected_source_hash
    ):
        reasons.append("OPPORTUNITY_SUPPLY_SOURCE_HASH_INVALID")
    return sorted(set(reasons))


def _paper_strategy_mode_beta_posterior(
    successes: int,
    total: int,
) -> dict[str, Any]:
    if total <= 0 or successes < 0 or successes > total:
        return {
            "successes": successes,
            "total": total,
            "posterior_mean": None,
            "posterior_standard_deviation": None,
            "posterior_lower_bound": None,
            "posterior_upper_bound": None,
        }
    alpha = successes + STRATEGY_MODE_COLLAPSE_POSTERIOR_PRIOR_ALPHA
    beta = total - successes + STRATEGY_MODE_COLLAPSE_POSTERIOR_PRIOR_BETA
    posterior_total = alpha + beta
    mean = alpha / posterior_total
    variance = (alpha * beta) / (posterior_total * posterior_total * (posterior_total + 1.0))
    standard_deviation = math.sqrt(max(0.0, variance))
    margin = STRATEGY_MODE_COLLAPSE_POSTERIOR_Z * standard_deviation
    return {
        "successes": successes,
        "total": total,
        "prior_alpha": STRATEGY_MODE_COLLAPSE_POSTERIOR_PRIOR_ALPHA,
        "prior_beta": STRATEGY_MODE_COLLAPSE_POSTERIOR_PRIOR_BETA,
        "credible_level_approx": 0.95,
        "credible_interval_method": "JEFFREYS_BETA_POSTERIOR_NORMAL_APPROXIMATION",
        "posterior_mean": mean,
        "posterior_standard_deviation": standard_deviation,
        "posterior_lower_bound": max(0.0, mean - margin),
        "posterior_upper_bound": min(1.0, mean + margin),
    }


def _paper_strategy_mode_collapse_guard(
    existing_ledger: dict[str, Any],
    candidate_mode: Any,
    *,
    opportunity_supply_evidence: Mapping[str, Any] | None = None,
    observed_at: Any | None = None,
) -> dict[str, Any]:
    mode = _normalized_strategy_mode(candidate_mode)
    closed_rows = _closed_trade_rows(existing_ledger)
    historical_counts = _strategy_mode_counts_for_rows(closed_rows)
    active_policy_rows = [
        row
        for row in closed_rows
        if str(row.get("paper_exit_policy_version") or "") == PAPER_EXIT_POLICY_VERSION
    ]
    active_policy_counts = _strategy_mode_counts_for_rows(active_policy_rows)
    active_policy_sample_ready = len(active_policy_rows) >= STRATEGY_MODE_COLLAPSE_MIN_CLOSED_TRADES
    counts = active_policy_counts if active_policy_sample_ready else historical_counts
    evidence_scope = (
        "active_policy"
        if active_policy_sample_ready
        else ("all_history_until_active_policy_min_sample" if active_policy_rows else "all_history")
    )
    total = sum(counts.values())
    top_mode = None
    top_count = 0
    if counts:
        top_mode, top_count = max(counts.items(), key=lambda item: item[1])
    top_share = (top_count / total) if total else None
    supply_rejection_reasons = _paper_strategy_mode_opportunity_supply_rejection_reasons(
        opportunity_supply_evidence,
        observed_at=observed_at,
    )
    supply_valid = not supply_rejection_reasons
    supplied_counts = (
        opportunity_supply_evidence.get("opportunity_mode_counts")
        if isinstance(opportunity_supply_evidence, Mapping)
        and isinstance(opportunity_supply_evidence.get("opportunity_mode_counts"), Mapping)
        else {}
    )
    opportunity_count = (
        int(opportunity_supply_evidence.get("opportunity_count"))
        if supply_valid and isinstance(opportunity_supply_evidence, Mapping)
        else 0
    )
    top_mode_opportunity_count = int(supplied_counts.get(top_mode, 0)) if top_mode else 0
    closed_posterior = _paper_strategy_mode_beta_posterior(top_count, total)
    opportunity_posterior = _paper_strategy_mode_beta_posterior(
        top_mode_opportunity_count,
        opportunity_count,
    )
    opportunity_upper_bound = _coerce_float(opportunity_posterior.get("posterior_upper_bound"))
    closed_lower_bound = _coerce_float(closed_posterior.get("posterior_lower_bound"))
    selected_ceiling = STRATEGY_MODE_COLLAPSE_MAJOR_MODE_SHARE
    credible_excess_concentration = False
    if supply_valid and opportunity_upper_bound is not None:
        selected_ceiling = min(
            STRATEGY_MODE_COLLAPSE_MAJOR_MODE_SHARE,
            max(0.0, opportunity_upper_bound),
        )
        credible_excess_concentration = (
            closed_lower_bound is not None and closed_lower_bound > opportunity_upper_bound
        )
    static_threshold_exceeded = (
        total >= STRATEGY_MODE_COLLAPSE_MIN_CLOSED_TRADES
        and top_share is not None
        and top_share >= STRATEGY_MODE_COLLAPSE_MAJOR_MODE_SHARE
    )
    adaptive_threshold_exceeded = (
        total >= STRATEGY_MODE_COLLAPSE_MIN_CLOSED_TRADES
        and top_share is not None
        and top_share >= selected_ceiling
    )
    collapsed = (
        adaptive_threshold_exceeded and credible_excess_concentration
        if supply_valid
        else static_threshold_exceeded
    )
    supply_payload = (
        opportunity_supply_evidence if isinstance(opportunity_supply_evidence, Mapping) else {}
    )
    status = {
        "schema_version": STRATEGY_MODE_COLLAPSE_ADAPTIVE_SCHEMA_VERSION,
        "adaptive_policy_version": STRATEGY_MODE_COLLAPSE_ADAPTIVE_POLICY_VERSION,
        "guard": STRATEGY_MODE_COLLAPSE_GUARD_NAME,
        "paper_only": True,
        "live_path_changed": False,
        "routes_to_exchange": False,
        "candidate_mode": mode,
        "allowed": True,
        "block_reason": None,
        "closed_trade_count": total,
        "mode_counts": counts,
        "top_mode": top_mode,
        "top_mode_count": top_count,
        "top_mode_share": top_share,
        "evidence_scope": evidence_scope,
        "policy_version": PAPER_EXIT_POLICY_VERSION,
        "policy_version_filter_enabled": active_policy_sample_ready,
        "unfiltered_closed_trade_count": len(closed_rows),
        "filtered_out_closed_trade_count": (
            len(closed_rows) - len(active_policy_rows) if active_policy_sample_ready else 0
        ),
        "historical_mode_counts": historical_counts,
        "active_policy_closed_trade_count": len(active_policy_rows),
        "active_policy_mode_counts": active_policy_counts,
        "active_policy_sample_ready": active_policy_sample_ready,
        "minimum_closed_trades": STRATEGY_MODE_COLLAPSE_MIN_CLOSED_TRADES,
        "major_mode_share_threshold": selected_ceiling,
        "static_max_major_mode_share_ceiling": (STRATEGY_MODE_COLLAPSE_MAJOR_MODE_SHARE),
        "selected_major_mode_share_ceiling": selected_ceiling,
        "adaptive_ceiling_never_above_static_max": (
            selected_ceiling <= STRATEGY_MODE_COLLAPSE_MAJOR_MODE_SHARE
        ),
        "adaptive_ceiling_tightened": (selected_ceiling < STRATEGY_MODE_COLLAPSE_MAJOR_MODE_SHARE),
        "static_major_mode_threshold_exceeded": static_threshold_exceeded,
        "adaptive_major_mode_threshold_exceeded": adaptive_threshold_exceeded,
        "credible_excess_concentration_required": True,
        "credible_excess_concentration": credible_excess_concentration,
        "closed_top_mode_posterior": closed_posterior,
        "opportunity_top_mode_posterior": opportunity_posterior,
        "opportunity_supply_status": (
            "PIT_EVIDENCE_VALID_ADAPTIVE" if supply_valid else "FALLBACK_CURRENT_POLICY"
        ),
        "opportunity_supply_fallback_to_current_policy": not supply_valid,
        "opportunity_supply_fallback_reasons": supply_rejection_reasons,
        "opportunity_supply_schema_version": supply_payload.get("schema_version"),
        "opportunity_supply_policy_version": supply_payload.get("policy_version"),
        "opportunity_supply_source_scope": supply_payload.get("source_scope"),
        "opportunity_supply_source_hash": supply_payload.get("source_hash"),
        "opportunity_supply_source_hash_contract": supply_payload.get("source_hash_contract"),
        "opportunity_supply_window_started_at": supply_payload.get("window_started_at"),
        "opportunity_supply_window_ended_at": supply_payload.get("window_ended_at"),
        "opportunity_supply_generated_at": supply_payload.get("generated_at"),
        "opportunity_supply_available_at": supply_payload.get("available_at"),
        "opportunity_supply_consumer_observed_at": observed_at,
        "opportunity_supply_expires_at": supply_payload.get("expires_at"),
        "opportunity_count": supply_payload.get("opportunity_count", 0),
        "opportunity_mode_counts": dict(supplied_counts),
        "opportunity_mode_shares": dict(
            supply_payload.get("opportunity_mode_shares")
            if isinstance(supply_payload.get("opportunity_mode_shares"), Mapping)
            else {}
        ),
        "top_mode_opportunity_count": top_mode_opportunity_count,
        "blocking_scope": "DOMINANT_MODE_CANDIDATE_ONLY",
        "minority_mode_force_enabled": False,
        "forced_trade": False,
        "strategy_mode_collapse_detected": collapsed,
    }
    if mode is None:
        status["allowed"] = False
        status["block_reason"] = "CANDIDATE_STRATEGY_MODE_MISSING"
    elif total < STRATEGY_MODE_COLLAPSE_MIN_CLOSED_TRADES:
        status["sample_status"] = "INSUFFICIENT_CLOSED_TRADE_SAMPLE"
    elif collapsed and mode == top_mode:
        status["allowed"] = False
        status["block_reason"] = STRATEGY_MODE_COLLAPSE_BLOCK_REASON
    status["receipt_hash_contract"] = "CANONICAL_JSON_SHA256_V1"
    status["receipt_hash"] = _paper_canonical_sha256(status)
    return status


def _paper_drawdown_recovery_confidence_policy(
    *,
    strategy_router: dict[str, Any],
    expected_move_after_cost_bps: float | None,
) -> dict[str, Any]:
    """Return a fail-closed contextual confidence floor for paper recovery fills."""
    explanation = strategy_router.get("explanation")
    explanation = explanation if isinstance(explanation, dict) else {}
    drawdown_bps = _coerce_float(
        _first_present(
            explanation.get("current_drawdown_bps"),
            explanation.get("portfolio_drawdown_bps"),
            strategy_router.get("current_drawdown_bps"),
        )
    )
    edge_bps = abs(float(expected_move_after_cost_bps or 0.0))
    drawdown_pressure = 0.0
    if drawdown_bps is not None:
        span = (
            PAPER_DRAWDOWN_RECOVERY_DRAWDOWN_TIGHTEN_FULL_BPS
            - PAPER_DRAWDOWN_RECOVERY_DRAWDOWN_TIGHTEN_START_BPS
        )
        if span > 0.0:
            drawdown_pressure = _clamp_float(
                (max(0.0, drawdown_bps) - PAPER_DRAWDOWN_RECOVERY_DRAWDOWN_TIGHTEN_START_BPS)
                / span,
                0.0,
                1.0,
            )
    weak_edge_pressure = _clamp_float(
        (PAPER_DRAWDOWN_RECOVERY_WEAK_EDGE_BPS - edge_bps) / PAPER_DRAWDOWN_RECOVERY_WEAK_EDGE_BPS,
        0.0,
        1.0,
    )
    dynamic_floor = _clamp_float(
        PAPER_DRAWDOWN_RECOVERY_MIN_CONFIDENCE
        + 0.12 * drawdown_pressure
        + 0.03 * weak_edge_pressure,
        PAPER_DRAWDOWN_RECOVERY_MIN_CONFIDENCE,
        PAPER_DRAWDOWN_RECOVERY_MAX_CONFIDENCE,
    )
    return {
        "threshold_id": "paper_drawdown_recovery_min_confidence",
        "mode": "DRAWDOWN_AND_EDGE_CONTEXTUAL_FAIL_CLOSED_NEVER_BELOW_STATIC",
        "static_floor": PAPER_DRAWDOWN_RECOVERY_MIN_CONFIDENCE,
        "dynamic_floor": round(dynamic_floor, 8),
        "operator_max_floor": PAPER_DRAWDOWN_RECOVERY_MAX_CONFIDENCE,
        "drawdown_bps": drawdown_bps,
        "drawdown_tighten_start_bps": PAPER_DRAWDOWN_RECOVERY_DRAWDOWN_TIGHTEN_START_BPS,
        "drawdown_tighten_full_bps": PAPER_DRAWDOWN_RECOVERY_DRAWDOWN_TIGHTEN_FULL_BPS,
        "weak_edge_bps": PAPER_DRAWDOWN_RECOVERY_WEAK_EDGE_BPS,
        "drawdown_pressure": round(drawdown_pressure, 8),
        "weak_edge_pressure": round(weak_edge_pressure, 8),
        "threshold_lowering_to_force_trades": False,
        "never_below_static": dynamic_floor >= PAPER_DRAWDOWN_RECOVERY_MIN_CONFIDENCE,
    }


def _paper_drawdown_recovery_router_result(
    *,
    existing_ledger: dict[str, Any],
    strategy_router: dict[str, Any],
    candidate_side: Any,
    current_position_state: str,
    paper_fill_allowed_upstream: bool,
    expected_move_after_cost_bps: float | None,
    confidence_calibrated: float | None,
    live_gate: str,
) -> tuple[dict[str, Any], dict[str, Any]]:
    """Paper-only recovery valve for minority-side audit evidence collection.

    The shared strategy router remains conservative under drawdown. This helper
    only affects the paper loop, only when the router block is exactly the
    drawdown limit, and only for a clean underrepresented side with no current
    open position for the symbol.
    """
    side = _normalized_directional_side(candidate_side)
    directional_guard = _paper_directional_collapse_guard(existing_ledger, side)
    current_state = str(current_position_state or "UNKNOWN").upper()
    reason_codes = {str(reason) for reason in strategy_router.get("reason_codes") or []}
    confidence_policy = _paper_drawdown_recovery_confidence_policy(
        strategy_router=strategy_router,
        expected_move_after_cost_bps=expected_move_after_cost_bps,
    )
    status: dict[str, Any] = {
        "guard": PAPER_DRAWDOWN_RECOVERY_GUARD_NAME,
        "paper_only": True,
        "candidate_side": side,
        "allowed": False,
        "recovered": False,
        "block_reason": None,
        "router_block_reason": strategy_router.get("block_reason"),
        "router_reason_codes": sorted(reason_codes),
        "current_position_state": current_state,
        "paper_fill_allowed_upstream": bool(paper_fill_allowed_upstream),
        "expected_move_after_cost_bps": expected_move_after_cost_bps,
        "confidence_calibrated": confidence_calibrated,
        "minimum_confidence": PAPER_DRAWDOWN_RECOVERY_MIN_CONFIDENCE,
        "maximum_confidence": PAPER_DRAWDOWN_RECOVERY_MAX_CONFIDENCE,
        "dynamic_minimum_confidence": confidence_policy["dynamic_floor"],
        "adaptive_confidence_policy": confidence_policy,
        "live_gate": live_gate,
        "directional_guard": directional_guard,
    }

    if strategy_router.get("block_reason") != "DRAWDOWN_LIMIT_BLOCK":
        status["block_reason"] = "ROUTER_BLOCK_NOT_DRAWDOWN_LIMIT"
        return strategy_router, status
    if "DRAWDOWN_LIMIT_BLOCK" not in reason_codes:
        status["block_reason"] = "DRAWDOWN_REASON_CODE_MISSING"
        return strategy_router, status
    if live_gate != LIVE_GATE_BLOCKED:
        status["block_reason"] = "LIVE_GATE_NOT_BLOCKED_FOR_PAPER_RECOVERY"
        return strategy_router, status
    if side not in {"long", "short"}:
        status["block_reason"] = "CANDIDATE_SIDE_INVALID"
        return strategy_router, status
    if current_state != "FLAT":
        status["block_reason"] = "CURRENT_POSITION_NOT_FLAT"
        return strategy_router, status
    if paper_fill_allowed_upstream is not True:
        status["block_reason"] = "UPSTREAM_PAPER_FILL_NOT_ALLOWED"
        return strategy_router, status
    if directional_guard.get("directional_collapse_detected") is not True:
        status["block_reason"] = "DIRECTIONAL_COLLAPSE_NOT_DETECTED"
        return strategy_router, status
    if side != directional_guard.get("minority_side"):
        status["block_reason"] = "CANDIDATE_NOT_MINORITY_SIDE"
        return strategy_router, status
    status["expected_move_after_cost_favorable_for_side"] = (
        expected_move_after_cost_favorable_for_side(
            side=side,
            expected_move_after_cost_bps=expected_move_after_cost_bps,
        )
    )
    if not status["expected_move_after_cost_favorable_for_side"]:
        status["block_reason"] = "EXPECTED_MOVE_AFTER_COST_NOT_FAVORABLE_FOR_SIDE"
        return strategy_router, status
    if confidence_calibrated is None or confidence_calibrated < confidence_policy["dynamic_floor"]:
        status["block_reason"] = "CONFIDENCE_BELOW_PAPER_RECOVERY_FLOOR"
        return strategy_router, status

    recovered = dict(strategy_router)
    recovered["selected_mode"] = "reduce_size_mode"
    recovered["block_reason"] = None
    recovered["size_multiplier"] = round(
        min(
            _coerce_float(strategy_router.get("size_multiplier")) or 1.0,
            PAPER_DRAWDOWN_RECOVERY_SIZE_MULTIPLIER,
        ),
        6,
    )
    action_mask = dict(recovered.get("action_mask") or {})
    action_mask.setdefault("hold", True)
    action_mask["long"] = side == "long"
    action_mask["short"] = side == "short"
    action_mask["close"] = False
    recovered["action_mask"] = action_mask
    recovered["allowed_actions"] = [name for name, allowed in action_mask.items() if allowed]
    recovered["reason_codes"] = sorted(reason_codes | {PAPER_DRAWDOWN_RECOVERY_REASON})
    recovered["regime_labels"] = sorted(
        {str(label) for label in recovered.get("regime_labels") or []} | {"paper_drawdown_recovery"}
    )
    explanation = dict(recovered.get("explanation") or {})
    explanation["paper_drawdown_recovery_guard"] = {
        "allowed": True,
        "guard": PAPER_DRAWDOWN_RECOVERY_GUARD_NAME,
        "reason": PAPER_DRAWDOWN_RECOVERY_REASON,
        "size_multiplier": recovered["size_multiplier"],
    }
    recovered["explanation"] = explanation
    status["allowed"] = True
    status["recovered"] = True
    status["recovery_reason"] = PAPER_DRAWDOWN_RECOVERY_REASON
    status["recovery_size_multiplier"] = recovered["size_multiplier"]
    return recovered, status


def _read_existing_ledger_payload(r) -> dict[str, Any]:
    payload: dict[str, Any] = {}
    if r is None:
        lifecycle_state = _read_lifecycle_state_file()
        if lifecycle_state:
            lifecycle_state["lifecycle_state_source"] = str(PAPER_LIFECYCLE_STATE_PATH)
        return lifecycle_state

    open_positions = _read_json_list_redis_key_if_small(
        r,
        f"{V2_REDIS_PREFIX}paper:positions",
    )
    if open_positions:
        payload["open_positions"] = open_positions
        payload["positions_by_symbol"] = {
            (
                f"{str(row['symbol']).upper()}::HEDGE"
                if row.get("hedge_parent_id")
                and str(row.get("hedge_state") or "").upper() == "HEDGE_CHILD"
                else str(row["symbol"]).upper()
            ): row
            for row in open_positions
            if isinstance(row, dict) and row.get("symbol")
        }
        payload["open_position_count"] = len(open_positions)

    closed_trades = _read_json_list_redis_key_if_small(
        r,
        f"{V2_REDIS_PREFIX}paper:closed_trades",
    )
    if closed_trades:
        payload["closed_trades"] = closed_trades
        payload["closes"] = closed_trades
        payload["closed_trade_count"] = len(closed_trades)

    outcome_labels = _read_json_list_redis_key_if_small(
        r,
        f"{V2_REDIS_PREFIX}paper:outcome_labels",
    )
    if outcome_labels:
        payload["outcome_labels"] = outcome_labels
        payload["outcome_label_count"] = len(outcome_labels)

    if not payload:
        redis_ledger = _read_json_redis_key_if_small(
            r,
            f"{V2_REDIS_PREFIX}paper:ledger",
        )
        if redis_ledger:
            payload = redis_ledger

    lifecycle_state = _read_lifecycle_state_file()
    if not lifecycle_state:
        lifecycle_skip = _state_file_skip_status(
            PAPER_LIFECYCLE_STATE_PATH,
            max_bytes=PAPER_STATE_FULL_FILE_READ_MAX_BYTES,
        )
        if lifecycle_skip:
            payload["lifecycle_state_file_skipped"] = lifecycle_skip
        if payload:
            payload.setdefault(
                "lifecycle_state_source",
                "v2:paper:positions+v2:paper:closed_trades+v2:paper:outcome_labels",
            )
        return payload
    merged = dict(payload)
    accepted_fills = lifecycle_state.get("accepted_fills")
    if isinstance(accepted_fills, list):
        merged["accepted"] = accepted_fills
        merged["accepted_intents"] = accepted_fills
        merged["accepted_count"] = len(accepted_fills)
        merged["accepted_fill_state_row_count"] = len(accepted_fills)
    for key in (
        "open_positions",
        "positions_by_symbol",
        "closed_trades",
        "closes",
        "outcome_labels",
        "trainer_feedback_outcomes",
        "trainer_feedback_outcomes_quarantine",
    ):
        value = lifecycle_state.get(key)
        if value in (None, ""):
            continue
        # CG-F044: Redis is the source of truth for close/label history; the
        # state file is a fallback for when Redis reads come back empty. A
        # test-contaminated or stale file replacing a successful non-empty
        # Redis read is exactly how 17 closed trades were destroyed on
        # 2026-07-08 (file carried 1 pytest fixture row; this loop overwrote
        # the 18-row Redis history with it).
        if key in ("closed_trades", "closes", "outcome_labels") and merged.get(key):
            continue
        merged[key] = value
    for source_key, count_key in (
        ("open_positions", "open_position_count"),
        ("closed_trades", "closed_trade_count"),
        ("outcome_labels", "outcome_label_count"),
        ("trainer_feedback_outcomes", "trainer_feedback_row_count"),
        ("trainer_feedback_outcomes_quarantine", "trainer_feedback_quarantined_row_count"),
    ):
        value = merged.get(source_key)
        if isinstance(value, list):
            merged[count_key] = len(value)
    merged["lifecycle_state_source"] = str(PAPER_LIFECYCLE_STATE_PATH)
    return merged


def _open_position_notional_usd(row: Mapping[str, Any]) -> float:
    for key in (
        "gross_notional_usd",
        "order_size_usd",
        "notional_usd",
        "target_notional_usd",
        "target_notional_usdt",
    ):
        value = _coerce_float(row.get(key))
        if value is not None:
            return max(0.0, abs(value))
    return 0.0


def _open_position_unrealized_pnl_usd(row: Mapping[str, Any]) -> float:
    for key in ("unrealized_pnl_usd", "unrealized_pnl_usdt"):
        value = _coerce_float(row.get(key))
        if value is not None:
            return value
    return 0.0


def _filter_symbol_rows(rows: Any, open_symbols: set[str]) -> list[Any]:
    if not isinstance(rows, list):
        return []
    if not open_symbols:
        return []
    return [
        row
        for row in rows
        if not isinstance(row, Mapping) or str(row.get("symbol") or "").upper() in open_symbols
    ]


def _sync_lifecycle_open_position_views(
    lifecycle_result: dict[str, Any],
    open_positions: list[dict[str, Any]],
) -> None:
    open_symbols = {
        str(row.get("symbol") or "").upper()
        for row in open_positions
        if isinstance(row, Mapping) and row.get("symbol")
    }
    lifecycle_result["open_positions"] = list(open_positions)
    lifecycle_result["positions_by_symbol"] = {
        str(row.get("symbol")).upper(): row
        for row in open_positions
        if isinstance(row, Mapping) and row.get("symbol")
    }
    lifecycle_result["open_position_count"] = len(open_positions)
    lifecycle_result["unrealized_pnl_usd"] = sum(
        _open_position_unrealized_pnl_usd(row) for row in open_positions
    )
    lifecycle_result["total_open_notional"] = sum(
        _open_position_notional_usd(row) for row in open_positions
    )

    lifecycle_status = dict(lifecycle_result.get("paper_position_lifecycle_status") or {})
    lifecycle_status["open_positions_count"] = len(open_positions)
    lifecycle_result["paper_position_lifecycle_status"] = lifecycle_status

    exposure_status = dict(lifecycle_result.get("paper_position_exposure_cap_status") or {})
    exposure_status["evaluations"] = _filter_symbol_rows(
        exposure_status.get("evaluations"),
        open_symbols,
    )
    exposure_status["blocked_count"] = sum(
        1
        for row in exposure_status["evaluations"]
        if isinstance(row, Mapping) and row.get("allowed") is False
    )
    lifecycle_result["paper_position_exposure_cap_status"] = exposure_status

    hedge_status = dict(lifecycle_result.get("paper_hedge_netting_status") or {})
    hedge_status["events"] = _filter_symbol_rows(hedge_status.get("events"), open_symbols)
    lifecycle_result["paper_hedge_netting_status"] = hedge_status

    exit_status = dict(lifecycle_result.get("paper_exit_coordinator_status") or {})
    exit_status["evaluations"] = _filter_symbol_rows(
        exit_status.get("evaluations"),
        open_symbols,
    )
    lifecycle_result["paper_exit_coordinator_status"] = exit_status

    trailing_status = dict(lifecycle_result.get("paper_stop_takeprofit_trailing_status") or {})
    trailing_context_policy = dict(trailing_status.get("trailing_stop_context_policy") or {})
    trailing_context_policy["position_decisions"] = _filter_symbol_rows(
        trailing_context_policy.get("position_decisions"),
        open_symbols,
    )
    trailing_status["trailing_stop_context_policy"] = trailing_context_policy
    lifecycle_result["paper_stop_takeprofit_trailing_status"] = trailing_status


def _read_portfolio_state(r) -> dict[str, Any]:
    payload = _read_json_key(r, f"{V2_REDIS_PREFIX}portfolio:state")
    return payload if isinstance(payload, dict) else {}


def _portfolio_equity_context(
    r,
    *,
    existing_ledger: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    portfolio = _read_portfolio_state(r)
    equity = _coerce_float(
        _first_present(portfolio.get("equity"), portfolio.get("current_session_equity"))
    )
    cash = _coerce_float(portfolio.get("cash_balance"))
    wallet = _coerce_float(
        _first_present(
            portfolio.get("wallet_balance"),
            cash,
            portfolio.get("initial_capital"),
            equity,
        )
    )
    # A reported zero/negative balance is account truth, not missing data.  In
    # particular, replacing depleted equity with initial capital resurrects
    # buying power after the account has exhausted it.  Fallback is permitted
    # only when the field is absent or non-numeric; canonical margin accounting
    # then fails closed on any preserved non-positive value.
    if equity is None:
        equity = _coerce_float(portfolio.get("initial_capital")) or 0.0
    if cash is None:
        cash = equity
    if wallet is None:
        wallet = equity
    ledger = existing_ledger if isinstance(existing_ledger, Mapping) else {}
    open_positions_value = ledger.get("open_positions")
    if not isinstance(open_positions_value, list):
        open_positions_value = ledger.get("positions")
    if not isinstance(open_positions_value, list):
        positions_by_symbol = ledger.get("positions_by_symbol")
        open_positions_value = (
            list(positions_by_symbol.values()) if isinstance(positions_by_symbol, Mapping) else []
        )
    # Preserve malformed collection members for the canonical accounting
    # boundary. Dropping them here would turn unknown existing exposure into
    # spendable buying power while the downstream module is specifically able
    # to represent those rows as fail-closed evidence.
    open_positions = list(open_positions_value)
    margin_status = build_paper_margin_status(
        equity=equity,
        wallet_balance=wallet,
        open_positions=open_positions,
    )
    # An unaccountable existing position must not silently become buying
    # power.  The reservation gate will surface the exact invalid rows.
    available_margin = (
        float(margin_status["free_margin_usd"])
        if margin_status["accounting_complete"] is True
        else 0.0
    )
    return {
        "equity": float(equity or 0.0),
        "available_margin": available_margin,
        "free_margin_usd": available_margin,
        "used_margin_usd": float(margin_status["used_margin_usd"]),
        "wallet_balance": float(wallet or 0.0),
        "drawdown_bps": abs(_coerce_float(portfolio.get("current_drawdown_bps")) or 0.0),
        "paper_account_margin_status": margin_status,
        "paper_ledger_open_position_count": len(open_positions),
        "portfolio_state_present": bool(portfolio),
        "portfolio_state_event_time": portfolio.get("event_time"),
        "portfolio_state_generated_at": _first_present(
            portfolio.get("generated_at"),
            portfolio.get("generated_utc"),
        ),
        "portfolio_state_available_at": _first_present(
            portfolio.get("available_at"),
            portfolio.get("source_available_at"),
        ),
        "portfolio_context_observed_at": _utc_iso(),
    }


EXIT_OVERSHOOT_ESTIMATE_REDIS_KEY = f"{V2_REDIS_PREFIX}paper:exit_overshoot_estimate"
_EXIT_OVERSHOOT_MAX_SAMPLE = 20

# Adaptive hedging (paper-only). Dangerous-setting rule: default OFF; the
# operator enables via environment (systemd drop-in) after explicit approval.
# Operator approval recorded 2026-07-16: hedge adverse moves instead of
# eating full ATR stop-outs; hedging preferred over closing losses.
PAPER_ADAPTIVE_HEDGE_ENABLED = str(
    os.environ.get("PAPER_ADAPTIVE_HEDGE_ENABLED", "")
).strip().lower() in ("1", "true", "yes", "on")
# Runtime safety interlock: the current deferred hedge implementation does not
# have atomic fill/margin reservation, exact parent-generation identity, or an
# independent canonical hedge decision. It can also defer an already-hit stop.
# Operator intent remains visible, but execution stays disabled until all four
# invariants are implemented and tested together.
PAPER_ADAPTIVE_HEDGE_RUNTIME_SAFETY_INTERLOCK = True
PAPER_ADAPTIVE_HEDGE_ATOMIC_FINAL_ADMISSION_IMPLEMENTED = False
PAPER_ADAPTIVE_HEDGE_RUNTIME_SAFETY_BLOCK_REASON = (
    "HEDGE_DISABLED_NO_ATOMIC_FUNDED_EXACT_LINEAGE_EXECUTION_PROOF"
)
# Redis operator flag so EVERY run_once caller agrees on hedge semantics.
# Shadow/soak tools (production-equivalence comparator, war-room scheduler)
# import this module and call run_once without the service env; if they ran
# with hedging disabled against the shared paper state they would net-close
# open hedge pairs through the TIER_3 netting path. env OR redis enables.
ADAPTIVE_HEDGE_ENABLED_REDIS_KEY = f"{V2_REDIS_PREFIX}paper:adaptive_hedge_enabled"
HEDGE_DIRECTIVES_REDIS_KEY = f"{V2_REDIS_PREFIX}paper:hedge_directives"
HEDGE_DIRECTIVES_MAX_AGE_SECONDS = 300.0

# Operator directive (2026-07-16): majors are processed first each cycle so
# admission budget/exposure caps prefer them; NOT an exclusion list — the
# full adaptive symbol universe still trades, and any gate may still block a
# major (that is the system deciding not to).
PAPER_PREFERRED_MAJOR_SYMBOLS = frozenset({"BTCUSDT", "ETHUSDT", "SOLUSDT"})


def _adaptive_hedge_enabled(r) -> bool:
    if (
        PAPER_ADAPTIVE_HEDGE_RUNTIME_SAFETY_INTERLOCK
        or not PAPER_ADAPTIVE_HEDGE_ATOMIC_FINAL_ADMISSION_IMPLEMENTED
    ):
        return False
    if PAPER_ADAPTIVE_HEDGE_ENABLED:
        return True
    if r is None:
        return False
    try:
        raw = r.get(ADAPTIVE_HEDGE_ENABLED_REDIS_KEY)
    except Exception:
        return False
    if isinstance(raw, bytes):
        raw = raw.decode("utf-8", "replace")
    return str(raw or "").strip().lower() in ("1", "true", "yes", "on")


def _synthesize_adaptive_hedge_fills(
    r,
    *,
    existing_ledger: dict[str, Any],
    existing_accepted: list[dict[str, Any]],
    accepted: list[dict[str, Any]],
    paper_session_id: str | None,
    starting_equity_usd: float | None,
) -> dict[str, Any]:
    """Turn prior-cycle hedge directives into tagged paper hedge fills.

    The hedge fill is a copy of the parent's persisted entry fill (which
    guarantees the classify_fill lineage contract: prediction_id,
    risk_decision_id, orchestrator_decision_id) with side flipped, quantity
    scaled by the adaptive hedge_ratio, and hedge pair tags set. It rides the
    normal accepted-fills pipeline; the lifecycle routes it to a
    "{SYM}::HEDGE" position instead of netting the parent closed.
    """
    status: dict[str, Any] = {
        "enabled": False,
        "synthesized": 0,
        "skipped": [],
        "paper_only": True,
        "places_real_order": False,
    }
    if (
        PAPER_ADAPTIVE_HEDGE_RUNTIME_SAFETY_INTERLOCK
        or not PAPER_ADAPTIVE_HEDGE_ATOMIC_FINAL_ADMISSION_IMPLEMENTED
    ):
        status["reason"] = PAPER_ADAPTIVE_HEDGE_RUNTIME_SAFETY_BLOCK_REASON
        status["final_admission_contract_required"] = True
        return status
    status["enabled"] = True
    payload = _read_json_any_key(r, HEDGE_DIRECTIVES_REDIS_KEY)
    if not isinstance(payload, dict):
        status["reason"] = "NO_PENDING_HEDGE_DIRECTIVES"
        return status
    directives = payload.get("directives")
    if not isinstance(directives, list) or not directives:
        status["reason"] = "NO_PENDING_HEDGE_DIRECTIVES"
        return status
    generated_utc = str(payload.get("generated_utc") or "")
    age_seconds = _seconds_since_iso(generated_utc)
    if age_seconds is None or age_seconds > HEDGE_DIRECTIVES_MAX_AGE_SECONDS:
        status["reason"] = "HEDGE_DIRECTIVES_STALE"
        status["directive_age_seconds"] = age_seconds
        try:
            r.delete(HEDGE_DIRECTIVES_REDIS_KEY)
        except Exception:
            pass
        return status
    positions_by_symbol = (
        existing_ledger.get("positions_by_symbol")
        if isinstance(existing_ledger.get("positions_by_symbol"), dict)
        else {}
    )
    accepted_by_identity = {
        _accepted_fill_identity(row): row for row in existing_accepted if isinstance(row, dict)
    }
    for directive in directives:
        if not isinstance(directive, dict):
            continue
        symbol = str(directive.get("symbol") or "").upper()
        parent_position_id = str(directive.get("parent_position_id") or "")
        hedge_side = str(directive.get("hedge_side") or "").lower()
        hedge_quantity = _coerce_float(directive.get("hedge_quantity"))
        mark_price = _coerce_float(directive.get("mark_price"))
        if (
            not symbol
            or hedge_side not in ("long", "short")
            or not hedge_quantity
            or hedge_quantity <= 0
        ):
            status["skipped"].append({"symbol": symbol, "reason": "DIRECTIVE_FIELDS_INVALID"})
            continue
        if symbol not in positions_by_symbol:
            status["skipped"].append({"symbol": symbol, "reason": "PARENT_POSITION_NO_LONGER_OPEN"})
            continue
        if f"{symbol}::HEDGE" in positions_by_symbol:
            status["skipped"].append({"symbol": symbol, "reason": "HEDGE_ALREADY_OPEN"})
            continue
        parent_fill = accepted_by_identity.get(str(directive.get("parent_entry_fill_id") or ""))
        if parent_fill is None:
            parent_fill = next(
                (
                    row
                    for row in existing_accepted
                    if isinstance(row, dict)
                    and str(row.get("symbol") or "").upper() == symbol
                    and row.get("hedge_intent") is not True
                ),
                None,
            )
        if parent_fill is None:
            status["skipped"].append({"symbol": symbol, "reason": "PARENT_ENTRY_FILL_NOT_FOUND"})
            continue
        if mark_price is None or mark_price <= 0:
            mark_price, _px_source, _px_utc = _read_v2_market_price(r, symbol)
        if mark_price is None or mark_price <= 0:
            status["skipped"].append({"symbol": symbol, "reason": "HEDGE_MARK_PRICE_UNAVAILABLE"})
            continue
        directive_ts = str(directive.get("generated_utc") or generated_utc)
        hedge_fill_id = f"{parent_position_id}:hedge:{directive_ts}"
        hedge_notional = abs(hedge_quantity * mark_price)
        hedge_fill = dict(parent_fill)
        hedge_fill.update(
            {
                "fill_id": hedge_fill_id,
                "intent_id": hedge_fill_id,
                "side": hedge_side,
                "selected_action": hedge_side,
                "quantity": hedge_quantity,
                "fill_price": mark_price,
                "price": mark_price,
                "notional": hedge_notional,
                "notional_usd": hedge_notional,
                "hedge_intent": True,
                "hedge_parent_id": parent_position_id,
                "hedge_child_id": hedge_fill_id,
                "hedge_ratio": _coerce_float(directive.get("hedge_ratio")),
                "hedge_state": "HEDGE_CHILD",
                "hedge_reason": str(directive.get("reason") or "ADAPTIVE_ADVERSE_EXCURSION_HEDGE"),
                "hedge_entry_parent_pnl_bps": _coerce_float(
                    directive.get("parent_pnl_bps_at_trigger")
                ),
                "hedge_budget_usd": hedge_notional,
                "unwind_plan": "adaptive_exhaustion_or_parent_recovery",
                "decision": "ACCEPTED_PAPER_FILL",
                "paper_fill_allowed": True,
                "paper_hedge_fill": True,
                "paper_fast_path": False,
                "generated_utc": _utc_iso(),
                "paper_only": True,
                "places_real_order": False,
                "routes_to_live": False,
            }
        )
        hedge_fill = _with_paper_session_metadata(
            hedge_fill,
            paper_session_id=paper_session_id,
            starting_equity_usd=starting_equity_usd,
        )
        accepted.append(hedge_fill)
        status["synthesized"] += 1
    try:
        r.delete(HEDGE_DIRECTIVES_REDIS_KEY)
    except Exception:
        pass
    return status


def _ensure_margin_leverage_consistency_rows(
    rows: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    """Normalize paper fill capital fields from executed quantity and price.

    The executed notional is authoritative. Positive upstream margin or
    notional values are retained under ``*_upstream`` when they disagree,
    but they cannot remain authoritative because that creates impossible
    leverage/liquidation state in the ledger and trainer feedback.
    """
    for row in rows:
        if not isinstance(row, dict):
            continue
        quantity = _coerce_float(row.get("quantity"))
        price = _coerce_float(
            _first_present(
                row.get("fill_price"),
                row.get("entry_price"),
                row.get("mark_price_at_fill"),
                row.get("price"),
            )
        )
        reported_notional = _coerce_float(
            _first_present(
                row.get("notional"),
                row.get("notional_usdt"),
                row.get("notional_usd"),
                row.get("gross_notional_usd"),
            )
        )
        notional = (
            abs(quantity * price)
            if quantity is not None and quantity != 0.0 and price is not None and price > 0.0
            else reported_notional
        )
        if notional is None or notional <= 0:
            continue
        notional = round(notional, 8)
        allocation = row.get("adaptive_allocation")
        allocation = allocation if isinstance(allocation, dict) else {}
        model_inputs = allocation.get("model_inputs")
        model_inputs = model_inputs if isinstance(model_inputs, dict) else {}
        risk_envelope = model_inputs.get("risk_envelope")
        risk_envelope = risk_envelope if isinstance(risk_envelope, dict) else {}
        current_capital = row.get("current_capital_accounting")
        current_capital = dict(current_capital) if isinstance(current_capital, dict) else {}

        row_effective = _coerce_float(row.get("effective_leverage"))
        allocation_effective = _coerce_float(allocation.get("effective_leverage"))
        leverage_cap = _coerce_float(
            _first_present(
                current_capital.get("decision_time_max_effective_leverage"),
                risk_envelope.get("max_effective_leverage"),
                row.get("decision_time_max_effective_leverage"),
            )
        )
        leverage = 1.0
        leverage_source = "FAIL_SAFE_DEFAULT_1X_UNVALIDATED_OR_MISSING"
        leverage_invalid_reason = None
        if (
            row_effective is not None
            and allocation_effective is not None
            and not math.isclose(
                row_effective,
                allocation_effective,
                rel_tol=1e-9,
                abs_tol=1e-9,
            )
        ):
            leverage_invalid_reason = "EFFECTIVE_LEVERAGE_ALLOCATION_MISMATCH"
        elif allocation_effective is not None:
            if allocation_effective < 1.0:
                leverage_invalid_reason = "EFFECTIVE_LEVERAGE_INVALID"
            elif leverage_cap is None or leverage_cap < 1.0:
                leverage_source = "FAIL_SAFE_DEFAULT_1X_MISSING_DECISION_TIME_CAP"
            elif allocation_effective > leverage_cap + 1e-9:
                leverage_invalid_reason = "EFFECTIVE_LEVERAGE_EXCEEDS_DECISION_TIME_ENVELOPE"
            else:
                leverage = float(allocation_effective)
                leverage_source = "VALIDATED_ADAPTIVE_ALLOCATION_EFFECTIVE_LEVERAGE"
        elif (
            current_capital.get("accounting_scope")
            in {"CURRENT_EXECUTED_PAPER_POSITION", "CURRENT_EXECUTED_PAPER_FILL"}
            and current_capital.get("effective_leverage_validated") is True
        ):
            current_effective = _coerce_float(current_capital.get("effective_leverage"))
            if current_effective is None or current_effective < 1.0:
                leverage_invalid_reason = "EFFECTIVE_LEVERAGE_INVALID"
            elif leverage_cap is not None and current_effective > leverage_cap + 1e-9:
                leverage_invalid_reason = "EFFECTIVE_LEVERAGE_EXCEEDS_DECISION_TIME_ENVELOPE"
            else:
                leverage = float(current_effective)
                leverage_source = "VALIDATED_CURRENT_CAPITAL_EFFECTIVE_LEVERAGE"
        margin = round(notional / leverage, 8)
        existing_margin = _coerce_float(row.get("allocated_margin_usd"))
        existing_gross = _coerce_float(row.get("gross_notional_usd"))
        tolerance = max(0.01, notional * 1e-6)
        if existing_margin is not None and abs(existing_margin - margin) > tolerance:
            row.setdefault("allocated_margin_usd_upstream", existing_margin)
            row["paper_margin_accounting_normalized"] = True
        if existing_gross is not None and abs(existing_gross - notional) > tolerance:
            row.setdefault("gross_notional_usd_upstream", existing_gross)
            row["paper_notional_accounting_normalized"] = True
        for field in ("notional", "notional_usdt", "notional_usd", "gross_notional_usd"):
            if field in row or field in {"notional", "gross_notional_usd"}:
                row[field] = notional
        row["allocated_margin_usd"] = margin
        row["allocated_margin_source"] = (
            "EXECUTED_QUANTITY_TIMES_PRICE_OVER_EFFECTIVE_LEVERAGE"
            if quantity is not None and price is not None
            else "REPORTED_NOTIONAL_OVER_EFFECTIVE_LEVERAGE"
        )
        row["effective_leverage"] = leverage
        row["effective_leverage_validated"] = leverage_invalid_reason is None
        row["effective_leverage_source"] = leverage_source
        row["decision_time_max_effective_leverage"] = leverage_cap
        if leverage_invalid_reason is not None:
            row["paper_margin_accounting_invalid_reason"] = leverage_invalid_reason
        if row.get("margin_mode_simulated") in (None, ""):
            row["margin_mode_simulated"] = "isolated_paper_simulated"

        maintenance_rate = None
        maintenance_rate_source = None
        for source, value in (
            (
                "CURRENT_CAPITAL_MAINTENANCE_MARGIN_RATE",
                current_capital.get("maintenance_margin_rate"),
            ),
            ("POSITION_MAINTENANCE_MARGIN_RATE", row.get("maintenance_margin_rate")),
            (
                "ALLOCATION_MODEL_INPUT_MAINTENANCE_MARGIN_RATE",
                model_inputs.get("maintenance_margin_rate"),
            ),
            (
                "ALLOCATION_MAINTENANCE_MARGIN_RATE",
                allocation.get("maintenance_margin_rate"),
            ),
        ):
            candidate_rate = _coerce_float(value)
            if candidate_rate is not None and 0.0 < candidate_rate < 1.0:
                maintenance_rate = float(candidate_rate)
                maintenance_rate_source = source
                break
        row["maintenance_margin_rate"] = maintenance_rate
        row["maintenance_margin_rate_source"] = maintenance_rate_source
        row["maintenance_margin_estimate"] = (
            round(notional * maintenance_rate, 8) if maintenance_rate is not None else None
        )
        side = str(row.get("side") or "").lower()
        if (
            maintenance_rate is not None
            and leverage_invalid_reason is None
            and price is not None
            and price > 0.0
            and side in {"long", "short"}
        ):
            liquidation_geometry = paper_isolated_liquidation_geometry(
                side=side,
                entry_price=price,
                leverage=leverage,
                maintenance_margin_rate=maintenance_rate,
            )
            if liquidation_geometry is not None:
                liquidation_buffer_bps, liquidation_price = liquidation_geometry
                row["liquidation_price_estimate"] = round(
                    liquidation_price,
                    12,
                )
                row["liquidation_buffer_bps"] = round(
                    liquidation_buffer_bps,
                    8,
                )
                row["paper_liquidation_validation_status"] = "AVAILABLE_FROM_SIDE_AWARE_EVIDENCE"
            else:
                row["liquidation_price_estimate"] = None
                row["liquidation_buffer_bps"] = None
                row["paper_liquidation_validation_status"] = (
                    "UNAVAILABLE_LIQUIDATION_GEOMETRY_INVALID"
                )
        else:
            for field in ("liquidation_price_estimate", "liquidation_buffer_bps"):
                upstream = _coerce_float(row.get(field))
                if upstream is not None:
                    row.setdefault(f"{field}_upstream", upstream)
                row[field] = None
            row["paper_liquidation_validation_status"] = (
                "UNAVAILABLE_MAINTENANCE_MARGIN_EVIDENCE_MISSING"
                if maintenance_rate is None
                else "UNAVAILABLE_EFFECTIVE_LEVERAGE_INVALID"
            )
            if maintenance_rate is None:
                row.setdefault(
                    "paper_margin_accounting_invalid_reason",
                    "MAINTENANCE_MARGIN_RATE_MISSING_OR_INVALID",
                )

        current_capital.update(
            {
                "gross_notional_usd": notional,
                "allocated_margin_usd": margin,
                "effective_leverage": leverage,
                "effective_leverage_validated": leverage_invalid_reason is None,
                "effective_leverage_source": leverage_source,
                "decision_time_max_effective_leverage": leverage_cap,
                "maintenance_margin_rate": maintenance_rate,
                "maintenance_margin_rate_source": maintenance_rate_source,
                "maintenance_margin_estimate": row["maintenance_margin_estimate"],
                "liquidation_price_estimate": row.get("liquidation_price_estimate"),
                "liquidation_buffer_bps": row.get("liquidation_buffer_bps"),
                "execution_notional_validated": (
                    quantity is not None and quantity != 0.0 and price is not None and price > 0.0
                ),
                "accounting_scope": "CURRENT_EXECUTED_PAPER_FILL",
                "paper_margin_accounting_valid": (
                    row.get("paper_margin_accounting_invalid_reason") in (None, "")
                ),
            }
        )
        row["current_capital_accounting"] = current_capital
    return rows


def _seconds_since_iso(value: str) -> float | None:
    if not value:
        return None
    try:
        parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
    except (TypeError, ValueError):
        return None
    return max(0.0, (datetime.now(timezone.utc) - parsed).total_seconds())


def _paper_exit_overshoot_premium_bps(r, existing_ledger: dict[str, Any]) -> float | None:
    """Rolling median of (|realized gross pnl_bps| - atr_stop_bps) over recent
    TIER_1 ATR stop closes.

    The 60s cycle overshoots the nominal stop by an observed 1.5-46bps; the
    premium feeds both the exit engine (wider enforced stop) and the allocator
    (wider sizing stop) so sized risk equals realized risk. Returns None until
    post-fix closes carrying atr_stop_bps telemetry accumulate (cold start).
    """
    rows = existing_ledger.get("closed_trades") if isinstance(existing_ledger, dict) else None
    if not isinstance(rows, list):
        return None
    samples: list[float] = []
    for row in reversed(rows):
        if not isinstance(row, dict):
            continue
        if (
            str(row.get("exit_reason") or row.get("close_reason") or "")
            != "TIER_1_ATR_VOLATILITY_STOP"
        ):
            continue
        stop_bps = _coerce_float(row.get("atr_stop_bps"))
        pnl_bps = _coerce_float(
            _first_present(row.get("realized_gross_pnl_bps"), row.get("realized_pnl_bps"))
        )
        if stop_bps is None or stop_bps <= 0 or pnl_bps is None:
            continue
        samples.append(max(0.0, abs(pnl_bps) - stop_bps))
        if len(samples) >= _EXIT_OVERSHOOT_MAX_SAMPLE:
            break
    if len(samples) < 2:
        return None
    samples.sort()
    mid = len(samples) // 2
    median = samples[mid] if len(samples) % 2 else (samples[mid - 1] + samples[mid]) / 2.0
    premium = round(float(median), 4)
    if r is not None:
        try:
            r.set(
                EXIT_OVERSHOOT_ESTIMATE_REDIS_KEY,
                json.dumps(
                    {
                        "generated_utc": _utc_iso(),
                        "exit_overshoot_premium_bps": premium,
                        "sample_size": len(samples),
                        "source": "rolling_median_tier1_atr_stop_closes",
                        "paper_only": True,
                    }
                ),
                ex=PAPER_RUNTIME_TRANSIENT_TTL_SECONDS,
            )
        except Exception:
            pass
    return premium


def _open_exposures_from_ledger(ledger: dict[str, Any]) -> tuple[dict[str, float], float]:
    symbol_exposures: dict[str, float] = {}
    total = 0.0
    for row in ledger.get("open_positions") or ledger.get("positions") or []:
        if not isinstance(row, dict):
            continue
        symbol = str(row.get("symbol") or "").upper()
        notional = _coerce_float(
            _first_present(row.get("notional"), row.get("gross_notional"), row.get("notional_usdt"))
        )
        if not symbol or notional is None:
            continue
        symbol_exposures[symbol] = symbol_exposures.get(symbol, 0.0) + abs(notional)
        total += abs(notional)
    return symbol_exposures, total


def _paper_open_position_rows(ledger: Mapping[str, Any]) -> list[Mapping[str, Any]]:
    rows = ledger.get("open_positions")
    if not isinstance(rows, list):
        rows = ledger.get("positions")
    if isinstance(rows, list):
        return [row for row in rows if isinstance(row, Mapping)]
    positions_by_symbol = ledger.get("positions_by_symbol")
    if isinstance(positions_by_symbol, Mapping):
        return [row for row in positions_by_symbol.values() if isinstance(row, Mapping)]
    return []


def _paper_accepted_fill_proof_source(r: Any) -> dict[str, Any]:
    """Read the canonical durable fill proofs used by open-position joins.

    Open-position payloads intentionally contain compact lifecycle state, not
    the complete final-admission seal.  The accepted-fill key is therefore a
    separate required proof source whenever an open position exists.  This
    reader never falls back to reconstructed position rows because doing so
    would turn missing proof into apparently valid proof.
    """

    observed_at = _utc_iso()
    redis_key = f"{V2_REDIS_PREFIX}paper:accepted_fills"
    base = {
        "schema_version": "paper_accepted_fill_proof_source_v1",
        "redis_key": redis_key,
        "observed_at": observed_at,
        "paper_only": True,
        "routes_to_live": False,
        "places_real_order": False,
    }
    if r is None:
        material = {
            **base,
            "status": "BLOCKED",
            "row_count": 0,
            "payload_hash": _paper_canonical_sha256([]),
            "rejection_reasons": ["ACCEPTED_FILL_PROOF_REDIS_UNAVAILABLE"],
        }
        return {**material, "source_hash": _paper_canonical_sha256(material), "rows": []}
    try:
        raw_size = _redis_string_length(r, redis_key)
    except Exception:
        raw_size = None
    if raw_size is not None and raw_size > PAPER_REDIS_HISTORY_READ_MAX_BYTES:
        material = {
            **base,
            "status": "BLOCKED",
            "raw_size_bytes": raw_size,
            "row_count": 0,
            "payload_hash": _paper_canonical_sha256([]),
            "rejection_reasons": ["ACCEPTED_FILL_PROOF_PAYLOAD_TOO_LARGE"],
        }
        return {**material, "source_hash": _paper_canonical_sha256(material), "rows": []}
    try:
        raw = r.get(redis_key)
    except Exception:
        material = {
            **base,
            "status": "BLOCKED",
            "raw_size_bytes": raw_size,
            "row_count": 0,
            "payload_hash": _paper_canonical_sha256([]),
            "rejection_reasons": ["ACCEPTED_FILL_PROOF_READ_FAILED"],
        }
        return {**material, "source_hash": _paper_canonical_sha256(material), "rows": []}
    if raw in (None, b"", ""):
        material = {
            **base,
            "status": "MISSING",
            "raw_size_bytes": 0 if raw_size is None else raw_size,
            "row_count": 0,
            "payload_hash": _paper_canonical_sha256([]),
            "rejection_reasons": ["ACCEPTED_FILL_PROOF_PAYLOAD_MISSING"],
        }
        return {**material, "source_hash": _paper_canonical_sha256(material), "rows": []}
    try:
        payload = json.loads(raw)
    except (TypeError, ValueError, UnicodeDecodeError):
        payload = None
    if not isinstance(payload, list) or not all(isinstance(row, Mapping) for row in payload):
        material = {
            **base,
            "status": "BLOCKED",
            "raw_size_bytes": raw_size,
            "row_count": 0,
            "payload_hash": _paper_canonical_sha256(payload),
            "rejection_reasons": ["ACCEPTED_FILL_PROOF_PAYLOAD_INVALID"],
        }
        return {**material, "source_hash": _paper_canonical_sha256(material), "rows": []}
    rows = [dict(row) for row in payload]
    material = {
        **base,
        "status": "READY",
        "raw_size_bytes": raw_size,
        "row_count": len(rows),
        "payload_hash": _paper_canonical_sha256(rows),
        "rejection_reasons": [],
    }
    return {**material, "source_hash": _paper_canonical_sha256(material), "rows": rows}


def _paper_nonunderstating_decimal_float(value: Decimal) -> float:
    """Serialize a nonnegative Decimal without rounding the resource down."""

    result = float(value)
    if not math.isfinite(result) or result < 0.0:
        raise ValueError("PAPER_RESOURCE_DECIMAL_NOT_SERIALIZABLE")
    while Decimal(str(result)) < value:
        result = math.nextafter(result, math.inf)
        if not math.isfinite(result):
            raise ValueError("PAPER_RESOURCE_DECIMAL_NOT_SERIALIZABLE")
    return 0.0 if result == 0.0 else result


def _paper_exact_positive_decimal_aliases(left: Any, right: Any) -> Decimal | None:
    """Return the exact positive resource only when both aliases are equal."""

    if isinstance(left, bool) or isinstance(right, bool):
        return None
    try:
        left_value = Decimal(str(left))
        right_value = Decimal(str(right))
    except (InvalidOperation, TypeError, ValueError):
        return None
    if (
        not left_value.is_finite()
        or not right_value.is_finite()
        or left_value <= 0
        or left_value != right_value
    ):
        return None
    return left_value


def _paper_precycle_current_mark_exposure_snapshot(
    r: Any,
    *,
    ledger: Mapping[str, Any],
    ledger_observed_at: str,
    accepted_fill_proof_source: Mapping[str, Any],
) -> dict[str, Any]:
    """Seal current-mark exposure and open-position stress before allocation.

    Entry notionals are historical and cannot govern current exposure. Every
    open quantity is therefore revalued with one fresh, source-hashed mark per
    symbol. Projected loss requires equal positive aliases from the sealed
    allocator payload and a valid v3 final-admission binding. Legacy or
    unsealed open rows block new entries while exits remain available.
    """

    snapshot_started_at = _utc_iso()
    rows = _paper_open_position_rows(ledger)
    mark_cache: dict[str, dict[str, Any]] = {}
    row_projections: list[dict[str, Any]] = []
    rejection_reasons: list[str] = []
    identities: set[str] = set()
    consumed_source_fill_ids: set[str] = set()

    proof_source_rows = accepted_fill_proof_source.get("rows")
    proof_source_rows = proof_source_rows if isinstance(proof_source_rows, list) else []
    proof_source_projection = {
        field: accepted_fill_proof_source.get(field)
        for field in (
            "schema_version",
            "redis_key",
            "status",
            "observed_at",
            "raw_size_bytes",
            "row_count",
            "payload_hash",
            "source_hash",
            "rejection_reasons",
            "paper_only",
            "routes_to_live",
            "places_real_order",
        )
    }
    proof_source_material = dict(proof_source_projection)
    proof_source_hash = proof_source_material.pop("source_hash", None)
    proof_source_ready = bool(
        accepted_fill_proof_source.get("status") == "READY"
        and accepted_fill_proof_source.get("rejection_reasons") == []
        and accepted_fill_proof_source.get("row_count") == len(proof_source_rows)
        and _paper_valid_sha256(accepted_fill_proof_source.get("payload_hash"))
        and accepted_fill_proof_source.get("payload_hash")
        == _paper_canonical_sha256(proof_source_rows)
        and _paper_valid_sha256(proof_source_hash)
        and proof_source_hash == _paper_canonical_sha256(proof_source_material)
    )
    proof_index: dict[str, Mapping[str, Any]] = {}
    proof_index_reasons: list[str] = []
    if rows and not proof_source_ready:
        proof_index_reasons.append("OPEN_POSITION_ACCEPTED_FILL_PROOF_SOURCE_INVALID")
    if proof_source_ready:
        for proof_index_value, proof_row in enumerate(proof_source_rows):
            aliases = {
                str(value).strip()
                for value in (
                    proof_row.get("fill_id"),
                    proof_row.get("ledger_row_id"),
                )
                if value not in (None, "") and str(value).strip()
            }
            if not aliases:
                proof_index_reasons.append(
                    f"ACCEPTED_FILL_PROOF_STABLE_FILL_ID_MISSING:{proof_index_value}"
                )
                continue
            for alias in aliases:
                prior = proof_index.get(alias)
                if prior is not None and dict(prior) != dict(proof_row):
                    proof_index_reasons.append(f"ACCEPTED_FILL_PROOF_DUPLICATE_FILL_ID:{alias}")
                    continue
                proof_index[alias] = proof_row
    if rows:
        rejection_reasons.extend(proof_index_reasons)

    for index, row in enumerate(rows):
        symbol = str(row.get("symbol") or "").strip().upper()
        identity = str(
            _first_present(
                row.get("position_generation_id"),
                row.get("position_id"),
                row.get("entry_fill_id"),
                row.get("allocation_id"),
            )
            or ""
        ).strip()
        if not symbol:
            rejection_reasons.append(f"OPEN_POSITION_SYMBOL_MISSING:{index}")
            continue
        if not identity:
            rejection_reasons.append(f"OPEN_POSITION_STABLE_IDENTITY_MISSING:{index}:{symbol}")
        elif identity in identities:
            rejection_reasons.append(f"OPEN_POSITION_STABLE_IDENTITY_DUPLICATE:{identity}")
        else:
            identities.add(identity)

        quantity = _coerce_float(_first_present(row.get("net_quantity"), row.get("quantity")))
        if quantity is None or not math.isfinite(quantity) or quantity == 0.0:
            rejection_reasons.append(f"OPEN_POSITION_NONZERO_QUANTITY_MISSING:{index}:{symbol}")
            continue

        mark_evidence = mark_cache.get(symbol)
        if mark_evidence is None:
            mark_evidence = _read_v2_mark_index_evidence(r, symbol)
            mark_cache[symbol] = mark_evidence
        mark = _coerce_float(mark_evidence.get("mark_price"))
        source_material = mark_evidence.get("mark_index_source_material")
        source_hash = mark_evidence.get("mark_index_source_hash")
        mark_times = {
            field: _strict_aware_utc_time(mark_evidence.get(field))
            for field in (
                "mark_index_event_time",
                "mark_index_generated_at",
                "mark_index_available_at",
                "mark_index_observed_at",
            )
        }
        mark_lineage_ready = bool(
            mark is not None
            and math.isfinite(mark)
            and mark > 0.0
            and mark_evidence.get("mark_index_freshness_state") == "CURRENT"
            and isinstance(source_material, Mapping)
            and _paper_valid_sha256(source_hash)
            and source_hash == _paper_canonical_sha256(source_material)
            and all(value is not None for value in mark_times.values())
            and mark_times["mark_index_event_time"]
            <= mark_times["mark_index_generated_at"]
            <= mark_times["mark_index_available_at"]
            <= mark_times["mark_index_observed_at"]
        )
        if not mark_lineage_ready:
            rejection_reasons.append(f"OPEN_POSITION_CURRENT_MARK_EVIDENCE_INVALID:{symbol}")
            continue

        raw_source_fill_ids = row.get("source_fill_ids")
        if not isinstance(raw_source_fill_ids, list) or not raw_source_fill_ids:
            rejection_reasons.append(f"OPEN_POSITION_SOURCE_FILL_IDS_MISSING:{index}:{symbol}")
            continue
        source_fill_ids = [
            str(value).strip()
            for value in raw_source_fill_ids
            if value not in (None, "") and str(value).strip()
        ]
        if len(source_fill_ids) != len(raw_source_fill_ids) or len(source_fill_ids) != len(
            set(source_fill_ids)
        ):
            rejection_reasons.append(f"OPEN_POSITION_SOURCE_FILL_IDS_INVALID:{index}:{symbol}")
            continue
        duplicated_across_positions = sorted(set(source_fill_ids) & consumed_source_fill_ids)
        if duplicated_across_positions:
            rejection_reasons.append(
                "OPEN_POSITION_SOURCE_FILL_ID_REUSED_ACROSS_POSITIONS:"
                f"{index}:{symbol}:{'|'.join(duplicated_across_positions)}"
            )
            continue
        consumed_source_fill_ids.update(source_fill_ids)

        source_fill_projections: list[dict[str, Any]] = []
        position_projected_loss = Decimal(0)
        source_fill_blocked = False
        for source_fill_id in source_fill_ids:
            proof_row = proof_index.get(source_fill_id)
            if not isinstance(proof_row, Mapping):
                rejection_reasons.append(
                    "OPEN_POSITION_SOURCE_FILL_PROOF_MISSING:" f"{index}:{symbol}:{source_fill_id}"
                )
                source_fill_blocked = True
                continue
            if str(proof_row.get("symbol") or "").strip().upper() != symbol:
                rejection_reasons.append(
                    "OPEN_POSITION_SOURCE_FILL_SYMBOL_MISMATCH:"
                    f"{index}:{symbol}:{source_fill_id}"
                )
                source_fill_blocked = True
                continue
            persisted_reasons = _paper_persisted_admission_rejection_reasons(proof_row)
            allocation = (
                proof_row.get("adaptive_allocation")
                if isinstance(proof_row.get("adaptive_allocation"), Mapping)
                else {}
            )
            max_loss = _paper_exact_positive_decimal_aliases(
                allocation.get("max_loss_if_stop_hit"),
                allocation.get("max_loss_usd"),
            )
            if persisted_reasons or max_loss is None:
                rejection_reasons.append(
                    "OPEN_POSITION_SOURCE_FILL_FINAL_V3_PROOF_INVALID:"
                    f"{index}:{symbol}:{source_fill_id}"
                )
                rejection_reasons.extend(
                    f"OPEN_POSITION_SOURCE_FILL_PROOF:{source_fill_id}:{reason}"
                    for reason in persisted_reasons
                )
                if max_loss is None:
                    rejection_reasons.append(
                        "OPEN_POSITION_SOURCE_FILL_MAX_LOSS_ALIASES_INVALID:"
                        f"{index}:{symbol}:{source_fill_id}"
                    )
                source_fill_blocked = True
                continue
            final_contract = proof_row.get("paper_final_admission_contract")
            final_receipt_hash = (
                final_contract.get("receipt_hash") if isinstance(final_contract, Mapping) else None
            )
            cycle_commit = proof_row.get("paper_cycle_reservation_commit_receipt")
            revocable_receipt = proof_row.get("paper_revocable_control_commit_revalidation")
            allocation_hash = _paper_canonical_sha256(allocation)
            position_projected_loss += max_loss
            source_fill_projections.append(
                {
                    "source_fill_id": source_fill_id,
                    "allocation_id": allocation.get("allocation_id"),
                    "allocation_input_hash": allocation.get("allocation_input_hash"),
                    "adaptive_allocation_hash": allocation_hash,
                    "projected_max_loss_usd": (_paper_nonunderstating_decimal_float(max_loss)),
                    "final_admission_receipt_hash": final_receipt_hash,
                    "cycle_reservation_snapshot_hash": proof_row.get(
                        "paper_cycle_reservation_snapshot_hash"
                    ),
                    "cycle_reservation_commit_receipt_hash": (
                        cycle_commit.get("receipt_hash")
                        if isinstance(cycle_commit, Mapping)
                        else None
                    ),
                    "revocable_control_receipt_hash": (
                        revocable_receipt.get("receipt_hash")
                        if isinstance(revocable_receipt, Mapping)
                        else None
                    ),
                }
            )
        if source_fill_blocked or len(source_fill_projections) != len(source_fill_ids):
            continue

        notional_decimal = Decimal(str(abs(quantity))) * Decimal(str(mark))
        projected_max_loss = _paper_nonunderstating_decimal_float(position_projected_loss)
        row_projections.append(
            {
                "row_index": index,
                "position_identity": identity,
                "symbol": symbol,
                "signed_quantity": quantity,
                "absolute_quantity": abs(quantity),
                "current_mark_price": mark,
                "current_mark_gross_notional_usd": (
                    _paper_nonunderstating_decimal_float(notional_decimal)
                ),
                "projected_max_loss_usd": projected_max_loss,
                "projected_max_loss_source": (
                    "SUM_DURABLE_SOURCE_FILL_FINAL_V3_EQUAL_MAX_LOSS_ALIASES"
                ),
                "source_fill_count": len(source_fill_projections),
                "source_fill_proofs": source_fill_projections,
                "mark_index_source": mark_evidence.get("mark_index_source"),
                "mark_index_source_hash": source_hash,
                "mark_index_event_time": mark_evidence.get("mark_index_event_time"),
                "mark_index_generated_at": mark_evidence.get("mark_index_generated_at"),
                "mark_index_available_at": mark_evidence.get("mark_index_available_at"),
                "mark_index_observed_at": mark_evidence.get("mark_index_observed_at"),
            }
        )

    snapshot_completed_at = _utc_iso()
    snapshot_started_utc = _strict_aware_utc_time(snapshot_started_at)
    snapshot_completed_utc = _strict_aware_utc_time(snapshot_completed_at)
    ledger_observed_utc = _strict_aware_utc_time(ledger_observed_at)
    proof_source_observed_utc = _strict_aware_utc_time(
        accepted_fill_proof_source.get("observed_at")
    )
    if (
        snapshot_started_utc is None
        or snapshot_completed_utc is None
        or ledger_observed_utc is None
        or ledger_observed_utc > snapshot_started_utc
        or snapshot_started_utc > snapshot_completed_utc
    ):
        rejection_reasons.append("PRECYCLE_EXPOSURE_SNAPSHOT_CLOCK_INVALID")
    if rows and (
        proof_source_observed_utc is None
        or snapshot_started_utc is None
        or proof_source_observed_utc > snapshot_started_utc
    ):
        rejection_reasons.append("PRECYCLE_ACCEPTED_FILL_PROOF_CLOCK_INVALID")
    for projection in row_projections:
        mark_available_utc = _strict_aware_utc_time(projection.get("mark_index_available_at"))
        mark_observed_utc = _strict_aware_utc_time(projection.get("mark_index_observed_at"))
        if (
            snapshot_completed_utc is None
            or snapshot_started_utc is None
            or mark_available_utc is None
            or mark_observed_utc is None
            or mark_available_utc > mark_observed_utc
            or mark_observed_utc < snapshot_started_utc
            or mark_observed_utc > snapshot_completed_utc
        ):
            rejection_reasons.append(
                "PRECYCLE_EXPOSURE_MARK_AFTER_SNAPSHOT_COMPLETION:" f"{projection.get('symbol')}"
            )

    row_projections.sort(
        key=lambda item: (
            str(item.get("symbol") or ""),
            str(item.get("position_identity") or ""),
            int(item.get("row_index") or 0),
        )
    )
    by_symbol: dict[str, Decimal] = {}
    total_notional = Decimal(0)
    total_projected_loss = Decimal(0)
    for row in row_projections:
        symbol = str(row["symbol"])
        notional = Decimal(str(row["current_mark_gross_notional_usd"]))
        projected_loss = Decimal(str(row["projected_max_loss_usd"]))
        by_symbol[symbol] = by_symbol.get(symbol, Decimal(0)) + notional
        total_notional += notional
        total_projected_loss += projected_loss

    material = {
        "schema_version": "paper_precycle_current_mark_exposure_snapshot_v1",
        "status": "READY" if not rejection_reasons else "BLOCKED",
        "ledger_observed_at": ledger_observed_at,
        "snapshot_started_at": snapshot_started_at,
        "snapshot_completed_at": snapshot_completed_at,
        "accepted_fill_proof_source": proof_source_projection,
        "ledger_open_position_count": len(rows),
        "validated_open_position_count": len(row_projections),
        "validated_source_fill_count": sum(
            int(row.get("source_fill_count") or 0) for row in row_projections
        ),
        "open_position_rows": row_projections,
        "current_mark_gross_notional_by_symbol_usd": {
            symbol: _paper_nonunderstating_decimal_float(value)
            for symbol, value in sorted(by_symbol.items())
        },
        "current_mark_gross_notional_total_usd": (
            _paper_nonunderstating_decimal_float(total_notional)
        ),
        "precycle_open_projected_max_loss_usd": (
            _paper_nonunderstating_decimal_float(total_projected_loss)
        ),
        "valuation_contract": "SUM_ABS_QUANTITY_TIMES_FRESH_CURRENT_MARK",
        "projected_loss_contract": (
            "CONSERVATIVE_SUM_ALL_DURABLE_SOURCE_FILL_FINAL_V3_EXACT_POSITIVE_"
            "ALLOCATOR_MAX_LOSS_ALIASES;PARTIAL_REDUCTIONS_DO_NOT_RELEASE_WITHOUT_"
            "SEALED_FILL_QUANTITY_ATTRIBUTION"
        ),
        "rejection_reasons": sorted(set(rejection_reasons)),
        "paper_only": True,
        "routes_to_live": False,
        "places_real_order": False,
    }
    return {**material, "snapshot_hash": _paper_canonical_sha256(material)}


def _paper_cycle_base_resource_evidence(
    portfolio_context: Mapping[str, Any],
) -> dict[str, Any]:
    """Seal the account resources consumed by every candidate this cycle."""

    material: dict[str, Any] = {
        "schema_version": "paper_cycle_base_resource_evidence_v1",
        "equity_usd": _coerce_float(portfolio_context.get("equity")),
        "available_margin_usd": _coerce_float(portfolio_context.get("available_margin")),
        "wallet_balance_usd": _coerce_float(portfolio_context.get("wallet_balance")),
        "drawdown_bps": _coerce_float(portfolio_context.get("drawdown_bps")),
        "paper_session_starting_equity_usd": _coerce_float(
            portfolio_context.get("paper_session_starting_equity_usd")
        ),
        "current_equity_usd": _coerce_float(portfolio_context.get("current_equity_usd")),
        "current_drawdown_fraction": _coerce_float(
            portfolio_context.get("current_drawdown_fraction")
        ),
        "portfolio_state_present": portfolio_context.get("portfolio_state_present"),
        "portfolio_state_event_time": portfolio_context.get("portfolio_state_event_time"),
        "portfolio_state_generated_at": portfolio_context.get("portfolio_state_generated_at"),
        "portfolio_state_available_at": portfolio_context.get("portfolio_state_available_at"),
        "portfolio_context_observed_at": portfolio_context.get("portfolio_context_observed_at"),
        "paper_ledger_generated_at": portfolio_context.get("paper_ledger_generated_at"),
        "paper_ledger_observed_at": portfolio_context.get("paper_ledger_observed_at"),
        "paper_only": True,
        "routes_to_live": False,
        "places_real_order": False,
    }
    numeric_ready = bool(
        material["equity_usd"] is not None
        and math.isfinite(material["equity_usd"])
        and material["equity_usd"] > 0.0
        and material["available_margin_usd"] is not None
        and math.isfinite(material["available_margin_usd"])
        and material["available_margin_usd"] >= 0.0
        and material["wallet_balance_usd"] is not None
        and math.isfinite(material["wallet_balance_usd"])
        and material["wallet_balance_usd"] >= 0.0
        and material["drawdown_bps"] is not None
        and math.isfinite(material["drawdown_bps"])
        and material["drawdown_bps"] >= 0.0
        and material["paper_session_starting_equity_usd"] is not None
        and math.isfinite(material["paper_session_starting_equity_usd"])
        and material["paper_session_starting_equity_usd"] > 0.0
        and material["current_equity_usd"] is not None
        and math.isfinite(material["current_equity_usd"])
        and material["current_equity_usd"] >= 0.0
        and material["current_drawdown_fraction"] is not None
        and math.isfinite(material["current_drawdown_fraction"])
        and material["current_drawdown_fraction"] >= 0.0
    )
    material["status"] = "READY" if numeric_ready else "BLOCKED"
    material["rejection_reasons"] = (
        [] if numeric_ready else ["BASE_RESOURCE_NUMERIC_EVIDENCE_INVALID"]
    )
    return {**material, "evidence_hash": _paper_canonical_sha256(material)}


PAPER_DYNAMIC_ENVELOPE_FIELDS = (
    "max_total_portfolio_risk_pct",
    "max_single_symbol_exposure_pct",
    "max_daily_drawdown_pct",
    "max_loss_per_trade_pct",
    "min_available_margin_buffer_pct",
    "max_correlation_exposure_pct",
    "min_liquidation_buffer_bps",
    "max_effective_leverage",
    "tail_loss_multiplier",
    "emergency_absolute_cap_usdt",
)

PAPER_STRICT_AFTER_COST_EDGE_SOURCE = "STRICT_GOVERNED_CLOSED_OUTCOMES_REALIZED_AFTER_COST_PNL_BPS"
PAPER_PROMOTED_CHECKPOINT_STATUS_SOURCE = "redis:v2:trainer:hybrid_cuda:status"


def _paper_promoted_checkpoint_growth_receipt(
    trainer_status_value: Any,
    *,
    candidate_checkpoint_id: Any,
    candidate_checkpoint_id_source: Any,
    decision_time: Any,
) -> dict[str, Any]:
    """Authenticate the exact promoted, positive-OOS trainer checkpoint."""

    trainer_status = dict(trainer_status_value) if isinstance(trainer_status_value, Mapping) else {}
    verified_value = trainer_status.get("current_cycle_verified_serving_checkpoint_evidence")
    verified = dict(verified_value) if isinstance(verified_value, Mapping) else {}
    source_fields = (
        "schema_version",
        "generated_utc",
        "status_payload_expires_at",
        "status_publication_status",
        "cycle_id",
        "process_instance_id",
        "status_publication",
        "current_cycle_learning_envelope_identity",
        "runtime_readiness_status",
        "trainer_learning_ready",
        "checkpoint_id",
        "candidate_policy_fingerprint",
        "checkpoint_promotion_allowed",
        "checkpoint_promotion_reason",
        "mandatory_pit_edge_gate_passed",
        "validation_split_pit_safe",
        "validation_policy_edge_status",
        "validation_policy_edge_after_cost_bps",
        "validation_policy_edge_lower_confidence_bound_bps",
        "validation_policy_edge_rows_evaluated",
        "model_serving_allowed",
        "model_serving_source",
    )
    source_material = {field: deepcopy(trainer_status.get(field)) for field in source_fields}
    source_material["current_cycle_verified_serving_checkpoint_evidence"] = verified
    checkpoint_id = str(candidate_checkpoint_id or "").strip()
    checkpoint_id_source = str(candidate_checkpoint_id_source or "").strip()
    decision = _strict_aware_utc_time(decision_time)
    status_generated = _strict_aware_utc_time(source_material.get("generated_utc"))
    status_expires = _strict_aware_utc_time(source_material.get("status_payload_expires_at"))
    checkpoint_generated = _strict_aware_utc_time(verified.get("generated_utc"))
    edge_lcb = _coerce_float(
        source_material.get("validation_policy_edge_lower_confidence_bound_bps")
    )
    edge_rows = _coerce_float(source_material.get("validation_policy_edge_rows_evaluated"))
    publication_value = source_material.get("status_publication")
    publication = dict(publication_value) if isinstance(publication_value, Mapping) else {}
    envelope_identity_value = source_material.get("current_cycle_learning_envelope_identity")
    envelope_identity = (
        dict(envelope_identity_value) if isinstance(envelope_identity_value, Mapping) else {}
    )
    fingerprint = source_material.get("candidate_policy_fingerprint")
    reasons: list[str] = []
    if not checkpoint_id:
        reasons.append("CANDIDATE_CHECKPOINT_ID_MISSING")
    if checkpoint_id_source not in {
        "trust_envelope.checkpoint_id",
        "signal.checkpoint_id",
        "prediction.checkpoint_id",
    }:
        reasons.append("CANDIDATE_CHECKPOINT_ID_SOURCE_NOT_EXPLICIT")
    if source_material.get("checkpoint_id") != checkpoint_id:
        reasons.append("TRAINER_STATUS_CHECKPOINT_ID_MISMATCH")
    if verified.get("checkpoint_id") != checkpoint_id:
        reasons.append("VERIFIED_SERVING_CHECKPOINT_ID_MISMATCH")
    if source_material.get("checkpoint_promotion_allowed") is not True:
        reasons.append("CHECKPOINT_PROMOTION_NOT_ALLOWED")
    if (
        source_material.get("checkpoint_promotion_reason")
        != "PIT_EDGE_CONFIDENCE_PARETO_SERVING_PROMOTION_PASS"
    ):
        reasons.append("CHECKPOINT_PROMOTION_REASON_INVALID")
    if source_material.get("mandatory_pit_edge_gate_passed") is not True:
        reasons.append("CHECKPOINT_POSITIVE_OOS_EDGE_GATE_NOT_PASSED")
    if source_material.get("validation_split_pit_safe") is not True:
        reasons.append("CHECKPOINT_VALIDATION_SPLIT_NOT_PIT_SAFE")
    if source_material.get("validation_policy_edge_status") != "VALID":
        reasons.append("CHECKPOINT_VALIDATION_EDGE_STATUS_INVALID")
    if edge_lcb is None or not math.isfinite(edge_lcb) or edge_lcb <= 0.0:
        reasons.append("CHECKPOINT_VALIDATION_EDGE_LCB_NOT_POSITIVE")
    if edge_rows is None or edge_rows < 1.0 or not edge_rows.is_integer():
        reasons.append("CHECKPOINT_VALIDATION_EDGE_ROWS_INVALID")
    if source_material.get("model_serving_allowed") is not True:
        reasons.append("CHECKPOINT_MODEL_SERVING_NOT_ALLOWED")
    if source_material.get("model_serving_source") != "VERIFIED_PROMOTED_SERVING_CHECKPOINT":
        reasons.append("CHECKPOINT_MODEL_SERVING_SOURCE_NOT_CURRENT_PROMOTION")
    if source_material.get("runtime_readiness_status") != "READY":
        reasons.append("TRAINER_RUNTIME_NOT_READY")
    if source_material.get("trainer_learning_ready") is not True:
        reasons.append("TRAINER_LEARNING_NOT_READY")
    if source_material.get("status_publication_status") != "ACTIVE":
        reasons.append("TRAINER_STATUS_PUBLICATION_NOT_ACTIVE")
    cycle_id = str(source_material.get("cycle_id") or "").strip()
    process_instance_id = str(source_material.get("process_instance_id") or "").strip()
    if not cycle_id or not process_instance_id:
        reasons.append("TRAINER_STATUS_CYCLE_IDENTITY_MISSING")
    if (
        publication.get("schema_version") != "v2_trainer_expiring_status_publication_v1"
        or publication.get("publication_complete") is not True
        or publication.get("cycle_id") != cycle_id
        or publication.get("process_instance_id") != process_instance_id
        or publication.get("generated_utc") != source_material.get("generated_utc")
        or publication.get("expires_at") != source_material.get("status_payload_expires_at")
        or not isinstance(publication.get("component_results"), Mapping)
        or set(publication.get("component_results") or {})
        != {
            "blocked_staging_status",
            "heartbeat",
            "metrics",
            "feature_schema_status",
            "status",
        }
        or not all(value is True for value in publication["component_results"].values())
    ):
        reasons.append("TRAINER_STATUS_PUBLICATION_RECEIPT_INVALID")
    if (
        envelope_identity.get("cycle_id") != cycle_id
        or envelope_identity.get("process_instance_id") != process_instance_id
        or envelope_identity.get("checkpoint_id") != checkpoint_id
        or envelope_identity.get("candidate_policy_fingerprint") != fingerprint
        or not _paper_valid_sha256(envelope_identity.get("envelope_sha256"))
    ):
        reasons.append("TRAINER_LEARNING_ENVELOPE_IDENTITY_BINDING_INVALID")
    if verified.get("checkpoint_artifact_verified") is not True:
        reasons.append("CHECKPOINT_ARTIFACT_NOT_VERIFIED")
    if verified.get("causal_order_verified") is not True:
        reasons.append("CHECKPOINT_CAUSAL_ORDER_NOT_VERIFIED")
    if verified.get("lineage_kind") != "VERIFIED_SERVING_POLICY":
        reasons.append("CHECKPOINT_LINEAGE_KIND_INVALID")
    if verified.get("ledger_disposition") != "SERVING_PROMOTED":
        reasons.append("CHECKPOINT_LEDGER_DISPOSITION_NOT_PROMOTED")
    if verified.get("exact_optimizer_contract_durable") is not True:
        reasons.append("CHECKPOINT_OPTIMIZER_CONTRACT_NOT_DURABLE")
    if verified.get("manager_semantic_verification_recomputed_this_cycle") is not True:
        reasons.append("CHECKPOINT_SEMANTIC_VERIFICATION_NOT_CURRENT_CYCLE")
    if not _paper_valid_sha256(fingerprint) or fingerprint != verified.get(
        "model_parameter_fingerprint"
    ):
        reasons.append("CHECKPOINT_POLICY_FINGERPRINT_BINDING_INVALID")
    if not _paper_valid_sha256(verified.get("weight_file_sha256")):
        reasons.append("CHECKPOINT_WEIGHT_HASH_INVALID")
    if decision is None:
        reasons.append("CHECKPOINT_CONSUMER_DECISION_TIME_INVALID")
    if status_generated is None:
        reasons.append("CHECKPOINT_STATUS_GENERATED_TIME_INVALID")
    if status_expires is None:
        reasons.append("CHECKPOINT_STATUS_EXPIRY_INVALID")
    if checkpoint_generated is None:
        reasons.append("CHECKPOINT_ARTIFACT_GENERATED_TIME_INVALID")
    if decision is not None and status_generated is not None and status_generated > decision:
        reasons.append("CHECKPOINT_STATUS_AVAILABLE_AFTER_DECISION")
    if decision is not None and status_expires is not None and status_expires < decision:
        reasons.append("CHECKPOINT_STATUS_EXPIRED_AT_DECISION")
    if (
        checkpoint_generated is not None
        and status_generated is not None
        and checkpoint_generated > status_generated
    ):
        reasons.append("CHECKPOINT_ARTIFACT_GENERATED_AFTER_STATUS")
    material = {
        "schema_version": "paper_promoted_checkpoint_growth_receipt_v1",
        "source": PAPER_PROMOTED_CHECKPOINT_STATUS_SOURCE,
        "candidate_checkpoint_id": checkpoint_id or None,
        "candidate_checkpoint_id_source": checkpoint_id_source or None,
        "decision_time": (
            decision.isoformat().replace("+00:00", "Z") if decision is not None else decision_time
        ),
        "source_material": source_material,
        "source_material_hash": _paper_canonical_sha256(source_material),
        "status": "READY" if not reasons else "BLOCKED",
        "rejection_reasons": sorted(set(reasons)),
        "paper_only": True,
        "routes_to_live": False,
        "places_real_order": False,
    }
    return {**material, "evidence_hash": _paper_canonical_sha256(material)}


def _paper_strict_after_cost_edge_growth_receipt(
    performance_status_value: Any,
    *,
    decision_time: Any,
) -> dict[str, Any]:
    """Bind and replay every statistic from one exact strict closed cohort."""

    status = dict(performance_status_value) if isinstance(performance_status_value, Mapping) else {}
    fields = (
        "after_cost_edge_mean_bps",
        "after_cost_edge_lower_bound_bps",
        "after_cost_edge_scale_bps",
        "after_cost_edge_resolution_bps",
        "after_cost_edge_evidence_count",
        "after_cost_edge_scale_evidence_count",
        "strict_after_cost_edge_win_rate",
        "strict_after_cost_edge_profit_factor",
        "strict_after_cost_edge_profit_factor_numeric",
        "strict_after_cost_edge_profit_factor_is_infinite",
        "after_cost_edge_evidence_source",
        "after_cost_edge_scale_method",
        "after_cost_edge_resolution_method",
        "after_cost_edge_available_at",
        "governed_closed_rows",
        "strict_governance_selector",
        "strict_after_cost_edge_cohort_status",
        "strict_after_cost_edge_cohort_rejection_reasons",
        "strict_after_cost_edge_cohort_material",
        "strict_after_cost_edge_cohort_material_hash",
    )
    source_material = {field: deepcopy(status.get(field)) for field in fields}
    cohort_value = source_material.get("strict_after_cost_edge_cohort_material")
    cohort = dict(cohort_value) if isinstance(cohort_value, Mapping) else {}
    cohort_hash = source_material.get("strict_after_cost_edge_cohort_material_hash")
    recomputed, cohort_reasons = _paper_strict_edge_cohort_statistics(
        cohort,
        decision_time=decision_time,
    )
    edge_lcb = _coerce_float(source_material.get("after_cost_edge_lower_bound_bps"))
    edge_scale = _coerce_float(source_material.get("after_cost_edge_scale_bps"))
    edge_resolution = _coerce_float(source_material.get("after_cost_edge_resolution_bps"))
    evidence_count = _coerce_float(source_material.get("after_cost_edge_evidence_count"))
    scale_count = _coerce_float(source_material.get("after_cost_edge_scale_evidence_count"))
    available = _strict_aware_utc_time(source_material.get("after_cost_edge_available_at"))
    decision = _strict_aware_utc_time(decision_time)
    reasons: list[str] = list(cohort_reasons)
    if (
        source_material.get("strict_after_cost_edge_cohort_status") != "READY"
        or source_material.get("strict_after_cost_edge_cohort_rejection_reasons") != []
    ):
        reasons.append("STRICT_AFTER_COST_EDGE_COHORT_NOT_READY")
    if (
        not cohort
        or not _paper_valid_sha256(cohort_hash)
        or cohort_hash != _paper_canonical_sha256(cohort)
    ):
        reasons.append("STRICT_AFTER_COST_EDGE_COHORT_HASH_INVALID")
    for field, expected in recomputed.items():
        if source_material.get(field) != expected:
            reasons.append(f"STRICT_AFTER_COST_EDGE_REPLAY_MISMATCH:{field}")
    if source_material.get("governed_closed_rows") != recomputed.get(
        "after_cost_edge_evidence_count"
    ):
        reasons.append("STRICT_AFTER_COST_EDGE_GOVERNED_COUNT_MISMATCH")
    if edge_lcb is None or not math.isfinite(edge_lcb) or edge_lcb <= 0.0:
        reasons.append("STRICT_AFTER_COST_EDGE_LCB_NOT_POSITIVE")
    if edge_scale is None or not math.isfinite(edge_scale) or edge_scale <= 0.0:
        reasons.append("STRICT_AFTER_COST_EDGE_SCALE_INVALID")
    if (
        edge_resolution is None
        or not math.isfinite(edge_resolution)
        or edge_resolution <= 0.0
        or edge_scale is None
        or edge_resolution > edge_scale
        or edge_resolution < math.ulp(edge_scale)
    ):
        reasons.append("STRICT_AFTER_COST_EDGE_RESOLUTION_INVALID")
    if (
        evidence_count is None
        or evidence_count < 1.0
        or not evidence_count.is_integer()
        or scale_count != evidence_count
    ):
        reasons.append("STRICT_AFTER_COST_EDGE_COHORT_COUNT_INVALID")
    if (
        source_material.get("after_cost_edge_evidence_source")
        != PAPER_STRICT_AFTER_COST_EDGE_SOURCE
    ):
        reasons.append("STRICT_AFTER_COST_EDGE_SOURCE_INVALID")
    if (
        source_material.get("after_cost_edge_scale_method")
        != "MEAN_ABSOLUTE_REALIZED_AFTER_COST_PNL_BPS"
    ):
        reasons.append("STRICT_AFTER_COST_EDGE_SCALE_METHOD_INVALID")
    if source_material.get("after_cost_edge_resolution_method") != "IEEE754_ULP_OF_EDGE_SCALE_BPS":
        reasons.append("STRICT_AFTER_COST_EDGE_RESOLUTION_METHOD_INVALID")
    if source_material.get("strict_governance_selector") != "STRICT_TIER_EXCLUSION_ACTIVE":
        reasons.append("STRICT_AFTER_COST_EDGE_SELECTOR_INVALID")
    if decision is None or available is None:
        reasons.append("STRICT_AFTER_COST_EDGE_TIME_INVALID")
    elif available > decision:
        reasons.append("STRICT_AFTER_COST_EDGE_AVAILABLE_AFTER_DECISION")
    material = {
        "schema_version": "paper_strict_after_cost_edge_growth_receipt_v1",
        "source_material": source_material,
        "source_material_hash": _paper_canonical_sha256(source_material),
        "decision_time": (
            decision.isoformat().replace("+00:00", "Z") if decision is not None else decision_time
        ),
        "status": "READY" if not reasons else "BLOCKED",
        "rejection_reasons": sorted(set(reasons)),
        "paper_only": True,
        "routes_to_live": False,
        "places_real_order": False,
    }
    return {**material, "evidence_hash": _paper_canonical_sha256(material)}


def _paper_candidate_market_context_growth_receipt(
    *,
    intent: Mapping[str, Any],
    allocation_input: Any,
    point_in_time_evidence: Mapping[str, Any],
    decision_time: Any,
) -> dict[str, Any]:
    """Bind one allocator candidate's exact context to its pre-decision PIT proof."""

    decision = _strict_aware_utc_time(decision_time)
    observed_value = point_in_time_evidence.get("observed_component_times")
    observed = dict(observed_value) if isinstance(observed_value, Mapping) else {}
    context_times: list[tuple[str, datetime]] = []
    for field, raw in observed.items():
        if not str(field).endswith("available_at") or str(field).startswith("dynamic_envelope_"):
            continue
        parsed = _strict_aware_utc_time(raw)
        if parsed is not None:
            context_times.append((str(field), parsed))
    context_available = max((value for _, value in context_times), default=None)
    liquidity = _coerce_float(getattr(allocation_input, "liquidity_score", None))
    regime = _coerce_float(getattr(allocation_input, "regime_score", None))
    confidence = _coerce_float(getattr(allocation_input, "confidence_calibrated", None))
    symbol = str(getattr(allocation_input, "symbol", "") or "").strip().upper()
    timeframe = str(getattr(allocation_input, "timeframe", "") or "").strip().lower()
    lineage_value = getattr(allocation_input, "lineage_ids", None)
    lineage = dict(lineage_value) if isinstance(lineage_value, Mapping) else {}
    liquidity_source_material_value = lineage.get(
        PAPER_ALLOCATOR_LIQUIDITY_SOURCE_MATERIAL_LINEAGE_KEY
    )
    liquidity_source_material = (
        deepcopy(dict(liquidity_source_material_value))
        if isinstance(liquidity_source_material_value, Mapping)
        else {}
    )
    regime_source_material_value = lineage.get(PAPER_ALLOCATOR_REGIME_SOURCE_MATERIAL_LINEAGE_KEY)
    regime_source_material = (
        deepcopy(dict(regime_source_material_value))
        if isinstance(regime_source_material_value, Mapping)
        else {}
    )
    liquidity_source_hash = lineage.get(PAPER_ALLOCATOR_LIQUIDITY_SOURCE_HASH_LINEAGE_KEY)
    regime_source_hash = lineage.get(PAPER_ALLOCATOR_REGIME_SOURCE_HASH_LINEAGE_KEY)
    pit_material = {
        "status": point_in_time_evidence.get("status"),
        "decision_time": point_in_time_evidence.get("decision_time"),
        "decision_time_semantics": point_in_time_evidence.get("decision_time_semantics"),
        "observed_component_times": observed,
        "rejection_reasons": list(point_in_time_evidence.get("rejection_reasons") or []),
    }
    pit_hash = _paper_canonical_sha256(pit_material)
    reasons: list[str] = []
    if point_in_time_evidence.get("status") != "PASS":
        reasons.append("CANDIDATE_MARKET_CONTEXT_PIT_NOT_PASS")
    if not symbol:
        reasons.append("CANDIDATE_MARKET_CONTEXT_SYMBOL_MISSING")
    if not timeframe:
        reasons.append("CANDIDATE_MARKET_CONTEXT_TIMEFRAME_MISSING")
    if liquidity is None or not math.isfinite(liquidity) or not 0.0 <= liquidity <= 1.0:
        reasons.append("CANDIDATE_MARKET_CONTEXT_LIQUIDITY_INVALID")
    if regime is None or not math.isfinite(regime) or not 0.0 <= regime <= 1.0:
        reasons.append("CANDIDATE_MARKET_CONTEXT_REGIME_INVALID")
    if confidence is None or not math.isfinite(confidence) or not 0.0 <= confidence <= 1.0:
        reasons.append("CANDIDATE_MARKET_CONTEXT_CONFIDENCE_INVALID")
    if (
        not liquidity_source_material
        or not _paper_valid_sha256(liquidity_source_hash)
        or liquidity_source_hash != _paper_canonical_sha256(liquidity_source_material)
    ):
        reasons.append("CANDIDATE_MARKET_CONTEXT_LIQUIDITY_SOURCE_HASH_INVALID")
    if (
        not regime_source_material
        or not _paper_valid_sha256(regime_source_hash)
        or regime_source_hash != _paper_canonical_sha256(regime_source_material)
    ):
        reasons.append("CANDIDATE_MARKET_CONTEXT_REGIME_SOURCE_HASH_INVALID")
    reasons.extend(_paper_allocator_liquidity_source_rejection_reasons(liquidity_source_material))
    reasons.extend(_paper_allocator_regime_source_rejection_reasons(regime_source_material))
    if (
        liquidity_source_material.get("symbol") != symbol
        or liquidity_source_material.get("timeframe") != timeframe
        or liquidity_source_material.get("final_score") != liquidity
    ):
        reasons.append("CANDIDATE_MARKET_CONTEXT_LIQUIDITY_INPUT_BINDING_INVALID")
    if (
        regime_source_material.get("symbol") != symbol
        or regime_source_material.get("timeframe") != timeframe
        or regime_source_material.get("score") != regime
    ):
        reasons.append("CANDIDATE_MARKET_CONTEXT_REGIME_INPUT_BINDING_INVALID")
    if intent.get("allocator_market_evidence_status") != "READY":
        reasons.append("CANDIDATE_ALLOCATOR_MARKET_EVIDENCE_NOT_READY")
    if decision is None or context_available is None:
        reasons.append("CANDIDATE_MARKET_CONTEXT_TIME_INVALID")
    elif context_available > decision:
        reasons.append("CANDIDATE_MARKET_CONTEXT_AVAILABLE_AFTER_DECISION")
    context_source = (
        f"PAPER_ALLOCATOR_CANDIDATE_PIT_CONTEXT:{pit_hash}"
        if _paper_valid_sha256(pit_hash)
        else None
    )
    material = {
        "schema_version": "paper_candidate_market_context_growth_receipt_v1",
        "symbol": symbol or None,
        "timeframe": timeframe or None,
        "liquidity_score": liquidity,
        "regime_quality_score": regime,
        "candidate_confidence_calibrated": confidence,
        "liquidity_source": liquidity_source_material.get("base_source"),
        "regime_source": regime_source_material.get("source"),
        "liquidity_source_material": liquidity_source_material,
        "liquidity_source_material_hash": liquidity_source_hash,
        "regime_source_material": regime_source_material,
        "regime_source_material_hash": regime_source_hash,
        "market_context_source": context_source,
        "market_context_available_at": (
            context_available.isoformat().replace("+00:00", "Z")
            if context_available is not None
            else None
        ),
        "availability_fields_used": sorted(field for field, _ in context_times),
        "decision_time": (
            decision.isoformat().replace("+00:00", "Z") if decision is not None else decision_time
        ),
        "point_in_time_material": pit_material,
        "point_in_time_material_hash": pit_hash,
        "status": "READY" if not reasons else "BLOCKED",
        "rejection_reasons": sorted(set(reasons)),
        "paper_only": True,
        "routes_to_live": False,
        "places_real_order": False,
    }
    return {**material, "evidence_hash": _paper_canonical_sha256(material)}


def _paper_candidate_growth_authorization_receipt(
    *,
    symbol: str,
    decision_time: Any,
    checkpoint_receipt: Mapping[str, Any],
    edge_receipt: Mapping[str, Any],
    market_context_receipt: Mapping[str, Any],
) -> dict[str, Any]:
    component_receipts = {
        "promoted_checkpoint": deepcopy(dict(checkpoint_receipt)),
        "strict_after_cost_edge": deepcopy(dict(edge_receipt)),
        "candidate_market_context": deepcopy(dict(market_context_receipt)),
    }
    reasons = sorted(
        {
            f"{name}:{reason}"
            for name, receipt in component_receipts.items()
            for reason in (
                receipt.get("rejection_reasons")
                or ([] if receipt.get("status") == "READY" else ["NOT_READY"])
            )
        }
    )
    material = {
        "schema_version": "paper_candidate_growth_authorization_receipt_v1",
        "symbol": str(symbol or "").strip().upper() or None,
        "decision_time": (
            decision_time.isoformat().replace("+00:00", "Z")
            if isinstance(decision_time, datetime)
            else decision_time
        ),
        "component_receipts": component_receipts,
        "component_receipt_hashes": {
            name: receipt.get("evidence_hash") for name, receipt in component_receipts.items()
        },
        "status": "READY" if not reasons else "BLOCKED",
        "rejection_reasons": reasons,
        "missing_or_invalid_growth_evidence_caps_leverage_at_1x": True,
        "paper_only": True,
        "routes_to_live": False,
        "places_real_order": False,
    }
    return {**material, "evidence_hash": _paper_canonical_sha256(material)}


def _paper_embedded_receipt_hash_valid(receipt_value: Any) -> bool:
    if not isinstance(receipt_value, Mapping):
        return False
    material = dict(receipt_value)
    supplied_hash = material.pop("evidence_hash", None)
    return bool(
        _paper_valid_sha256(supplied_hash) and supplied_hash == _paper_canonical_sha256(material)
    )


def _paper_candidate_context_receipt_rejection_reasons(
    receipt_value: Any,
) -> list[str]:
    if not isinstance(receipt_value, Mapping):
        return ["CANDIDATE_MARKET_CONTEXT_RECEIPT_MISSING"]
    receipt = dict(receipt_value)
    reasons: list[str] = []
    if not _paper_embedded_receipt_hash_valid(receipt):
        reasons.append("CANDIDATE_MARKET_CONTEXT_RECEIPT_HASH_INVALID")
    if receipt.get("schema_version") != "paper_candidate_market_context_growth_receipt_v1":
        reasons.append("CANDIDATE_MARKET_CONTEXT_RECEIPT_SCHEMA_INVALID")
    pit = receipt.get("point_in_time_material")
    if not isinstance(pit, Mapping):
        reasons.append("CANDIDATE_MARKET_CONTEXT_PIT_MATERIAL_MISSING")
        pit = {}
    if not _paper_valid_sha256(receipt.get("point_in_time_material_hash")) or receipt.get(
        "point_in_time_material_hash"
    ) != _paper_canonical_sha256(pit):
        reasons.append("CANDIDATE_MARKET_CONTEXT_PIT_HASH_INVALID")
    if pit.get("status") != "PASS" or list(pit.get("rejection_reasons") or []):
        reasons.append("CANDIDATE_MARKET_CONTEXT_PIT_NOT_PASS")
    decision = _strict_aware_utc_time(receipt.get("decision_time"))
    available = _strict_aware_utc_time(receipt.get("market_context_available_at"))
    if decision is None or available is None or available > decision:
        reasons.append("CANDIDATE_MARKET_CONTEXT_TIME_INVALID")
    if pit.get("decision_time") != receipt.get("decision_time"):
        reasons.append("CANDIDATE_MARKET_CONTEXT_DECISION_TIME_MISMATCH")
    observed_value = pit.get("observed_component_times")
    observed = dict(observed_value) if isinstance(observed_value, Mapping) else {}
    expected_availability_fields = sorted(
        str(field)
        for field in observed
        if str(field).endswith("available_at") and not str(field).startswith("dynamic_envelope_")
    )
    parsed_context_times = [
        _strict_aware_utc_time(observed.get(field)) for field in expected_availability_fields
    ]
    valid_context_times = [value for value in parsed_context_times if value is not None]
    if receipt.get("availability_fields_used") != expected_availability_fields:
        reasons.append("CANDIDATE_MARKET_CONTEXT_AVAILABILITY_FIELDS_MISMATCH")
    if (
        not parsed_context_times
        or len(valid_context_times) != len(parsed_context_times)
        or available != max(valid_context_times)
    ):
        reasons.append("CANDIDATE_MARKET_CONTEXT_AVAILABILITY_REPLAY_MISMATCH")
    liquidity = _coerce_float(receipt.get("liquidity_score"))
    regime = _coerce_float(receipt.get("regime_quality_score"))
    confidence = _coerce_float(receipt.get("candidate_confidence_calibrated"))
    if liquidity is None or not 0.0 <= liquidity <= 1.0:
        reasons.append("CANDIDATE_MARKET_CONTEXT_LIQUIDITY_INVALID")
    if regime is None or not 0.0 <= regime <= 1.0:
        reasons.append("CANDIDATE_MARKET_CONTEXT_REGIME_INVALID")
    if confidence is None or not 0.0 <= confidence <= 1.0:
        reasons.append("CANDIDATE_MARKET_CONTEXT_CONFIDENCE_INVALID")
    symbol = str(receipt.get("symbol") or "").strip().upper()
    timeframe = str(receipt.get("timeframe") or "").strip().lower()
    liquidity_material = receipt.get("liquidity_source_material")
    regime_material = receipt.get("regime_source_material")
    if (
        not symbol
        or not timeframe
        or not isinstance(liquidity_material, Mapping)
        or not isinstance(regime_material, Mapping)
    ):
        reasons.append("CANDIDATE_MARKET_CONTEXT_EXACT_SOURCE_MATERIAL_MISSING")
        liquidity_material = {}
        regime_material = {}
    if receipt.get("liquidity_source_material_hash") != _paper_canonical_sha256(liquidity_material):
        reasons.append("CANDIDATE_MARKET_CONTEXT_LIQUIDITY_SOURCE_HASH_INVALID")
    if receipt.get("regime_source_material_hash") != _paper_canonical_sha256(regime_material):
        reasons.append("CANDIDATE_MARKET_CONTEXT_REGIME_SOURCE_HASH_INVALID")
    reasons.extend(_paper_allocator_liquidity_source_rejection_reasons(liquidity_material))
    reasons.extend(_paper_allocator_regime_source_rejection_reasons(regime_material))
    if (
        liquidity_material.get("symbol") != symbol
        or liquidity_material.get("timeframe") != timeframe
        or liquidity_material.get("final_score") != liquidity
        or receipt.get("liquidity_source") != liquidity_material.get("base_source")
    ):
        reasons.append("CANDIDATE_MARKET_CONTEXT_LIQUIDITY_REPLAY_BINDING_INVALID")
    if (
        regime_material.get("symbol") != symbol
        or regime_material.get("timeframe") != timeframe
        or regime_material.get("score") != regime
        or receipt.get("regime_source") != regime_material.get("source")
    ):
        reasons.append("CANDIDATE_MARKET_CONTEXT_REGIME_REPLAY_BINDING_INVALID")
    pit_hash = receipt.get("point_in_time_material_hash")
    if receipt.get("market_context_source") != (
        f"PAPER_ALLOCATOR_CANDIDATE_PIT_CONTEXT:{pit_hash}"
    ):
        reasons.append("CANDIDATE_MARKET_CONTEXT_SOURCE_BINDING_INVALID")
    if receipt.get("status") == "READY" and receipt.get("rejection_reasons") != []:
        reasons.append("CANDIDATE_MARKET_CONTEXT_STATUS_INVALID")
    return sorted(set(reasons))


def _paper_growth_authorization_rejection_reasons(
    authorization_value: Any,
    *,
    arguments: Mapping[str, Any],
    base_material: Mapping[str, Any],
) -> list[str]:
    if not isinstance(authorization_value, Mapping):
        return ["CANDIDATE_GROWTH_AUTHORIZATION_RECEIPT_MISSING"]
    authorization = dict(authorization_value)
    reasons: list[str] = []
    if not _paper_embedded_receipt_hash_valid(authorization):
        reasons.append("CANDIDATE_GROWTH_AUTHORIZATION_HASH_INVALID")
    if authorization.get("schema_version") != "paper_candidate_growth_authorization_receipt_v1":
        reasons.append("CANDIDATE_GROWTH_AUTHORIZATION_SCHEMA_INVALID")
    components_value = authorization.get("component_receipts")
    components = dict(components_value) if isinstance(components_value, Mapping) else {}
    hashes_value = authorization.get("component_receipt_hashes")
    hashes = dict(hashes_value) if isinstance(hashes_value, Mapping) else {}
    required_components = {
        "promoted_checkpoint",
        "strict_after_cost_edge",
        "candidate_market_context",
    }
    if set(components) != required_components or set(hashes) != required_components:
        reasons.append("CANDIDATE_GROWTH_AUTHORIZATION_COMPONENT_SET_INVALID")
    for name in required_components:
        receipt = components.get(name)
        if not _paper_embedded_receipt_hash_valid(receipt):
            reasons.append(f"CANDIDATE_GROWTH_COMPONENT_HASH_INVALID:{name}")
        elif isinstance(receipt, Mapping) and hashes.get(name) != receipt.get("evidence_hash"):
            reasons.append(f"CANDIDATE_GROWTH_COMPONENT_HASH_MISMATCH:{name}")
    checkpoint = components.get("promoted_checkpoint")
    if isinstance(checkpoint, Mapping):
        replayed_checkpoint = _paper_promoted_checkpoint_growth_receipt(
            checkpoint.get("source_material"),
            candidate_checkpoint_id=checkpoint.get("candidate_checkpoint_id"),
            candidate_checkpoint_id_source=checkpoint.get("candidate_checkpoint_id_source"),
            decision_time=checkpoint.get("decision_time"),
        )
        if dict(checkpoint) != replayed_checkpoint:
            reasons.append("PROMOTED_CHECKPOINT_RECEIPT_SEMANTIC_REPLAY_MISMATCH")
    edge = components.get("strict_after_cost_edge")
    if isinstance(edge, Mapping):
        replayed_edge = _paper_strict_after_cost_edge_growth_receipt(
            edge.get("source_material"),
            decision_time=edge.get("decision_time"),
        )
        if dict(edge) != replayed_edge:
            reasons.append("STRICT_AFTER_COST_EDGE_RECEIPT_SEMANTIC_REPLAY_MISMATCH")
    context = components.get("candidate_market_context")
    reasons.extend(_paper_candidate_context_receipt_rejection_reasons(context))
    component_ready = bool(
        len(components) == len(required_components)
        and all(
            isinstance(components.get(name), Mapping)
            and components[name].get("status") == "READY"
            and components[name].get("rejection_reasons") == []
            for name in required_components
        )
    )
    expected_status = "READY" if component_ready else "BLOCKED"
    if authorization.get("status") != expected_status:
        reasons.append("CANDIDATE_GROWTH_AUTHORIZATION_STATUS_MISMATCH")
    if expected_status == "READY" and authorization.get("rejection_reasons") != []:
        reasons.append("CANDIDATE_GROWTH_AUTHORIZATION_READY_REASONS_INVALID")
    if expected_status == "BLOCKED" and not authorization.get("rejection_reasons"):
        reasons.append("CANDIDATE_GROWTH_AUTHORIZATION_BLOCK_REASONS_MISSING")
    if authorization.get("symbol") != arguments.get("symbol"):
        reasons.append("CANDIDATE_GROWTH_AUTHORIZATION_SYMBOL_MISMATCH")
    if authorization.get("decision_time") != arguments.get("decision_time"):
        reasons.append("CANDIDATE_GROWTH_AUTHORIZATION_DECISION_TIME_MISMATCH")
    growth_fields = (
        "win_rate",
        "profit_factor",
        "closed_trade_count",
        "after_cost_edge_lower_bound_bps",
        "after_cost_edge_scale_bps",
        "after_cost_edge_resolution_bps",
        "after_cost_edge_evidence_count",
        "after_cost_edge_evidence_source",
        "edge_available_at",
        "liquidity_score",
        "regime_quality_score",
        "market_context_source",
        "market_context_available_at",
    )
    if expected_status == "READY":
        edge_mapping = dict(edge) if isinstance(edge, Mapping) else {}
        context_mapping = dict(context) if isinstance(context, Mapping) else {}
        edge_material = dict(edge_mapping.get("source_material") or {})
        expected_edge_arguments = {
            "win_rate": edge_material.get("strict_after_cost_edge_win_rate"),
            "profit_factor": edge_material.get("strict_after_cost_edge_profit_factor_numeric"),
            "closed_trade_count": edge_material.get("after_cost_edge_evidence_count"),
            "after_cost_edge_lower_bound_bps": edge_material.get("after_cost_edge_lower_bound_bps"),
            "after_cost_edge_scale_bps": edge_material.get("after_cost_edge_scale_bps"),
            "after_cost_edge_resolution_bps": edge_material.get("after_cost_edge_resolution_bps"),
            "after_cost_edge_evidence_count": edge_material.get("after_cost_edge_evidence_count"),
            "after_cost_edge_evidence_source": edge_material.get("after_cost_edge_evidence_source"),
            "edge_available_at": edge_material.get("after_cost_edge_available_at"),
        }
        expected_context_arguments = {
            "model_avg_confidence": context_mapping.get("candidate_confidence_calibrated"),
            "liquidity_score": context_mapping.get("liquidity_score"),
            "regime_quality_score": context_mapping.get("regime_quality_score"),
            "market_context_source": context_mapping.get("market_context_source"),
            "market_context_available_at": context_mapping.get("market_context_available_at"),
        }
        if any(
            arguments.get(field) != value
            for field, value in {
                **expected_edge_arguments,
                **expected_context_arguments,
            }.items()
        ):
            reasons.append("CANDIDATE_GROWTH_ARGUMENT_BINDING_MISMATCH")
    else:
        if any(arguments.get(field) is not None for field in growth_fields):
            reasons.append("BLOCKED_CANDIDATE_GROWTH_ARGUMENTS_NOT_WITHHELD")
        configured_leverage = _coerce_float(base_material.get("max_effective_leverage"))
        if configured_leverage is None or configured_leverage > 1.0:
            reasons.append("BLOCKED_CANDIDATE_GROWTH_NOT_CAPPED_AT_1X")
    return sorted(set(reasons))


def _paper_dynamic_envelope_semantic_rejection_reasons(
    evidence_value: Any,
) -> list[str]:
    """Recalculate the envelope from its exact bound inputs and base."""

    if not isinstance(evidence_value, Mapping):
        return ["DYNAMIC_ENVELOPE_EVIDENCE_MISSING"]
    calculation = evidence_value.get("calculation_input_material")
    if not isinstance(calculation, Mapping):
        return ["DYNAMIC_ENVELOPE_CALCULATION_INPUT_MISSING"]
    calculation_hash = evidence_value.get("calculation_input_hash")
    reasons: list[str] = []
    calculation_schema = calculation.get("schema_version")
    if (
        calculation_schema
        not in {
            "paper_dynamic_envelope_calculation_input_v1",
            "paper_dynamic_envelope_calculation_input_v2",
        }
        or not _paper_valid_sha256(calculation_hash)
        or calculation_hash != _paper_canonical_sha256(calculation)
    ):
        reasons.append("DYNAMIC_ENVELOPE_CALCULATION_INPUT_HASH_INVALID")
    base_material = calculation.get("base_envelope")
    arguments = calculation.get("arguments")
    if not isinstance(base_material, Mapping) or set(base_material) != set(
        PAPER_DYNAMIC_ENVELOPE_FIELDS
    ):
        reasons.append("DYNAMIC_ENVELOPE_BASE_INPUT_INVALID")
    if not isinstance(arguments, Mapping):
        reasons.append("DYNAMIC_ENVELOPE_ARGUMENTS_INVALID")
    if calculation_schema == "paper_dynamic_envelope_calculation_input_v2":
        authorization = calculation.get("growth_authorization_receipt")
        if not isinstance(authorization, Mapping) or calculation.get(
            "growth_authorization_receipt_hash"
        ) != authorization.get("evidence_hash"):
            reasons.append("CANDIDATE_GROWTH_AUTHORIZATION_BINDING_INVALID")
        elif isinstance(base_material, Mapping) and isinstance(arguments, Mapping):
            reasons.extend(
                _paper_growth_authorization_rejection_reasons(
                    authorization,
                    arguments=arguments,
                    base_material=base_material,
                )
            )
    if reasons:
        return sorted(set(reasons))
    assert isinstance(arguments, Mapping)
    assert isinstance(base_material, Mapping)
    if arguments.get("paper_mode") is not True:
        reasons.append("DYNAMIC_ENVELOPE_NOT_PAPER_MODE")
    try:
        from v2.backend.app.services.adaptive_capital_allocator.contracts import (  # noqa: PLC0415
            RiskEnvelope,
        )
        from v2.backend.app.services.adaptive_capital_allocator.dynamic_envelope import (  # noqa: PLC0415
            calculate_dynamic_risk_envelope,
        )

        base_envelope = RiskEnvelope(
            **{field: base_material[field] for field in PAPER_DYNAMIC_ENVELOPE_FIELDS}
        )
        replayed = calculate_dynamic_risk_envelope(
            base_envelope=base_envelope,
            **dict(arguments),
        )
        replayed_limits = {
            field: getattr(replayed, field) for field in PAPER_DYNAMIC_ENVELOPE_FIELDS
        }
    except (TypeError, ValueError, KeyError):
        reasons.append("DYNAMIC_ENVELOPE_SEMANTIC_REPLAY_FAILED")
        replayed_limits = {}
    if dict(evidence_value.get("limits") or {}) != replayed_limits:
        reasons.append("DYNAMIC_ENVELOPE_SEMANTIC_REPLAY_MISMATCH")
    return sorted(set(reasons))


def _paper_dynamic_envelope_reservation_evidence(
    envelope: Any,
    *,
    evidence: Mapping[str, Any],
    calculation_input_material: Mapping[str, Any],
) -> dict[str, Any]:
    """Bind and replay every input and dynamic limit used by reservation."""

    calculation_material = deepcopy(dict(calculation_input_material))
    material: dict[str, Any] = {
        "schema_version": "paper_dynamic_envelope_reservation_evidence_v1",
        "limits": {
            field: getattr(envelope, field, None) for field in PAPER_DYNAMIC_ENVELOPE_FIELDS
        },
        "source_evidence": dict(evidence),
        "calculation_input_material": calculation_material,
        "calculation_input_hash": _paper_canonical_sha256(calculation_material),
        "paper_only": True,
        "routes_to_live": False,
        "places_real_order": False,
    }
    finite_limits = all(
        value is None
        or (
            (parsed := _coerce_float(value)) is not None and math.isfinite(parsed) and parsed >= 0.0
        )
        for value in material["limits"].values()
    )
    semantic_reasons = _paper_dynamic_envelope_semantic_rejection_reasons(material)
    reasons = list(semantic_reasons)
    if not finite_limits:
        reasons.append("DYNAMIC_ENVELOPE_LIMIT_INVALID")
    material["status"] = "READY" if not reasons else "BLOCKED"
    material["rejection_reasons"] = sorted(set(reasons))
    return {**material, "evidence_hash": _paper_canonical_sha256(material)}


def _paper_candidate_dynamic_envelope_bundle(
    *,
    symbol: str,
    intent: Mapping[str, Any],
    allocation_input: Any,
    point_in_time_evidence: Mapping[str, Any],
    allocation_decision_time: datetime,
    performance_status: Mapping[str, Any],
    trainer_status: Mapping[str, Any] | None,
    candidate_checkpoint_id: Any,
    candidate_checkpoint_id_source: Any,
    current_drawdown_pct: Any,
) -> tuple[Any, dict[str, Any]]:
    """Return one candidate envelope and its fully replayable reservation receipt."""

    from v2.backend.app.services.adaptive_capital_allocator.contracts import (  # noqa: PLC0415
        RiskEnvelope,
    )
    from v2.backend.app.services.adaptive_capital_allocator.dynamic_envelope import (  # noqa: PLC0415
        calculate_dynamic_risk_envelope,
    )
    from v2.backend.app.services.paper_trade_management.leverage_recommendation import (  # noqa: PLC0415
        PAPER_MAX_LEVERAGE,
    )

    decision_time = allocation_decision_time.isoformat(timespec="microseconds").replace(
        "+00:00", "Z"
    )
    checkpoint_receipt = _paper_promoted_checkpoint_growth_receipt(
        trainer_status,
        candidate_checkpoint_id=candidate_checkpoint_id,
        candidate_checkpoint_id_source=candidate_checkpoint_id_source,
        decision_time=decision_time,
    )
    edge_receipt = _paper_strict_after_cost_edge_growth_receipt(
        performance_status,
        decision_time=decision_time,
    )
    context_receipt = _paper_candidate_market_context_growth_receipt(
        intent=intent,
        allocation_input=allocation_input,
        point_in_time_evidence=point_in_time_evidence,
        decision_time=decision_time,
    )
    authorization = _paper_candidate_growth_authorization_receipt(
        symbol=symbol,
        decision_time=decision_time,
        checkpoint_receipt=checkpoint_receipt,
        edge_receipt=edge_receipt,
        market_context_receipt=context_receipt,
    )
    growth_ready = authorization.get("status") == "READY"
    configured_base = replace(
        RiskEnvelope(),
        max_effective_leverage=(float(PAPER_MAX_LEVERAGE) if growth_ready else 1.0),
    )
    edge_material_value = edge_receipt.get("source_material")
    edge_material = dict(edge_material_value) if isinstance(edge_material_value, Mapping) else {}
    arguments: dict[str, Any] = {
        "win_rate": (
            edge_material.get("strict_after_cost_edge_win_rate") if growth_ready else None
        ),
        "profit_factor": (
            edge_material.get("strict_after_cost_edge_profit_factor_numeric")
            if growth_ready
            else None
        ),
        "closed_trade_count": (
            edge_material.get("after_cost_edge_evidence_count") if growth_ready else None
        ),
        "current_drawdown_pct": current_drawdown_pct,
        # The pure envelope's historical parameter name is
        # ``model_avg_confidence``. At candidate scope the exact PIT input is
        # the candidate's calibrated confidence, bound in the context receipt.
        "model_avg_confidence": context_receipt.get("candidate_confidence_calibrated"),
        "paper_mode": True,
        "after_cost_edge_lower_bound_bps": (
            edge_material.get("after_cost_edge_lower_bound_bps") if growth_ready else None
        ),
        "after_cost_edge_scale_bps": (
            edge_material.get("after_cost_edge_scale_bps") if growth_ready else None
        ),
        "after_cost_edge_resolution_bps": (
            edge_material.get("after_cost_edge_resolution_bps") if growth_ready else None
        ),
        "after_cost_edge_evidence_count": (
            edge_material.get("after_cost_edge_evidence_count") if growth_ready else None
        ),
        "after_cost_edge_evidence_source": (
            edge_material.get("after_cost_edge_evidence_source") if growth_ready else None
        ),
        "edge_available_at": (
            edge_material.get("after_cost_edge_available_at") if growth_ready else None
        ),
        "liquidity_score": (context_receipt.get("liquidity_score") if growth_ready else None),
        "regime_quality_score": (
            context_receipt.get("regime_quality_score") if growth_ready else None
        ),
        "market_context_source": (
            context_receipt.get("market_context_source") if growth_ready else None
        ),
        "market_context_available_at": (
            context_receipt.get("market_context_available_at") if growth_ready else None
        ),
        "decision_time": decision_time,
        "symbol": str(symbol or "").strip().upper(),
    }
    calculation_input = {
        "schema_version": "paper_dynamic_envelope_calculation_input_v2",
        "base_envelope": {
            field: getattr(configured_base, field) for field in PAPER_DYNAMIC_ENVELOPE_FIELDS
        },
        "arguments": deepcopy(arguments),
        "growth_authorization_receipt": deepcopy(authorization),
        "growth_authorization_receipt_hash": authorization.get("evidence_hash"),
    }
    envelope = calculate_dynamic_risk_envelope(
        base_envelope=configured_base,
        **arguments,
    )
    computed_at = _utc_iso()
    source_evidence = {
        "candidate_symbol": str(symbol or "").strip().upper(),
        "candidate_checkpoint_id": str(candidate_checkpoint_id or "").strip() or None,
        "candidate_checkpoint_id_source": str(candidate_checkpoint_id_source or "").strip() or None,
        "decision_time": decision_time,
        "computed_at": computed_at,
        "growth_authorization_status": authorization.get("status"),
        "growth_authorization_rejection_reasons": list(
            authorization.get("rejection_reasons") or []
        ),
        "growth_authorization_receipt": deepcopy(authorization),
        "growth_authorization_receipt_hash": authorization.get("evidence_hash"),
        "after_cost_edge_lower_bound_bps": arguments.get("after_cost_edge_lower_bound_bps"),
        "after_cost_edge_scale_bps": arguments.get("after_cost_edge_scale_bps"),
        "after_cost_edge_resolution_bps": arguments.get("after_cost_edge_resolution_bps"),
        "after_cost_edge_evidence_count": arguments.get("after_cost_edge_evidence_count"),
        "after_cost_edge_evidence_source": arguments.get("after_cost_edge_evidence_source"),
        "edge_available_at": arguments.get("edge_available_at"),
        "liquidity_score": arguments.get("liquidity_score"),
        "regime_quality_score": arguments.get("regime_quality_score"),
        "model_avg_confidence": arguments.get("model_avg_confidence"),
        "model_avg_confidence_semantics": (
            "EXACT_CANDIDATE_CALIBRATED_CONFIDENCE_FROM_ALLOCATION_INPUT"
        ),
        "market_context_source": arguments.get("market_context_source"),
        "market_context_available_at": arguments.get("market_context_available_at"),
        "max_effective_leverage": float(envelope.max_effective_leverage),
        "configured_growth_ceiling": float(configured_base.max_effective_leverage),
        "default_operating_baseline": float(RiskEnvelope().max_effective_leverage),
        "missing_or_invalid_growth_evidence_caps_leverage_at_1x": True,
    }
    receipt = _paper_dynamic_envelope_reservation_evidence(
        envelope,
        evidence=source_evidence,
        calculation_input_material=calculation_input,
    )
    return envelope, receipt


def _paper_rebind_cycle_reservation_dynamic_envelope(
    snapshot_value: Any,
    *,
    envelope: Any,
    envelope_receipt: Mapping[str, Any],
) -> tuple[dict[str, Any], list[str]]:
    """Rebind a pure reservation snapshot when every consumed limit is unchanged."""

    if not isinstance(snapshot_value, Mapping):
        return {}, ["CANDIDATE_CYCLE_RESERVATION_SNAPSHOT_MISSING"]
    snapshot = deepcopy(dict(snapshot_value))
    reasons: list[str] = []
    if envelope_receipt.get("status") != "READY" or not _paper_valid_sha256(
        envelope_receipt.get("evidence_hash")
    ):
        reasons.append("CANDIDATE_DYNAMIC_ENVELOPE_RECEIPT_BLOCKED")
    inputs_value = snapshot.get("inputs")
    inputs = dict(inputs_value) if isinstance(inputs_value, Mapping) else {}
    limits_value = inputs.get("dynamic_envelope_limits")
    limits = dict(limits_value) if isinstance(limits_value, Mapping) else {}
    for field in (
        "max_total_portfolio_risk_pct",
        "max_single_symbol_exposure_pct",
        "min_available_margin_buffer_pct",
        "max_daily_drawdown_pct",
        "max_loss_per_trade_pct",
        "emergency_absolute_cap_usdt",
    ):
        if limits.get(field) != getattr(envelope, field, None):
            reasons.append(f"CANDIDATE_DYNAMIC_ENVELOPE_RESERVATION_LIMIT_CHANGED:{field}")
    bindings_value = snapshot.get("evidence_bindings")
    bindings = dict(bindings_value) if isinstance(bindings_value, Mapping) else {}
    if not bindings:
        reasons.append("CANDIDATE_CYCLE_RESERVATION_BINDINGS_MISSING")
    if reasons:
        return {}, sorted(set(reasons))
    bindings["dynamic_envelope_evidence_hash"] = envelope_receipt.get("evidence_hash")
    snapshot["evidence_bindings"] = bindings
    snapshot.pop("snapshot_hash", None)
    snapshot_hash = _paper_canonical_sha256(snapshot)
    if not _paper_valid_sha256(snapshot_hash):
        return {}, ["CANDIDATE_CYCLE_RESERVATION_REBIND_HASH_INVALID"]
    rebound = {**snapshot, "snapshot_hash": snapshot_hash}
    semantic_reasons = list(cycle_reservation_snapshot_rejection_reasons(rebound))
    if semantic_reasons:
        return {}, sorted(set(semantic_reasons))
    return rebound, []


def _paper_lifecycle_exposure_caps_from_dynamic_envelope(
    envelope: Any,
) -> PaperExposureCaps:
    """Project the cycle's adaptive envelope into the lifecycle backstop.

    Lifecycle reconciliation is a late safety check, so it must never fall
    back to looser static base caps after the allocator has contracted risk.
    Invalid dynamic values collapse to zero and therefore fail closed.
    Position-count limits remain the lifecycle's immutable capacity guards.
    """
    max_symbol_pct = _coerce_float(getattr(envelope, "max_single_symbol_exposure_pct", None))
    max_total_pct = _coerce_float(getattr(envelope, "max_total_portfolio_risk_pct", None))
    emergency_cap = _coerce_float(getattr(envelope, "emergency_absolute_cap_usdt", None))
    return PaperExposureCaps(
        max_single_symbol_exposure_pct=(
            max(0.0, max_symbol_pct)
            if max_symbol_pct is not None and math.isfinite(max_symbol_pct)
            else 0.0
        ),
        max_total_paper_exposure_pct=(
            max(0.0, max_total_pct)
            if max_total_pct is not None and math.isfinite(max_total_pct)
            else 0.0
        ),
        emergency_absolute_cap_usdt=(
            max(0.0, emergency_cap)
            if emergency_cap is not None and math.isfinite(emergency_cap)
            else None
        ),
    )


def _paper_symbol_current_mark_gross_exposure(
    *,
    ledger: Mapping[str, Any],
    same_cycle_accepted: list[dict[str, Any]],
    symbol: str,
    mark_price: Any,
) -> dict[str, Any]:
    """Value all current and same-cycle symbol quantities at one fresh mark.

    Gross absolute exposure is deliberately used as a conservative upper
    bound.  It remains safe for adds, reductions, reversals, and conflicting
    rows without pretending those rows form one valid signed net position.
    Missing quantity evidence fails closed instead of falling back to stale
    entry notional.
    """
    canonical_symbol = str(symbol or "").strip().upper()
    mark = _coerce_float(mark_price)
    result = {
        "status": "BLOCKED",
        "symbol": canonical_symbol,
        "mark_price": mark,
        "gross_mark_exposure_usd": None,
        "row_count": 0,
        "same_cycle_row_count": 0,
        "rejection_reasons": [],
        "valuation_contract": "SUM_ABS_QUANTITY_TIMES_CURRENT_MARK",
    }
    if not canonical_symbol:
        result["rejection_reasons"] = ["SYMBOL_MISSING"]
        return result
    if mark is None or not math.isfinite(mark) or mark <= 0.0:
        result["rejection_reasons"] = ["CURRENT_MARK_PRICE_MISSING_OR_INVALID"]
        return result
    ledger_rows = ledger.get("open_positions") or ledger.get("positions") or []
    if not isinstance(ledger_rows, list):
        positions_by_symbol = ledger.get("positions_by_symbol")
        ledger_rows = (
            list(positions_by_symbol.values()) if isinstance(positions_by_symbol, Mapping) else []
        )
    candidates: list[tuple[str, Mapping[str, Any]]] = [
        ("ledger", row) for row in ledger_rows if isinstance(row, Mapping)
    ]
    candidates.extend(
        ("same_cycle", row) for row in same_cycle_accepted if isinstance(row, Mapping)
    )
    gross = 0.0
    rejection_reasons: list[str] = []
    row_count = 0
    same_cycle_count = 0
    for source, row in candidates:
        row_symbol = str(row.get("symbol") or "").strip().upper()
        if row_symbol != canonical_symbol:
            continue
        quantity = _coerce_float(_first_present(row.get("net_quantity"), row.get("quantity")))
        if quantity is None or not math.isfinite(quantity) or quantity == 0.0:
            rejection_reasons.append(f"{source}:MISSING_NONZERO_QUANTITY")
            continue
        gross += abs(quantity) * mark
        row_count += 1
        same_cycle_count += int(source == "same_cycle")
    result.update(
        {
            "status": "READY" if not rejection_reasons else "BLOCKED",
            "gross_mark_exposure_usd": round(gross, 8),
            "row_count": row_count,
            "same_cycle_row_count": same_cycle_count,
            "rejection_reasons": sorted(set(rejection_reasons)),
        }
    )
    return result


def _read_json_any_key(r, key: str) -> Any:
    if r is None:
        return None
    try:
        raw = r.get(key)
    except Exception:
        return None
    if not raw:
        return None
    try:
        return json.loads(raw)
    except (TypeError, ValueError):
        return None


def _parse_epoch_ms(value: Any) -> int | None:
    if value is None or isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        parsed = float(value)
        if parsed != parsed or parsed in (float("inf"), float("-inf")):
            return None
        return int(parsed * 1000) if abs(parsed) < 10_000_000_000 else int(parsed)
    if isinstance(value, str):
        stripped = value.strip()
        if not stripped:
            return None
        try:
            parsed = float(stripped)
        except ValueError:
            try:
                parsed_dt = datetime.fromisoformat(stripped.replace("Z", "+00:00"))
            except (TypeError, ValueError):
                return None
            if parsed_dt.tzinfo is None or parsed_dt.utcoffset() is None:
                return None
            return int(parsed_dt.astimezone(timezone.utc).timestamp() * 1000)
        return int(parsed * 1000) if abs(parsed) < 10_000_000_000 else int(parsed)
    return None


def _correlation_candle_rows_from_payload(payload: Any) -> list[Any]:
    if isinstance(payload, list):
        return [row for row in payload if isinstance(row, (dict, list))]
    if not isinstance(payload, dict):
        return []
    for key in ("candles", "rows", "items", "data", "market_candles"):
        value = payload.get(key)
        if isinstance(value, list):
            return [row for row in value if isinstance(row, (dict, list))]
    if any(key in payload for key in ("close", "close_time", "candle_close_time", "ohlcv")):
        return [dict(payload)]
    return []


def _closed_candle_flag_confirmed(
    row: dict[str, Any],
    *,
    source_key: str | None,
) -> str | None:
    del source_key
    confirmed_fields = sorted(
        field
        for field in (
            "candle_closed_confirmed",
            "closed_candle",
            "is_closed",
            "feature_eligible",
        )
        if row.get(field) is True
    )
    return ",".join(confirmed_fields) if confirmed_fields else None


def _correlation_candle_point(
    row: Any,
    *,
    generated_ms: int | None,
    source_key: str | None,
) -> tuple[int, float, int, str] | str:
    if generated_ms is None:
        return "DECISION_TIME_NOT_AWARE_OR_INVALID"
    available_ms: int | None = None
    if isinstance(row, list) and len(row) > 6:
        close_ms = _parse_epoch_ms(row[6])
        close_value = _coerce_float(row[4])
        finality_evidence = "BINANCE_KLINE_ARRAY_CLOSE_TIME_PASSED"
    elif isinstance(row, dict):
        close_ms = _parse_epoch_ms(
            _first_present(
                row.get("candle_close_time"),
                row.get("close_time"),
                row.get("event_time"),
                row.get("source_sequence_id"),
            )
        )
        ohlcv = row.get("ohlcv") if isinstance(row.get("ohlcv"), dict) else {}
        close_value = _coerce_float(_first_present(row.get("close"), ohlcv.get("close")))
        available_ms = _parse_epoch_ms(
            _first_present(row.get("available_at"), row.get("ingested_at"))
        )
        confirmed_finality_fields = _closed_candle_flag_confirmed(
            row,
            source_key=source_key,
        )
        if confirmed_finality_fields is None:
            return "CANDLE_FINALITY_NOT_EXPLICITLY_CONFIRMED"
        finality_evidence = f"EXPLICIT_FINALITY_FIELDS:{confirmed_finality_fields}"
    else:
        return "UNSUPPORTED_CANDLE_ROW"
    if close_ms is None:
        return "MISSING_CANDLE_CLOSE_TIME"
    if close_ms > generated_ms:
        return "CANDLE_CLOSE_TIME_AFTER_DECISION_TIME"
    if available_ms is None:
        return "MISSING_AVAILABLE_AT"
    if available_ms > generated_ms:
        return "AVAILABLE_AT_AFTER_DECISION_TIME"
    if close_value is None or close_value <= 0.0:
        return "MISSING_OR_NON_POSITIVE_CLOSE"
    return close_ms, close_value, available_ms, finality_evidence


def _correlation_returns_from_candles(
    rows: list[Any],
    *,
    generated_utc: str,
    source_key: str | None,
) -> tuple[dict[int, float], dict[str, Any]]:
    generated_dt = _strict_aware_utc_time(generated_utc)
    generated_ms = int(generated_dt.timestamp() * 1000) if generated_dt else None
    points_by_time: dict[int, float] = {}
    accepted_material_by_time: dict[int, dict[str, Any]] = {}
    rejects: dict[str, int] = {}
    for row in rows:
        point = _correlation_candle_point(row, generated_ms=generated_ms, source_key=source_key)
        if isinstance(point, str):
            rejects[point] = rejects.get(point, 0) + 1
            continue
        close_ms, close_value, available_ms, finality_evidence = point
        points_by_time[close_ms] = close_value
        accepted_material_by_time[close_ms] = {
            "candle_close_time_epoch_ms": close_ms,
            "close": close_value,
            "available_at_epoch_ms": available_ms,
            "finality_evidence": finality_evidence,
        }
    ordered_points = sorted(points_by_time.items())
    returns: dict[int, float] = {}
    previous_close: float | None = None
    for close_ms, close_value in ordered_points:
        if previous_close and previous_close > 0.0:
            returns[close_ms] = (close_value / previous_close) - 1.0
        previous_close = close_value
    last_close_ms = ordered_points[-1][0] if ordered_points else None
    max_available_ms = (
        max(
            int(material["available_at_epoch_ms"])
            for material in accepted_material_by_time.values()
        )
        if accepted_material_by_time
        else None
    )
    age_seconds = None
    if generated_ms and last_close_ms is not None:
        age_seconds = max(0.0, (generated_ms - last_close_ms) / 1000.0)
    diagnostics = {
        "source": source_key,
        "raw_candle_count": len(rows),
        "accepted_candle_count": len(ordered_points),
        "return_count": len(returns),
        "last_candle_age_seconds": round(age_seconds, 3) if age_seconds is not None else None,
        "feature_cutoff": (
            datetime.fromtimestamp(last_close_ms / 1000.0, tz=timezone.utc)
            .isoformat()
            .replace("+00:00", "Z")
            if last_close_ms is not None
            else None
        ),
        "source_available_at": (
            datetime.fromtimestamp(max_available_ms / 1000.0, tz=timezone.utc)
            .isoformat()
            .replace("+00:00", "Z")
            if max_available_ms is not None
            else None
        ),
        "decision_time": generated_utc,
        "source_hash": _paper_canonical_sha256(
            {
                "schema_version": "paper_correlation_accepted_source_material_v2",
                "source_key": source_key,
                "decision_time": generated_utc,
                "accepted_points": [
                    accepted_material_by_time[close_ms] for close_ms, _close_value in ordered_points
                ],
                "reject_counts": dict(sorted(rejects.items())),
            }
        ),
        "source_hash_contract": CORRELATION_CHILD_SOURCE_HASH_CONTRACT,
        "reject_counts": rejects,
    }
    return returns, diagnostics


def _pearson_correlation(left: list[float], right: list[float]) -> float | None:
    if len(left) != len(right) or len(left) < CORRELATION_MIN_RETURN_POINTS:
        return None
    left_mean = sum(left) / len(left)
    right_mean = sum(right) / len(right)
    covariance = sum((x - left_mean) * (y - right_mean) for x, y in zip(left, right))
    left_var = sum((x - left_mean) ** 2 for x in left)
    right_var = sum((y - right_mean) ** 2 for y in right)
    if left_var <= 0.0 or right_var <= 0.0:
        return None
    return covariance / ((left_var * right_var) ** 0.5)


def _read_symbol_correlation_returns(
    r,
    symbol: str,
    *,
    generated_utc: str,
) -> tuple[dict[int, float] | None, dict[str, Any]]:
    normalized = symbol.upper()
    candidate_keys = (
        f"{V2_REDIS_PREFIX}market:ohlcv_closed:binance:{normalized}:{CORRELATION_CANDLE_TIMEFRAME}",
        f"{V2_REDIS_PREFIX}market:ohlcv:binance:{normalized}:{CORRELATION_CANDLE_TIMEFRAME}",
    )
    last_rejected_diagnostics: dict[str, Any] | None = None
    for key in candidate_keys:
        rows = _correlation_candle_rows_from_payload(_read_json_any_key(r, key))
        if not rows:
            continue
        returns, diagnostics = _correlation_returns_from_candles(
            rows,
            generated_utc=generated_utc,
            source_key=key,
        )
        age = _coerce_float(diagnostics.get("last_candle_age_seconds"))
        if age is None:
            diagnostics["status"] = "MISSING_ACCEPTED_CANDLES"
            last_rejected_diagnostics = diagnostics
            continue
        if age > CORRELATION_MAX_CANDLE_AGE_SECONDS:
            diagnostics["status"] = "STALE_LAST_CANDLE"
            last_rejected_diagnostics = diagnostics
            continue
        if len(returns) < CORRELATION_MIN_RETURN_POINTS:
            diagnostics["status"] = "INSUFFICIENT_RETURN_POINTS"
            last_rejected_diagnostics = diagnostics
            continue
        diagnostics["status"] = "READY"
        return returns, diagnostics
    if last_rejected_diagnostics is not None:
        return None, last_rejected_diagnostics
    return None, {
        "source": None,
        "status": "MISSING_MARKET_CANDLES",
        "raw_candle_count": 0,
        "accepted_candle_count": 0,
        "return_count": 0,
    }


def _derive_candidate_correlation_contexts(
    r,
    *,
    candidate_symbols: list[str],
    open_symbols: list[str],
    generated_utc: str,
) -> dict[str, dict[str, Any]]:
    unique_open_symbols = sorted({symbol.upper() for symbol in open_symbols if symbol})
    unique_candidate_symbols = sorted({symbol.upper() for symbol in candidate_symbols if symbol})
    if not unique_open_symbols:
        observed_at = _utc_iso()
        empty_source_material = {
            "schema_version": "paper_correlation_aggregate_source_material_v1",
            "decision_time": generated_utc,
            "candidate_symbols": unique_candidate_symbols,
            "open_symbols": [],
            "child_sources": [],
        }
        empty_source_hash = _paper_canonical_sha256(empty_source_material)
        return {
            symbol: {
                "correlation_exposure_pct": 0.0,
                "correlation_input_status": "NO_OPEN_POSITIONS",
                "correlation_input_source": "NO_OPEN_POSITIONS",
                "correlation_pair_count": 0,
                "correlation_required_pair_count": 0,
                "correlation_unresolved_open_symbols": [],
                "correlation_decision_time": generated_utc,
                "correlation_source_available_at": None,
                "correlation_computed_at": observed_at,
                "correlation_feature_cutoff": None,
                "correlation_source_hash": empty_source_hash,
                "correlation_source_hash_contract": (CORRELATION_AGGREGATE_SOURCE_HASH_CONTRACT),
                "correlation_source_material": empty_source_material,
                "correlation_source_child_count": 0,
            }
            for symbol in unique_candidate_symbols
        }
    returns_by_symbol: dict[str, dict[int, float]] = {}
    diagnostics_by_symbol: dict[str, Any] = {}
    for symbol in sorted(set(unique_open_symbols) | set(unique_candidate_symbols)):
        returns, diagnostics = _read_symbol_correlation_returns(
            r,
            symbol,
            generated_utc=generated_utc,
        )
        diagnostics_by_symbol[symbol] = diagnostics
        if returns is not None:
            returns_by_symbol[symbol] = returns
    contexts: dict[str, dict[str, Any]] = {}
    for symbol in unique_candidate_symbols:
        required_pair_symbols = [
            open_symbol for open_symbol in unique_open_symbols if open_symbol != symbol
        ]
        candidate_returns = returns_by_symbol.get(symbol)
        if candidate_returns is None:
            contexts[symbol] = {
                "correlation_exposure_pct": CORRELATION_FAIL_CLOSED_EXPOSURE_PCT,
                "correlation_input_status": diagnostics_by_symbol.get(symbol, {}).get(
                    "status", "MISSING_MARKET_CANDLES"
                ),
                "correlation_input_source": "MISSING_CANDIDATE_RETURNS_FAIL_CLOSED",
                "correlation_pair_count": 0,
                "correlation_required_pair_count": len(required_pair_symbols),
                "correlation_unresolved_open_symbols": required_pair_symbols,
                "correlation_diagnostics": diagnostics_by_symbol.get(symbol, {}),
            }
            continue
        max_abs_correlation: float | None = None
        pair_count = 0
        unresolved_pair_symbols: list[str] = []
        for open_symbol in required_pair_symbols:
            open_returns = returns_by_symbol.get(open_symbol)
            if open_returns is None:
                unresolved_pair_symbols.append(open_symbol)
                continue
            common_times = sorted(set(candidate_returns) & set(open_returns))
            if len(common_times) < CORRELATION_MIN_RETURN_POINTS:
                unresolved_pair_symbols.append(open_symbol)
                continue
            correlation = _pearson_correlation(
                [candidate_returns[close_time] for close_time in common_times],
                [open_returns[close_time] for close_time in common_times],
            )
            if correlation is None:
                unresolved_pair_symbols.append(open_symbol)
                continue
            pair_count += 1
            abs_correlation = abs(correlation)
            max_abs_correlation = (
                abs_correlation
                if max_abs_correlation is None
                else max(max_abs_correlation, abs_correlation)
            )
        if unresolved_pair_symbols:
            contexts[symbol] = {
                "correlation_exposure_pct": CORRELATION_FAIL_CLOSED_EXPOSURE_PCT,
                "correlation_input_status": "INCOMPLETE_REQUIRED_OPEN_PAIR_COVERAGE",
                "correlation_input_source": "MISSING_PAIRWISE_RETURNS_FAIL_CLOSED",
                "correlation_pair_count": pair_count,
                "correlation_required_pair_count": len(required_pair_symbols),
                "correlation_unresolved_open_symbols": sorted(set(unresolved_pair_symbols)),
                "correlation_diagnostics": diagnostics_by_symbol.get(symbol, {}),
            }
            continue
        if max_abs_correlation is None:
            if len(unique_open_symbols) == 1 and unique_open_symbols[0] == symbol:
                contexts[symbol] = {
                    "correlation_exposure_pct": 0.0,
                    "correlation_input_status": "ONLY_SAME_SYMBOL_OPEN",
                    "correlation_input_source": "SYMBOL_EXPOSURE_BUDGET_HANDLES_SELF_EXPOSURE",
                    "correlation_pair_count": 0,
                    "correlation_required_pair_count": 0,
                    "correlation_unresolved_open_symbols": [],
                    "correlation_diagnostics": diagnostics_by_symbol.get(symbol, {}),
                }
            else:
                contexts[symbol] = {
                    "correlation_exposure_pct": CORRELATION_FAIL_CLOSED_EXPOSURE_PCT,
                    "correlation_input_status": "INSUFFICIENT_ALIGNED_OPEN_RETURNS",
                    "correlation_input_source": "MISSING_PAIRWISE_RETURNS_FAIL_CLOSED",
                    "correlation_pair_count": pair_count,
                    "correlation_required_pair_count": len(required_pair_symbols),
                    "correlation_unresolved_open_symbols": required_pair_symbols,
                    "correlation_diagnostics": diagnostics_by_symbol.get(symbol, {}),
                }
            continue
        contexts[symbol] = {
            "correlation_exposure_pct": round(max_abs_correlation, 8),
            "correlation_input_status": "READY",
            "correlation_input_source": "MARKET_OHLCV_RETURN_CORRELATION",
            "correlation_pair_count": pair_count,
            "correlation_required_pair_count": len(required_pair_symbols),
            "correlation_unresolved_open_symbols": [],
            "correlation_diagnostics": diagnostics_by_symbol.get(symbol, {}),
        }
    observed_at = _utc_iso()
    feature_cutoffs = [
        parsed
        for diagnostics in diagnostics_by_symbol.values()
        if isinstance(diagnostics, Mapping)
        and (parsed := _strict_aware_utc_time(diagnostics.get("feature_cutoff"))) is not None
    ]
    governing_feature_cutoff = (
        max(feature_cutoffs).isoformat().replace("+00:00", "Z") if feature_cutoffs else None
    )
    source_available_times = [
        parsed
        for diagnostics in diagnostics_by_symbol.values()
        if isinstance(diagnostics, Mapping)
        and (parsed := _strict_aware_utc_time(diagnostics.get("source_available_at"))) is not None
    ]
    governing_source_available_at = (
        max(source_available_times).isoformat().replace("+00:00", "Z")
        if source_available_times
        else None
    )
    child_source_material = [
        {
            "symbol": symbol,
            "source_key": diagnostics.get("source"),
            "status": diagnostics.get("status"),
            "source_hash": diagnostics.get("source_hash"),
            "source_hash_contract": diagnostics.get("source_hash_contract"),
            "feature_cutoff": diagnostics.get("feature_cutoff"),
            "source_available_at": diagnostics.get("source_available_at"),
            "raw_candle_count": diagnostics.get("raw_candle_count"),
            "accepted_candle_count": diagnostics.get("accepted_candle_count"),
            "return_count": diagnostics.get("return_count"),
        }
        for symbol, diagnostics in sorted(diagnostics_by_symbol.items())
        if isinstance(diagnostics, Mapping)
    ]
    aggregate_source_material = {
        "schema_version": "paper_correlation_aggregate_source_material_v1",
        "decision_time": generated_utc,
        "candidate_symbols": unique_candidate_symbols,
        "open_symbols": unique_open_symbols,
        "child_sources": child_source_material,
    }
    governing_source_hash = _paper_canonical_sha256(aggregate_source_material)
    for context in contexts.values():
        context["correlation_decision_time"] = generated_utc
        context["correlation_source_available_at"] = governing_source_available_at
        context["correlation_computed_at"] = observed_at
        context["correlation_feature_cutoff"] = governing_feature_cutoff
        context["correlation_source_hash"] = governing_source_hash
        context["correlation_source_hash_contract"] = CORRELATION_AGGREGATE_SOURCE_HASH_CONTRACT
        context["correlation_source_material"] = aggregate_source_material
        context["correlation_source_child_count"] = len(child_source_material)
    return contexts


def _derive_position_state(existing_ledger: dict[str, Any], symbol: str) -> str:
    """Return the current open position state for one symbol.

    The paper ledger intentionally keeps historical accepted fills for
    reconciliation and trainer feedback. Those historical rows must not be
    treated as current inventory when the strategy router checks whether a new
    long/short transition is valid.
    """
    wanted = symbol.upper()
    candidates: list[dict[str, Any]] = []
    for row in existing_ledger.get("open_positions") or existing_ledger.get("positions") or []:
        if not isinstance(row, dict):
            continue
        if str(row.get("symbol") or "").upper() != wanted:
            continue
        state = str(row.get("position_state") or "").upper()
        if state in {"CLOSED_POSITION", "CLOSED", "FLAT", "NO_OPEN_POSITION"}:
            continue
        quantity = _coerce_float(_first_present(row.get("net_quantity"), row.get("quantity")))
        if quantity is not None and abs(quantity) <= 1e-12:
            continue
        candidates.append(row)
    if not candidates:
        return "FLAT"
    sides = {
        str(_first_present(row.get("side"), row.get("selected_action")) or "").lower()
        for row in candidates
    }
    sides.discard("")
    if len(sides) > 1:
        return "INVALID_CONFLICTING_OPEN_POSITIONS"
    candidates.sort(
        key=lambda row: (
            _first_present(
                row.get("generated_utc"),
                row.get("fill_price_utc"),
                row.get("entry_price_utc"),
            )
            or "",
            row.get("signal_id") or "",
        )
    )
    latest = candidates[-1]
    state = str(latest.get("position_state") or "").upper()
    if state in {"LONG", "SHORT", "FLAT"}:
        return state
    side = str(_first_present(latest.get("side"), latest.get("selected_action")) or "").lower()
    if side == "long":
        return "LONG"
    if side == "short":
        return "SHORT"
    return "INVALID_OPEN_POSITION_SIDE_MISSING"


def _read_recent_execution_metrics(r) -> dict[str, Any]:
    ledger = _read_existing_ledger_payload(r)
    accepted = int(ledger.get("accepted_count") or 0)
    blocked = int(ledger.get("blocked_count") or 0)
    shadow = int(ledger.get("shadow_observation_count") or 0)
    raw_outcomes = [
        row
        for row in ledger.get("outcome_labels") or ledger.get("closed_trades") or []
        if isinstance(row, dict)
        and row.get("winner") is not None
        and row.get("realized_pnl_bps") is not None
    ]
    outcomes = [row for row in raw_outcomes if _closed_outcome_is_alpha_complete(row)]
    clean_outcome_ids = {id(row) for row in outcomes}
    dirty_outcomes = [row for row in raw_outcomes if id(row) not in clean_outcome_ids]
    if outcomes:
        wins = sum(1 for row in outcomes if row.get("winner") is True)
        attempts = len(outcomes)
        success_probability = wins / attempts
        metric_source = "V2_PAPER_CLOSED_TRADE_OUTCOMES_ALPHA_COMPLETE"
        sample_status = "ALPHA_COMPLETE_OUTCOME_SAMPLE"
    elif raw_outcomes:
        attempts = 0
        success_probability = None
        metric_source = "INSUFFICIENT_ALPHA_FEEDBACK_OUTCOMES"
        sample_status = "DIRTY_OUTCOMES_QUARANTINED"
    else:
        attempts = accepted + blocked + shadow
        success_probability = 1.0 if attempts <= 0 else accepted / attempts
        metric_source = "V2_PAPER_ACCEPTED_BLOCKED_FALLBACK"
        sample_status = "NO_CLOSED_OUTCOMES_FALLBACK"
    return {
        "accepted_count": accepted,
        "blocked_count": blocked,
        "shadow_observation_count": shadow,
        "closed_trade_outcome_count": len(outcomes),
        "clean_closed_trade_outcome_count": len(outcomes),
        "dirty_closed_trade_outcome_count": len(dirty_outcomes),
        "raw_closed_trade_outcome_count": len(raw_outcomes),
        "execution_success_probability": round(success_probability, 6)
        if success_probability is not None
        else None,
        "execution_success_metric_source": metric_source,
        "execution_success_sample_status": sample_status,
    }


def _closed_outcome_is_alpha_complete(row: dict[str, Any]) -> bool:
    if row.get("winner") is None or row.get("realized_pnl_bps") is None:
        return False
    return all(
        row.get(field) not in (None, "") for field in REQUIRED_FEEDBACK_FIELDS
    ) and not audit_quality_rejection_reasons(row)


def _paper_current_risk_state_from_sources(
    source_materials: Mapping[str, Any],
) -> dict[str, Any]:
    position_source = source_materials.get("paper_position_or_ledger_source")
    position_material = position_source if isinstance(position_source, Mapping) else {}
    position_payload = position_material.get("payload")
    if isinstance(position_payload, list):
        open_rows = [row for row in position_payload if isinstance(row, dict)]
    elif isinstance(position_payload, Mapping):
        ledger = dict(position_payload)
        ledger_rows = ledger.get("open_positions")
        if not isinstance(ledger_rows, list):
            ledger_rows = ledger.get("positions")
        if not isinstance(ledger_rows, list):
            by_symbol = ledger.get("positions_by_symbol")
            ledger_rows = list(by_symbol.values()) if isinstance(by_symbol, Mapping) else []
        open_rows = [row for row in ledger_rows if isinstance(row, dict)]
    else:
        open_rows = []
    portfolio_source = source_materials.get("portfolio_state_source")
    portfolio_material = portfolio_source if isinstance(portfolio_source, Mapping) else {}
    portfolio_payload = portfolio_material.get("payload")
    portfolio = dict(portfolio_payload) if isinstance(portfolio_payload, Mapping) else {}
    portfolio_drawdown = _coerce_float(portfolio.get("current_drawdown_bps"))
    open_position_drawdowns: list[float] = []
    for row in open_rows:
        row_drawdown = _coerce_float(
            _first_present(row.get("drawdown_bps"), row.get("max_drawdown_bps"), row.get("mae_bps"))
        )
        if row_drawdown is not None:
            open_position_drawdowns.append(abs(row_drawdown))
        unrealized_bps = _coerce_float(row.get("unrealized_pnl_bps"))
        if unrealized_bps is not None and unrealized_bps < 0:
            open_position_drawdowns.append(abs(unrealized_bps))
    worst_open_position_drawdown = max(open_position_drawdowns) if open_position_drawdowns else 0.0
    current_drawdown = (
        abs(portfolio_drawdown) if portfolio_drawdown is not None else worst_open_position_drawdown
    )
    return {
        "current_drawdown_bps": current_drawdown,
        "current_drawdown_source": (
            "CURRENT_PORTFOLIO_STATE"
            if portfolio_drawdown is not None
            else "OPEN_POSITION_DRAWDOWN_FALLBACK"
        ),
        "worst_open_position_drawdown_bps": worst_open_position_drawdown,
        "open_position_drawdown_source": "OPEN_POSITION_MAE_AND_UNREALIZED_LOSS",
        "open_position_count": len(open_rows),
        "position_source_key": position_material.get("source_key"),
        "portfolio_source_key": portfolio_material.get("source_key"),
    }


def _paper_ledger_with_exact_safety_sources(
    ledger: Mapping[str, Any] | None,
    source_materials: Mapping[str, Any],
) -> dict[str, Any]:
    """Override file/fallback safety rows with the exact frozen Redis reads."""

    merged = dict(ledger) if isinstance(ledger, Mapping) else {}
    position_material = source_materials.get("paper_position_or_ledger_source")
    position_source = position_material if isinstance(position_material, Mapping) else {}
    if position_source.get("read_status") == "READY":
        position_payload = position_source.get("payload")
        if isinstance(position_payload, list):
            open_rows = [dict(row) for row in position_payload if isinstance(row, Mapping)]
        elif isinstance(position_payload, Mapping):
            raw_open_rows = position_payload.get("open_positions")
            if not isinstance(raw_open_rows, list):
                raw_open_rows = position_payload.get("positions")
            if not isinstance(raw_open_rows, list):
                positions_by_symbol = position_payload.get("positions_by_symbol")
                raw_open_rows = (
                    list(positions_by_symbol.values())
                    if isinstance(positions_by_symbol, Mapping)
                    else []
                )
            open_rows = [dict(row) for row in raw_open_rows if isinstance(row, Mapping)]
        else:
            open_rows = []
        merged["open_positions"] = open_rows
        merged["positions"] = open_rows
        merged["positions_by_symbol"] = {
            (
                f"{str(row.get('symbol') or '').upper()}::HEDGE"
                if row.get("hedge_parent_id")
                and str(row.get("hedge_state") or "").upper() == "HEDGE_CHILD"
                else str(row.get("symbol") or "").upper()
            ): row
            for row in open_rows
            if row.get("symbol") not in (None, "")
        }
        merged["open_position_count"] = len(open_rows)

    closed_material = source_materials.get("paper_closed_trades_source")
    closed_source = closed_material if isinstance(closed_material, Mapping) else {}
    if closed_source.get("read_status") == "READY" and isinstance(
        closed_source.get("payload"), list
    ):
        closed_rows = [dict(row) for row in closed_source["payload"] if isinstance(row, Mapping)]
        merged["closed_trades"] = closed_rows
        merged["closes"] = closed_rows
        merged["closed_trade_count"] = len(closed_rows)
    merged["exact_safety_position_source_key"] = position_source.get("source_key")
    merged["exact_safety_closed_trade_source_key"] = closed_source.get("source_key")
    return merged


def _read_current_risk_state(r) -> dict[str, Any]:
    return _paper_current_risk_state_from_sources(_paper_revocable_control_source_materials(r))


def _build_market_state_envelope(
    *,
    signal: dict[str, Any],
    prediction: dict[str, Any],
) -> dict[str, Any]:
    explicit_decision_time = _first_present(
        prediction.get("decision_time"),
        signal.get("decision_time"),
        signal.get("entry_feature_decision_time"),
    )
    explicit_available_at = _first_present(
        prediction.get("available_at"),
        signal.get("available_at"),
        signal.get("entry_feature_available_at"),
    )
    explicit_feature_cutoff = _first_present(
        prediction.get("feature_cutoff"),
        signal.get("feature_cutoff"),
        signal.get("entry_feature_cutoff"),
    )
    decision_dt = _strict_aware_utc_time(explicit_decision_time)
    available_dt = _strict_aware_utc_time(explicit_available_at)
    cutoff_dt = _strict_aware_utc_time(explicit_feature_cutoff)
    temporal_reasons: list[str] = []
    for field, value, parsed in (
        ("strategy_decision_time", explicit_decision_time, decision_dt),
        ("strategy_available_at", explicit_available_at, available_dt),
        ("strategy_feature_cutoff", explicit_feature_cutoff, cutoff_dt),
    ):
        if value in (None, ""):
            temporal_reasons.append(f"MISSING:{field}")
        elif parsed is None:
            temporal_reasons.append(f"UNPARSEABLE_OR_NAIVE:{field}")
    if decision_dt is not None and available_dt is not None and available_dt > decision_dt:
        temporal_reasons.append("STRATEGY_AVAILABLE_AT_AFTER_DECISION_TIME")
    if decision_dt is not None and cutoff_dt is not None and cutoff_dt > decision_dt:
        temporal_reasons.append("STRATEGY_FEATURE_CUTOFF_AFTER_DECISION_TIME")
    envelope = {
        "symbol": _first_present(signal.get("symbol"), prediction.get("symbol")),
        "exchange": _first_present(signal.get("exchange"), prediction.get("exchange"), "unknown"),
        "decision_time": _first_present(
            prediction.get("decision_time"),
            prediction.get("decision_cutoff"),
            prediction.get("feature_cutoff"),
            prediction.get("generated_utc"),
            prediction.get("generated_at"),
            signal.get("decision_time"),
            signal.get("decision_cutoff"),
            signal.get("generated_utc"),
        ),
        "event_time": _first_present(
            prediction.get("source_event_time_utc"),
            prediction.get("event_time"),
            prediction.get("generated_utc"),
        ),
        "available_at": _first_present(
            prediction.get("available_at"),
            prediction.get("generated_utc"),
            prediction.get("generated_at"),
        ),
        "ingested_at": _first_present(
            prediction.get("ingested_at"),
            prediction.get("generated_utc"),
            prediction.get("generated_at"),
        ),
        "feature_cutoff": _first_present(
            prediction.get("feature_cutoff"),
            prediction.get("generated_utc"),
            prediction.get("generated_at"),
        ),
        "prediction_id": _first_present(
            signal.get("prediction_id"), prediction.get("prediction_id")
        ),
        "timeframe": _first_present(signal.get("timeframe"), prediction.get("timeframe")),
        "market_state_integrity_score": _first_present(
            signal.get("market_state_integrity_score"),
            prediction.get("market_state_integrity_score"),
        ),
        "data_quality_score": _first_present(
            signal.get("market_state_integrity_score"),
            prediction.get("market_state_integrity_score"),
        ),
        "data_quality_flags": list(
            signal.get("market_state_reject_reasons")
            or prediction.get("market_state_reject_reasons")
            or []
        ),
        "confidence_calibrated": _first_present(
            signal.get("confidence_calibrated"),
            prediction.get("confidence_calibrated"),
        ),
        "action_probabilities": _first_present(
            prediction.get("action_probabilities"),
            prediction.get("policy_action_probabilities"),
        ),
        "expected_move_after_cost_bps": _paper_expected_move_after_cost_value(
            signal,
            prediction,
        ),
        "expected_move_after_cost_bps_directional": (
            _paper_directional_expected_move_after_cost_value(signal, prediction)
        ),
        "ppo_confidence": _first_present(
            signal.get("confidence_calibrated"),
            prediction.get("confidence_calibrated"),
        ),
        "paper_only": True,
        "mode": "paper",
        "live_allowed": False,
        "paper_major_move_candidate": bool(
            _first_present(
                signal.get("paper_major_move_candidate"),
                prediction.get("paper_major_move_candidate"),
                signal.get("major_move_signal_id"),
                prediction.get("major_move_signal_id"),
            )
        ),
        "major_move_signal_id": _first_present(
            signal.get("major_move_signal_id"), prediction.get("major_move_signal_id")
        ),
        "major_move_direction": _first_present(
            signal.get("major_move_direction"),
            prediction.get("major_move_direction"),
            signal.get("side"),
            signal.get("selected_action"),
            prediction.get("selected_action"),
        ),
        "major_move_evidence_score": _first_present(
            signal.get("major_move_evidence_score"),
            prediction.get("major_move_evidence_score"),
            signal.get("squeeze_evidence_score"),
            prediction.get("squeeze_evidence_score"),
        ),
        "squeeze_evidence_score": _first_present(
            signal.get("squeeze_evidence_score"), prediction.get("squeeze_evidence_score")
        ),
        "strategy_temporal_contract_status": ("PASS" if not temporal_reasons else "BLOCKED"),
        "strategy_temporal_contract_rejection_reasons": sorted(set(temporal_reasons)),
        "strategy_explicit_decision_time": explicit_decision_time,
        "strategy_explicit_available_at": explicit_available_at,
        "strategy_explicit_feature_cutoff": explicit_feature_cutoff,
    }
    for field in (
        "trend_strength",
        "htf_trend_strength",
        "range_chop_score",
        "chop_score",
        "range_score",
        "volatility_expansion",
        "atr_percentile",
        "fakeout_reversal_probability",
        "cross_asset_btc_eth_sol_regime",
        "cross_asset_regime",
        "market_wide_risk",
        "risk_on_risk_off",
        "expected_slippage_bps",
        "public_orderbook_trust_score",
        "composite_microstructure_trust_score",
        "microstructure_trust_score",
        "orderbook_trust_score",
        "microstructure_action",
        "final_a_plus_min_composite_trust",
        "final_a_plus_eligible",
        "non_book_confirmation_pass",
        "composite_confirmation_missing_fields",
        "reduced_size_bootstrap_tier",
        "bootstrap_reduced_size_paper_only",
        "sweep_risk",
        "sweep_risk_score",
        "cross_venue_confirmation_score",
        "trade_tape_confirmation_score",
    ):
        value = _first_present(signal.get(field), prediction.get(field))
        if value not in (None, ""):
            envelope[field] = value
    for context_field in (
        "liquidity_context",
        "liquidation_context",
        "liquidation_distance_context",
        "microstructure_context",
        "oi_funding_context",
        "public_intel_context",
    ):
        value = _first_present(signal.get(context_field), prediction.get(context_field))
        if isinstance(value, dict):
            envelope[context_field] = dict(value)
    return envelope


def _validated_strategy_cascade_context(
    payload: Mapping[str, Any] | None,
    *,
    strategy_decision_time: Any,
) -> tuple[dict[str, Any] | None, dict[str, Any]]:
    """Validate cascade/squeeze context before it can affect strategy routing."""

    base = {
        "strategy_cascade_context_status": "MISSING",
        "strategy_cascade_context_rejection_reasons": [],
        "strategy_cascade_event_time": None,
        "strategy_cascade_available_at": None,
        "strategy_cascade_generated_at": None,
        "strategy_cascade_decision_time": None,
        "strategy_cascade_feature_cutoff": None,
    }
    if not isinstance(payload, Mapping) or not payload:
        return None, base
    context = dict(payload)
    raw_times = {
        "event_time": context.get("event_time"),
        "available_at": context.get("available_at"),
        "generated_at": _first_present(
            context.get("generated_at"),
            context.get("generated_utc"),
        ),
        "decision_time": context.get("decision_time"),
        "feature_cutoff": _first_present(
            context.get("feature_cutoff"),
            context.get("event_time"),
        ),
    }
    parsed = {key: _strict_aware_utc_time(value) for key, value in raw_times.items()}
    consumer_decision = _strict_aware_utc_time(strategy_decision_time)
    reasons: list[str] = []
    for field in ("event_time", "available_at", "generated_at", "decision_time"):
        if raw_times[field] in (None, ""):
            reasons.append(f"MISSING_STRATEGY_CASCADE_{field.upper()}")
        elif parsed[field] is None:
            reasons.append(f"UNPARSEABLE_OR_NAIVE_STRATEGY_CASCADE_{field.upper()}")
    if consumer_decision is None:
        reasons.append("STRATEGY_DECISION_TIME_UNPROVEN_FOR_CASCADE")
    if (
        parsed["available_at"] is not None
        and parsed["decision_time"] is not None
        and parsed["available_at"] > parsed["decision_time"]
    ):
        reasons.append("STRATEGY_CASCADE_AVAILABLE_AFTER_SOURCE_DECISION")
    if (
        parsed["feature_cutoff"] is not None
        and parsed["decision_time"] is not None
        and parsed["feature_cutoff"] > parsed["decision_time"]
    ):
        reasons.append("STRATEGY_CASCADE_FEATURE_CUTOFF_AFTER_SOURCE_DECISION")
    if consumer_decision is not None:
        for field in ("available_at", "generated_at", "decision_time"):
            if parsed[field] is not None and parsed[field] > consumer_decision:
                reasons.append(f"STRATEGY_CASCADE_{field.upper()}_AFTER_STRATEGY_DECISION")
    status = {
        **base,
        "strategy_cascade_context_status": (
            "ATTACHED_PIT_VALID" if not reasons else "REJECTED_PIT_INVALID"
        ),
        "strategy_cascade_context_rejection_reasons": sorted(set(reasons)),
        "strategy_cascade_event_time": raw_times["event_time"],
        "strategy_cascade_available_at": raw_times["available_at"],
        "strategy_cascade_generated_at": raw_times["generated_at"],
        "strategy_cascade_decision_time": raw_times["decision_time"],
        "strategy_cascade_feature_cutoff": raw_times["feature_cutoff"],
    }
    return (context if not reasons else None), status


def _feature_snapshot_features(feature_snapshot: dict[str, Any] | None) -> dict[str, Any]:
    if not isinstance(feature_snapshot, dict):
        return {}
    features = feature_snapshot.get("features")
    return features if isinstance(features, dict) else {}


def _strategy_feature_snapshot_number(
    features: dict[str, Any],
    *keys: str,
) -> tuple[float | None, str | None]:
    for key in keys:
        value = _coerce_float(features.get(key))
        if value is not None:
            return value, key
    return None, None


def _strategy_score01_from_percent(value: float | None) -> float | None:
    if value is None:
        return None
    if value > 1.0:
        value = value / 100.0
    return max(0.0, min(1.0, float(value)))


def _strategy_snapshot_aggressive_flow(features: dict[str, Any]) -> tuple[float | None, str | None]:
    taker_quote = _coerce_float(features.get("taker_buy_quote_vol"))
    quote_volume = _coerce_float(features.get("quote_volume"))
    if taker_quote is not None and quote_volume is not None and quote_volume > 0.0:
        return max(
            -1.0, min(1.0, (taker_quote / quote_volume - 0.5) * 2.0)
        ), "taker_buy_quote_vol/quote_volume"
    taker_base = _coerce_float(features.get("taker_buy_base_vol"))
    volume = _coerce_float(features.get("volume"))
    if taker_base is not None and volume is not None and volume > 0.0:
        return max(-1.0, min(1.0, (taker_base / volume - 0.5) * 2.0)), "taker_buy_base_vol/volume"
    return None, None


def _strategy_snapshot_nearest_liquidation_bps(
    features: dict[str, Any],
) -> tuple[float | None, str | None]:
    candidates: list[tuple[float, str]] = []
    for key in (
        "liquidation_sweep_target_short_distance_bps",
        "liquidation_sweep_target_long_distance_bps",
    ):
        value = _coerce_float(features.get(key))
        if value is not None:
            candidates.append((abs(value), key))
    if candidates:
        return min(candidates, key=lambda item: item[0])
    pct_candidates: list[tuple[float, str]] = []
    for key in ("liquidation_short_distance_pct", "liquidation_long_distance_pct"):
        value = _coerce_float(features.get(key))
        if value is not None:
            pct_candidates.append((abs(value) * 100.0, key))
    if pct_candidates:
        return min(pct_candidates, key=lambda item: item[0])
    return None, None


def _merge_strategy_context(
    envelope: dict[str, Any],
    context_name: str,
    values: dict[str, Any],
) -> None:
    clean = {key: value for key, value in values.items() if value not in (None, "", [], {})}
    if not clean:
        return
    existing = envelope.get(context_name)
    merged = dict(existing) if isinstance(existing, dict) else {}
    for key, value in clean.items():
        merged.setdefault(key, value)
    envelope[context_name] = merged


def _attach_strategy_router_feature_snapshot_context(
    envelope: dict[str, Any],
    feature_snapshot: dict[str, Any] | None,
) -> None:
    features = _feature_snapshot_features(feature_snapshot)
    if not features:
        reason = (
            feature_snapshot.get("unavailable_reason")
            if isinstance(feature_snapshot, dict)
            else "MISSING_FEATURE_SNAPSHOT"
        )
        envelope["strategy_feature_snapshot_status"] = f"UNAVAILABLE_{reason or 'UNKNOWN'}"
        return

    envelope["strategy_feature_snapshot_status"] = "ATTACHED_PIT_VALID_FEATURE_SNAPSHOT"
    for source_field, envelope_field in (
        ("feature_snapshot_id", "strategy_feature_snapshot_id"),
        ("available_at", "strategy_feature_snapshot_available_at"),
        ("feature_cutoff", "strategy_feature_snapshot_feature_cutoff"),
        ("candle_closed_confirmed", "strategy_feature_snapshot_candle_closed_confirmed"),
        (
            "latest_unclosed_kline_excluded",
            "strategy_feature_snapshot_latest_unclosed_kline_excluded",
        ),
    ):
        value = feature_snapshot.get(source_field) if isinstance(feature_snapshot, dict) else None
        if value not in (None, ""):
            envelope[envelope_field] = value

    source_map: dict[str, str] = {}

    def set_direct(field: str, value: Any, source: str | None) -> None:
        if value in (None, "") or envelope.get(field) not in (None, ""):
            return
        envelope[field] = value
        if source:
            source_map[field] = f"feature_snapshot.{source}"

    adx, adx_key = _strategy_feature_snapshot_number(
        features, "trend_strength", "ta_ADX", "ta_ADXR"
    )
    set_direct("trend_strength", _strategy_score01_from_percent(adx), adx_key)

    chop, chop_key = _strategy_feature_snapshot_number(features, "range_chop_score", "chop_score")
    if chop is None:
        trend_mode, trend_mode_key = _strategy_feature_snapshot_number(
            features, "ta_HT_TRENDMODE_integer"
        )
        if trend_mode is not None:
            chop = 0.0 if trend_mode >= 1.0 else 1.0
            chop_key = trend_mode_key
    set_direct("range_chop_score", _strategy_score01_from_percent(chop), chop_key)

    volatility, volatility_key = _strategy_feature_snapshot_number(
        features,
        "volatility_expansion",
        "true_range_pct",
        "bb_width_pct",
        "ta_BB_width_pct",
        "ta_NATR",
    )
    set_direct("volatility_expansion", volatility, volatility_key)

    atr_percentile, atr_percentile_key = _strategy_feature_snapshot_number(
        features,
        "atr_percentile",
    )
    set_direct("atr_percentile", _strategy_score01_from_percent(atr_percentile), atr_percentile_key)

    funding_bps, funding_key = _strategy_feature_snapshot_number(features, "expected_funding_bps")
    if funding_bps is None:
        funding_rate, funding_rate_key = _strategy_feature_snapshot_number(features, "funding_rate")
        if funding_rate is not None:
            funding_bps = funding_rate * 10_000.0
            funding_key = funding_rate_key
    set_direct("funding_skew", funding_bps, funding_key)

    oi_change, oi_key = _strategy_feature_snapshot_number(
        features, "oi_change_pct", "open_interest_change_pct"
    )
    set_direct("open_interest_change", oi_change, oi_key)

    long_short_ratio, long_short_key = _strategy_feature_snapshot_number(
        features, "long_short_ratio"
    )
    set_direct("long_short_ratio", long_short_ratio, long_short_key)

    liquidation_bps, liquidation_key = _strategy_snapshot_nearest_liquidation_bps(features)
    set_direct("liquidation_cluster_proximity", liquidation_bps, liquidation_key)

    depth_imbalance, depth_imbalance_key = _strategy_feature_snapshot_number(
        features, "depth_imbalance", "orderbook_imbalance"
    )
    set_direct("orderbook_imbalance", depth_imbalance, depth_imbalance_key)

    aggressive_flow, aggressive_flow_key = _strategy_snapshot_aggressive_flow(features)
    set_direct("aggressive_flow", aggressive_flow, aggressive_flow_key)

    spread_bps, spread_key = _strategy_feature_snapshot_number(
        features, "bid_ask_spread_bps", "actual_observed_spread_entry_bps"
    )
    slippage_bps, slippage_key = _strategy_feature_snapshot_number(
        features, "expected_slippage_bps"
    )
    depth_usd, depth_key = _strategy_feature_snapshot_number(
        features, "orderbook_depth_usd", "bid_depth_usd", "ask_depth_usd"
    )
    bid_depth, bid_depth_key = _strategy_feature_snapshot_number(features, "bid_depth_usd")
    ask_depth, ask_depth_key = _strategy_feature_snapshot_number(features, "ask_depth_usd")
    _merge_strategy_context(
        envelope,
        "liquidity_context",
        {
            "source": "PIT_VALID_FEATURE_SNAPSHOT",
            "orderbook_depth_usd": depth_usd,
            "bid_depth_usd": bid_depth,
            "ask_depth_usd": ask_depth,
            "depth_imbalance": depth_imbalance,
            "source_fields": sorted(
                key for key in (depth_key, bid_depth_key, ask_depth_key, depth_imbalance_key) if key
            ),
        },
    )
    _merge_strategy_context(
        envelope,
        "liquidation_context",
        {
            "source": "PIT_VALID_FEATURE_SNAPSHOT",
            "liquidation_sweep_target_short_distance_bps": features.get(
                "liquidation_sweep_target_short_distance_bps"
            ),
            "liquidation_sweep_target_long_distance_bps": features.get(
                "liquidation_sweep_target_long_distance_bps"
            ),
            "liquidation_short_strength": features.get("liquidation_short_strength"),
            "liquidation_long_strength": features.get("liquidation_long_strength"),
            "liquidation_cascade_risk": features.get("liquidation_cascade_risk"),
            "nearest_distance_bps": liquidation_bps,
            "source_field": liquidation_key,
        },
    )
    _merge_strategy_context(
        envelope,
        "microstructure_context",
        {
            "source": "PIT_VALID_FEATURE_SNAPSHOT",
            "bid_ask_spread_bps": spread_bps,
            "expected_slippage_bps": slippage_bps,
            "orderbook_depth_usd": depth_usd,
            "orderbook_imbalance": depth_imbalance,
            "depth_imbalance": depth_imbalance,
            "order_flow_imbalance": aggressive_flow,
            "source_fields": sorted(
                key
                for key in (
                    spread_key,
                    slippage_key,
                    depth_key,
                    depth_imbalance_key,
                    aggressive_flow_key,
                )
                if key
            ),
        },
    )
    _merge_strategy_context(
        envelope,
        "oi_funding_context",
        {
            "source": "PIT_VALID_FEATURE_SNAPSHOT",
            "funding_bps": funding_bps,
            "funding_rate": features.get("funding_rate"),
            "oi_change_pct": oi_change,
            "long_short_ratio": long_short_ratio,
            "long_account_ratio": features.get("long_account_ratio"),
            "short_account_ratio": features.get("short_account_ratio"),
            "source_fields": sorted(key for key in (funding_key, oi_key, long_short_key) if key),
        },
    )
    if source_map:
        envelope["strategy_regime_feature_source_map"] = source_map


def _attach_strategy_router_microstructure_context(
    envelope: dict[str, Any],
    microstructure_trust: dict[str, Any] | None,
) -> None:
    if not isinstance(microstructure_trust, dict) or not microstructure_trust:
        return
    source = str(
        microstructure_trust.get("microstructure_trust_source") or "v2:microstructure:trust_score"
    )
    fakeout_probability = _coerce_float(
        _first_present(
            microstructure_trust.get("fakeout_reversal_probability"),
            microstructure_trust.get("post_sweep_reversal_probability"),
        )
    )
    if fakeout_probability is not None and envelope.get("fakeout_reversal_probability") in (
        None,
        "",
    ):
        envelope["fakeout_reversal_probability"] = max(0.0, min(1.0, fakeout_probability))
        source_map = dict(envelope.get("strategy_regime_feature_source_map") or {})
        source_map["fakeout_reversal_probability"] = f"{source}.post_sweep_reversal_probability"
        envelope["strategy_regime_feature_source_map"] = source_map
    for field in (
        "public_orderbook_trust_score",
        "composite_microstructure_trust_score",
        "microstructure_trust_score",
        "orderbook_trust_score",
        "microstructure_action",
        "final_a_plus_min_composite_trust",
        "final_a_plus_eligible",
        "non_book_confirmation_pass",
        "composite_confirmation_missing_fields",
        "reduced_size_bootstrap_tier",
        "bootstrap_reduced_size_paper_only",
        "sweep_risk_score",
        "trade_tape_confirmation_score",
        "cross_venue_confirmation_score",
    ):
        value = microstructure_trust.get(field)
        if value not in (None, "") and envelope.get(field) in (None, ""):
            envelope[field] = value
    _merge_strategy_context(
        envelope,
        "microstructure_context",
        {
            "source": source,
            "microstructure_trust_status": microstructure_trust.get("microstructure_trust_status"),
            "microstructure_trust_score": microstructure_trust.get("microstructure_trust_score"),
            "public_orderbook_trust_score": microstructure_trust.get(
                "public_orderbook_trust_score"
            ),
            "composite_microstructure_trust_score": microstructure_trust.get(
                "composite_microstructure_trust_score"
            ),
            "orderbook_trust_score": microstructure_trust.get("orderbook_trust_score"),
            "microstructure_action": microstructure_trust.get("microstructure_action"),
            "final_a_plus_min_composite_trust": microstructure_trust.get(
                "final_a_plus_min_composite_trust"
            ),
            "final_a_plus_eligible": microstructure_trust.get("final_a_plus_eligible"),
            "non_book_confirmation_pass": microstructure_trust.get("non_book_confirmation_pass"),
            "composite_confirmation_missing_fields": microstructure_trust.get(
                "composite_confirmation_missing_fields"
            ),
            "reduced_size_bootstrap_tier": microstructure_trust.get("reduced_size_bootstrap_tier"),
            "bootstrap_reduced_size_paper_only": microstructure_trust.get(
                "bootstrap_reduced_size_paper_only"
            ),
            "sweep_risk": microstructure_trust.get("sweep_risk_score"),
            "post_sweep_reversal_probability": fakeout_probability,
            "available_at": microstructure_trust.get("microstructure_available_at"),
            "generated_at": microstructure_trust.get("microstructure_generated_at"),
            "decision_time": microstructure_trust.get("microstructure_trust_decision_time"),
            "source_fields": ["post_sweep_reversal_probability"]
            if fakeout_probability is not None
            else [],
        },
    )


def _strategy_prediction_row_pit_safe(row: dict[str, Any], decision_time: Any) -> bool:
    decision_dt = _parse_strategy_time(decision_time)
    available_dt = _parse_strategy_time(
        _first_present(
            row.get("available_at"),
            row.get("generated_utc"),
            row.get("generated_at"),
        )
    )
    feature_cutoff_dt = _parse_strategy_time(
        _first_present(row.get("feature_cutoff"), row.get("generated_at"))
    )
    return (
        decision_dt is not None
        and available_dt is not None
        and feature_cutoff_dt is not None
        and available_dt <= decision_dt
        and feature_cutoff_dt <= decision_dt
    )


def _strategy_prediction_move_bps(row: dict[str, Any]) -> float | None:
    return _coerce_float(
        _first_present(
            row.get("expected_move_after_cost_bps"),
            row.get("expected_move_bps"),
            row.get("price_target_bps"),
        )
    )


def _strategy_cross_asset_prediction_context(
    *,
    predictions_by_symbol: dict[str, list[dict[str, Any]]],
    decision_time: Any,
    timeframe: Any,
) -> dict[str, Any]:
    selected_rows: list[dict[str, Any]] = []
    timeframe_text = str(timeframe or "").strip()
    for symbol in ("BTCUSDT", "ETHUSDT", "SOLUSDT"):
        candidates = [
            row
            for row in predictions_by_symbol.get(symbol, [])
            if isinstance(row, dict)
            and _strategy_prediction_row_pit_safe(row, decision_time)
            and _strategy_prediction_move_bps(row) is not None
        ]
        if timeframe_text:
            same_timeframe = [
                row for row in candidates if str(row.get("timeframe") or "") == timeframe_text
            ]
            if same_timeframe:
                candidates = same_timeframe
        if not candidates:
            continue
        selected_rows.append(
            max(
                candidates,
                key=lambda row: str(
                    _first_present(
                        row.get("available_at"),
                        row.get("generated_utc"),
                        row.get("generated_at"),
                    )
                    or ""
                ),
            )
        )
    if len(selected_rows) < 2:
        return {
            "status": "INSUFFICIENT_PIT_BTC_ETH_SOL_PREDICTION_ROWS",
            "source": "PIT_PREDICTION_GRID",
            "available_symbol_count": len(selected_rows),
        }
    moves = [_strategy_prediction_move_bps(row) for row in selected_rows]
    numeric_moves = [move for move in moves if move is not None]
    positive_count = sum(1 for move in numeric_moves if move > 0.0)
    negative_count = sum(1 for move in numeric_moves if move < 0.0)
    neutral_count = len(numeric_moves) - positive_count - negative_count
    average_move = sum(numeric_moves) / len(numeric_moves)
    if positive_count >= 2 and average_move > 0.0:
        regime = "btc_eth_sol_risk_on"
        market_wide_risk = "risk_on"
    elif negative_count >= 2 and average_move < 0.0:
        regime = "btc_eth_sol_risk_off"
        market_wide_risk = "risk_off"
    else:
        regime = "btc_eth_sol_mixed"
        market_wide_risk = "mixed"
    market_breadth_score = (positive_count - negative_count) / len(numeric_moves)
    return {
        "status": "ATTACHED_PIT_BTC_ETH_SOL_PREDICTION_GRID",
        "source": "PIT_PREDICTION_GRID",
        "cross_asset_btc_eth_sol_regime": regime,
        "market_wide_risk": market_wide_risk,
        "market_breadth_score": round(float(market_breadth_score), 8),
        "average_expected_move_after_cost_bps": round(float(average_move), 8),
        "positive_symbol_count": positive_count,
        "negative_symbol_count": negative_count,
        "neutral_symbol_count": neutral_count,
        "available_symbol_count": len(selected_rows),
        "timeframe": timeframe_text or None,
        "decision_time": decision_time,
        "source_rows": [
            {
                "symbol": row.get("symbol"),
                "timeframe": row.get("timeframe"),
                "prediction_id": row.get("prediction_id"),
                "available_at": row.get("available_at"),
                "feature_cutoff": row.get("feature_cutoff"),
                "expected_move_after_cost_bps": _strategy_prediction_move_bps(row),
                "selected_action": row.get("selected_action"),
            }
            for row in selected_rows
        ],
    }


def _attach_strategy_router_cross_asset_context(
    envelope: dict[str, Any],
    predictions_by_symbol: dict[str, list[dict[str, Any]]],
) -> None:
    context = _strategy_cross_asset_prediction_context(
        predictions_by_symbol=predictions_by_symbol,
        decision_time=envelope.get("decision_time"),
        timeframe=envelope.get("timeframe"),
    )
    envelope["strategy_cross_asset_context_status"] = context["status"]
    envelope["strategy_cross_asset_context_source"] = context["source"]
    if context["status"] != "ATTACHED_PIT_BTC_ETH_SOL_PREDICTION_GRID":
        envelope["strategy_cross_asset_available_symbol_count"] = context.get(
            "available_symbol_count"
        )
        return
    if envelope.get("cross_asset_btc_eth_sol_regime") in (None, ""):
        envelope["cross_asset_btc_eth_sol_regime"] = context["cross_asset_btc_eth_sol_regime"]
    if envelope.get("market_wide_risk") in (None, ""):
        envelope["market_wide_risk"] = context["market_wide_risk"]
    _merge_strategy_context(
        envelope,
        "public_intel_context",
        {
            "source": context["source"],
            "cross_asset_btc_eth_sol_regime": context["cross_asset_btc_eth_sol_regime"],
            "market_wide_risk": context["market_wide_risk"],
            "market_breadth_score": context["market_breadth_score"],
            "average_expected_move_after_cost_bps": context["average_expected_move_after_cost_bps"],
            "positive_symbol_count": context["positive_symbol_count"],
            "negative_symbol_count": context["negative_symbol_count"],
            "neutral_symbol_count": context["neutral_symbol_count"],
            "available_symbol_count": context["available_symbol_count"],
            "source_rows": context["source_rows"],
        },
    )


def _parse_strategy_time(value: Any) -> datetime | None:
    if value in (None, ""):
        return None
    if isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        iso_value = _iso_from_epoch_ms(value)
        if iso_value is None:
            return None
        value = iso_value
    try:
        parsed = datetime.fromisoformat(str(value).replace("Z", "+00:00"))
    except ValueError:
        numeric_value = _coerce_float(value)
        if numeric_value is not None:
            iso_value = _iso_from_epoch_ms(numeric_value)
            if iso_value is not None:
                try:
                    parsed = datetime.fromisoformat(iso_value.replace("Z", "+00:00"))
                except ValueError:
                    return None
            else:
                return None
        else:
            return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc)


PAPER_ALLOCATION_COMPONENT_TIME_FIELDS = (
    # Price evidence used directly by AllocationInput.price.
    "entry_price_source_available_at",
    "entry_price_source_generated_utc",
    "entry_price_utc",
    # Closed-candle feature/model evidence used by routing and allocation.
    "entry_feature_cutoff",
    "entry_feature_available_at",
    "entry_feature_generated_at",
    "entry_feature_decision_time",
    "strategy_feature_cutoff",
    "strategy_available_at",
    "strategy_decision_time",
    "strategy_feature_snapshot_feature_cutoff",
    "strategy_feature_snapshot_available_at",
    "strategy_cascade_event_time",
    "strategy_cascade_feature_cutoff",
    "strategy_cascade_available_at",
    "strategy_cascade_generated_at",
    "strategy_cascade_decision_time",
    # Runtime spread/depth evidence used by sizing.
    "entry_spread_event_time",
    "entry_spread_generated_at",
    "entry_spread_available_at",
    "entry_spread_captured_at",
    "entry_spread_decision_time",
    "paper_admission_decision_time",
    "runtime_cost_capture_decision_time",
    # Composite microstructure evidence can change liquidity and size.
    "microstructure_available_at",
    "microstructure_generated_at",
    "microstructure_decision_time",
    # Conditional allocation sources.
    "fee_schedule_effective_at",
    "fee_schedule_generated_at",
    "fee_schedule_ingested_at",
    "fee_schedule_available_at",
    "entry_atr_feature_cutoff",
    "entry_atr_available_at",
    "entry_atr_generated_at",
    "correlation_feature_cutoff",
    "correlation_source_available_at",
    "correlation_decision_time",
    "correlation_computed_at",
    "dynamic_envelope_edge_available_at",
    "dynamic_envelope_market_context_available_at",
    "dynamic_envelope_decision_time",
    "dynamic_envelope_computed_at",
    # Capital/reservation state used by risk and notional sizing.
    "portfolio_state_event_time",
    "portfolio_state_generated_at",
    "portfolio_state_available_at",
    "portfolio_context_observed_at",
    "paper_ledger_generated_at",
    "paper_ledger_observed_at",
    "open_exposure_observed_at",
    "paper_precycle_exposure_snapshot_started_at",
    "paper_precycle_exposure_snapshot_completed_at",
    # Venue execution constraints consumed by quantity quantization.
    "paper_exchange_filter_available_at",
    "paper_exchange_filter_observed_at",
)


def _strict_aware_utc_time(value: Any) -> datetime | None:
    """Parse an explicitly timezone-aware timestamp without assuming UTC."""

    if value in (None, "") or isinstance(value, bool):
        return None
    if isinstance(value, datetime):
        parsed = value
    elif isinstance(value, str):
        try:
            parsed = datetime.fromisoformat(value.strip().replace("Z", "+00:00"))
        except ValueError:
            return None
    else:
        # Component readers normalize exchange epochs before attaching them.
        # Accepting a bare number here would hide unit/clock ambiguity.
        return None
    if parsed.tzinfo is None or parsed.utcoffset() is None:
        return None
    return parsed.astimezone(timezone.utc)


def _paper_bind_liquidation_atr_evidence(
    *,
    intent: dict[str, Any],
    allocation_input: Any,
    allocation_decision_time: datetime,
    point_in_time_status: str,
) -> Any:
    """Bind final canonical feature-snapshot ATR to one PAPER allocation.

    Missing, defaulted, top-level, prediction-only, and TA-flat values never
    receive this receipt. The allocator consequently keeps those candidates at
    1x even if their other evidence is favorable.
    """

    lineage_ids = dict(getattr(allocation_input, "lineage_ids", {}) or {})
    prior_binding_is_canonical = bool(
        lineage_ids.get("paper_liquidation_atr_allocation_input_binding")
        == "EXACT_CANONICAL_PIT_FINAL_ENTRY_FEATURE_SNAPSHOT_RECEIPT"
    )
    preserved_prebind_entry_atr = (
        _coerce_float(lineage_ids.get("paper_liquidation_atr_prebind_entry_atr_bps"))
        if prior_binding_is_canonical
        else _coerce_float(getattr(allocation_input, "entry_atr_bps", None))
    )
    preserved_prebind_mismatch = bool(
        prior_binding_is_canonical
        and lineage_ids.get("paper_liquidation_atr_prebind_value_mismatch") is True
    )
    lineage_ids.pop(PAPER_LIQUIDATION_ATR_EVIDENCE_LINEAGE_KEY, None)
    lineage_ids.pop(PAPER_LIQUIDATION_ATR_EVIDENCE_HASH_LINEAGE_KEY, None)
    for field in (
        "paper_liquidation_atr_prebind_entry_atr_bps",
        "paper_liquidation_atr_prebind_value_mismatch",
        "paper_liquidation_atr_allocation_input_binding",
    ):
        lineage_ids.pop(field, None)
    for field in (
        "paper_liquidation_atr_evidence",
        "paper_liquidation_atr_evidence_sha256",
    ):
        intent.pop(field, None)

    rejection_reasons: list[str] = []
    receipt: dict[str, Any] | None = None
    validated_atr: float | None = None
    if point_in_time_status != "PASS":
        rejection_reasons.append("PAPER_LIQUIDATION_ATR_ALLOCATION_POINT_IN_TIME_NOT_PASS")
    else:
        receipt, rejection_reasons = build_paper_liquidation_atr_evidence(
            feature_snapshot=(
                intent.get("entry_feature_snapshot")
                if isinstance(intent.get("entry_feature_snapshot"), Mapping)
                else None
            ),
            symbol=str(getattr(allocation_input, "symbol", "") or ""),
            timeframe=str(getattr(allocation_input, "timeframe", "") or ""),
            entry_price=float(getattr(allocation_input, "price", 0.0) or 0.0),
            allocation_decision_time=allocation_decision_time,
        )
        if receipt is not None:
            receipt_hash = receipt.get("evidence_sha256")
            validated_atr, validation_reasons = validate_paper_liquidation_atr_evidence(
                receipt,
                receipt_hash,
                symbol=str(getattr(allocation_input, "symbol", "") or ""),
                timeframe=str(getattr(allocation_input, "timeframe", "") or ""),
                # The receipt is the canonical PAPER authority.  The
                # pre-bind row may still contain a prediction alias,
                # default, or TA-flat fallback; requiring that value to
                # equal the canonical snapshot would keep otherwise valid
                # paper candidates pinned at 1x.  Validate the receipt
                # internally here, then replace the PAPER row value with
                # this exact receipt ATR before allocation.
                entry_atr_bps=receipt.get("atr_bps"),
            )
            if validation_reasons or validated_atr is None:
                rejection_reasons.extend(validation_reasons)
                receipt = None

    unique_reasons = sorted(set(str(reason) for reason in rejection_reasons if reason))
    if receipt is not None and not unique_reasons:
        receipt_hash = receipt["evidence_sha256"]
        previous_entry_atr = _coerce_float(getattr(allocation_input, "entry_atr_bps", None))
        prebind_value_mismatch = bool(
            preserved_prebind_mismatch
            or previous_entry_atr is None
            or validated_atr is None
            or abs(previous_entry_atr - validated_atr) > max(1e-12, abs(validated_atr) * 1e-12)
        )
        lineage_ids[PAPER_LIQUIDATION_ATR_EVIDENCE_LINEAGE_KEY] = receipt
        lineage_ids[PAPER_LIQUIDATION_ATR_EVIDENCE_HASH_LINEAGE_KEY] = receipt_hash
        lineage_ids["paper_liquidation_atr_prebind_entry_atr_bps"] = preserved_prebind_entry_atr
        lineage_ids["paper_liquidation_atr_prebind_value_mismatch"] = prebind_value_mismatch
        lineage_ids["paper_liquidation_atr_allocation_input_binding"] = (
            "EXACT_CANONICAL_PIT_FINAL_ENTRY_FEATURE_SNAPSHOT_RECEIPT"
        )
        intent["paper_liquidation_atr_evidence"] = receipt
        intent["paper_liquidation_atr_evidence_sha256"] = receipt_hash
        intent["paper_liquidation_atr_evidence_status"] = "READY"
        intent["paper_liquidation_atr_evidence_rejection_reasons"] = []
        intent["paper_liquidation_atr_bps"] = receipt.get("atr_bps")
        if prebind_value_mismatch:
            intent["paper_liquidation_atr_prebind_entry_atr_bps"] = preserved_prebind_entry_atr
        intent["paper_liquidation_atr_prebind_value_mismatch"] = prebind_value_mismatch
        intent["paper_liquidation_atr_allocation_input_binding"] = (
            "EXACT_CANONICAL_PIT_FINAL_ENTRY_FEATURE_SNAPSHOT_RECEIPT"
        )
    else:
        intent["paper_liquidation_atr_evidence_status"] = "BLOCKED"
        intent["paper_liquidation_atr_evidence_rejection_reasons"] = unique_reasons
        intent["paper_liquidation_atr_bps"] = None
    return replace(
        allocation_input,
        lineage_ids=lineage_ids,
        entry_atr_bps=(
            validated_atr
            if receipt is not None and not unique_reasons
            else getattr(allocation_input, "entry_atr_bps", None)
        ),
    )


def _paper_allocation_point_in_time_contract(
    intent: Mapping[str, Any],
    *,
    allocation_decision_time: datetime,
) -> dict[str, Any]:
    """Validate every attached component clock against one immutable decision.

    The decision timestamp is captured after the last allocation input is
    assembled.  Generic ``timestamp``/``generated_at`` aliases are deliberately
    excluded: only component-owned clocks with defined semantics are accepted.
    """

    decision_utc = _strict_aware_utc_time(allocation_decision_time)
    rejection_reasons: list[str] = []
    observed: dict[str, str] = {}
    parsed_times: dict[str, datetime] = {}
    if decision_utc is None:
        rejection_reasons.append("ALLOCATION_DECISION_TIME_NOT_TIMEZONE_AWARE")
    else:
        for field in PAPER_ALLOCATION_COMPONENT_TIME_FIELDS:
            raw = intent.get(field)
            if raw in (None, ""):
                continue
            parsed = _strict_aware_utc_time(raw)
            if parsed is None:
                rejection_reasons.append(f"ALLOCATION_INPUT_TIME_UNPARSEABLE_OR_NAIVE:{field}")
                continue
            observed[field] = parsed.isoformat().replace("+00:00", "Z")
            parsed_times[field] = parsed
            if parsed > decision_utc:
                rejection_reasons.append(f"ALLOCATION_INPUT_TIME_AFTER_DECISION:{field}")

    required_fields: set[str] = set()
    if intent.get("entry_price_provenance_present") is True:
        required_fields.update(
            {
                "entry_price_source_available_at",
                "entry_price_utc",
            }
        )
    if intent.get("entry_feature_snapshot_id") not in (None, ""):
        required_fields.update(
            {
                "entry_feature_cutoff",
                "entry_feature_available_at",
                "entry_feature_generated_at",
                "entry_feature_decision_time",
            }
        )
    if any(
        intent.get(field) not in (None, "")
        for field in (
            "strategy_router_selected_mode",
            "strategy_selected_mode",
            "strategy_decision_time",
        )
    ):
        required_fields.update(
            {
                "strategy_feature_cutoff",
                "strategy_available_at",
                "strategy_decision_time",
            }
        )
        if intent.get("strategy_temporal_contract_status") != "PASS":
            rejection_reasons.append("STRATEGY_TEMPORAL_CONTRACT_NOT_PASS")
    if intent.get("strategy_feature_snapshot_status") == ("ATTACHED_PIT_VALID_FEATURE_SNAPSHOT"):
        required_fields.update(
            {
                "strategy_feature_snapshot_feature_cutoff",
                "strategy_feature_snapshot_available_at",
            }
        )
    if intent.get("strategy_cascade_context_status") == "ATTACHED_PIT_VALID":
        required_fields.update(
            {
                "strategy_cascade_event_time",
                "strategy_cascade_available_at",
                "strategy_cascade_generated_at",
                "strategy_cascade_decision_time",
            }
        )
    if (
        _coerce_float(intent.get("actual_observed_spread_entry_bps")) is not None
        and intent.get("bid_ask_spread_bps_fallback") is not True
    ):
        required_fields.update(
            {
                "entry_spread_available_at",
                "entry_spread_event_time",
                "entry_spread_generated_at",
                "entry_spread_captured_at",
                "entry_spread_decision_time",
                "paper_admission_decision_time",
            }
        )
        spread_hash = str(intent.get("entry_spread_source_hash") or "")
        if (
            len(spread_hash) != 64
            or any(character not in "0123456789abcdef" for character in spread_hash)
            or intent.get("entry_spread_source_hash_contract")
            != "REDIS_KEY_AND_FULL_CANONICAL_SOURCE_PAYLOAD_SHA256_V1"
        ):
            rejection_reasons.append("ENTRY_SPREAD_SOURCE_HASH_INVALID")
    microstructure_used = any(
        intent.get(field) not in (None, "")
        for field in (
            "microstructure_trust_source",
            "microstructure_action",
            "microstructure_trust_score",
            "composite_microstructure_trust_score",
            "public_orderbook_trust_score",
            "orderbook_trust_score",
        )
    )
    if microstructure_used:
        required_fields.update(
            {
                "microstructure_available_at",
                "microstructure_generated_at",
                "microstructure_decision_time",
            }
        )
        microstructure_hash = str(intent.get("microstructure_source_hash") or "")
        if (
            len(microstructure_hash) != 64
            or any(character not in "0123456789abcdef" for character in microstructure_hash)
            or intent.get("microstructure_source_hash_contract")
            != "REDIS_KEY_AND_FULL_CANONICAL_SOURCE_PAYLOAD_SHA256_V1"
        ):
            rejection_reasons.append("MICROSTRUCTURE_SOURCE_HASH_INVALID")
    if (
        intent.get("fee_bps_readonly_schedule") is True
        or intent.get("pre_trade_fee_bps_readonly_schedule") is True
    ):
        required_fields.add("fee_schedule_available_at")
    if str(intent.get("entry_atr_bps_source") or "").startswith("v2_ta_flat_"):
        required_fields.update(
            {
                "entry_atr_feature_cutoff",
                "entry_atr_available_at",
                "entry_atr_generated_at",
            }
        )
        source_hash = str(intent.get("entry_atr_source_hash") or "")
        if (
            intent.get("ta_flat_atr_candle_closed_confirmed") is not True
            or intent.get("entry_atr_source") != "v2_ta_flat_hash_adapter_v1"
            or len(source_hash) != 64
            or any(character not in "0123456789abcdef" for character in source_hash)
        ):
            rejection_reasons.append("TA_FLAT_ATR_PROVENANCE_INVALID")
    if (
        intent.get("correlation_input_status") == "READY"
        and intent.get("correlation_input_source") == "MARKET_OHLCV_RETURN_CORRELATION"
    ):
        required_fields.update(
            {
                "correlation_feature_cutoff",
                "correlation_source_available_at",
                "correlation_decision_time",
                "correlation_computed_at",
            }
        )
        correlation_hash = str(intent.get("correlation_source_hash") or "")
        if len(correlation_hash) != 64 or any(
            character not in "0123456789abcdef" for character in correlation_hash
        ):
            rejection_reasons.append("CORRELATION_SOURCE_HASH_INVALID")
    if any(
        intent.get(field) not in (None, "")
        for field in (
            "dynamic_envelope_decision_time",
            "dynamic_envelope_computed_at",
            "dynamic_envelope_max_effective_leverage",
        )
    ):
        required_fields.update(
            {
                "dynamic_envelope_decision_time",
                "dynamic_envelope_computed_at",
            }
        )
        if (_coerce_float(intent.get("dynamic_envelope_max_effective_leverage")) or 1.0) > 1.0:
            required_fields.update(
                {
                    "dynamic_envelope_edge_available_at",
                    "dynamic_envelope_market_context_available_at",
                }
            )
    required_fields.update(
        {
            "portfolio_context_observed_at",
            "open_exposure_observed_at",
        }
        if "portfolio_context_observed_at" in intent or "open_exposure_observed_at" in intent
        else set()
    )
    if intent.get("portfolio_state_present") is True:
        required_fields.update(
            {
                "portfolio_state_available_at",
                "portfolio_state_generated_at",
                "portfolio_context_observed_at",
            }
        )
    if (_coerce_float(intent.get("paper_ledger_open_position_count")) or 0.0) > 0:
        required_fields.update(
            {
                "paper_ledger_generated_at",
                "paper_ledger_observed_at",
            }
        )
    if intent.get("paper_cycle_reservation_snapshot") not in (None, {}, []):
        required_fields.update(
            {
                "paper_precycle_exposure_snapshot_started_at",
                "paper_precycle_exposure_snapshot_completed_at",
            }
        )
    required_fields.update(
        {
            "paper_exchange_filter_available_at",
            "paper_exchange_filter_observed_at",
        }
    )
    if intent.get("paper_exchange_filter_status") != "READY":
        rejection_reasons.append("PAPER_EXCHANGE_FILTER_STATUS_NOT_READY")

    for field in sorted(required_fields):
        if intent.get(field) in (None, ""):
            rejection_reasons.append(f"ALLOCATION_INPUT_TIME_MISSING:{field}")

    def require_order(left: str, right: str) -> None:
        left_time = parsed_times.get(left)
        right_time = parsed_times.get(right)
        if left_time is not None and right_time is not None and left_time > right_time:
            rejection_reasons.append(f"ALLOCATION_INPUT_TIME_ORDER_INVALID:{left}>{right}")

    for left, right in (
        ("entry_price_source_available_at", "entry_price_utc"),
        ("entry_feature_cutoff", "entry_feature_decision_time"),
        ("entry_feature_available_at", "entry_feature_decision_time"),
        ("strategy_feature_cutoff", "strategy_decision_time"),
        ("strategy_available_at", "strategy_decision_time"),
        (
            "strategy_feature_snapshot_feature_cutoff",
            "strategy_decision_time",
        ),
        ("strategy_feature_snapshot_available_at", "strategy_decision_time"),
        ("strategy_cascade_event_time", "strategy_cascade_decision_time"),
        ("strategy_cascade_feature_cutoff", "strategy_cascade_decision_time"),
        ("strategy_cascade_available_at", "strategy_cascade_decision_time"),
        ("strategy_cascade_decision_time", "strategy_decision_time"),
        ("strategy_cascade_generated_at", "strategy_decision_time"),
        ("entry_spread_available_at", "entry_spread_captured_at"),
        ("entry_spread_event_time", "entry_spread_generated_at"),
        ("entry_spread_generated_at", "entry_spread_available_at"),
        ("entry_spread_available_at", "entry_spread_decision_time"),
        ("entry_spread_captured_at", "paper_admission_decision_time"),
        ("microstructure_generated_at", "microstructure_available_at"),
        ("microstructure_available_at", "microstructure_decision_time"),
        ("entry_atr_feature_cutoff", "entry_atr_available_at"),
        ("entry_atr_available_at", "entry_atr_generated_at"),
        ("correlation_feature_cutoff", "correlation_decision_time"),
        ("correlation_source_available_at", "correlation_decision_time"),
        ("correlation_decision_time", "correlation_computed_at"),
        (
            "dynamic_envelope_edge_available_at",
            "dynamic_envelope_decision_time",
        ),
        (
            "dynamic_envelope_market_context_available_at",
            "dynamic_envelope_decision_time",
        ),
        ("dynamic_envelope_decision_time", "dynamic_envelope_computed_at"),
        ("portfolio_state_event_time", "portfolio_state_available_at"),
        ("portfolio_state_generated_at", "portfolio_context_observed_at"),
        ("portfolio_state_available_at", "portfolio_context_observed_at"),
        ("paper_ledger_generated_at", "paper_ledger_observed_at"),
        (
            "paper_ledger_observed_at",
            "paper_precycle_exposure_snapshot_started_at",
        ),
        (
            "paper_precycle_exposure_snapshot_started_at",
            "paper_precycle_exposure_snapshot_completed_at",
        ),
        (
            "paper_exchange_filter_available_at",
            "paper_exchange_filter_observed_at",
        ),
    ):
        require_order(left, right)

    unique_reasons = sorted(set(rejection_reasons))
    return {
        "status": "PASS" if not unique_reasons else "BLOCKED",
        "decision_time": (
            decision_utc.isoformat().replace("+00:00", "Z") if decision_utc is not None else None
        ),
        "decision_time_semantics": (
            "IMMUTABLE_CAPTURE_AFTER_ALL_CANDIDATE_ALLOCATION_INPUTS_BEFORE_FIRST_ALLOCATION"
        ),
        "component_time_fields_checked": list(PAPER_ALLOCATION_COMPONENT_TIME_FIELDS),
        "required_component_time_fields": sorted(required_fields),
        "observed_component_times": observed,
        "rejection_reasons": unique_reasons,
        "future_input_count": sum(
            reason.startswith("ALLOCATION_INPUT_TIME_AFTER_DECISION:") for reason in unique_reasons
        ),
    }


