def _paper_canonical_sha256(value: Any) -> str | None:
    try:
        canonical = json.dumps(
            value,
            sort_keys=True,
            separators=(",", ":"),
            default=str,
            allow_nan=False,
        )
    except (TypeError, ValueError):
        return None
    return hashlib.sha256(canonical.encode("utf-8")).hexdigest()


def _paper_valid_sha256(value: Any) -> bool:
    text = str(value or "")
    return len(text) == 64 and all(character in "0123456789abcdef" for character in text)


def _paper_cycle_reservation_contract_rejection_reasons(
    row: Mapping[str, Any],
    allocation: Mapping[str, Any],
) -> list[str]:
    """Replay the candidate's precycle evidence and append-time receipt."""

    reasons: list[str] = []

    def validate_embedded_hash(
        *,
        field: str,
        hash_field: str,
        embedded_hash_field: str,
        required_status: str,
    ) -> tuple[Mapping[str, Any], Any]:
        payload = row.get(field)
        if not isinstance(payload, Mapping):
            reasons.append(f"CYCLE_RESERVATION_EVIDENCE_MISSING:{field}")
            return {}, None
        material = dict(payload)
        embedded_hash = material.pop(embedded_hash_field, None)
        if (
            payload.get("status") != required_status
            or payload.get("rejection_reasons") not in ([], ())
            or not _paper_valid_sha256(embedded_hash)
            or embedded_hash != _paper_canonical_sha256(material)
            or embedded_hash != row.get(hash_field)
        ):
            reasons.append(f"CYCLE_RESERVATION_EVIDENCE_HASH_INVALID:{field}")
        return payload, embedded_hash

    precycle, precycle_hash = validate_embedded_hash(
        field="paper_precycle_current_mark_exposure_snapshot",
        hash_field="paper_precycle_current_mark_exposure_snapshot_hash",
        embedded_hash_field="snapshot_hash",
        required_status="READY",
    )
    base_resource, base_resource_hash = validate_embedded_hash(
        field="paper_cycle_base_resource_evidence",
        hash_field="paper_cycle_base_resource_evidence_hash",
        embedded_hash_field="evidence_hash",
        required_status="READY",
    )
    dynamic_envelope, dynamic_envelope_hash = validate_embedded_hash(
        field="paper_dynamic_envelope_reservation_evidence",
        hash_field="paper_dynamic_envelope_reservation_evidence_hash",
        embedded_hash_field="evidence_hash",
        required_status="READY",
    )
    reasons.extend(_paper_dynamic_envelope_semantic_rejection_reasons(dynamic_envelope))
    if precycle.get("snapshot_started_at") != row.get(
        "paper_precycle_exposure_snapshot_started_at"
    ) or precycle.get("snapshot_completed_at") != row.get(
        "paper_precycle_exposure_snapshot_completed_at"
    ):
        reasons.append("CYCLE_RESERVATION_PRECYCLE_CLOCK_ALIAS_MISMATCH")

    snapshot = row.get("paper_cycle_reservation_snapshot")
    if not isinstance(snapshot, Mapping):
        reasons.append("CYCLE_RESERVATION_SNAPSHOT_MISSING")
        snapshot = {}
    else:
        reasons.extend(cycle_reservation_snapshot_rejection_reasons(snapshot))
    snapshot_hash = snapshot.get("snapshot_hash")
    if (
        not _paper_valid_sha256(snapshot_hash)
        or snapshot_hash != row.get("paper_cycle_reservation_snapshot_hash")
        or row.get("paper_cycle_reservation_status") != "PASS"
    ):
        reasons.append("CYCLE_RESERVATION_SNAPSHOT_TOP_LEVEL_BINDING_INVALID")
    evidence_bindings = (
        snapshot.get("evidence_bindings")
        if isinstance(snapshot.get("evidence_bindings"), Mapping)
        else {}
    )
    for field, expected in (
        ("base_resource_evidence_hash", base_resource_hash),
        ("precycle_exposure_snapshot_hash", precycle_hash),
        ("dynamic_envelope_evidence_hash", dynamic_envelope_hash),
    ):
        if evidence_bindings.get(field) != expected:
            reasons.append(f"CYCLE_RESERVATION_EVIDENCE_BINDING_MISMATCH:{field}")

    allocation_hash = _paper_canonical_sha256(allocation)
    allocation_lineage = (
        allocation.get("lineage_ids") if isinstance(allocation.get("lineage_ids"), Mapping) else {}
    )
    allocation_input_material = allocation.get("allocation_input_material")
    allocation_input = (
        allocation_input_material.get("allocation_input")
        if isinstance(allocation_input_material, Mapping)
        and isinstance(allocation_input_material.get("allocation_input"), Mapping)
        else {}
    )
    allocation_input_lineage = (
        allocation_input.get("lineage_ids")
        if isinstance(allocation_input.get("lineage_ids"), Mapping)
        else {}
    )
    if (
        allocation_lineage.get(CYCLE_RESERVATION_LINEAGE_KEY) != snapshot_hash
        or allocation_input_lineage.get(CYCLE_RESERVATION_LINEAGE_KEY) != snapshot_hash
    ):
        reasons.append("CYCLE_RESERVATION_ALLOCATION_LINEAGE_MISMATCH")

    commit = row.get("paper_cycle_reservation_commit_receipt")
    if not isinstance(commit, Mapping):
        reasons.append("CYCLE_RESERVATION_COMMIT_RECEIPT_MISSING")
        commit = {}
    commit_material = dict(commit)
    commit_hash = commit_material.pop("receipt_hash", None)
    if (
        commit.get("schema_version") != "paper_cycle_reservation_commit_v1"
        or commit.get("status") != "PASS"
        or commit.get("rejection_reasons") not in ([], ())
        or commit.get("paper_only") is not True
        or commit.get("routes_to_live") is not False
        or commit.get("places_real_order") is not False
        or not _paper_valid_sha256(commit_hash)
        or commit_hash != _paper_canonical_sha256(commit_material)
        or commit_hash != row.get("paper_cycle_reservation_commit_receipt_hash")
        or row.get("paper_cycle_reservation_commit_status") != "PASS"
        or commit.get("cycle_reservation_snapshot_hash") != snapshot_hash
        or commit.get("allocation_id") != allocation.get("allocation_id")
        or commit.get("allocation_input_hash") != allocation.get("allocation_input_hash")
        or commit.get("adaptive_allocation_hash") != allocation_hash
    ):
        reasons.append("CYCLE_RESERVATION_COMMIT_RECEIPT_INVALID")
    reasons.extend(str(reason) for reason in commit.get("rejection_reasons") or [] if reason)
    reasons.extend(
        str(reason)
        for reason in row.get("paper_cycle_reservation_commit_rejection_reasons") or []
        if reason
    )
    intrinsic_reasons = intrinsic_candidate_commit_receipt_rejection_reasons(
        snapshot=snapshot,
        adaptive_allocation=allocation,
        receipt=commit,
    )
    reasons.extend(intrinsic_reasons)
    if not validate_intrinsic_candidate_commit_receipt(
        snapshot=snapshot,
        adaptive_allocation=allocation,
        receipt=commit,
    ):
        reasons.append("CYCLE_RESERVATION_COMMIT_INTRINSIC_REPLAY_NOT_PASS")
    return sorted(set(reasons))


