def _paper_persisted_admission_projection(
    row: Mapping[str, Any],
) -> dict[str, Any]:
    """Project fields that no downstream persistence step may rewrite."""

    nested_fields = (
        "adaptive_allocation",
        "paper_normal_adaptive_allocation_contract",
        "paper_allocator_economic_contract",
        "paper_pre_cycle_control_snapshot",
        "a_plus_context_snapshot",
        "paper_entry_gate_snapshot",
        "paper_entry_gate_evaluation",
        "a_plus_gate_evaluation",
        "preemptive_edge_control",
        "paper_exchange_filter_snapshot",
        "paper_precycle_current_mark_exposure_snapshot",
        "paper_cycle_base_resource_evidence",
        "paper_dynamic_envelope_reservation_evidence",
        "paper_cycle_reservation_snapshot",
        "paper_cycle_reservation_commit_receipt",
        "paper_revocable_control_commit_revalidation",
        "paper_maintenance_margin_bracket_evidence",
        "maintenance_bracket_evidence",
        "mark_index_source_material",
        "long_short_source_material",
        "ordinary_paper_admission_evidence",
        ORDINARY_PAPER_ROUTER_PROOF_FIELD,
        "microstructure_trust_evidence",
    )
    return {
        "schema_version": "paper_persisted_admission_projection_v1",
        "critical_fields": {
            field: row.get(field)
            for field in (
                *PAPER_PERSISTED_ADMISSION_CRITICAL_FIELDS,
                *PAPER_FINAL_ADMISSION_COMPONENT_TIME_FIELDS,
            )
        },
        "nested_payload_hashes": {
            field: _paper_canonical_sha256(row.get(field)) for field in nested_fields
        },
    }


def _paper_persisted_admission_rejection_reasons(
    row: Mapping[str, Any],
) -> list[str]:
    reasons: list[str] = []
    contract = row.get("paper_final_admission_contract")
    if not isinstance(contract, Mapping):
        return ["PERSISTED_ADMISSION_FINAL_CONTRACT_MISSING"]
    contract_without_hash = dict(contract)
    receipt_hash = contract_without_hash.pop("receipt_hash", None)
    if (
        contract.get("schema_version") != "paper_final_admission_contract_v3"
        or contract.get("status") != "PASS"
        or not _paper_valid_sha256(receipt_hash)
        or receipt_hash != _paper_canonical_sha256(contract_without_hash)
        or receipt_hash != row.get("paper_final_admission_receipt_hash")
    ):
        reasons.append("PERSISTED_ADMISSION_FINAL_RECEIPT_INVALID")
    revocable_receipt = contract.get("revocable_control_commit_revalidation")
    if not isinstance(revocable_receipt, Mapping):
        reasons.append("PERSISTED_ADMISSION_REVOCABLE_CONTROL_RECEIPT_MISSING")
    else:
        revocable_without_hash = dict(revocable_receipt)
        revocable_hash = revocable_without_hash.pop("receipt_hash", None)
        if (
            revocable_receipt.get("schema_version")
            != "paper_revocable_control_commit_revalidation_v1"
            or revocable_receipt.get("status") != "PASS"
            or revocable_receipt.get("paper_only") is not True
            or revocable_receipt.get("routes_to_live") is not False
            or revocable_receipt.get("places_real_order") is not False
            or revocable_receipt.get("cross_process_atomic") is not False
            or not revocable_receipt.get("residual_toctou_risk")
            or revocable_receipt.get("rejection_reasons") not in ([], ())
            or not _paper_valid_sha256(revocable_hash)
            or revocable_hash != _paper_canonical_sha256(revocable_without_hash)
        ):
            reasons.append("PERSISTED_ADMISSION_REVOCABLE_CONTROL_RECEIPT_INVALID")
        if (
            dict(revocable_receipt) != row.get("paper_revocable_control_commit_revalidation")
            or revocable_hash != row.get("paper_revocable_control_commit_revalidation_receipt_hash")
            or row.get("paper_revocable_control_commit_revalidation_status") != "PASS"
        ):
            reasons.append("PERSISTED_ADMISSION_REVOCABLE_CONTROL_TOP_LEVEL_MISMATCH")
    bound_material = contract.get("bound_material")
    bound_material_hash = contract.get("bound_material_hash")
    if (
        not isinstance(bound_material, Mapping)
        or not _paper_valid_sha256(bound_material_hash)
        or bound_material_hash != _paper_canonical_sha256(bound_material)
        or bound_material_hash != row.get("paper_final_admission_bound_material_hash")
    ):
        reasons.append("PERSISTED_ADMISSION_BOUND_MATERIAL_INVALID")
        return sorted(set(reasons))
    if not isinstance(revocable_receipt, Mapping) or bound_material.get(
        "revocable_control_commit_revalidation"
    ) != dict(revocable_receipt):
        reasons.append("PERSISTED_ADMISSION_REVOCABLE_CONTROL_BOUND_MATERIAL_MISMATCH")
    allocation = row.get("adaptive_allocation")
    if not isinstance(allocation, Mapping):
        reasons.append("PERSISTED_ADMISSION_CYCLE_ALLOCATION_MISSING")
        allocation = {}
    reasons.extend(
        f"PERSISTED_ADMISSION_{reason}"
        for reason in _paper_cycle_reservation_contract_rejection_reasons(
            row,
            allocation,
        )
    )
    cycle_snapshot = row.get("paper_cycle_reservation_snapshot")
    expected_cycle_contract = {
        "paper_cycle_reservation_snapshot": cycle_snapshot,
        "paper_cycle_reservation_snapshot_hash": row.get("paper_cycle_reservation_snapshot_hash"),
        "paper_cycle_reservation_commit_receipt": row.get("paper_cycle_reservation_commit_receipt"),
        "paper_cycle_reservation_commit_receipt_hash": row.get(
            "paper_cycle_reservation_commit_receipt_hash"
        ),
        "paper_cycle_reservation_commit_status": row.get("paper_cycle_reservation_commit_status"),
        "cycle_identity": (
            cycle_snapshot.get("cycle_identity") if isinstance(cycle_snapshot, Mapping) else None
        ),
    }
    if bound_material.get("cycle_reservation_contract") != expected_cycle_contract:
        reasons.append("PERSISTED_ADMISSION_CYCLE_RESERVATION_BOUND_MATERIAL_MISMATCH")
    sealed_projection = bound_material.get("persisted_row_projection")
    sealed_projection_hash = bound_material.get("persisted_row_projection_hash")
    current_projection = _paper_persisted_admission_projection(row)
    if (
        not isinstance(sealed_projection, Mapping)
        or not _paper_valid_sha256(sealed_projection_hash)
        or sealed_projection_hash != _paper_canonical_sha256(sealed_projection)
        or sealed_projection_hash != _paper_canonical_sha256(current_projection)
        or dict(sealed_projection) != current_projection
    ):
        reasons.append("PERSISTED_ADMISSION_ROW_MUTATED_AFTER_FINAL_SEAL")
    if row.get("paper_final_admission_status") != "PASS":
        reasons.append("PERSISTED_ADMISSION_TOP_LEVEL_STATUS_NOT_PASS")
    if row.get("paper_final_admission_decision_time") != contract.get("final_decision_time"):
        reasons.append("PERSISTED_ADMISSION_FINAL_TIME_MISMATCH")
    return sorted(set(reasons))


def _seal_paper_persisted_ledger_contract(
    row: Mapping[str, Any],
) -> dict[str, Any]:
    sealed = dict(row)
    projection = _paper_persisted_admission_projection(sealed)
    material = {
        "schema_version": "paper_persisted_ledger_contract_v1",
        "observed_at": _utc_iso(),
        "final_admission_receipt_hash": sealed.get("paper_final_admission_receipt_hash"),
        "final_admission_bound_material_hash": sealed.get(
            "paper_final_admission_bound_material_hash"
        ),
        "projection_hash": _paper_canonical_sha256(projection),
        "projection": projection,
        "status": "PASS",
        "paper_only": True,
        "routes_to_live": False,
        "places_real_order": False,
    }
    receipt_hash = _paper_canonical_sha256(material)
    material["receipt_hash"] = receipt_hash
    sealed["paper_persisted_ledger_contract"] = material
    sealed["paper_persisted_ledger_contract_hash"] = receipt_hash
    sealed["paper_persisted_ledger_status"] = "PASS"
    return sealed


def _paper_allocator_contract_projection(current: Any, sealed: Any) -> Any:
    """Project current allocation state onto the exact allocator-owned key set.

    Downstream gates may add telemetry keys, but they may not change or delete
    any value emitted by the allocator.  Recursive projection ignores additions
    while representing deletions/type changes with an impossible sentinel so a
    later hash comparison fails closed.
    """

    if isinstance(sealed, Mapping):
        if not isinstance(current, Mapping):
            return {"__paper_allocator_contract_type_mismatch__": True}
        projected: dict[str, Any] = {}
        for key, sealed_value in sealed.items():
            if key not in current:
                projected[str(key)] = {"__paper_allocator_contract_missing_key__": str(key)}
            else:
                projected[str(key)] = _paper_allocator_contract_projection(
                    current.get(key), sealed_value
                )
        return projected
    return current


def _seal_paper_allocator_economic_contract(
    *,
    intent: dict[str, Any],
    allocation: dict[str, Any],
    sealed_at: datetime | None = None,
) -> dict[str, Any]:
    """Seal allocator output before any later admission gate can mutate it."""

    captured = sealed_at or datetime.now(timezone.utc)
    captured_utc = _strict_aware_utc_time(captured)
    material = deepcopy(allocation)
    material_hash = _paper_canonical_sha256(material)
    receipt = {
        "schema_version": "paper_allocator_economic_contract_v1",
        "sealed_at": (
            captured_utc.isoformat().replace("+00:00", "Z") if captured_utc is not None else None
        ),
        "allocation_id": allocation.get("allocation_id"),
        "material_hash": material_hash,
        "material": material,
        "projection_contract": (
            "RECURSIVE_EXACT_VALUES_FOR_ALLOCATOR_EMITTED_KEYS;" "DOWNSTREAM_ADDITIONS_ONLY"
        ),
    }
    receipt_hash = _paper_canonical_sha256(receipt)
    receipt["receipt_hash"] = receipt_hash
    for target in (intent, allocation):
        target["paper_allocator_economic_contract_sealed_at"] = receipt["sealed_at"]
        target["paper_allocator_economic_contract_hash"] = material_hash
        target["paper_allocator_economic_contract_receipt_hash"] = receipt_hash
        target["paper_allocator_economic_contract_schema_version"] = receipt["schema_version"]
    intent["paper_allocator_economic_contract"] = receipt
    return receipt


def _seal_paper_normal_allocation_before_reduction(
    *,
    intent: dict[str, Any],
    normal_allocation: dict[str, Any],
) -> dict[str, Any]:
    """Preserve the exact first allocation and the later reduction authority.

    Reduced paper tiers are classified only after the normal allocator pass.
    Replacing the top-level allocation decision clock used to erase the proof
    that the first pass preceded the gates and that the second pass followed
    them.  This receipt retains both the full normal economic seal and the
    exact gate/tier fields that authorize a recomputation at a smaller budget.
    """

    normal_pit = deepcopy(intent.get("paper_allocation_point_in_time_evidence"))
    normal_economic_contract = deepcopy(intent.get("paper_allocator_economic_contract"))
    normal_decision_time = intent.get("paper_allocation_decision_time")
    material = {
        "schema_version": "paper_normal_allocation_before_reduction_v1",
        "receipt_sealed_at": _utc_iso(),
        "allocation_id": normal_allocation.get("allocation_id"),
        "allocation_hash": normal_allocation.get("allocation_hash"),
        "allocation_input_hash": normal_allocation.get("allocation_input_hash"),
        "allocation_decision_time": normal_decision_time,
        "allocation_point_in_time_status": intent.get("paper_allocation_point_in_time_status"),
        "allocation_point_in_time_evidence": normal_pit,
        "allocation_point_in_time_evidence_hash": _paper_canonical_sha256(normal_pit),
        "economic_contract_hash": intent.get("paper_allocator_economic_contract_hash"),
        "economic_contract_receipt_hash": intent.get(
            "paper_allocator_economic_contract_receipt_hash"
        ),
        "economic_contract_sealed_at": intent.get("paper_allocator_economic_contract_sealed_at"),
        "economic_contract": normal_economic_contract,
        "normal_economics": {
            field: normal_allocation.get(field)
            for field in (
                "target_quantity",
                "target_notional_usd",
                "target_notional_usdt",
                "gross_notional_usd",
                "risk_budget_usd",
                "expected_max_loss_usd",
                "effective_leverage",
                "recommended_leverage",
                "allocated_margin_usd",
                "recommended_margin_mode",
                "margin_mode_simulated",
            )
        },
        "reduction_authority": {
            field: intent.get(field)
            for field in (
                "paper_opportunity_tier",
                "paper_opportunity_tier_reason",
                "paper_fill_allowed_source",
                "risk_budget_fraction_of_normal_adaptive",
                "paper_entry_gate_evaluation_hash",
                "paper_entry_gate_evaluated_at",
                "a_plus_gate_evaluation_hash",
                "a_plus_gate_evaluated_at",
                "preemptive_decision_id",
                "preemptive_input_hash",
                "preemptive_decision_time",
            )
        },
        "paper_only": True,
        "routes_to_live": False,
        "places_real_order": False,
    }
    receipt_hash = _paper_canonical_sha256(material)
    receipt = {**material, "receipt_hash": receipt_hash}
    for target in (intent, normal_allocation):
        target["normal_adaptive_allocation_decision_time"] = normal_decision_time
        target["normal_adaptive_allocation_point_in_time_evidence_hash"] = material[
            "allocation_point_in_time_evidence_hash"
        ]
        target["normal_adaptive_allocator_economic_contract_receipt_hash"] = material[
            "economic_contract_receipt_hash"
        ]
        target["normal_adaptive_allocator_economic_contract_sealed_at"] = material[
            "economic_contract_sealed_at"
        ]
        target["normal_adaptive_allocation_contract_hash"] = receipt_hash
        target["normal_adaptive_allocation_contract_sealed_at"] = material["receipt_sealed_at"]
    intent["paper_normal_adaptive_allocation_contract"] = receipt
    return receipt


def _paper_normal_allocation_contract_rejection_reasons(
    intent: Mapping[str, Any],
    reduced_allocation: Mapping[str, Any],
) -> list[str]:
    """Validate the sealed normal pass retained by a reduced allocation."""

    reasons: list[str] = []
    contract = intent.get("paper_normal_adaptive_allocation_contract")
    if not isinstance(contract, Mapping):
        return ["NORMAL_ALLOCATION_CONTRACT_MISSING"]
    material = dict(contract)
    receipt_hash = material.pop("receipt_hash", None)
    if (
        contract.get("schema_version") != "paper_normal_allocation_before_reduction_v1"
        or contract.get("paper_only") is not True
        or contract.get("routes_to_live") is not False
        or contract.get("places_real_order") is not False
    ):
        reasons.append("NORMAL_ALLOCATION_CONTRACT_AUTHORITY_INVALID")
    if (
        not _paper_valid_sha256(receipt_hash)
        or receipt_hash != _paper_canonical_sha256(material)
        or receipt_hash != intent.get("normal_adaptive_allocation_contract_hash")
        or receipt_hash != reduced_allocation.get("normal_adaptive_allocation_contract_hash")
    ):
        reasons.append("NORMAL_ALLOCATION_CONTRACT_HASH_INVALID")

    normal_id = contract.get("allocation_id")
    normal_input_hash = contract.get("allocation_input_hash")
    if (
        normal_id in (None, "")
        or normal_id != intent.get("normal_adaptive_allocation_id")
        or normal_id != reduced_allocation.get("normal_adaptive_allocation_id")
        or normal_id == reduced_allocation.get("allocation_id")
    ):
        reasons.append("NORMAL_ALLOCATION_CONTRACT_IDENTITY_INVALID")
    if (
        not _paper_valid_sha256(normal_input_hash)
        or normal_input_hash != intent.get("normal_adaptive_allocation_input_hash")
        or normal_input_hash != reduced_allocation.get("normal_adaptive_allocation_input_hash")
    ):
        reasons.append("NORMAL_ALLOCATION_INPUT_HASH_INVALID")

    normal_decision_time = contract.get("allocation_decision_time")
    if (
        _strict_aware_utc_time(normal_decision_time) is None
        or normal_decision_time != intent.get("normal_adaptive_allocation_decision_time")
        or normal_decision_time
        != reduced_allocation.get("normal_adaptive_allocation_decision_time")
    ):
        reasons.append("NORMAL_ALLOCATION_DECISION_TIME_INVALID")
    pit = contract.get("allocation_point_in_time_evidence")
    pit_hash = contract.get("allocation_point_in_time_evidence_hash")
    if (
        not isinstance(pit, Mapping)
        or pit.get("status") != "PASS"
        or pit.get("decision_time") != normal_decision_time
        or contract.get("allocation_point_in_time_status") != "PASS"
        or not _paper_valid_sha256(pit_hash)
        or pit_hash != _paper_canonical_sha256(pit)
        or pit_hash != intent.get("normal_adaptive_allocation_point_in_time_evidence_hash")
        or pit_hash
        != reduced_allocation.get("normal_adaptive_allocation_point_in_time_evidence_hash")
    ):
        reasons.append("NORMAL_ALLOCATION_PIT_RECEIPT_INVALID")
    elif isinstance(pit.get("observed_component_times"), Mapping):
        normal_decision_utc = _strict_aware_utc_time(normal_decision_time)
        for field, raw_time in pit["observed_component_times"].items():
            component_time = _strict_aware_utc_time(raw_time)
            if (
                component_time is None
                or normal_decision_utc is None
                or component_time > normal_decision_utc
            ):
                reasons.append(f"NORMAL_ALLOCATION_PIT_COMPONENT_TIME_INVALID:{field}")

    economic = contract.get("economic_contract")
    economic_hash = contract.get("economic_contract_hash")
    economic_receipt_hash = contract.get("economic_contract_receipt_hash")
    if not isinstance(economic, Mapping):
        reasons.append("NORMAL_ALLOCATION_ECONOMIC_CONTRACT_MISSING")
    else:
        economic_receipt_material = dict(economic)
        nested_receipt_hash = economic_receipt_material.pop("receipt_hash", None)
        economic_material = economic.get("material")
        if (
            economic.get("schema_version") != "paper_allocator_economic_contract_v1"
            or economic.get("allocation_id") != normal_id
            or not _paper_valid_sha256(nested_receipt_hash)
            or nested_receipt_hash != _paper_canonical_sha256(economic_receipt_material)
            or nested_receipt_hash != economic_receipt_hash
            or economic_receipt_hash
            != intent.get("normal_adaptive_allocator_economic_contract_receipt_hash")
            or not isinstance(economic_material, Mapping)
            or economic.get("material_hash") != _paper_canonical_sha256(economic_material)
            or economic.get("material_hash") != economic_hash
            or economic_hash != intent.get("normal_adaptive_allocator_economic_contract_hash")
            or economic_hash
            != reduced_allocation.get("normal_adaptive_allocator_economic_contract_hash")
        ):
            reasons.append("NORMAL_ALLOCATION_ECONOMIC_CONTRACT_INVALID")

    expected_authority = {
        field: intent.get(field)
        for field in (
            "paper_opportunity_tier",
            "paper_opportunity_tier_reason",
            "paper_fill_allowed_source",
            "risk_budget_fraction_of_normal_adaptive",
            "paper_entry_gate_evaluation_hash",
            "paper_entry_gate_evaluated_at",
            "a_plus_gate_evaluation_hash",
            "a_plus_gate_evaluated_at",
            "preemptive_decision_id",
            "preemptive_input_hash",
            "preemptive_decision_time",
        )
    }
    if contract.get("reduction_authority") != expected_authority:
        reasons.append("NORMAL_ALLOCATION_REDUCTION_AUTHORITY_MISMATCH")

    normal_economics = contract.get("normal_economics")
    if not isinstance(normal_economics, Mapping):
        reasons.append("NORMAL_ALLOCATION_ECONOMICS_MISSING")
    else:
        for field in B_GRADE_EXPLORATION_SCALABLE_ALLOCATION_FIELDS:
            alias = f"normal_adaptive_{field}"
            if alias in reduced_allocation and (
                reduced_allocation.get(alias) != normal_economics.get(field)
            ):
                reasons.append(f"NORMAL_ALLOCATION_ECONOMIC_ALIAS_MISMATCH:{field}")

    reduced_pit = intent.get("paper_allocation_point_in_time_evidence")
    if (
        intent.get("paper_reduced_allocation_decision_time")
        != intent.get("paper_allocation_decision_time")
        or not isinstance(reduced_pit, Mapping)
        or reduced_pit.get("status") != "PASS"
        or reduced_pit.get("decision_time") != intent.get("paper_reduced_allocation_decision_time")
        or not _paper_valid_sha256(
            intent.get("paper_reduced_allocation_point_in_time_evidence_hash")
        )
        or intent.get("paper_reduced_allocation_point_in_time_evidence_hash")
        != _paper_canonical_sha256(reduced_pit)
        or intent.get("paper_reduced_allocation_decision_time")
        != reduced_allocation.get("paper_reduced_allocation_decision_time")
        or intent.get("paper_reduced_allocation_point_in_time_evidence_hash")
        != reduced_allocation.get("paper_reduced_allocation_point_in_time_evidence_hash")
    ):
        reasons.append("REDUCED_ALLOCATION_PIT_RECEIPT_INVALID")
    return sorted(set(reasons))


def _paper_revocable_control_commit_revalidation(
    intent: Mapping[str, Any],
    *,
    redis_client: Any,
    validation_started_at: datetime | None,
) -> dict[str, Any]:
    """Exact-reread mutable admission controls immediately before commit.

    Redis does not provide one transaction spanning these independently-owned
    keys and procfs/systemd ownership.  This receipt therefore proves a single
    ordered reread chain and records the residual append-window TOCTOU rather
    than claiming cross-process atomicity.
    """

    rejection_reasons: list[str] = []

    def reject(reason: str) -> None:
        rejection_reasons.append(str(reason))

    frozen_snapshot = intent.get("paper_pre_cycle_control_snapshot")
    frozen_lineage = (
        frozen_snapshot.get("lineage") if isinstance(frozen_snapshot, Mapping) else None
    )
    frozen_by_role: dict[str, Mapping[str, Any]] = {}
    if not isinstance(frozen_lineage, list):
        reject("FROZEN_PRE_CYCLE_LINEAGE_MISSING")
    else:
        for raw_receipt in frozen_lineage:
            if not isinstance(raw_receipt, Mapping):
                reject("FROZEN_PRE_CYCLE_LINEAGE_ROW_INVALID")
                continue
            role = str(raw_receipt.get("role") or "")
            if not role:
                reject("FROZEN_PRE_CYCLE_LINEAGE_ROLE_MISSING")
                continue
            if role in frozen_by_role:
                reject(f"FROZEN_PRE_CYCLE_LINEAGE_ROLE_DUPLICATE:{role}")
                continue
            frozen_by_role[role] = raw_receipt

    current_sources = _paper_revocable_control_source_materials(redis_client)
    source_status_policy = {
        "continuous_edge_guardian": {"READY"},
        "paper_entry_freeze_source": {"READY", "MISSING"},
        "portfolio_state_source": {"READY"},
        "adaptive_tuning_source": {"READY"},
        "paper_session_source": {"READY"},
        "paper_position_or_ledger_source": {"READY"},
        "paper_closed_trades_source": {"READY"},
    }
    source_receipts: dict[str, dict[str, Any]] = {}
    for role, allowed_statuses in source_status_policy.items():
        current = current_sources.get(role)
        current_material = dict(current) if isinstance(current, Mapping) else {}
        current_hash = _paper_canonical_sha256(current_material)
        frozen = frozen_by_role.get(role)
        frozen_hash = frozen.get("payload_hash") if isinstance(frozen, Mapping) else None
        exact_match = bool(
            _paper_valid_sha256(current_hash)
            and _paper_valid_sha256(frozen_hash)
            and current_hash == frozen_hash
        )
        read_status = str(current_material.get("read_status") or "MISSING")
        source_key = current_material.get("source_key")
        source_label_match = bool(
            isinstance(frozen, Mapping) and frozen.get("redis_key") == source_key
        )
        source_receipts[role] = {
            "source_kind": current_material.get("source_kind"),
            "source_key": source_key,
            "read_status": read_status,
            "present": current_material.get("present") is True,
            "frozen_hash": frozen_hash,
            "current_hash": current_hash,
            "exact_match": exact_match,
            "source_label_match": source_label_match,
        }
        if not isinstance(frozen, Mapping):
            reject(f"FROZEN_CONTROL_RECEIPT_MISSING:{role}")
        if read_status not in allowed_statuses:
            reject(f"CURRENT_CONTROL_SOURCE_NOT_READY:{role}:{read_status}")
        if not source_label_match:
            reject(f"CONTROL_SOURCE_LABEL_MISMATCH:{role}")
        if not exact_match:
            reject(f"CONTROL_SOURCE_CHANGED:{role}")

    current_session_payload = _paper_exact_source_payload(
        current_sources.get("paper_session_source"),
        expected_container="mapping",
    )
    (
        current_paper_session_id,
        current_session_rejection_reasons,
    ) = _paper_session_identity(current_session_payload)
    if current_paper_session_id != intent.get("paper_session_id"):
        current_session_rejection_reasons.append("CURRENT_PAPER_SESSION_CHANGED_FROM_CANDIDATE")
    for session_reason in current_session_rejection_reasons:
        reject(f"PAPER_SESSION_REVALIDATION:{session_reason}")
    source_receipts.setdefault("paper_session_source", {}).update(
        {
            "resolved_paper_session_id": current_paper_session_id,
            "semantic_status": ("PASS" if not current_session_rejection_reasons else "BLOCKED"),
            "semantic_rejection_reasons": sorted(set(current_session_rejection_reasons)),
        }
    )
    current_tuning_payload = _paper_exact_source_payload(
        current_sources.get("adaptive_tuning_source"),
        expected_container="mapping",
    )
    tuning_semantic_observed_at = _utc_iso()
    tuning_semantic_revalidation = _paper_adaptive_tuning_semantic_validation(
        current_tuning_payload,
        observed_at=tuning_semantic_observed_at,
        current_paper_session_id=current_paper_session_id,
        session_identity_rejection_reasons=(current_session_rejection_reasons),
    )
    source_receipts.setdefault("adaptive_tuning_source", {}).update(
        {
            "semantic_validation": tuning_semantic_revalidation,
            "semantic_validation_status": tuning_semantic_revalidation.get("status"),
            "semantic_validation_receipt_hash": (tuning_semantic_revalidation.get("receipt_hash")),
        }
    )
    for tuning_reason in tuning_semantic_revalidation.get("rejection_reasons") or []:
        reject(f"ADAPTIVE_TUNING_REVALIDATION:{tuning_reason}")

    guardian_ttl: int | None = None
    try:
        if redis_client is not None:
            guardian_ttl = int(redis_client.ttl(CONTINUOUS_EDGE_GUARDIAN_GATE_REDIS_KEY))
    except Exception:
        guardian_ttl = None
    guardian_ttl_valid = bool(guardian_ttl is not None and 0 < guardian_ttl <= 180)
    if not guardian_ttl_valid:
        reject("GUARDIAN_TTL_INVALID_OR_STALE")
    guardian_payload = _paper_exact_source_payload(
        current_sources.get("continuous_edge_guardian"),
        expected_container="mapping",
    )
    final_tier = str(intent.get("paper_opportunity_tier") or "").upper()
    guardian_currently_allows = _continuous_edge_guardian_allows_new_entries(guardian_payload)
    if (
        final_tier
        in {
            PAPER_TIER_A_GRADE_EXECUTION,
            PAPER_TIER_A_PLUS_BOOTSTRAP_REDUCED_SIZE,
        }
        and not guardian_currently_allows
    ):
        reject("GUARDIAN_CURRENTLY_BLOCKS_EXECUTION_TIER")

    current_freeze = _compose_paper_entry_freeze(
        _paper_exact_source_payload(
            current_sources.get("paper_entry_freeze_source"),
            expected_container="mapping",
        ),
        _paper_exact_source_payload(
            current_sources.get("portfolio_state_source"),
            expected_container="mapping",
        ),
    )
    current_freeze_hash = _paper_canonical_sha256(current_freeze)
    frozen_freeze = frozen_by_role.get("paper_entry_freeze")
    frozen_freeze_hash = (
        frozen_freeze.get("payload_hash") if isinstance(frozen_freeze, Mapping) else None
    )
    freeze_exact_match = bool(
        _paper_valid_sha256(current_freeze_hash)
        and _paper_valid_sha256(frozen_freeze_hash)
        and current_freeze_hash == frozen_freeze_hash
    )
    if not isinstance(frozen_freeze, Mapping):
        reject("FROZEN_EFFECTIVE_ENTRY_FREEZE_RECEIPT_MISSING")
    elif frozen_freeze.get("redis_key") != (
        "IN_PROCESS_COMPOSED_FROM_EXACT_REDIS_FREEZE_AND_PORTFOLIO_SOURCES"
    ):
        reject("FROZEN_EFFECTIVE_ENTRY_FREEZE_SOURCE_LABEL_INVALID")
    if not freeze_exact_match:
        reject("EFFECTIVE_ENTRY_FREEZE_CHANGED")

    freeze_halted = current_freeze.get("paper_new_entries_halted") is True
    freeze_nonoverridable = _paper_entry_freeze_nonoverridable(current_freeze)
    freeze_override_allowed = False
    if freeze_halted:
        if freeze_nonoverridable:
            reject("NONOVERRIDABLE_PORTFOLIO_TRUTH_FREEZE_ACTIVE")
        elif final_tier == PAPER_TIER_POSITIVE_EDGE_PROBATION:
            freeze_override_allowed = True
        elif final_tier == PAPER_TIER_RISK_CONTROLLER_EXPLORATION:
            freeze_override_allowed = _paper_risk_controller_exploration_can_override_entry_freeze(
                intent=intent,
                paper_entry_freeze=current_freeze,
            )
            if not freeze_override_allowed:
                reject("RISK_EXPLORATION_ENTRY_FREEZE_OVERRIDE_NOT_AUTHORIZED")
        else:
            reject("EFFECTIVE_ENTRY_FREEZE_ACTIVE")

    current_risk_state = _paper_current_risk_state_from_sources(current_sources)
    current_risk_hash = _paper_canonical_sha256(current_risk_state)
    frozen_risk = frozen_by_role.get("current_risk_state")
    frozen_risk_hash = frozen_risk.get("payload_hash") if isinstance(frozen_risk, Mapping) else None
    risk_exact_match = bool(
        _paper_valid_sha256(current_risk_hash)
        and _paper_valid_sha256(frozen_risk_hash)
        and current_risk_hash == frozen_risk_hash
    )
    if not isinstance(frozen_risk, Mapping):
        reject("FROZEN_CURRENT_RISK_STATE_RECEIPT_MISSING")
    elif frozen_risk.get("redis_key") != (
        "IN_PROCESS_DERIVED_FROM_EXACT_PAPER_POSITION_AND_PORTFOLIO_SOURCES"
    ):
        reject("FROZEN_CURRENT_RISK_STATE_SOURCE_LABEL_INVALID")
    if not risk_exact_match:
        reject("CURRENT_RISK_STATE_CHANGED")

    current_owner_status = _paper_active_runtime_owner_status()
    current_owner_projection = _paper_runtime_owner_minimal_projection(current_owner_status)
    current_owner_hash = _paper_canonical_sha256(current_owner_projection)
    frozen_owner = frozen_by_role.get("paper_runtime_owner")
    frozen_owner_hash = (
        frozen_owner.get("payload_hash") if isinstance(frozen_owner, Mapping) else None
    )
    owner_exact_match = bool(
        _paper_valid_sha256(current_owner_hash)
        and _paper_valid_sha256(frozen_owner_hash)
        and current_owner_hash == frozen_owner_hash
    )
    if not isinstance(frozen_owner, Mapping):
        reject("FROZEN_RUNTIME_OWNER_RECEIPT_MISSING")
    elif frozen_owner.get("redis_key") != ("PROCFS_AND_SYSTEMD_CURRENT_PROCESS_OWNER_PROJECTION"):
        reject("FROZEN_RUNTIME_OWNER_SOURCE_LABEL_INVALID")
    if not owner_exact_match:
        reject("RUNTIME_OWNER_PROJECTION_CHANGED")
    owner_conditions = current_owner_projection.get("pass_conditions")
    owner_conditions_pass = bool(
        isinstance(owner_conditions, Mapping)
        and owner_conditions
        and all(value is True for value in owner_conditions.values())
    )
    owner_allows = bool(
        current_owner_projection.get("status") == "PASS_ACTIVE_RUNTIME_OWNER_VALIDATION"
        and current_owner_projection.get("active_new_entry_owner")
        == "v2_trade_management_paper_loop"
        and current_owner_projection.get("canonical_paper_writer_count") == 1
        and current_owner_projection.get("canonical_service_scope_writer_count") == 1
        and current_owner_projection.get("forbidden_entry_process_count") == 0
        and current_owner_projection.get("duplicate_paper_writer_count") == 0
        and current_owner_projection.get("current_process_is_only_canonical_writer") is True
        and current_owner_projection.get("paper_only") is True
        and current_owner_projection.get("routes_to_live") is False
        and current_owner_projection.get("places_real_order") is False
        and owner_conditions_pass
    )
    if not owner_allows:
        reject("RUNTIME_OWNER_CURRENT_PROJECTION_BLOCKED")

    checked_at = _utc_iso()
    checked_utc = _strict_aware_utc_time(checked_at)
    if checked_utc is None:
        reject("REVALIDATION_CHECKED_AT_NOT_TIMEZONE_AWARE")
    elif validation_started_at is None or checked_utc < validation_started_at:
        reject("REVALIDATION_CLOCK_MOVED_BACKWARDS")
    commit_clock_tuning_validation = _paper_adaptive_tuning_semantic_validation(
        current_tuning_payload,
        observed_at=checked_at,
        current_paper_session_id=current_paper_session_id,
        session_identity_rejection_reasons=(current_session_rejection_reasons),
    )
    if commit_clock_tuning_validation.get("status") != "PASS":
        reject("ADAPTIVE_TUNING_EXPIRED_OR_INVALID_DURING_REVALIDATION")
    source_receipts.setdefault("adaptive_tuning_source", {}).update(
        {
            "commit_clock_semantic_validation": (commit_clock_tuning_validation),
            "commit_clock_semantic_validation_status": (
                commit_clock_tuning_validation.get("status")
            ),
            "commit_clock_semantic_validation_receipt_hash": (
                commit_clock_tuning_validation.get("receipt_hash")
            ),
        }
    )

    unique_reasons = sorted(set(rejection_reasons))
    receipt: dict[str, Any] = {
        "schema_version": "paper_revocable_control_commit_revalidation_v1",
        "status": "PASS" if not unique_reasons else "BLOCKED",
        "validation_started_at": (
            validation_started_at.isoformat().replace("+00:00", "Z")
            if validation_started_at is not None
            else None
        ),
        "checked_at": checked_at,
        "source_revalidation": source_receipts,
        "guardian": {
            "currently_allows_execution_tier": guardian_currently_allows,
            "ttl_remaining_seconds": guardian_ttl,
            "ttl_required_range_seconds": [1, 180],
            "ttl_valid": guardian_ttl_valid,
        },
        "effective_entry_freeze": {
            "frozen_hash": frozen_freeze_hash,
            "current_hash": current_freeze_hash,
            "exact_match": freeze_exact_match,
            "paper_new_entries_halted": freeze_halted,
            "nonoverridable": freeze_nonoverridable,
            "tier_override_allowed": freeze_override_allowed,
        },
        "current_risk_state": {
            "frozen_hash": frozen_risk_hash,
            "current_hash": current_risk_hash,
            "exact_match": risk_exact_match,
        },
        "runtime_owner": {
            "frozen_hash": frozen_owner_hash,
            "current_hash": current_owner_hash,
            "exact_match": owner_exact_match,
            "current_projection": current_owner_projection,
            "current_projection_allows": owner_allows,
        },
        "paper_only": True,
        "routes_to_live": False,
        "places_real_order": False,
        "cross_process_atomic": False,
        "residual_toctou_risk": (
            "CONTROL_OR_OWNER_CAN_CHANGE_AFTER_FINAL_REREAD_BEFORE_IN_PROCESS_LIST_APPEND;"
            "PERSISTENCE_REJECTS_MISSING_OR_MUTATED_RECEIPT_BUT_REDIS_KEYS_ARE_NOT_ONE_CAS"
        ),
        "rejection_reasons": unique_reasons,
    }
    receipt_hash = _paper_canonical_sha256(receipt)
    if not _paper_valid_sha256(receipt_hash):
        receipt["status"] = "BLOCKED"
        receipt["rejection_reasons"] = sorted(
            set(receipt["rejection_reasons"]) | {"REVALIDATION_RECEIPT_HASH_INVALID"}
        )
        receipt_hash = _paper_canonical_sha256(receipt)
    receipt["receipt_hash"] = receipt_hash
    return receipt


def _paper_final_admission_point_in_time_contract(
    intent: Mapping[str, Any],
    *,
    redis_client: Any = None,
    maintenance_bracket_security_context: Any = None,
    authoritative_ordinary_router_result: Mapping[str, Any] | None = None,
    authoritative_ordinary_router_input_material: Mapping[str, Any] | None = None,
    authoritative_current_position_state: Any = None,
) -> dict[str, Any]:
    """Revalidate the complete candidate at the actual list-append boundary.

    Earlier PASS fields are evidence, not authority.  This function reparses
    every late component clock, recomputes snapshot hashes and the allocation
    PIT contract from the current row, and proves the final allocator quantity,
    notional, leverage, margin, exchange filters, and bracket generation still
    form one identity immediately before materialization.
    """

    reasons: list[str] = []
    validation_started_utc = _strict_aware_utc_time(_utc_iso())
    # Component clocks are first checked against the start of validation.  A
    # second commit clock is captured after all authoritative re-reads and is
    # the only timestamp published as the final admission decision.
    final_utc = validation_started_utc
    parsed_times: dict[str, datetime] = {}
    observed_times: dict[str, str] = {}

    def reject(reason: str) -> None:
        reasons.append(reason)

    def parse_time(
        field: str,
        value: Any = None,
        *,
        required: bool = False,
        nested: bool = False,
        allow_after_final: bool = False,
    ) -> datetime | None:
        raw = value if nested else intent.get(field)
        if raw in (None, ""):
            if required:
                reject(f"FINAL_ADMISSION_TIME_MISSING:{field}")
            return None
        parsed = _strict_aware_utc_time(raw)
        if parsed is None:
            reject(f"FINAL_ADMISSION_TIME_UNPARSEABLE_OR_NAIVE:{field}")
            return None
        parsed_times[field] = parsed
        observed_times[field] = parsed.isoformat().replace("+00:00", "Z")
        if final_utc is not None and parsed > final_utc and not allow_after_final:
            reject(f"FINAL_ADMISSION_TIME_AFTER_DECISION:{field}")
        return parsed

    def require_order(left: str, right: str) -> None:
        left_time = parsed_times.get(left)
        right_time = parsed_times.get(right)
        if left_time is not None and right_time is not None and left_time > right_time:
            reject(f"FINAL_ADMISSION_TIME_ORDER_INVALID:{left}>{right}")

    if final_utc is None:
        reject("FINAL_ADMISSION_DECISION_TIME_NOT_TIMEZONE_AWARE")

    ordinary_final_assessment = _paper_ordinary_transport_assessment(
        redis_client,
        intent,
    )
    ordinary_final_revalidated = bool(
        ordinary_final_assessment.claimed and ordinary_final_assessment.accepted
    )
    if isinstance(intent, dict) and ordinary_final_assessment.claimed:
        intent["ordinary_paper_final_boundary_revalidated"] = ordinary_final_revalidated
        intent["ordinary_paper_final_boundary_rejection_reasons"] = list(
            ordinary_final_assessment.rejection_reasons
        )
        intent["ordinary_paper_final_boundary_evidence_sha256"] = (
            ordinary_final_assessment.evidence_sha256
        )
        intent["ordinary_paper_final_boundary_effective_sizing_weight"] = (
            ordinary_final_assessment.effective_sizing_weight
            if ordinary_final_revalidated
            else None
        )
        if ordinary_final_revalidated:
            intent.update(ordinary_final_assessment.transport_payload())
    if ordinary_final_assessment.claimed and not ordinary_final_revalidated:
        if ordinary_final_assessment.rejection_reasons:
            for ordinary_reason in ordinary_final_assessment.rejection_reasons:
                reject("FINAL_ORDINARY_PAPER_TRANSPORT_REVALIDATION:" f"{ordinary_reason}")
        else:
            reject("FINAL_ORDINARY_PAPER_TRANSPORT_REVALIDATION_FAILED")

    ordinary_final_router_proof = intent.get(ORDINARY_PAPER_ROUTER_PROOF_FIELD)
    ordinary_final_router_revalidated = False
    ordinary_final_router_weight: float | None = None
    ordinary_final_router_rejection_reasons: list[str] = []
    if ordinary_final_assessment.claimed:
        ordinary_final_router_rejection_reasons.extend(
            _paper_ordinary_router_proof_rejection_reasons(
                ordinary_final_router_proof,
                expected_admission_evidence_sha256=(ordinary_final_assessment.evidence_sha256),
            )
        )
        if isinstance(ordinary_final_router_proof, Mapping):
            current_proof_sha256 = ordinary_final_router_proof.get("proof_sha256")
            if intent.get(ORDINARY_PAPER_ROUTER_PROOF_SHA256_FIELD) != current_proof_sha256:
                ordinary_final_router_rejection_reasons.append(
                    "ORDINARY_PAPER_ROUTER_TOP_LEVEL_PROOF_HASH_MISMATCH"
                )
            if not isinstance(authoritative_ordinary_router_result, Mapping):
                ordinary_final_router_rejection_reasons.append(
                    "ORDINARY_PAPER_ROUTER_AUTHORITATIVE_RESULT_MISSING"
                )
            if not isinstance(
                authoritative_ordinary_router_input_material,
                Mapping,
            ):
                ordinary_final_router_rejection_reasons.append(
                    "ORDINARY_PAPER_ROUTER_AUTHORITATIVE_INPUT_MISSING"
                )
            if authoritative_current_position_state in (None, ""):
                ordinary_final_router_rejection_reasons.append(
                    "ORDINARY_PAPER_ROUTER_AUTHORITATIVE_POSITION_STATE_MISSING"
                )
            if (
                ordinary_final_revalidated
                and isinstance(authoritative_ordinary_router_result, Mapping)
                and isinstance(
                    authoritative_ordinary_router_input_material,
                    Mapping,
                )
                and authoritative_current_position_state not in (None, "")
            ):
                expected_final_router_proof = _paper_ordinary_strategy_router_interpretation_proof(
                    router_result=authoritative_ordinary_router_result,
                    router_input_material=(authoritative_ordinary_router_input_material),
                    ordinary_admission=ordinary_final_assessment,
                    proposed_action=_first_present(
                        intent.get("side"),
                        intent.get("selected_action"),
                        intent.get("action"),
                    ),
                    current_position_state=authoritative_current_position_state,
                )
                if dict(ordinary_final_router_proof) != dict(expected_final_router_proof):
                    ordinary_final_router_rejection_reasons.append(
                        "ORDINARY_PAPER_ROUTER_PROOF_NOT_REPLAYABLE_FROM_FINAL_READBACK"
                    )
                expected_interpretation = expected_final_router_proof.get("interpretation")
                if isinstance(expected_interpretation, Mapping):
                    ordinary_final_router_rejection_reasons.extend(
                        "ORDINARY_PAPER_ROUTER_FINAL_REPLAY:" f"{reason}"
                        for reason in expected_interpretation.get("hard_reasons") or []
                    )
                ordinary_final_router_weight = _coerce_float(
                    expected_interpretation.get("continuous_weight")
                    if isinstance(expected_interpretation, Mapping)
                    else None
                )
        ordinary_final_router_rejection_reasons = sorted(
            set(ordinary_final_router_rejection_reasons)
        )
        ordinary_final_router_revalidated = bool(
            ordinary_final_revalidated
            and not ordinary_final_router_rejection_reasons
            and ordinary_final_router_weight is not None
            and ordinary_final_router_weight > 0.0
        )
        if isinstance(intent, dict):
            intent["ordinary_paper_strategy_router_final_boundary_revalidated"] = (
                ordinary_final_router_revalidated
            )
            intent["ordinary_paper_strategy_router_final_boundary_rejection_reasons"] = list(
                ordinary_final_router_rejection_reasons
            )
            intent["ordinary_paper_strategy_router_final_boundary_continuous_weight"] = (
                ordinary_final_router_weight if ordinary_final_router_revalidated else None
            )
        for router_reason in ordinary_final_router_rejection_reasons:
            reject(f"FINAL_{router_reason}")

    executable_tiers = {
        PAPER_TIER_A_GRADE_EXECUTION,
        PAPER_TIER_A_PLUS_BOOTSTRAP_REDUCED_SIZE,
        PAPER_TIER_B_GRADE_EXPLORATION,
        PAPER_TIER_POSITIVE_EDGE_PROBATION,
        PAPER_TIER_RISK_CONTROLLER_EXPLORATION,
    }
    final_tier = str(intent.get("paper_opportunity_tier") or "").strip().upper()
    if intent.get("paper_opportunity_tier") != final_tier:
        reject("FINAL_ADMISSION_TIER_NOT_CANONICAL_ENUM")
    if final_tier not in executable_tiers:
        reject("FINAL_ADMISSION_TIER_NOT_EXECUTABLE:" f"{final_tier or 'MISSING'}")
    if intent.get("paper_fill_allowed") is not True:
        reject("FINAL_ADMISSION_PAPER_FILL_ALLOWED_NOT_TRUE")
    if not ordinary_final_revalidated and intent.get("valid_for_paper") is not True:
        reject("FINAL_ADMISSION_VALID_FOR_PAPER_NOT_TRUE")
    if str(intent.get("decision") or "").strip().upper() != ("ACCEPTED_PAPER_FILL"):
        reject("FINAL_ADMISSION_EXECUTABLE_DECISION_INVALID")
    for blocker in _non_relaxable_entry_gate_reasons(dict(intent)):
        reject(f"FINAL_ADMISSION_NON_RELAXABLE_ENTRY_GATE:{blocker}")

    tier_source_contracts: dict[
        str,
        tuple[set[tuple[str, str]], str | None],
    ] = {
        PAPER_TIER_A_GRADE_EXECUTION: (
            {
                (
                    "STRICT_UPSTREAM_PAPER_FILL_GATE",
                    "STRICT_UPSTREAM_PAPER_FILL_GATE_ALLOWED",
                ),
                (
                    "DYNAMIC_A_GRADE_PAPER_TAG",
                    "DYNAMIC_A_GRADE_SIGNAL_TAG_ALLOWED_PAPER_ONLY",
                ),
            },
            None,
        ),
        PAPER_TIER_A_PLUS_BOOTSTRAP_REDUCED_SIZE: (
            {
                (
                    "A_PLUS_REDUCED_SIZE_BOOTSTRAP_PAPER_LOCAL_GATE",
                    "MICROSTRUCTURE_TRUST_BOOTSTRAP_FLAG",
                ),
                (
                    "A_PLUS_REDUCED_SIZE_BOOTSTRAP_PAPER_LOCAL_GATE",
                    "REDUCED_SIZE_COMPOSITE_BELOW_FINAL_A_PLUS",
                ),
            },
            "A_PLUS_REDUCED_SIZE_BOOTSTRAP_OUTCOME_LABEL",
        ),
        PAPER_TIER_B_GRADE_EXPLORATION: (
            {
                ("B_GRADE_EXPLORATION_PAPER_LOCAL_GATE", reason)
                for reason in (
                    "PAPER_ONLY_PRIORITY_BUCKET_LABEL_COLLECTION",
                    "EXPLICIT_B_GRADE_PAPER_TAG",
                    "PAPER_CONFIDENCE_THRESHOLD_TRIAL",
                    "DYNAMIC_POSITIVE_EDGE_BELOW_A_GRADE_EXPLORATION",
                )
            },
            "B_GRADE_EXPLORATION_OUTCOME_LABEL",
        ),
        PAPER_TIER_POSITIVE_EDGE_PROBATION: (
            {
                (
                    "POSITIVE_EDGE_PROBATION_PAPER_LOCAL_GATE",
                    "GLOBAL_HALT_POSITIVE_EDGE_PROBATION_PAPER_ONLY",
                )
            },
            POSITIVE_EDGE_PROBATION_OUTCOME_LABEL,
        ),
        PAPER_TIER_RISK_CONTROLLER_EXPLORATION: (
            {
                (
                    "PAPER_RISK_CONTROLLER_EXPLORATION_LOCAL_GATE",
                    "DYNAMIC_EVIDENCE_AWARE_PAPER_RISK_CONTROLLER_EXPLORATION",
                )
            },
            PAPER_RISK_CONTROLLER_EXPLORATION_OUTCOME_LABEL,
        ),
    }
    tier_source_contract = tier_source_contracts.get(final_tier)
    if tier_source_contract is not None:
        allowed_pairs, required_label = tier_source_contract
        observed_pair = (
            intent.get("paper_fill_allowed_source"),
            intent.get("paper_opportunity_tier_reason"),
        )
        if observed_pair not in allowed_pairs:
            reject("FINAL_ADMISSION_TIER_SOURCE_REASON_PAIR_INVALID")
        if required_label is not None and intent.get("calibration_label_purpose") != required_label:
            reject("FINAL_ADMISSION_TIER_CALIBRATION_LABEL_INVALID")
    if final_tier == PAPER_TIER_A_GRADE_EXECUTION:
        if intent.get("continuous_edge_guardian_new_entries_allowed") is not True:
            reject("FINAL_ADMISSION_A_GRADE_GUARDIAN_NOT_ALLOWING_ENTRIES")
        if intent.get("paper_reduced_budget_allocator_recomputed") is True:
            reject("FINAL_ADMISSION_A_GRADE_MARKED_REDUCED_BUDGET")
    elif final_tier in executable_tiers:
        if intent.get("paper_reduced_budget_allocator_recomputed") is not True:
            reject("FINAL_ADMISSION_REDUCED_TIER_NOT_REALLOCATED")
        for required_false_field in (
            "counts_as_a_grade_evidence",
            "counts_as_A_plus",
            "counts_as_final_a_plus",
            "counts_as_live_ready",
        ):
            if intent.get(required_false_field) is not False:
                reject("FINAL_ADMISSION_REDUCED_TIER_FLAG_NOT_FALSE:" f"{required_false_field}")
        for required_true_field in (
            "mandatory_size_haircut",
            "no_static_dollar_notional",
            "no_leverage_increase_to_compensate_for_lower_trust",
        ):
            if intent.get(required_true_field) is not True:
                reject("FINAL_ADMISSION_REDUCED_TIER_FLAG_NOT_TRUE:" f"{required_true_field}")
    if final_tier == PAPER_TIER_RISK_CONTROLLER_EXPLORATION:
        for alias in (
            "tier",
            "exploration_tier",
            "paper_exploration_tier",
        ):
            if intent.get(alias) != PAPER_TIER_RISK_CONTROLLER_EXPLORATION:
                reject(f"FINAL_ADMISSION_RISK_EXPLORATION_ALIAS_INVALID:{alias}")
        if (
            intent.get("paper_risk_controller_exploration") is not True
            or intent.get("allow_paper_risk_controller_exploration") is not True
            or intent.get("paper_risk_controller_exploration_eligible") is not True
            or intent.get("paper_exploration_paper_fill_allowed") is not True
        ):
            reject("FINAL_ADMISSION_RISK_EXPLORATION_ELIGIBILITY_INVALID")

    required_common_times = {
        "paper_allocation_decision_time",
        "paper_precycle_exposure_snapshot_started_at",
        "paper_precycle_exposure_snapshot_completed_at",
        "advanced_indicator_lookup_observed_at",
        "altdata_lookup_observed_at",
        "long_short_lookup_observed_at",
        "a_plus_context_snapshot_observed_at",
        "a_plus_gate_evaluated_at",
        "paper_entry_gate_snapshot_observed_at",
        "paper_entry_gate_evaluated_at",
        "paper_pre_cycle_control_snapshot_observed_at",
        "runtime_cost_capture_decision_time",
        "preemptive_decision_time",
        "maintenance_bracket_available_at",
        "maintenance_bracket_expires_at",
        "maintenance_bracket_consumer_observed_at",
        "paper_allocator_economic_contract_sealed_at",
        "paper_exchange_filter_available_at",
        "paper_exchange_filter_observed_at",
    }
    if intent.get("paper_reduced_budget_allocator_recomputed") is True:
        required_common_times.update(
            {
                "normal_adaptive_allocation_decision_time",
                "normal_adaptive_allocator_economic_contract_sealed_at",
                "normal_adaptive_allocation_contract_sealed_at",
                "paper_reduced_allocation_decision_time",
            }
        )
    for field in PAPER_FINAL_ADMISSION_COMPONENT_TIME_FIELDS:
        parse_time(
            field,
            required=field in required_common_times,
            # Expiry is a validity deadline, not an input-availability clock.
            # A usable signed bracket must expire *after* final admission.
            allow_after_final=field == "maintenance_bracket_expires_at",
        )

    allocation_decision = parsed_times.get("paper_allocation_decision_time")
    if allocation_decision is not None:
        recomputed_allocation_pit = _paper_allocation_point_in_time_contract(
            intent,
            allocation_decision_time=allocation_decision,
        )
        if recomputed_allocation_pit.get("status") != "PASS":
            for reason in recomputed_allocation_pit.get("rejection_reasons") or []:
                reject(f"FINAL_RECOMPUTED_ALLOCATION_PIT:{reason}")
        if intent.get("paper_allocation_point_in_time_status") != (
            recomputed_allocation_pit.get("status")
        ):
            reject("STORED_ALLOCATION_PIT_STATUS_DIFFERS_FROM_RECOMPUTED")
    else:
        recomputed_allocation_pit = {
            "status": "BLOCKED",
            "rejection_reasons": ["ALLOCATION_DECISION_TIME_MISSING"],
        }

    for left, right in (
        (
            "paper_precycle_exposure_snapshot_started_at",
            "paper_precycle_exposure_snapshot_completed_at",
        ),
        (
            "paper_precycle_exposure_snapshot_completed_at",
            "paper_allocation_decision_time",
        ),
        ("a_plus_context_snapshot_observed_at", "paper_allocation_decision_time"),
        ("paper_entry_gate_snapshot_observed_at", "paper_allocation_decision_time"),
        ("paper_pre_cycle_control_snapshot_observed_at", "paper_allocation_decision_time"),
        ("advanced_indicator_lookup_observed_at", "paper_allocation_decision_time"),
        ("altdata_lookup_observed_at", "paper_allocation_decision_time"),
        ("long_short_lookup_observed_at", "paper_allocation_decision_time"),
        ("mark_index_observed_at", "paper_allocation_decision_time"),
        ("runtime_cost_capture_decision_time", "paper_allocation_decision_time"),
        ("runtime_cost_capture_decision_time", "preemptive_decision_time"),
        ("preemptive_decision_time", "paper_entry_gate_evaluated_at"),
        ("paper_entry_gate_evaluated_at", "a_plus_gate_evaluated_at"),
        ("cost_source_timestamp", "runtime_cost_capture_decision_time"),
        ("source_timestamp", "runtime_cost_capture_decision_time"),
        ("maintenance_bracket_available_at", "paper_allocation_decision_time"),
        ("paper_allocation_decision_time", "maintenance_bracket_consumer_observed_at"),
        (
            "paper_allocation_decision_time",
            "paper_allocator_economic_contract_sealed_at",
        ),
        (
            "paper_exchange_filter_available_at",
            "paper_exchange_filter_observed_at",
        ),
        ("paper_exchange_filter_observed_at", "paper_allocation_decision_time"),
    ):
        require_order(left, right)
    if intent.get("paper_reduced_budget_allocator_recomputed") is True:
        require_order(
            "normal_adaptive_allocation_decision_time",
            "normal_adaptive_allocator_economic_contract_sealed_at",
        )
        require_order(
            "normal_adaptive_allocator_economic_contract_sealed_at",
            "preemptive_decision_time",
        )
        require_order(
            "a_plus_gate_evaluated_at",
            "normal_adaptive_allocation_contract_sealed_at",
        )
        require_order(
            "normal_adaptive_allocation_contract_sealed_at",
            "paper_reduced_allocation_decision_time",
        )
        require_order(
            "paper_reduced_allocation_decision_time",
            "paper_allocation_decision_time",
        )
        require_order("a_plus_gate_evaluated_at", "paper_allocation_decision_time")
        require_order("preemptive_decision_time", "paper_allocation_decision_time")
    else:
        require_order("paper_allocation_decision_time", "preemptive_decision_time")
        require_order(
            "paper_allocator_economic_contract_sealed_at",
            "preemptive_decision_time",
        )

    decision_record_revalidation: dict[str, dict[str, Any]] = {}

    def validate_canonical_decision_record(label: str) -> tuple[bool, str]:
        normalized = label.lower()
        id_field = f"{normalized}_decision_id"
        record_field = f"{normalized}_decision_record"
        key_field = f"{normalized}_decision_record_key"
        hash_field = f"{normalized}_decision_record_hash"
        resolved_field = f"{normalized}_decision_record_resolved"
        source_field = f"{normalized}_decision_source"
        decision_id = intent.get(id_field)
        expected_key = (
            f"{V2_REDIS_PREFIX}decision:{normalized}:{decision_id}"
            if decision_id not in (None, "")
            else None
        )
        record = intent.get(record_field)
        allowed = True
        raw_action = ""
        if decision_id in (None, ""):
            reject(f"FINAL_ADMISSION_{label}_DECISION_ID_MISSING")
            allowed = False
        if intent.get(resolved_field) is not True:
            reject(f"FINAL_ADMISSION_{label}_DECISION_RECORD_UNRESOLVED")
            allowed = False
        if intent.get(source_field) != "PER_ID_DECISION_RECORD":
            reject(f"FINAL_ADMISSION_{label}_DECISION_SOURCE_INVALID")
            allowed = False
        if intent.get(key_field) != expected_key:
            reject(f"FINAL_ADMISSION_{label}_DECISION_KEY_MISMATCH")
            allowed = False
        if not isinstance(record, Mapping):
            reject(f"FINAL_ADMISSION_{label}_DECISION_RECORD_MISSING")
            return False, raw_action
        expected_producer = (
            "v2_risk_gateway_live_loop" if label == "RISK" else "v2_orchestrator_arbitration_loop"
        )
        expected_schema = (
            "v2_per_id_risk_decision_record_v1"
            if label == "RISK"
            else "v2_per_id_orchestrator_decision_record_v1"
        )
        if (
            record.get("schema_version") != expected_schema
            or record.get("producer") != expected_producer
            or record.get("_decision_record_key") != expected_key
            or record.get("_decision_record_store") != "PER_ID_DECISION_RECORD"
            or str(record.get(id_field) or "") != str(decision_id or "")
        ):
            reject(f"FINAL_ADMISSION_{label}_DECISION_RECORD_AUTHORITY_MISMATCH")
            allowed = False
        current_record_raw = (
            _read_json_key(redis_client, expected_key) if expected_key not in (None, "") else {}
        )
        current_record = dict(current_record_raw) if isinstance(current_record_raw, Mapping) else {}
        if current_record:
            current_record["_decision_record_key"] = expected_key
            current_record["_decision_record_store"] = "PER_ID_DECISION_RECORD"
        current_record_hash = (
            hashlib.sha256(
                json.dumps(
                    current_record,
                    sort_keys=True,
                    default=str,
                ).encode("utf-8")
            ).hexdigest()
            if current_record
            else None
        )
        current_record_observed_at = _utc_iso()
        decision_record_revalidation[normalized] = {
            "source_key": expected_key,
            "record_hash": current_record_hash,
            "observed_at": current_record_observed_at,
            "exact_match": bool(current_record) and current_record == dict(record),
        }
        if not current_record or current_record != dict(record):
            reject(f"FINAL_ADMISSION_{label}_DECISION_RECORD_CHANGED_OR_MISSING")
            allowed = False
        recomputed_record_hash = hashlib.sha256(
            json.dumps(dict(record), sort_keys=True, default=str).encode("utf-8")
        ).hexdigest()
        if (
            not _paper_valid_sha256(intent.get(hash_field))
            or intent.get(hash_field) != recomputed_record_hash
        ):
            reject(f"FINAL_ADMISSION_{label}_DECISION_RECORD_HASH_MISMATCH")
            allowed = False
        expected_timeframe = str(
            _first_present(intent.get("timeframe"), intent.get("thesis_timeframe")) or ""
        )
        if (
            str(record.get("symbol") or "").upper() != str(intent.get("symbol") or "").upper()
            or str(record.get("timeframe") or "") != expected_timeframe
        ):
            reject(f"FINAL_ADMISSION_{label}_DECISION_RECORD_CANDIDATE_MISMATCH")
            allowed = False
        intended_side = str(intent.get("side") or "").lower()
        record_side = str(record.get("side") or "").lower()
        if not record_side or record_side != intended_side:
            reject(f"FINAL_ADMISSION_{label}_DECISION_RECORD_SIDE_MISMATCH")
            allowed = False
        if (
            record.get("paper_only") is not True
            or record.get("routes_to_live") is not False
            or record.get("places_real_order") is not False
            or record.get("live_gate") != LIVE_GATE_BLOCKED
        ):
            reject(f"FINAL_ADMISSION_{label}_DECISION_RECORD_SAFETY_FLAGS_INVALID")
            allowed = False
        for field, candidates in (
            ("prediction_id", ("prediction_id", "source_prediction_id")),
            ("signal_id", ("signal_id",)),
            ("feature_snapshot_id", ("feature_snapshot_id",)),
        ):
            expected_value = _first_present(*(intent.get(candidate) for candidate in candidates))
            if expected_value not in (None, "") and str(record.get(field) or "") != str(
                expected_value
            ):
                reject(f"FINAL_ADMISSION_{label}_DECISION_RECORD_{field.upper()}_MISMATCH")
                allowed = False
        expected_feature_hash = _first_present(
            intent.get("feature_vector_hash"), intent.get("input_feature_hash")
        )
        record_feature_hash = _first_present(
            record.get("feature_vector_hash"), record.get("input_feature_hash")
        )
        if (
            expected_feature_hash not in (None, "") or record_feature_hash not in (None, "")
        ) and str(expected_feature_hash or "") != str(record_feature_hash or ""):
            reject(f"FINAL_ADMISSION_{label}_DECISION_RECORD_FEATURE_HASH_MISMATCH")
            allowed = False
        if label == "RISK" and str(record.get("orchestrator_decision_id") or "") != str(
            intent.get("orchestrator_decision_id") or ""
        ):
            reject("FINAL_ADMISSION_RISK_DECISION_ORCHESTRATOR_ID_MISMATCH")
            allowed = False
        generated_value = _first_present(
            record.get("generated_utc"),
            record.get("created_at"),
            record.get("generated_at"),
        )
        generated_time = parse_time(
            f"{record_field}.generated_at",
            generated_value,
            required=True,
            nested=True,
        )
        expires_time = parse_time(
            f"{record_field}.expires_at",
            record.get("expires_at"),
            required=True,
            nested=True,
            allow_after_final=True,
        )
        if (
            generated_time is None
            or expires_time is None
            or generated_time >= expires_time
            or final_utc is None
            or expires_time <= final_utc
            or (final_utc - generated_time).total_seconds() > _POLICY_DECISION_RECORD_STALE_SECONDS
        ):
            reject(f"FINAL_ADMISSION_{label}_DECISION_RECORD_TIME_INVALID")
            allowed = False
        raw_action = (
            str(
                _first_present(
                    record.get("risk_action") if label == "RISK" else None,
                    record.get("orchestrator_action") if label == "ORCHESTRATOR" else None,
                    record.get("decision"),
                )
                or ""
            )
            .strip()
            .lower()
        )
        expected_action = "allow" if label == "RISK" else f"proceed_{intended_side}"
        if raw_action != expected_action:
            reject(f"FINAL_ADMISSION_{label}_DECISION_ACTION_INVALID:" f"{raw_action or 'MISSING'}")
            allowed = False
        top_decision = _first_present(
            intent.get("risk_controller_decision") if label == "RISK" else None,
            intent.get("risk_decision") if label == "RISK" else None,
            intent.get("orchestrator_decision") if label == "ORCHESTRATOR" else None,
        )
        if _paper_decision_action(top_decision, default="deny") != "allow":
            reject(f"FINAL_ADMISSION_{label}_TOP_LEVEL_DECISION_NOT_ALLOW")
            allowed = False
        return allowed, raw_action

    canonical_risk_allowed_final, canonical_risk_action_final = validate_canonical_decision_record(
        "RISK"
    )
    canonical_orchestrator_allowed_final, canonical_orchestrator_action_final = (
        validate_canonical_decision_record("ORCHESTRATOR")
    )

    def validate_lineage_snapshot(
        *,
        prefix: str,
        snapshot: Any,
        top_hash: Any,
        top_observed: Any,
        lineage_field: str,
        expected_roles: set[str] | None = None,
    ) -> None:
        if not isinstance(snapshot, Mapping):
            reject(f"{prefix}_SNAPSHOT_MISSING")
            return
        lineage = snapshot.get(lineage_field)
        if not isinstance(lineage, list) or not lineage:
            reject(f"{prefix}_LINEAGE_MISSING")
            return
        expected_hash = _paper_canonical_sha256(lineage)
        snapshot_hash = snapshot.get("snapshot_hash") or top_hash
        if not _paper_valid_sha256(snapshot_hash) or snapshot_hash != expected_hash:
            reject(f"{prefix}_SNAPSHOT_HASH_MISMATCH")
        if top_hash not in (None, "") and top_hash != snapshot_hash:
            reject(f"{prefix}_TOP_LEVEL_HASH_MISMATCH")
        snapshot_observed = parse_time(
            f"{prefix}.observed_at",
            snapshot.get("observed_at"),
            required=True,
            nested=True,
        )
        top_observed_time = _strict_aware_utc_time(top_observed)
        if (
            snapshot_observed is not None
            and top_observed_time is not None
            and snapshot_observed != top_observed_time
        ):
            reject(f"{prefix}_TOP_LEVEL_OBSERVED_AT_MISMATCH")
        role_values: list[str] = []
        for index, receipt in enumerate(lineage):
            label = f"{prefix}.lineage[{index}]"
            if not isinstance(receipt, Mapping):
                reject(f"{prefix}_LINEAGE_RECEIPT_INVALID:{index}")
                continue
            role = str(receipt.get("role") or "")
            if role:
                role_values.append(role)
            if not role or receipt.get("redis_key") in (None, ""):
                reject(f"{prefix}_LINEAGE_IDENTITY_MISSING:{index}")
            receipt_observed = parse_time(
                f"{label}.observed_at",
                receipt.get("observed_at"),
                required=True,
                nested=True,
            )
            if (
                receipt_observed is not None
                and snapshot_observed is not None
                and receipt_observed > snapshot_observed
            ):
                reject(f"{prefix}_LINEAGE_RECEIPT_AFTER_SNAPSHOT:{index}")
            if prefix == "A_PLUS_CONTEXT" and role == "derived_side_performance":
                allowed_hash_contracts = {"FULL_CANONICAL_DERIVED_PAYLOAD_SHA256_V1"}
            elif prefix == "PRE_CYCLE_CONTROL":
                allowed_hash_contracts = {
                    "FULL_CANONICAL_PAYLOAD_SHA256_V1;" "SOURCE_LABEL_SEPARATELY_BOUND"
                }
            else:
                # Legacy A+ context receipts remain readable while newly
                # captured mappings use the truthful source-label contract.
                allowed_hash_contracts = {
                    "REDIS_KEY_AND_FULL_CANONICAL_PAYLOAD_SHA256_V1",
                    "FULL_CANONICAL_PAYLOAD_SHA256_V1;" "SOURCE_LABEL_SEPARATELY_BOUND",
                }
            if receipt.get("hash_contract") not in allowed_hash_contracts:
                reject(f"{prefix}_LINEAGE_HASH_CONTRACT_INVALID:{index}")
            if not isinstance(receipt.get("present"), bool):
                reject(f"{prefix}_LINEAGE_PRESENT_FLAG_INVALID:{index}")
            if not _paper_valid_sha256(receipt.get("payload_hash")):
                reject(f"{prefix}_LINEAGE_PAYLOAD_HASH_INVALID:{index}")
            receipt_times: dict[str, datetime] = {}
            for clock in (
                "event_time",
                "feature_cutoff",
                "available_at",
                "generated_at",
                "source_decision_time",
            ):
                raw_clock = receipt.get(clock)
                if raw_clock in (None, ""):
                    continue
                source_time = parse_time(
                    f"{label}.{clock}",
                    raw_clock,
                    nested=True,
                )
                if source_time is not None:
                    receipt_times[clock] = source_time
                if (
                    source_time is not None
                    and receipt_observed is not None
                    and source_time > receipt_observed
                ):
                    reject(f"{prefix}_LINEAGE_CLOCK_AFTER_OBSERVATION:{index}:{clock}")
            for left, right in (
                ("event_time", "available_at"),
                ("feature_cutoff", "available_at"),
            ):
                if (
                    left in receipt_times
                    and right in receipt_times
                    and receipt_times[left] > receipt_times[right]
                ):
                    reject(f"{prefix}_LINEAGE_CLOCK_ORDER_INVALID:{index}:{left}>{right}")
        if expected_roles is not None:
            if (
                len(lineage) != len(expected_roles)
                or len(role_values) != len(expected_roles)
                or len(set(role_values)) != len(role_values)
                or set(role_values) != expected_roles
            ):
                reject(f"{prefix}_LINEAGE_ROLE_SET_MISMATCH")

        source_by_role = {
            str(receipt.get("role") or ""): str(receipt.get("redis_key") or "")
            for receipt in lineage
            if isinstance(receipt, Mapping)
        }
        receipt_by_role = {
            str(receipt.get("role") or ""): receipt
            for receipt in lineage
            if isinstance(receipt, Mapping) and receipt.get("role")
        }
        symbol = str(intent.get("symbol") or "").upper()
        timeframe = str(
            _first_present(intent.get("timeframe"), intent.get("thesis_timeframe")) or ""
        )
        if prefix == "A_PLUS_CONTEXT":
            exact_sources = {
                "trainer_metrics": f"{V2_REDIS_PREFIX}trainer:hybrid_cuda:metrics",
                "cross_asset": f"{V2_REDIS_PREFIX}context:cross_asset",
                "feedback_rows": f"{V2_REDIS_PREFIX}trainer:feedback:outcomes",
                "derived_side_performance": ("IN_PROCESS_FROM_TRUSTED_FEEDBACK_ROWS"),
                "regime_decision": (f"{V2_REDIS_PREFIX}regime:gate:{symbol}:{timeframe}"),
                "htf_context": f"{V2_REDIS_PREFIX}context:htf:{symbol}",
                "trade_tape": (f"{V2_REDIS_PREFIX}market:trade_tape_features:{symbol}"),
            }
            for role, expected_source in exact_sources.items():
                if source_by_role.get(role) != expected_source:
                    reject(f"{prefix}_LINEAGE_SOURCE_MISMATCH:{role}")
            feedback_receipt = receipt_by_role.get("feedback_rows")
            derived_receipt = receipt_by_role.get("derived_side_performance")
            if not isinstance(feedback_receipt, Mapping) or not isinstance(
                derived_receipt, Mapping
            ):
                reject("A_PLUS_CONTEXT_DERIVATION_LINEAGE_MISSING")
            else:
                if (
                    derived_receipt.get("source_role") != "feedback_rows"
                    or derived_receipt.get("source_redis_key")
                    != f"{V2_REDIS_PREFIX}trainer:feedback:outcomes"
                    or not _paper_valid_sha256(derived_receipt.get("source_payload_hash"))
                    or derived_receipt.get("source_payload_hash")
                    != feedback_receipt.get("payload_hash")
                ):
                    reject("A_PLUS_CONTEXT_DERIVATION_SOURCE_BINDING_INVALID")
                feedback_observed = parse_time(
                    "A_PLUS_CONTEXT.feedback_rows.observed_at",
                    feedback_receipt.get("observed_at"),
                    required=True,
                    nested=True,
                )
                derived_source_observed = parse_time(
                    "A_PLUS_CONTEXT.derived_side_performance.source_observed_at",
                    derived_receipt.get("source_observed_at"),
                    required=True,
                    nested=True,
                )
                derivation_started = parse_time(
                    "A_PLUS_CONTEXT.derived_side_performance.derivation_started_at",
                    derived_receipt.get("derivation_started_at"),
                    required=True,
                    nested=True,
                )
                derived_generated = parse_time(
                    "A_PLUS_CONTEXT.derived_side_performance.generated_at",
                    derived_receipt.get("generated_at"),
                    required=True,
                    nested=True,
                )
                derived_available = parse_time(
                    "A_PLUS_CONTEXT.derived_side_performance.available_at",
                    derived_receipt.get("available_at"),
                    required=True,
                    nested=True,
                )
                derived_observed = parse_time(
                    "A_PLUS_CONTEXT.derived_side_performance.observed_at",
                    derived_receipt.get("observed_at"),
                    required=True,
                    nested=True,
                )
                if (
                    feedback_observed is not None
                    and derived_source_observed is not None
                    and feedback_observed != derived_source_observed
                ):
                    reject("A_PLUS_CONTEXT_DERIVATION_SOURCE_CLOCK_MISMATCH")
                derived_clock_chain = (
                    derived_source_observed,
                    derivation_started,
                    derived_generated,
                    derived_available,
                    derived_observed,
                    snapshot_observed,
                )
                if all(value is not None for value in derived_clock_chain) and any(
                    left > right
                    for left, right in zip(
                        derived_clock_chain,
                        derived_clock_chain[1:],
                        strict=False,
                    )
                ):
                    reject("A_PLUS_CONTEXT_DERIVATION_CLOCK_ORDER_INVALID")
            allowed_microstructure_sources = {
                f"{V2_REDIS_PREFIX}microstructure:trust_score:{symbol}:{timeframe}",
                f"{V2_REDIS_PREFIX}microstructure:trust_score:{symbol}:1m",
                f"{V2_REDIS_PREFIX}microstructure:feed_quality:binance:{symbol}",
            }
            if source_by_role.get("microstructure_trust") not in (allowed_microstructure_sources):
                reject("A_PLUS_CONTEXT_LINEAGE_SOURCE_MISMATCH:microstructure_trust")
        elif prefix == "PRE_CYCLE_CONTROL":
            exact_sources = {
                "continuous_edge_guardian": CONTINUOUS_EDGE_GUARDIAN_GATE_REDIS_KEY,
                "paper_performance_circuit_breaker": ("IN_PROCESS_PRE_CYCLE_PERFORMANCE_CIRCUIT"),
                "churn_equity_bleed_governor": ("IN_PROCESS_PRE_CYCLE_CHURN_GOVERNOR"),
                "bucket_quarantine": "IN_PROCESS_PRE_CYCLE_BUCKET_QUARANTINE",
                "b_grade_calibration_safety": ("IN_PROCESS_PRE_CYCLE_CALIBRATION_SAFETY"),
                "paper_entry_freeze": (
                    "IN_PROCESS_COMPOSED_FROM_EXACT_REDIS_FREEZE_AND_" "PORTFOLIO_SOURCES"
                ),
                "paper_entry_freeze_source": PAPER_ENTRY_FREEZE_REDIS_KEY,
                "portfolio_state_source": PAPER_PORTFOLIO_STATE_REDIS_KEY,
                "adaptive_tuning_source": PAPER_ADAPTIVE_TUNING_REDIS_KEY,
                "paper_session_source": PAPER_SESSION_REDIS_KEY,
                "paper_position_or_ledger_source": {
                    PAPER_POSITIONS_REDIS_KEY,
                    PAPER_LEDGER_REDIS_KEY,
                },
                "paper_closed_trades_source": PAPER_CLOSED_TRADES_REDIS_KEY,
                "high_confidence_loss_cluster": (
                    "IN_PROCESS_PRE_CYCLE_HIGH_CONFIDENCE_LOSS_CLUSTER"
                ),
                "preemptive_bucket_health": ("IN_PROCESS_PRE_CYCLE_PREEMPTIVE_BUCKET_HEALTH"),
                "current_risk_state": (
                    "IN_PROCESS_DERIVED_FROM_EXACT_PAPER_POSITION_AND_" "PORTFOLIO_SOURCES"
                ),
                "paper_runtime_owner": ("PROCFS_AND_SYSTEMD_CURRENT_PROCESS_OWNER_PROJECTION"),
                "maintenance_bracket_security": ("ENV_DERIVED_SECRET_FREE_SECURITY_BINDING"),
                "dynamic_risk_envelope": ("IN_PROCESS_PRE_CYCLE_DYNAMIC_RISK_ENVELOPE"),
            }
            for role, expected_source in exact_sources.items():
                if (
                    isinstance(expected_source, set)
                    and source_by_role.get(role) not in expected_source
                ) or (
                    not isinstance(expected_source, set)
                    and source_by_role.get(role) != expected_source
                ):
                    reject(f"{prefix}_LINEAGE_SOURCE_MISMATCH:{role}")

    a_plus_lineage = intent.get("a_plus_context_snapshot_lineage")
