        strategy_mode_opportunity_observed_at = _utc_iso()
        strategy_mode_opportunity_observed_dt = _strict_aware_utc_time(
            strategy_mode_opportunity_observed_at
        )
        retained_strategy_mode_opportunities: list[dict[str, Any]] = []
        for prior_opportunity in strategy_mode_opportunity_supply_rows:
            prior_expiry = _strict_aware_utc_time(prior_opportunity.get("source_expires_at"))
            if (
                strategy_mode_opportunity_observed_dt is not None
                and prior_expiry is not None
                and strategy_mode_opportunity_observed_dt < prior_expiry
            ):
                retained_strategy_mode_opportunities.append(prior_opportunity)
            else:
                strategy_mode_opportunity_exclusion_counts[
                    "OPPORTUNITY_SOURCE_EXPIRED_BEFORE_CURRENT_OBSERVATION"
                ] += 1
        strategy_mode_opportunity_supply_rows[:] = retained_strategy_mode_opportunities
